SEARCH_ADD("hoshanot-a",{"p":[["hoshanot-a-1.html","שער א · פתיחה","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-10.html","שער י · כהושעת אדם","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-2.html","שער ב · למען אמיתך","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-3.html","שער ג · אבן שתיה","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-4.html","שער ד · אערוך שועי","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-5.html","שער ה · אום אני חומה","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-6.html","שער ו · אל למושעות","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-7.html","שער ז · אדון המושיע","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-8.html","שער ח · כהושעת אלים","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-9.html","שער ט · אום נצורה","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-hakdama.html","הקדמה","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-mavo.html","מבוא","תענה אמונים · חלק א · יום טוב וחול המועד"],["hoshanot-a-seder.html","סדר הושענות","תענה אמונים · חלק א · יום טוב וחול המועד"]],"e":[[0,"piyut","נוסח הפיוט","הוֹשַׁע נָא לְמַעַנְךָ אֱלֹהֵינוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ בּוֹרְאֵנוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ גּוֹאֲלֵנוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ דּוֹרְשֵׁנוּ, הוֹשַׁע נָא."],[0,"s1","הוֹשַׁע נָא","– על פי לשון הכתוב: \"אָנָּא ה' הוֹשִׁיעָה נָּא\" (תהילים קיח כה). ה'ישועה' היא מוחלטת, שאין אחריה עוד צרה, בשונה מ'הצלה' שהיא זמנית. המלבי\"ם מסביר שהדבר המבדיל את המושג 'ישועה' מהמושג 'עזרה' הוא, שהעזרה נעשית בסיוע הנעזר, והישועה נעשית על ידי המושיע לבדו; לפיכך, כשהקב\"ה מסייע לעם ישראל מכוח זכויותיהם, סיוע זה נחשב 'עזר', מפני שגם הם שותפים בו. במקרה כזה, אם בהמשך הזמן כבר לא יהיו ראויים לכך – תיפסק אותה עזרה. אך כשלישראל אין די זכויות, ובכל זאת הקב\"ה מסייע להם מצד מידת החסד, הרי שסיוע זה נחשב 'ישועה' – מפני שהוא פועל אותה מכוחו בלבד. במקרה כזה, הישועה לא תיפסק, שהרי ישראל זכו לה בחסד ואינה תלויה בזכות, ואם כן – אין סיבה שתצדיק את הפסקתה. על פי זה יובן מדוע אנו מתפללים דווקא ל'ישועה' – בקשתנו היא לזכות לישועה מוחלטת ונצחית, שלא תיפסק, אף אם איננו ראויים לכך על פי מעשינו. הבקשות לישועה המלוות את כל פיוטי ה'הושענות', כוללות שני מובנים: בקשה לישועות בעניינים שונים בחיינו הפרטיים או הלאומיים, ובפרט בעניין ירידת הגשמים והצלחת החקלאות בשנה החדשה, ובקשה לקירוב הישועה השלימה – ביאת המשיח ובניין המקדש. 'נָא' הוא גם לשון בקשה, וגם מילה נרדפת ל'עכשיו'; מטבע הלשון 'הוֹשַׁע נָא', עשוי לכלול את שתי המשמעויות הללו."],[0,"s2","סיכום","ארבע השורות הבאות, הפותחות את סדר ה'הושענות' בכל יום מימי החג, מציינות ארבע סיבות שמחמתן גאולת עם ישראל היא למען הקב\"ה, כביכול: מצד זה שהוא 'אֱלֹהֵינוּ', ומצד זה שהוא 'בּוֹרְאֵנוּ', וכן הלאה; ומשום כך אנו מבקשים: 'הוֹשַׁע נָא': לְמַעַנְךָ אֱלֹהֵינוּ – תפקידו של עם ישראל הוא לייצג את הקב\"ה ולפרסם בעולם את אלוהותו ומלכותו; דבר זה יכול להעשות באופן מושלם רק כאשר הוא עומד ברום המעלה ובעל יכולת השפעה על אומות העולם. על כך אנו מתפללים: \"לְמַעַנְךָ אֱלֹהֵינוּ הוֹשַׁע נָא\" – הושיענו ישועה שלימה ורומם את קרננו, 'לְמַעַנְךָ' – כדי שנוכל לפרסם בעולם את אלוהותך. רעיון זה – שכל תפילותינו אינן עבור עצמנו וטובתנו האישית, אלא כדי להגדיל את כבוד ה', שכן זוהי מטרתנו בעולם – עומד בבסיסן של תפילות ה'הושענות', והוא יסוד הכרחי עבור גישה נכונה לתפילה באופן כללי. לפיכך, אנו פותחים את סדר אמירת ה'הושענות' בשורות אלו, ואף מסיימים אותן באמירת הפיוט 'כהושעת אלים', שרעיון זה חורז את שורותיו, ולאחריו חותמים באמירת הפסוק המציין מטרה זו: \"לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ – כִּי ה' הוּא הָאֱלֹהִים, אֵין עוֹד\" (מלכים א' ח ס). הערות 65 להרחבה בנושא זה, ראה להלן עמ' 61-60"],[0,"s3","לְמַעַנְךָ בּוֹרְאֵנוּ","– הושיענו למענך, בוראנו – בורא העולם והאדם, כדי שרצונך בבריאתם תתממש. הקב\"ה ברא את העולם כדי להיטיב לנבראים על ידי שיעבדוהו ויתקרבו אליו, ויקבלו על כך שכר רוחני; לשם כך, ברא את כל העולם העשיר הסובב את האדם – שעל ידו יכול הוא להעמיק את הכרתו בבוראו ולחזק את האמונה בו והקשר עימו, וכך להתעלות ולהיות ראוי לאותו שכר. על כך אמרו חז\"ל: \"כל מה שברא הקב\"ה בעולמו, לא בראו אלא לכבודו, שנאמר: 'כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו' (ישעיהו מג ז)\". אנו מתפללים לישועה כדי שנוכל לעבוד את הקב\"ה טוב יותר, ללא שיעבוד לעול הגויים ולעול הגלויות וללא טרדות הזמן, וכך לממש את הפוטנציאל הטמון בנו – כיחידים וכאומה, ואת מטרת בריאתנו. נבואת זכריה על מלחמת גוג ומגוג והגאולה העתידה, פותחת בפסוק: \"מַשָּׂא דְבַר ה' עַל יִשְׂרָאֵל; נְאֻם ה' נֹטֶה שָׁמַיִם וְיֹסֵד אָרֶץ וְיֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ\" (זכריה יב א), וכתב שם המלבי\"ם: שרוח האדם בקרב גופו הוא החיבור והקשר שנעשה בין השמיים ובין הארץ; שהגוף מתולדות הארץ, והרוח הוא מן העליונים. ובזה נברא האדם בתבנית העולם הגדול, וכל העולם העליון והתחתון נכלל בו ונברא בשבילו, והוא התכלית אל העולם כולו, וּמְהַלֵּך מַהֲלַךְ השלימות אל כל המציאות. ולכן יחשוב ה' מחשבות בל יידח ממנו נידח, ויבננו בבניין שלם לעתיד, כשיגיע עת התיקון. לעתיד לבוא, בעת הגאולה השלימה עליה אנו מתפללים, יבוא האדם – ועימו העולם כולו – לתיקונם השלם ולהתממשות מטרת בריאתם; על כך אנו מבקשים: \"לְמַעַנְךָ בּוֹרְאֵנוּ, הוֹשַׁע נָא\". הערות 66 סוף מסכת אבות"],[0,"s4","לְמַעַנְךָ גּוֹאֲלֵנוּ","– אף בזמן זה, לפני הגאולה העתידה, הקב\"ה מכונה 'גּוֹאֲלֵנוּ'. זאת, לא רק מחמת הגאולות שגאלָנו בעבר, אלא בעיקר בגלל מה שהן מבטאות: 'תפקידו' של הקב\"ה הוא לגאול את ישראל, בכל עת וכל שעה. מי שבעבר עשה פעולה כל שהיא, אפילו אם חזר עליה מספר פעמים, לא יצדק לכנותו כעת על שם אותה הפעולה – הרי כעת אין כל קשר בינו לבינה; אך הקב\"ה נקרא 'גואל ישראל', בלשון הווה, משום שזוהי מגמתו התמידית. ממילא, כאשר ישראל שרויים בגלות, במצור ובמצוק, הרי שבעיני העמים נראה הדבר כחסרון יכולת של הקב\"ה – שהרי תפקידו הוא לגאול את ישראל, וכעת אינו עושה זאת. משום כך, אנו משתמשים בבקשה זו בתואר 'גּוֹאֲלֵנוּ' – מכיוון שאתה גואלנו, הרי שהישועה שתושיענו היא למענך, כדי להראות את יכולתך, כמאמר הכתוב: \"וַיּוֹשִׁיעֵם לְמַעַן שְׁמוֹ, לְהוֹדִיעַ אֶת גְּבוּרָתוֹ\" (תהילים קו ח). לֹא לָנוּ ה', לֹא לָנוּ, כִּי לְשִׁמְךָ תֵּן כָּבוֹד, עַל חַסְדְּךָ עַל אֲמִתֶּךָ. לָמָּה יֹאמְרוּ הַגּוֹיִם: אַיֵּה נָא אֱלֹהֵיהֶם? וֵאלֹהֵינוּ בַשָּׁמָיִם, כֹּל אֲשֶׁר חָפֵץ עָשָׂה. הערות 67 תהילים קטו א-ג"],[0,"s5","לְמַעַנְךָ דּוֹרְשֵׁנוּ","– 'לדרוש' היינו לחפש דבר ולנסות להשיגו. הקב\"ה דורש את ישראל, כלומר: פועל כדי להשיבם למוטב ולקרבם אליו; בתקופה שהיתה נבואה – על ידי הנביאים, כמאמר הכתוב: \"לְמִן הַיּוֹם אֲשֶׁר יָצְאוּ אֲבוֹתֵיכֶם מֵאֶרֶץ מִצְרַיִם עַד הַיּוֹם הַזֶּה, וָאֶשְׁלַח אֲלֵיכֶם אֶת כָּל עֲבָדַי הַנְּבִיאִים יוֹם הַשְׁכֵּם וְשָׁלֹחַ\" (ירמיהו ז כה); ולאחריה – על ידי מאורעות שמעוררים את האדם להיטיב את דרכיו ולרומם את רצונותיו ואישיותו. כמבואר לעיל, אנו מתפללים לישועה כדי שנוכל לעבוד את הקב\"ה טוב יותר; לפיכך אנו מבקשים: \"לְמַעַנְךָ דּוֹרְשֵׁנוּ הוֹשַׁע נָא\" – מאחר ורצונו של הקב\"ה הוא לקרבנו לעבודתו, וכשניוושע – רצון זה יתממש באופן נרחב ונעלה לאין ערוך מאשר התממשותו כעת, הרי שהישועה היא 'לְמַעַנְךָ'."],[0,"n61","הערה 61","פירוש ה'רוקח' לסידור התפילה (הוצאת מכון הרב הרשלר), עמ' שעב-שעג."],[0,"n62","הערה 62","ישעיהו יב ב"],[0,"n63","הערה 63","תלמוד בבלי, ברכות ט."],[0,"n64","הערה 64","אונקלוס, אבן עזרא, רד\"ק, ורמב\"ן, על בראשית יב יא, ובמקומות נוספים"],[1,"piyut","נוסח הפיוט","אֲנִי וָהוּ הוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ אָדָם יְצִיר כַּפֶּיךָ לְגוֹנְנָה, בְּשַׁבַּת קֹדֶשׁ הִמְצֵאתוֹ כֹּפֶר וַחֲנִינָה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ גּוֹי מְצֻיָּן מְקַוִּים חֹפֶשׁ, דֵּעָה כִּוְּנוּ לָבוּר שְׁבִיעִי לְנֹפֶשׁ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ הָעָם נִהַגְתָּ כַּצֹּאן לְהַנְחוֹת, וְחֹק שַׂמְתָּ בְּמָרָה עַל מֵי מְנוּחוֹת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ זְבוּדֶיךָ בְּמִדְבַּר סִין בַּמַחֲנֶה, חָכְמוּ וְלָקְטוּ בַּשִּׁשִּׁי לֶחֶם מִשְׁנֶה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ טְפוּלֶיךָ הוֹרוּ הֲכָנָה בְּמַדָּעָם, יִשַּׁר כֹּחָם וְהוֹדָה לָמוֹ רוֹעָם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ כֻּלְכְּלוּ בְּעֹנֶג מָן הַמְּשֻׁמָּר, לֹא הָפַךְ עֵינוֹ וְרֵיחוֹ לֹא נָמָר, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מִשְׁפְּטֵי מַשְׂאֹת שַׁבָּת גָּמָרוּ, נָחוּ וְשָׁבְתוּ, רְשׁוּיוֹת וּתְחוּמִים שָׁמָרוּ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ סִינַי הָשְׁמְעוּ בְּדִבּוּר רְבִיעִי, עִנְיַן זָכוֹר וְשָׁמוֹר לְקַדֵּשׁ שְׁבִיעִי, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ פֻּקְּדוּ יְרִיחוֹ שֶׁבַע לְהַקֵּף, צָרוּ עַד רִדְתָּהּ בַּשַּׁבָּת לְתַקֵּף, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ קֹהֶלֶת וְעַמּוֹ בְּבֵית עוֹלָמִים, רִצּוּךָ בְּחָגְגָם שִׁבְעָה וְשִׁבְעָה יָמִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שָׁבִים עוֹלֵי גוֹלָה לְפִדְיוֹם, תּוֹרָתְךָ בְּקָרְאָם בֶּחָג יוֹם יוֹם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מְשַׂמְּחֶיךָ בְּבִנְיַן שֵׁנִי הַמְחֻדָּשׁ, נוֹטְלִין לוּלָב כָּל שִׁבְעָה בַּמִּקְדָּשׁ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ חִבּוּט עֲרָבָה שַׁבָּת מַדְחִים, מֻרְבִּיּוֹת מוֹצָא לִיסוֹד מִזְבֵּחַ מַנִּיחִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ בְּרַכּוֹת וַאֲרוּכּוֹת וּגְבוֹהוֹת מְעַלְּסִים, בִּפְטִירָתָן יֹפִי לְךָ מִזְבֵּחַ מְקַלְּסִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מוֹדִים וּמְיַחֲלִים וְלֹא מְשַׁנִּים, כֻּלָּנוּ אָנוּ לְיָהּ וְעֵינֵינוּ לְיָהּ שׁוֹנִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ יֶקֶב מַחֲצָבֶיךָ סוֹבְבִים בְּרַעֲנָנָה, רוֹנְנִים אֲנִי וָהוּ הוֹשִׁיעָה נָּא, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ חֵיל זְרִיזִים מְשָׁרְתִים בִּמְנוּחָה, קָרְבַּן שַׁבָּת כָּפוּל עוֹלָה וּמִנְחָה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ לְוִיֶּךָ עַל דּוּכָנָם לְהַרְבָּת, אוֹמְרִים מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ נִחוּמֶיךָ בְּמִצְוֹתֶיךָ תָּמִיד יִשְׁתַּעְשְׁעוּן, וּרְצֵם וְהַחֲלִיצֵם, בְּשׁוּבָה וָנַחַת יִוָּשֵׁעוּן, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב, וְהוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי יְשׁוּעוֹת, אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא."],[1,"s1","על הפיוט","בפיוט זה אנו מזכירים ישועות שונות שהקב\"ה פעל במשך ההיסטוריה, שכל אחת מהן קשורה בעניינה של השבת או בעניינו של חג הסוכות. אנו מבקשים ישועות בתחומים שונים, בהתאם לסוגי הישועות שנעשו בעבר, אותן אנו מזכירים. בשונה משאר ה'הושענות' שחוברו על ידי רבי אלעזר הקליר, הושענא זו נתחברה בתקופה מאוחרת יותר, על ידי רבי מנחם בן רבי מכיר, ושמו חתום בראשי החרוזים, לאחר סדר הא\"ב ('מנחם ברבי מכיר חזק לעד אמן')."],[1,"s2","כְּהוֹשַׁעְתָּ אָדָם יְצִיר כַּפֶּיךָ לְגוֹנְנָה, בְּשַׁבַּת קֹדֶשׁ הִמְצֵאתוֹ כֹּפֶר וַחֲנִינָה","– אדם הראשון היה יציר כפיו של הקב\"ה, כמאמר הכתוב: \"וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה, וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה\" (בראשית ב ז). לאחר שחטא ואכל מעץ הדעת טוב ורע – היה ראוי למות, כפי שהזהירו הקב\"ה: \"וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת\" (שם שם יז). האכילה היתה ביום השישי בו נברא, ולאחר כמה שעות, ביום השבת, הקב\"ה הושיעו מעונש זה 'לְגוֹנְנָה' = להגן עליו מהמיתה, והמציאו (=המציא לידו, נתן לו) כפרה וחנינה, כדברי המדרש: \"מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת\" (תהילים צב) – רבי שמעון אומר: המזמור הזה אדם הראשון אמרו. לפי שבא יום השבת ונעשה סניגור לאדם לפני הקב\"ה, ואמר: \"ריבון העולם! בששת ימי המעשה לא נהרג איש בעולם, ובי אתה מתחיל?! זו היא קדושתי?! וזו היא ברכתי?!\"; וניצל אדם הראשון מדינה של גיהנם בזכות השבת. וכשראה אדם כוחה של שבת – התחיל משורר: \"מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת\". על פי ההבנה הפשוטה בלשון אזהרת הקב\"ה לאדם, היה עליו למות ביום בו אכל מהעץ; אך בזכות השבת, הקב\"ה פסק את דינו לפי הבנה אחרת המתאפשרת בלשון האזהרה, לפיה כוונת העונש 'מוֹת תָּמוּת' היא שייעשה לבן מוות, ובפרט שבמידה מסויימת גם יש לכך משמעות מיידית, שכן כבר מאז התחיל תהליך המיתה, שהרי כל יום שעובר מקרב אותו אל מיתתו. ניתן גם להסביר שעונש המיתה מתייחס לירידת נשמתו ממדרגתה העליונה בה היתה קודם החטא, ודבר זה נחשב כמיתה, כלומר: ירידת מדרגת חיי הנשמה, שהם חיי האדם האמיתיים. ניתן להסביר את עומק כוונת המדרש, שוודאי לא היתה כאן רק טענה חיצונית של יום השבת, שמפאת קדושתו לא ראוי שהמיתה הראשונה בהיסטוריה תתרחש בו; שאם כן, לא מובן מדוע לא מת אדם הראשון לאחר השבת. כוונת המדרש היא, שיום השבת הוא זמן של התבוננות פנימית – האדם שובת ממלאכתו ומפעולותיו המעשיות, ומפנה את מחשבתו להתבוננות במשמעות הפנימית של חייו ושל העולם. טענת יום השבת שמציג המדרש, היא עצם ההסתכלות על המציאות מתוך מבט של שבת, מבט פנימי ומעמיק. במבט כזה, חטא האדם הוא חיצוני לו, תוצאת השפעת היצר עליו, ואינו חלק ממהותו העצמית. לפיכך – אף על פי שבפועל האדם חטא, אין בכך בכדי להותיר את חייו חסרי ערך ולהצדיק עונש מיתה עבורו, שהרי עצמיותו נותרה כשהיתה, ולא היתה כאן כי אם סטייה חיצונית מהדרך, אותה יש לתקן בתוך מסגרת חיי האדם. גם 'מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת', אותו אמר אדם הראשון באותה שעה, מתבונן על המציאות במבט פנימי: מַה גָּדְלוּ מַעֲשֶׂיךָ ה', מְאֹד עָמְקוּ מַחְשְׁבֹתֶיךָ. אִישׁ בַּעַר לֹא יֵדָע, וּכְסִיל לֹא יָבִין אֶת זֹאת. הבער והכסיל, שהם אנשים חומריים, רגילים להסתכל על המציאות בצורה שטחית – כשם שהם חשים שייכות אל העולם רק מצד חיצוניותו: החומר. מי שמסתכל כך על המציאות, אינו יכול להבין את פשר מעשי ה' בהנהגת העולם ואת מחשבותיו העומדות מאחוריהם. בִּפְרֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב, וַיָּצִיצוּ כָּל פֹּעֲלֵי אָוֶן – לְהִשָּׁמְדָם עֲדֵי עַד. וְאַתָּה מָרוֹם לְעֹלָם, ה'. כִּי הִנֵּה אֹיְבֶיךָ ה', כִּי הִנֵּה אֹיְבֶיךָ יֹאבֵדוּ, יִתְפָּרְדוּ כָּל פֹּעֲלֵי אָוֶן. [...] צַדִּיק כַּתָּמָר יִפְרָח, כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה. שְׁתוּלִים בְּבֵית ה' – בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ. עוֹד יְנוּבוּן בְּשֵׂיבָה, דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ. לְהַגִּיד כִּי יָשָׁר ה', צוּרִי וְלֹא עלתה (קרֵי: עַוְלָתָה) בּוֹ. על פי המציאות הנראית לעין, הרשעים פורחים ומצליחים, והצדיקים נרדפים – דבר שאינו מובן במבט חיצוני, והבער והכסיל אף יכולים לקבל מכך אישוש לכדאיות אורח חייהם. רק אדם רוחני ופנימי, שמבין שמעל כל הבריאה ניצב הקב\"ה ומנהיגה בצדק – \"וְאַתָּה מָרוֹם לְעֹלָם, ה'\" – יכול לשאת מבטו למרחוק ולהבין את המשמעות האמיתית של המאורעות המתרחשים לעיניו. מי שלא רואה בעולם הזה, החומרי, את חזות הכול, אלא יודע להעריך כראוי את חשיבותו של העולם הבא, הנצחי, שלעומתו העולם הזה הוא כאין וכאפס, כחלום יעוף – מבין ששלוות הרשעים בעולם הזה נועדה כדי לגמול להם על מעט הזכויות שבידם, ועל ידי כך להכחידם מהעולם הנצחי – \"לְהִשָּׁמְדָם עֲדֵי עַד\". כך גם מפורש בתורה: \"וּמְשַׁלֵּם לְשֹׂנְאָיו אֶל פָּנָיו – לְהַאֲבִידוֹ\" (דברים ז י). לעומת זאת, הצדיק נענש בעולם הזה על מעט העוונות שבידו, כדי שיזכה לעולם הבא, שהוא הטוב האמיתי והנצחי. הסתכלות כזו, בכוחה \"לְהַגִּיד כִּי יָשָׁר ה', צוּרִי וְלֹא עַוְלָתָה בּוֹ\" – כל מעשיו הם ביושר ובצדק, ואין בהם כל עוולה. \"הַצּוּר תָּמִים פָּעֳלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט, אֵל אֱמוּנָה וְאֵין עָוֶל, צַדִּיק וְיָשָׁר הוּא\" (שם לב ד). בעל המאמר במדרש שהובא, הוא רבי שמעון בר יוחאי; שיטתו של רבי שמעון היא ההסתכלות הפנימית. הדבר בא לידי ביטוי הן בזיקתו לתורת הסוד – פנימיות התורה, הן בשיטתו ההלכתית, בה הוא נוטה לפסוק על פי ראיית המציאות בפנימיותה, כגון לייחס יותר חשיבות לכוונת האדם בעשיית הפעולה מאשר לפעולה עצמה. גם בוויכוחו עם רבי יהודה לגבי היחס למעשי הרומאים, הוא פוסל אותם אף על פי שבפועל הם יעילים, משום שכוונת הרומאים בעשייתם היא פסולה. במאמר זה מגלה רבי שמעון את המבט הפנימי, מבט השבת, על חטאי האדם, הרואה בהם דבר חיצוני בלבד. הביטוי 'יְצִיר כַּפֶּיךָ' בו משתמש הפייטן, מהווה אף הוא טעם לכך שהקב\"ה הגן על אדם הראשון מעונש המיתה. כפי שבואר לעיל, משמעותה של מידת 'חַנּוּן', שמכוחה העניק הקב\"ה לאדם הראשון 'חֲנִינָה' היא, שכשם שכל יוצר חש קשר והזדהות עם יצירתו, כך הקב\"ה חש, כביכול, קשר רגשי והזדהות עם האדם – יציר כפיו. הדברים נכונים ביתר שאת לגבי אדם הראשון, שהיה יציר כפיו של הקב\"ה באופן ישיר; מכוח מידה זו – העניק לו הקב\"ה חנינה. 'כֹּפֶר וַחֲנִינָה' – בביאור שני מושגים אלו והיחס שביניהם ניתן להסביר, ש'כֹּפֶר' = כפרה, הוא המתקת גזר הדין; אך גם לאחריה, הנפש עדיין מוכתמת מהחטא, והיחס בין האדם לבוראו אינו כבתחילה. 'כפרה' היא לשון כיסוי – החטא עצמו נשאר תחת הכיסוי, אלא שאינו גורר בעקבותיו עונש. לפיכך דרושה גם ה'חֲנִינָה' – שנובעת ממציאת 'חן' של הנאשם בעיני השופט ומקשר רגשי עמוק ביניהם; היא, באשר איננה מוגבלת לחוקים הפורמליים, יכולה למחוק לגמרי את רושם החטא, ולהשיב את מערכת היחסים שבין האדם לבוראו על כנה. זוהי גם הסיבה שהחוטא צריך להקריב גם קורבן עולה לאחר הקרבת קורבן החטאת; קורבן החטאת נועד למנוע את העונש, וקורבן העולה נועד לפייס, כביכול, את הקב\"ה, כפי שכתב רש\"י: \"'וְהִקְרִיב אֶת אֲשֶׁר לַחַטָּאת רִאשׁוֹנָה' – חטאת קודמת לעולה; למה הדבר דומה? לפרקליט שנכנס לרַצות, ריצה פרקליט – נכנס דורון אחריו\". אנו מתפללים לישועה ולהגנה על חיינו, כפי שהושיע הקב\"ה את אדם הראשון והגן עליו מן המיתה, ואף אנו נזכה ל'כֹּפֶר וַחֲנִינָה' – ביטול תוצאות החטאים ורשמיהם השליליים, ותיקון מערכת היחסים שביננו לבין הקב\"ה, ומתוך כך – נהיה זכאים לשנה טובה וברוכה ברוחניות ובגשמיות. אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף, לְהַגִּיד לְאָדָם יָשְׁרוֹ. וַיְחֻנֶּנּוּ , וַיֹּאמֶר פְּדָעֵהוּ [=פְּדֵהוּ] מֵרֶדֶת שָׁחַת, מָצָאתִי כֹפֶר . [...] לְהָשִׁיב נַפְשׁוֹ מִנִּי שָׁחַת, לֵאוֹר בְּאוֹר הַחַיִּים. הערות 391 לכאורה מדרש זה חלוק על התלמוד הבבלי (סנהדרין לח:), בו מפורש שאדם הראשון נידון ביום השישי. 392 ילקוט שמעוני, תהילים צב, רמז תתמג 393 כך פירשו רס\"ג, רמב\"ן, חזקוני, מלבי\"ם, ועוד, בפירוש האזהרה עצמה (בראשית ב יז). אך לדעת הפייטן, פירושה המקורי של האזהרה הוא כפשוטה, ולפיכך לולא זכה ל'כופר וחנינה', היה מתחייב מיתה מיידית, וכך היא גם דעת המדרש שהובא. 394 מלבי\"ם 395 שם 396 'בער' הוא אדם בהמי וחסר דעת, מלשון 'בעיר' = בהמה, כמו \"אֲנַחְנוּ וּבְעִירֵנוּ\" (במדבר כ ד); 'כסיל' הוא ההולך אחר תאוותו מחמת רשעות - מלבי\"ם על אתר. 397 כגון בעניין 'דבר שאינו מתכוון' (תלמוד בבלי, שבת נ., ועוד), ובעניין 'מלאכה שאינה צריכה לגופה' (שם קז:, ועוד). 398 שם, לג: 399 הסבר שיטתו הפנימית של רבי שמעון – על פי הרב דוד כהן ('הנזיר'), קול הנבואה, עמ' קמז 400 עמ' 99-98 401 רש\"י, שמות לב ל. בספר ישעיהו (מז יא) פירש באופן שונה, ש'כפרה' היא 'לשון קינוח וסילוק'; גם לפירוש זה הרעיון עומד בעינו, שכן גם אחרי הניקוי נשאר רושם מהחטא, וה'חנינה' מסירה אף אותו. 402 ויקרא ה ח 403 איוב לג כג-כד,ל"],[1,"s3","כְּהוֹשַׁעְתָּ גּוֹי מְצֻיָּן מְקַוִּים חֹפֶשׁ","– כשם שהושעת ממצרים את עם ישראל, שהיה מצויין = מסומן ונבדל, כגוי = עם, בפני עצמו, כפי שכתוב ב'הגדה של פסח': \"מְלַמֵּד שֶׁהָיוּ יִשְׂרָאֵל ¿מÀציּ»!ƒים שָׁם\". דבר זה התבטא בכך שלא שינו את שמותיהם, לשונם, ולבושם, אלא שמרו על ייחודיותם הלאומית, מתוך כך שהיו 'מְקַוִּים חוֹפֶשׁ' – מצפים לגאולה ולהיפרדותם מהמצרים. דֵּעָה כִּוְּנוּ לָבוּר (=לברור, לבחור) שְׁבִיעִי לְנֹפֶשׁ – על פי המסופר במדרש, שמשה יעץ לפרעה לתת לישראל יום מנוחה קבוע בשבוע כדי שלא ימותו מקושי העבודה, ומשפרעה קיבל את עצתו – בחר משה ביום השבת, וקבעו ליום מנוחה לישראל. אך ישנם כמה הבדלים בין המסופר במדרש לבין העולה מלשון הפיוט: לפי המדרש, משה הוא זה שבחר את יום השבת ליום המנוחה, ומתוך ידיעה שאכן יום זה הוא יום השבת, אותו שמרו האבות; לעומת זאת, מהפיוט נראה כי עם ישראל הוא זה שבחר את יום השבת, ולא מתוך ידיעה על מעלתו של היום (שהרי עדיין לא ניתנה להם התורה), אלא 'דֵּעָה כִּוְּנוּ' – הם מצידם בחרו יום אקראי, ודעתם זו היתה מכוונת למה שאכן ראוי היה להיות, שהיום שייבחר למנוחה יהיה יום השבת. על ידי סגולתו הפנימית של עם ישראל, הוא זיהה, באופן תת-מודע, את היום המתאים לו למנוחה. הערות 404 במדבר רבה, פרשה יג, אות כ; פסיקתא זוטרתי, שמות, פרק ו, פסוק ו 405 שמות רבה, פרשה א, אות כח"],[1,"s4","כְּהוֹשַׁעְתָּ הָעָם נִהַגְתָּ כַּצֹּאן לְהַנְחוֹת","– כשם שהושעת את ישראל מהמצרים שרדפו אחריהם ומפגעי המדבר, ונהגת אותם כרועה המנחה את צאנו, מגן עליו, ומטפל בכל צרכיו; על פי לשון הכתוב: \"וַיַּסַּע כּצּ…אן עמּוֹ , וי¿!הג≈ם כַּעֵדֶר בַּמִּדְבָּר. ויּ!¿≈חם לָבֶטַח וְלֹא פָחָדוּ, וְאֶת אוֹיְבֵיהֶם כִּסָּה הַיָּם\" (תהילים עח נב-נג). וְחֹק שַׂמְתָּ בְמָרָה עַל מֵי מְנוּחוֹת – על פי המסופר בכתוב: וַיָּבֹאוּ מָרָתָה, וְלֹא יָכְלוּ לִשְׁתֹּת מַיִם מִמָּרָה כִּי מָרִים הֵם, עַל כֵּן קָרָא שְׁמָהּ מָרָה. וַיִּלֹּנוּ הָעָם עַל מֹשֶׁה לֵּאמֹר: מַה נִּשְׁתֶּה? וַיִּצְעַק אֶל ה', וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. לדעת חז\"ל, ה'חֹק וּמִשְׁפָּט' שנתן הקב\"ה לישראל במרה הם שבע מצוות בני נח, ומצוות דינים, כיבוד אב ואם, ושבת – וזהו הקשר שבין מאורע זה לפיוט, העוסק בעניין השבת. רמב\"ן מפרש על דרך הפשט, שהכוונה היא לתוכחות מוסר ולקביעת סדרים חברתיים: שייסרם בחוקי המדבר, לסבול הרעב והצמא, לקרוא בהם אל ה', לא דרך תלונה. ומשפטים שיחיו בהם: לאהוב איש את רעהו, ולהתנהג בעצת הזקנים, והצנע לכת באהליהם בעניין הנשים והילדים, ושינהגו שלום עם הבאים במחנה למכור להם דבר, ותוכחות מוסר שלא יהיו כמחנות השוללים אשר יעשו כל תועבה ולא יתבוששו, וכעניין שציוה בתורה: \"כִּי תֵצֵא מַחֲנֶה עַל אֹיְבֶיךָ – וְנִשְׁמַרְתָּ מִכֹּל דָּבָר רָע\" (דברים כג י). 'עַל מֵי מְנוּחוֹת' – ליד מי מנוחות = מים צלולים, והם המים שמצאו במרה, שנמתקו על ידי הנס. טעם הדבר שמשה לימד את ישראל 'חֹק וּמִשְׁפָּט' דווקא 'עַל מֵי מְנוּחוֹת', רמוז בפסוק שלאחר מכן: וַיֹּאמֶר: אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךָ, וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה, וְהַאֲזַנְתָּ לְמִצְוֹתָיו, וְשָׁמַרְתָּ כָּל חֻקָּיו, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךָ, כִּי אֲנִי ה' רֹפְאֶךָ. משה משתמש בנס המתקת המים להמחיש באופן מציאותי לעם ישראל את הכדאיות שבשמירה על אותו החוק והמשפט שלימדם אז ועל שאר מצוות ה': כשם שהקב\"ה המתיק את המים המרים על ידי העץ שהשליך לתוכם משה, על אף שאין סיבה טבעית לכך שהעץ ימתיק את המים – כך גם שמירת מצוותיו מגינה על האדם מפגעים וממחלות, על אף שאין סיבה טבעית הנראית לעין שגורמת לכך. יסוד מוסרי זה, נקל לאדם להבינו בשכלו, אך כדי שהוא יהיה חי בליבו כנתון ריאלי וממשי, קיים צורך להמחיש זאת לעיניו במציאות. הערות 406 שמות טז, כג-כה 407 תלמוד בבלי, סנהדרין נו:. לדעה זו, מצוַת דינים אינה כלולה בשבע מצוות בני נח. 408 \"כי מים הנחים המה צלולים, מה שאין כן הרודפים, כי יגרשו מימיו רפש וטיט\" – מצודת ציון, תהילים כג ב."],[1,"s5","כְּהוֹשַׁעְתָּ זְבוּדֶיךָ","– עם ישראל, שבחרת אותם לך לזֶבֶד = חלק טוב, כמו שכתוב: \"כִּי יַעֲקֹב בָּחַר לוֹ יָהּ, יִשְׂרָאֵל לִסְגֻלָּתוֹ\" (תהילים קלה ו); בְּמִדְבַּר סִין בַּמַחֲנֶה – כשם שהושעת את ישראל בעת ששהו במדבר סין, בכך שהורדת להם מן בתוך המחנה – כך תושיענו ותספק לנו את מזוננו וצרכינו במשך השנה. חָכְמוּ וְלָקְטוּ בַּשִּׁשִּׁי לֶחֶם מִשְׁנֶה – ביום השישי, נהגו מדעת עצמם בחכמה, ולקטו 'לֶחֶם מִשְׁנֶה' – כמות מן כפולה, גם עבור יום השבת, ופי שיבואר בשורה הבאה. הערות 409 ראה להלן חלק ב, עמ' 77 410 הפייטן אינו סבור כדעת רש\"י (שמות טז כב), שפירש שהם לקטו את הכמות הרגילה והיא הוכפלה בכליהם בדרך נס, ואף לא כדעת 'אבן עזרא' (שם), שפירש שמשה הורה להם ללקוט כמות מן כפולה."],[1,"s6","סיכום","שורה זו היא המשך לקודמתה, ועוסקת בלקיטת ישראל כמות מן כפולה ביום השישי: כְּהוֹשַׁעְתָּ טְפוּלֶיךָ – ישראל, הדבקים בך, הוֹרוּ הֲכָנָה בְּמַדָּעָם – שהורו לעצמם, במדעם = מתוך דעתם ותבונתם האישית, להכין מן ביום השישי עבור השבת, מבלי שמשה הורה להם לעשות כן. כשנשיאי העדה ראו זאת, סברו שהעם עובר בכך על ציווי משה שלא להותיר מהמן ליום המחרת, וכשאמרו זאת למשה, השיב להם שציווי זה אינו חל על יום השבת: יִשַּׁר כֹּחָם וְהוֹדָה לָמוֹ רוֹעָם – משה, רועה ישראל, יישר את כוחם = חיזק את כוחם ואישר את מה שעשו, והודה למו = הסכים עמהם, כמו שכתוב: וַיֹּאמֶר אֲלֵהֶם: הוּא אֲשֶׁר דִּבֶּר ה': שַׁבָּתוֹן שַׁבַּת קֹדֶשׁ לַה' מָחָר, אֵת אֲשֶׁר תֹּאפוּ אֵפוּ, וְאֵת אֲשֶׁר תְּבַשְּׁלוּ בַּשֵּׁלוּ, וְאֵת כָּל הָעֹדֵף הַנִּיחוּ לָכֶם לְמִשְׁמֶרֶת עַד הַבֹּקֶר. [...] וַיֹּאמֶר מֹשֶׁה: אִכְלֻהוּ הַיּוֹם כִּי שַׁבָּת הַיּוֹם לַה', הַיּוֹם לֹא תִמְצָאֻהוּ בַּשָּׂדֶה. שֵׁשֶׁת יָמִים תִּלְקְטֻהוּ, וּבַיּוֹם הַשְּׁבִיעִי – שַׁבָּת, לֹא יִהְיֶה בּוֹ. משה לא הורה לעם ללקוט כמות כפולה, משום שאכן לא נצטווה לומר להם זאת, אלא שהקב\"ה תיאר לו שכך יהיה: \"וְהָיָה בַּיּוֹם הַשִּׁשִּׁי, וְהֵכִינוּ אֵת אֲשֶׁר יָבִיאוּ, וְהָיָה מִשְׁנֶה עַל אֲשֶׁר יִלְקְטוּ יוֹם יוֹם\" (שם שם ה). ייתכן שהמטרה בכך היתה שהם יעשו זאת דווקא מדעתם, כדי שבכך ירגישו יותר קשר וחיבור לשבת ולקדושתה; שכן, בכך שאדם מבצע פעולה מדעתו לצורך דבר מסויים, הוא מפתח בקרבו אחריות אישית על הדבר שעבורו הוא פועל, ומחזק את תחושת הקשר אליו. מאחר וראו בני ישראל שירדה כמות כפולה של מן, הבינו מדעתם שאין זה מכבוד השבת לצאת וללקוט בה מן, אלא יש להכין עבורה כבר ביום השישי, ולשם כך הוריד להם הקב\"ה כמות כפולה. לאחר מעשה, לימדם משה שלקיטת המן בשבת אסורה מן הדין, מחמת איסור 'הוצאה מרשות לרשות'. הערות 411 ראה לעיל עמ' 121 412 שמות טז, כג-כו 413 אור החיים שם, פסוק כב"],[1,"s7","כְּהוֹשַׁעְתָּ כֻּלְכְּלוּ בְּעֹנֶג מָן הַמְּשֻׁמָּר","– גם שורה זו ממשיכה בעניין המן; בני ישראל כולכלו על ידי הקב\"ה במן, ואף ביום השבת בו לא ירד, כולכלו ב'מָן הַמְּשֻׁמָּר' = ששמרוהו אצלם מאתמול; אף על פי שהמן ששמרו אנשים מהעם בימות החול, בניגוד לציווי משה – התקלקל, כמו שכתוב: \"וְלֹא שָׁמְעוּ אֶל מֹשֶׁה, וַיּוֹתִרוּ אֲנָשִׁים מִמֶּנּוּ עַד בֹּקֶר, וַיָּרֻם תּוֹלָעִים וַיִּבְאַשׁ\" (שם שם כ), המן ששמרו בשבת על פי ציווי משה – לֹא הָפַךְ עֵינוֹ וְרֵיחוֹ לֹא נָמָר – לא שינה את מראהו, וריחו לא התחלף, כמו שכתוב: \"וַיַּנִּיחוּ אֹתוֹ עַד הַבֹּקֶר כַּאֲשֶׁר צִוָּה מֹשֶׁה, וְלֹא הִבְאִישׁ, וְרִמָּה לֹא הָיְתָה בּוֹ\" (שם שם כד). הפייטן השתמש במילה 'עֹנֶג' ביחס למן שאכלו בשבת, על פי דברי המדרש, שבשבת המן היה משובח יותר. הערות 414 על פי לשון הכתוב: \"לֹא הָפַךְ הַנֶּגַע אֶת עֵינוֹ\" (ויקרא יג נה). 415 מלשון תמורה והחלפה, על פי לשון הכתוב: \"עַל כֵּן עָמַד טַעְמוֹ בּוֹ, וְרֵיחוֹ לֹא נָמָר\" (ירמיהו מח יא). 416 ילקוט שמעוני, בשלח, שט 417 'שיחה שלימה'"],[1,"s8","כְּהוֹשַׁעְתָּ מִשְׁפְּטֵי מַשְׂאֹת שַׁבָּת גָּמָרוּ","– שורה זו ממשיכה בעניין בני ישראל במדבר, שגמרו (=למדו) דיני נשיאת משא בשבת, דהיינו פרטי איסור הוצאה מרשות לרשות ואיסור נשיאת חפץ ארבע אמות ברשות הרבים, וקיימו דינים אלה: נָחוּ וְשָׁבְתוּ, רְשׁוּיוֹת וּתְחוּמִים שָׁמָרוּ – שמרו על הלכות 'רְשׁוּיוֹת' – הוצאה מרשות לרשות, ועל הלכות 'תְּחוּמִים' – שלא לצאת מחוץ ל'תחום שבת'. על אף שהאיסור לצאת מחוץ לתחום שבת של אלפיים אמה הוא מדרבנן, ולא נהג בתקופת דור המדבר, הפייטן נוקט כדעה לפיה קיים איסור 'תחום שבת' אף מן התורה, אלא שמדין התורה התחום המותר גדול יותר: שנים עשר מיל (000,24 אמה). הערות 418 ראה לעיל עמ' 169 419 כאמור בפיוט הקודם: \"הַקּוֹבַעַת אַלְפַּיִם תְּחוּם שַׁבָּת\". 420 תלמוד ירושלמי, עירובין, פרק ג, הלכה ד, ופרק ה, הלכה ד; משנה תורה לרמב\"ם, הלכות שבת, פרק כז, הלכה א"],[1,"s9","כְּהוֹשַׁעְתָּ סִינַי הָשְׁמְעוּ בְּדִבּוּר רְבִיעִי, עִנְיַן זָכוֹר וְשָׁמוֹר לְקַדֵּשׁ שְׁבִיעִי","– גם שורה זו ממשיכה בעניין אנשי דור המדבר, שהושמעו במעמד הר סיני בדיבור הרביעי: \"זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\" (שמות כ ח), ובעשר הדיברות שבפרשת ואתחנן כתוב: \"שָׁמוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\" (דברים ו יב) – וראה לעיל (עמ' 172-171) ביאור עניין זה בהרחבה."],[1,"s10","כְּהוֹשַׁעְתָּ פֻּקְּדוּ יְרִיחוֹ שֶׁבַע לְהַקֵּף","– כשם שהושעת את ישראל, שפוקדו (=נצטוו) על ידי הקב\"ה להקיף את יריחו במשך שישה ימים הקפה אחת בכל יום, וביום השביעי להקיפה שבע פעמים, ועזרת להם לכובשה, כן תושיענו ותעזרנו לגבור על אויבינו כיום; צָרוּ עַד רִדְתָּהּ בַּשַּׁבָּת לְתַקֵּף – ישראל צרו על יריחו, 'עַד רִדְתָּהּ' = עד שהצליחו לכובשה ביום השביעי, שלדעת חז\"ל חל בשבת; אז תקפו את העיר, כמתואר בכתוב: וַיְהִי בַּיּוֹם הַשְּׁבִיעִי, וַיַּשְׁכִּמוּ כַּעֲלוֹת הַשַּׁחַר וַיָּסֹבּוּ אֶת הָעִיר כַּמִּשְׁפָּט הַזֶּה שֶׁבַע פְּעָמִים, רַק בַּיּוֹם הַהוּא סָבְבוּ אֶת הָעִיר שֶׁבַע פְּעָמִים. וַיְהִי בַּפַּעַם הַשְּׁבִיעִית, תָּקְעוּ הַכֹּהֲנִים בַּשּׁוֹפָרוֹת; וַיֹּאמֶר יְהוֹשֻׁעַ אֶל הָעָם: הָרִיעוּ, כִּי נָתַן ה' לָכֶם אֶת הָעִיר. [...] וַיָּרַע הָעָם וַיִּתְקְעוּ בַּשֹּׁפָרוֹת, וַיְהִי כִשְׁמֹעַ הָעָם אֶת קוֹל הַשּׁוֹפָר וַיָּרִיעוּ הָעָם תְּרוּעָה גְדוֹלָה, וַתִּפֹּל הַחוֹמָה תַּחְתֶּיהָ, וַיַּעַל הָעָם הָעִירָה אִישׁ נֶגְדּוֹ, וַיִּלְכְּדוּ אֶת הָעִיר. כיבוש יריחו נעשה בשילוב של פעילות מצד ישראל ושל נס מצד הקב\"ה; ישראל הקיפו את יריחו במשך שבעה ימים כפי שנצטוו, ונפילת החומה – שאיפשרה בפועל את הכיבוש – היתה בנס. אופן כיבוש זה, שהוא הכיבוש הראשון שנעשה לאחר הכניסה לארץ, נועד ללמד על מהותו של תהליך הכיבוש כולו ושל חיי עם ישראל בארצו באופן כללי: אף על פי שמצוות כיבוש הארץ ויישובה, מתממשות על ידי פעולות חומריות – מלחמות, בניין, וחקלאות, יש בהן מימד של 'נס', של קדושה על-טבעית. פעולות אלו אצל ישראל שונות באופן מהותי מאותן פעולות עצמן אצל אומות העולם, שכן אצל ישראל גם מדרגת הטבע והחומר שייכת לקדושה. כיבוש יריחו, שנעשה בנס על-טבעי, מלמד שכל חיי המעשה של עם ישראל בארצו שייכים למדרגה שמעל הטבע, למדרגת הקדושה. זוהי גם הסיבה שהכיבוש נעשה דווקא בשבת, כפי שמציין הפייטן; בדומה לארץ ישראל, המשלבת קדושה וטבע, כך גם השבת: מצד עצמה, שייכת היא למדרגה העל-טבעית – 'מעין עולם הבא', אך היא משפיעה מקדושתה גם על ששת ימי המעשה. זאת, על ידי שהיא מזכירה לאדם \"כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ\" (שמות כ יא), ושמשום כך – גם פעולותיו החומריות במשך ימי המעשה, צריכות להעשות מתוך מטרה לרומם את עולם החומר ולקדשו, ולממש את המטרות האלוהיות לשמן הוא נברא, על ידי הכוונתו לייעודיו הנכונים. על פי זה יובן, שאותה 'הוראת שעה' שניתנה אז, להילחם בשבת על אף שכרוכות בכך פעולות שיש בהן איסור מלאכה – אינה מהווה סתירה לשמירת השבת; אדרבה, לשבת ולכיבוש הארץ עניין אחד – העלאת מדרגת החומר ושילובו במארג אחד עם הקדושה, כך שהיא תאיר ותשפיע עליו. בתור נקודת הפתיחה של הפעילות המעשית של ישראל בארץ, המהווה סמל לה, התיר כיבוש יריחו את איסורי השבת, גם בפועל ממש. לרעיון זה, של שילוב הנס עם הפעילות האנושית בכיבוש יריחו, גם פן מוסרי: ישראל הקיפו את יריחו שבעה ימים על פי סדר מפורט שנצטוו עליו, עם ארון הברית, הכוהנים, ותקיעה בשופרות; אך בפועל, מצד הטבע – פעולות אלו לא הועילו מאומה לכיבוש העיר, שנעשה בנס גלוי: חומת יריחו נבלעה באדמה – \"וַתִּפֹּל הַחוֹמָה תַּחְתֶּיהָ\". עם כניסתם של ישראל לארץ והתחלת חיי המעשה הטבעיים בה (בניגוד לשנים בהן היו במדבר, שאז החיים התבססו על ניסים, כגון המן, השליו, ובאר מִרְיָם), אירוע פתיחה זה של כיבוש יריחו מסמל את המסר שכל הפעולות המעשיות שיפעלו ישראל בכיבוש הארץ, בניינה, ופיתוחה החקלאי, הצלחתן תלויה בקב\"ה. כשם שבכיבוש יריחו ישראל עשו את המוטל עליהם, ועל ידי כך אירע הנס ונכבשה העיר, על אף שאין להקפות אלו יכולת מצד הטבע להפיל את החומה – כך גם בפעולות שמצד הטבע נראה שאכן הן הגורמות לתוצאה, יש לזכור כי מצד האמת אין הדבר כן; גם בפעולות אלו הקב\"ה הוא זה שיוצר את ההצלחה, ופעילותנו היא רק עשיית ההשתדלות המוטלת עלינו. \"וְאָמַרְתָּ בִּלְבָבֶךָ: כֹּחִי וְעֹצֶם יָדִי עָשָׂה לִי אֶת הַחַיִל הַזֶּה; וְזָכַרְתָּ אֶת ה' אֱלֹהֶיךָ כִּי הוּא הַנֹּתֵן לְךָ כֹּחַ לַעֲשׂוֹת חָיִל\" (דברים ח יז-יח). ייתכן, שזוהי הסיבה לכך שטקס הקפות יריחו התבצע באופן הדומה לעריכת מלחמה: המקיפים היו 'אנשי המלחמה', עם 'החלוץ' ו'המאסף', כשהם מלֻווים בארון הברית ובכוהנים שתוקעים בשופרות; דימיון זה עשוי לחזק אצל ישראל את המסר האמור, המשווה בין הקפות אלו לבין המלחמות הממשיות שנכונו להם בעתיד. על פי זה ניתן להסביר באופן נוסף את הקשר שבין כיבוש יריחו לבין השבת: כמבואר לעיל, השבת מבטאת הסתכלות פנימית ואמיתית על המציאות; בהסתכלות כזו רואים את יד ה' בכל פרט מפרטי הטבע, אף באלו שהיא נסתרת בהם. השבת, שהיא 'זִכָּרוֹן לְמַעֲשֶׂה בְרֵאשִׁית', מזכירה לנו כי כל עולם הטבע הסובב אותנו, ונראה לנו כמובן מאליו וכנתון תחת שליטתנו, הוא בריאתו של הקב\"ה ונתון לשליטתו הבלעדית. משום כך, השבת היא מקור הברכה וההצלחה של ימות השבוע; כשהאדם נפגש עם תוכנה של השבת, ולומד לייחס את פעולותיו למקורן האמיתי, ממילא הן קרובות יותר לאותו מקור, ויכולות לינוק ממנו יותר ברכה, כוח, והצלחה. הערות 421 מלשון 'לרדות', כמו בפסוק: \"וּבָנִיתָ מָצוֹר עַל הָעִיר אֲשֶׁר הִוא עֹשָׂה עִמְּךָ מִלְחָמָה, עַד רִדְתָּהּ\" (דברים כ כ). 422 תלמוד ירושלמי, שבת, פרק א, הלכה ח 423 יהושע ו טו-טז,כ 424 השלב הראשון בכל דבר עשוי ללמד על מהותו של כל ההמשך, כמבואר בדברי מהר\"ל מפראג (נר מצוה, עמ' טו, ובמקומות נוספים). 425 הר\"ן בדרשותיו (תחילת הדרוש העשירי) מסביר, שהפסוק: \"וְאָמַרְתָּ בִּלְבָבֶךָ: כֹּחִי וְעֹצֶם יָדִי עָשָׂה לִי אֶת הַחַיִל הַזֶּה\" נאמר באופן חיובי, כלומר: נכון הוא הדבר שכוחך עשה לך את 'הַחַיִל הַזֶּה', אך עליך לזכור שהקב\"ה הוא זה שנתן לך את אותו כוח שבו עשית חיל. 426 עמ' 190"],[1,"s11","כְּהוֹשַׁעְתָּ קֹהֶלֶת וְעַמּוֹ בְּבֵית עוֹלָמִים, רִצּוּךָ בְּחָגְגָם שִׁבְעָה וְשִׁבְעָה יָמִים","– כשם שהושעת את שלמה המלך, שנקרא 'קֹהֶלֶת', ואת עמו, בחנוכת בית המקדש שנקרא 'בֵּית עוֹלָמִים' – על שם כך שמאז שנבנה לא פסקה הקדושה ממקומו, כפי שאמר שלמה: \"בָּנֹה בָנִיתִי בֵּית זְבֻל לָךְ, מָכוֹן לְשִׁבְתְּךָ עוֹלָמִים\" (מלכים א' ח יג). כשהסתיימה מלאכת בניית הבית, חגגו את חנוכת המקדש במשך שבוע אחד מח' תשרי עד י\"ד בו, ושבוע נוסף של חג הסוכות, כמסופר בכתוב: וַיַּעַשׂ שְׁלֹמֹה אֶת הֶחָג בָּעֵת הַהִיא שִׁבְעַת יָמִים, וְכָל יִשְׂרָאֵל עִמּוֹ קָהָל גָּדוֹל מְאֹד מִלְּבוֹא חֲמָת עַד נַחַל מִצְרָיִם. וַיַּעֲשׂוּ בַּיּוֹם הַשְּׁמִינִי עֲצָרֶת, כִּי חֲנֻכַּת הַמִּזְבֵּחַ עָשׂוּ שִׁבְעַת יָמִים, וְהֶחָג שִׁבְעַת יָמִים. וּבְיוֹם עֶשְׂרִים וּשְׁלֹשָׁה לַחֹדֶשׁ הַשְּׁבִיעִי שִׁלַּח אֶת הָעָם לְאָהֳלֵיהֶם, שְׂמֵחִים וְטוֹבֵי לֵב עַל הַטּוֹבָה אֲשֶׁר עָשָׂה ה' לְדָוִיד וְלִשְׁלֹמֹה וּלְיִשְׂרָאֵל עַמּוֹ. בגמרא מבואר שגם ביום הכיפורים, שחל בשבוע הראשון, המשיכו ישראל בשמחת האכילה והשתייה, ולמדו את ההיתר לכך מ'קל וחומר': אם קרבנות הנשיאים שהוקרבו בשנים עשר הימים של חנוכת המשכן, דחו את השבת, על אף שקדושת המשכן היתה זמנית, וקרבנות אלו היו קרבנות יחיד – כל שכן שהקרבת קרבנות ציבור, במקדש, שקדושתו היא נצחית – תדחה את יום הכיפורים, שקדושתו קלה מקדושת השבת, ומותר להקריב את קרבנות חנוכת המקדש ולאוכלם. לאחר מעשה, היה ליבם נוקפם, שכן חששו שמא דווקא הקרבת קרבנות, שהיא 'צורך גבוה' = לצורך הקב\"ה, כביכול – דוחה את השבת, אך אכילה, שהיא 'צורך הדיוט' = לצורך האדם – אינה דוחה אף את יום הכיפורים. יצאה בת קול ואמרה להם: \"כולכם מזומנים לחיי העולם הבא\". 'בת קול' היא קול פנימי ששומע האדם מתוכו, כעין נבואה ורוח הקודש, \"והיא מדרגה למטה מן החזון והדיבור האלוהי\". באותו מעמד, כל ישראל שמעו מתוכם בת קול זו, שאישרה את האופן בו נהגו, והניחה את דעתם. על כך נאמר בפיוט: \" כּ¿הוֹשׁ¿ע»תּ קֹהֶלֶת וְעַמּוֹ בְּבֵית עוֹלָמִים\" – הושעת אותם מהמצוקה הנפשית שהיו שרויים בה מחמת החשש הנזכר, \" רƒצּוּךָ בְּחָגְגָם שִׁבְעָה וְשִׁבְעָה יָמִים\" – על אף שחגיגה זו כללה אכילה ביום הכיפורים, היא היתה רצויה לפני הקב\"ה. רבינו חננאל פירש שם: \"כולכם מזומנים לחיי העולם הבא – שלא נתכוונתם אלא למצווה\". ישראל חששו שמא אכילתם לא היתה בכוונה מוחלטת לשם שמיים, ולפיכך דאגו, שהרי דבר שהוא לצורך האדם אינו דוחה את יום הכיפורים; בת הקול הודיעה להם שכוונתם היתה טהורה דיה כדי שאכילתם עצמה תחשב 'צורך גבוה', וממילא לא היה בכך כל איסור או פגם בקדושת יום הכיפורים. מטרתה של התענית ביום הכיפורים היא שהאדם יתנתק מנטיותיו החומריות ויתעלה מעליהן; באותו מעמד של חנוכת המקדש, התעלו ישראל למדרגה כה גבוהה, עד שגם אכילתם היתה טהורה מנטיות חומריות והיתה כולה מתוך קדושה ושמחה של מצוה. כשנשמת האדם מתעלה והיא נמצאת קרובה למקורה האלוהי – גם כשהוא בא במגע עם דברים חומריים ופעולות גשמיות, הוא פוגש את הפן הטוב והאלוהי שבהם; ממילא, אותן פעולות נחשבת כ'צורך גבוה', כיוון שגם דרכן האדם מתקרב לקב\"ה. זוהי המדרגה אליה הגיעו ישראל בזמן חנוכת המקדש, מדרגה שבה גם תענוג גשמי כאכילה ושתייה היה עשוי לרומם אותם. משום כך, אכילתם היתה שוות ערך לקורבן ויכלה לדחות את יום הכיפורים, שהרי זהו תפקידו של הקורבן – לקרב את האדם לבוראו. הגמרא שם מקשה: מדוע אכן אכלו ישראל את בשר קרבנותיהם ביום הכיפורים, ולא הסתפקו בעצם הקרבתם? ומשיבה: \"אין שמחה בלא אכילה ושתייה\". אפילו שמחה כה גדולה ועליונה של חנוכת בית המקדש, אינה שלימה ללא אכילה ושתייה; וליתר דיוק: דווקא שמחה עליונה כזו, אינה שלימה מבלי שהיא כוללת בתוכה גם את רגשי הקודש שיכולים להתעורר בקרב האדם מתוך העונג הגופני. והנה האיש המתקדש בקדושת בוראו, אפילו מעשיו הגשמיים חוזרים להיות ענייני קדושה ממש. וסימנך: אכילת קודשים, שהיא עצמה מצוַת עשה, ואמרו זכרונם לברכה: \"כוהנים אוכלים ובעלים מתכפרים\" [...] כללו של דבר: עניין הקדושה הוא שיהיה האדם דבק כל כך באלוהיו עד שבשום מעשה אשר יעשה לא ייפרד ולא יזוז ממנו יתברך, עד שיותר יתעלו הדברים הגשמיים הנחשבים לאחד מתשמישיו, במה שהוא משתמש בהם, ממה שירד הוא מדבקותו ומעלתו בהשתמשו בדברים גשמיים [...] ואז יהיה כמלאך ה' ממש, וכל מעשיו – אפילו השפלים והגשמיים – כקורבנות ועבודות. הערות 427 דברי הימים ב' ז ח-י 428 תלמוד בבלי, מועד קטן ט. 429 לשון ספר הכוזרי, מאמר ג, פיסקה עג; וראה גם ב'מורה נבוכים', חלק ב, מאמר מב, ו'תוספות יום טוב' על יבמות, פרק ז, משנה ו. 430 על פי 'חתם סופר' על התורה, הפטרת פקודי 431 תורת כוהנים, פרק י, פסוק יז 432 מסילת ישרים, פרק כו; וראה עוד בעניין זה לעיל, עמ' 81-80"],[1,"s12","כְּהוֹשַׁעְתָּ שָׁבִים עוֹלֵי גוֹלָה לְפִדְיוֹם, תּוֹרָתְךָ בְּקָרְאָם בֶּחָג יוֹם יוֹם","– כשם שהושעת את השבים מגלות בבל ופדית אותם ממנה, וכן הושעת אותם ישועה רוחנית מאי ידיעתם את מצוות התורה, כשקראו בספר התורה בכל יום מימי חג הסוכות (כמבואר להלן), כך תושיע אף אותנו ישועה לאומית וישועה רוחנית – \"הָאֵר עֵינֵינוּ בְּתוֹרָתֶךָ, וְדַבֵּק לִבֵּנוּ בְמִצְוֹתֶיךָ, וְיַחֵד לְבָבֵנוּ לְאַהֲבָה וּלְיִרְאָה אֶת שְׁמֶךָ [...] וַהֲבִיאֵנוּ לְשָׁלוֹם מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ, וְתוֹלִיכֵנוּ קוֹמְמִיּוּת לְאַרְצֵנוּ\". במשך זמן גלות בבל, נשתכחה התורה מרבים מישראל, ולפיכך העולים שעלו עם עזרא ונחמיה לא ידעו אף את דיני התורה הבסיסיים ביותר, כגון הלכות המועדים. קריאת התורה שהנהיג אז עזרא הסופר, היתה עבורם לימוד ראשוני של דיני התורה, ולאחר שקראו בראש השנה על מצוות חג הסוכות, חגגו אותו בזמנו וקראו בתורה בכל יום מימי החג, כמאמר הכתוב: \"וַיִּקְרָא בְּסֵפֶר תּוֹרַת הָאֱלֹהִים יוֹם בְּיוֹם, מִן הַיּוֹם הָרִאשׁוֹן עַד הַיּוֹם הָאַחֲרוֹן, וַיַּעֲשׂוּ חָג שִׁבְעַת יָמִים\" (נחמיה ח יח). הערות 433 מתוך ברכת 'אהבת עולם' בתפילת שחרית"],[1,"s13","כְּהוֹשַׁעְתָּ מְשַׂמְּחֶיךָ בְּבִנְיַן שֵׁנִי הַמְחֻדָּשׁ","– כשם שהושעת את השבים מגלות בבל ממצבם הרוחני והלאומי הירוד, שנבע מחסרונו של מרכזם הרוחני – בית המקדש, בכך שסייעת להם לבנותו – כך תושיענו במהרה בבניין הבית השלישי. 'מְשַׂמְּחֶיךָ' – שגרמו לך שמחה, כביכול, בעבודתם ובשמחתם בבית המקדש. נוֹטְלִין לוּלָב כָּל שִׁבְעָה בַּמִּקְדָּשׁ – במשנה מבואר, כי מן התורה מצוַת נטילת הלולב נוהגת במשך כל ימי החג במקדש בלבד, ובשאר המקומות – רק ביום-טוב הראשון; לאחר חורבן בית שני, תיקן רבן יוחנן בן זכאי שהלולב יינטל בכל המקומות בכל ימי החג, מלבד בשבת, כזכר למקדש. בזמן גלות בבל לא היתה קיימת תקנה כזו, וכך שנים רבות לא יכלו ישראל ליטול לולב בכל שבעת הימים, אלא ביום הראשון בלבד. לאחר ששָבֵי הגולה בנו את 'בִּנְיַן שֵׁנִי הַמְחֻדָּשׁ', יכלו לקיים את המצוה שנמנעה מהם במשך שבעים שנה, וחזרו להיות 'נוֹטְלִין לוּלָב כָּל שִׁבְעָה', שהרי היו 'בַּמִּקְדָּשׁ'. הערות 434 סוכה, פרק ג, משנה יב"],[1,"s14","סיכום","לשם הבנת השורה הבאה יש להקדים, שמצוַת נטילת ערבה במקדש היא 'הלכה למשה מסיני', ובה מביאים ערבות באורך אחת עשרה אמות, זוקפים אותן סביב המזבח, ולאחר מכן נוטלים אותן ומקיימים את 'חיבוט הערבה'; הראשונים נחלקו מהו ה'חיבוט': לדעת רש\"י הוא נענוע הערבות, ולדעת הרמב\"ם – חבטת הערבות על הקרקע או על כלי. מדין התורה, מצוַת נטילת הערבה נוהגת בכל שבעת ימי החג, אך חכמים תיקנו שבשבת לא יקיימוה, אלא אם כן חל היום השביעי של החג בשבת, שאז מצוַת הערבה נוהגת גם ביום זה. הטעם לכך הוא, שחכמים ביטלו את מצוַת נטילת לולב בשבת, מחשש פן ישכחו ויטלטלוהו ברשות הרבים, ואילו מצוַת ערבה היתה נוהגת בשבת – מצוַת הלולב היתה נראית לעומתה כבעלת חשיבות מועטה, ואנשים היו נוטים לזלזל בה באופן כללי. משום כך, תיקנו חכמים שאף מצוַת הערבה לא תתקיים בשבת, מלבד ביום השביעי של החג, שהרי גם הלולב דוחה את השבת באחד מימי החג – ביום-טוב, ולפיכך לא יהיה בכך עדיפות של מצוַת הערבה על מצוַת הלולב. כְּהוֹשַׁעְתָּ חִבּוּט עֲרָבָה שַׁבָּת מַדְחִים – כשם שהושעת את ישראל בזמן בית המקדש, שהיו מקיימים בו את חיבוט הערבה, וכשחל היום השביעי בשבת היו 'מַדְחִים' (=דוחים) את השבת בחיבוט הערבה, דהיינו שקיימו מצוה זו על אף השבת, ובאותו מעמד גם היו: מֻרְבִּיּוֹת מוֹצָא לִיסוֹד מִזְבֵּחַ מַנִּיחִים – על פי האמור במשנה: \"מצוַת ערבה כיצד? מקום היה למטה מירושלים, ונקרא 'מוצא'. יורדים לשם ומלקטים משם מורביות של ערבה, ובאין וזוקפין אותן בצדי המזבח, וראשיהן כפופין על גבי המזבח\". 'מֻרְבִּיּוֹת' הן ענפים ארוכים, או עצים שלמים שנעקרו מהשורש. בגמרא נאמר שאת הערבות היו מניחים על גבי יסוד המזבח, שהוא בליטה סביב המזבח סמוך לרצפה, בגובה אמה ורוחב אמה; זאת, כדי שהערבות תהיינה גבוהות יותר וראשיהן יוכלו להיות כפופים על גבי המזבח בגובה אמה מעליו, על מנת לנאות את המראה. אנו מבקשים מהקב\"ה שכשם שהושיע את ישראל וענה לתפילות שנשאו בעת שקיימו את מצוַת הערבה – כך יושיע אף אותנו, למרות שאיננו יכולים לקיים מצוה זו, שעל ידה מושפעים לישראל ברכה וישועה. זוהי גם משמעות הבקשה: \"כְּהוֹשַׁעְתָּ ... כֵּן הוֹשַׁע נָא\" שבשורות הבאות, המתייחסות אף הן לעובדים במקדש, שעל ידי עבודתם השפיעו ברכה וישועה לישראל. הערות 435 כל הכתוב להלן, על פי תלמוד בבלי, סוכה מג:- מה. 436 סוכה מג: ד\"ה והביאום 437 משנה תורה, הלכות שופר סוכה ולולב, פרק ז, הלכה כב 438 וראה שולחן ערוך, אורח חיים, סימן תרסד, סעיף ד: \"וחובט בה על הקרקע או על הכלי פעמיים או שלוש. הגהת רמ\"א: ויש אומרים שצריך לנענע בה. ונהגו לעשות שתיהן: מנענעין בה ואחר כך חובטין אותה\". 439 מסכת סוכה, פרק ד, משנה ה 440 ספר הערוך, ערך 'מורביות' ב' 441 רש\"י, סוכה מג: ד\"ה מורביות, וראה רש\"ש שם יג. ד\"ה מצות"],[1,"s15","כְּהוֹשַׁעְתָּ בְּרַכּוֹת וַאֲרוּכּוֹת וּגְבוֹהוֹת מְעַלְּסִים","– שורה זו ממשיכה בעניין קיום מצוַת הערבה במקדש. בברייתא בגמרא נאמר שהערבות שנטלו במקדש היו \"רכות וארוכות וגבוהות אחת עשרה אמה, כדי שיהו גוחות על המזבח אמה\"; 'רַכּוֹת' – ולא יבשות וקשות, שאז ראשיהן לא יוכלו להתכופף, ו'אֲרוּכּוֹת' – שאף אם לא מצאו מורביות באורך אחת עשרה אמה, יביאו את הארוכות ביותר שמצאו, ולכתחילה צריך שתהיינה 'גבוהות אחת עשרה אמה'. יש גורסים בגמרא במקום 'רַכּוֹת' – 'רַבּוֹת', דהיינו שזקפו סביב המזבח מספר רב של מורביות. 'מְעַלְּסִים' = משמחים – את העם שנכח במעמד, ואף את הקב\"ה, כביכול, כמו שנאמר לעיל: \"כְּהוֹשַׁעְתָּ מְשַׂמְּחֶיךָ בְּבִנְיַן שֵׁנִי הַמְחֻדָּשׁ\". בִּפְטִירָתָן יֹפִי לְךָ מִזְבֵּחַ מְקַלְּסִים – כמתואר שם בהמשך המשנה: \"בשעת פטירתן מה הם אומרים? 'יופי לך מזבח, יופי לך מזבח!'\" – בסיום ההקפה, כשנפטרו (=נפרדו) מהמזבח והלכו לבתיהם, היו מקלסים (=משבחים) את המזבח בנוסח זה, כדי לחקוק בליבם את רושם המראה המרומם. הערות 442 תלמוד בבלי, סוכה מה. 443 שפת אמת על הש\"ס, שם 444 כך מופיע בנוסח הגמרא שלפנינו; בחידושי הריטב\"א ובפסקי הרי\"ד שם, הגירסה היא: 'רַכּוֹת', וכן הגיה שם מהר\"ב רנשבורג. 445 מלשון עליזות ועליצות - מפרשים על איוב לט יג"],[1,"s16","כְּהוֹשַׁעְתָּ מוֹדִים וּמְיַחֲלִים וְלֹא מְשַׁנִּים, כֻּלָּנוּ אָנוּ לְיָהּ וְעֵינֵינוּ לְיָהּ שׁוֹנִים","– על פי תיאור המשנה את המעמד שהתקיים במקדש לאחר שמחת בית השואבה: \"הגיעו לשער היוצא ממזרח, הפכו פניהם למערב ואמרו: \"אבותינו שהיו במקום הזה 'אֲחֹרֵיהֶם אֶל הֵיכַל ה' וּפְנֵיהֶם קֵדְמָה וְהֵמָּה מִשְׁתַּחֲוִיתֶם קֵדְמָה לַשָּׁמֶשׁ' (יחזקאל ח טז), ואנו – לְיָהּ עינינו. רבי יהודה אומר: היו שונין [=אומרים פעמיים], ואומרין: אנו לְיָהּ, וּלְיָהּ עינינו\". בגמרא מבואר שהנוסח המלא לדעת רבי יהודה הוא: \"ואנו ליה מודים , ועינינו ליה מייחלות \". הפייטן נקט כאן כדעת רבי יהודה, שהעם היו 'מוֹדִים וּמְיַחֲלִים': 'אָנוּ לְיָהּ' – מודים על העבר, 'וְעֵינֵינוּ לְיָהּ'– בייחול ובתקווה על העתיד; 'וְלֹא מְשַׁנִּים' – לא משנים את אמונתם בקב\"ה כמו אבותיהם בימי בית ראשון שהשתחוו לשמש. הערות 446 מסכת סוכה, פרק ה, משנה ד 447 תלמוד בבלי שם, נג: 448 סידור 'בית יעקב'"],[1,"s17","כְּהוֹשַׁעְתָּ יֶקֶב מַחֲצָבֶיךָ סוֹבְבִים בְּרַעֲנָנָה, רוֹנְנִים אֲנִי וָהוּ הוֹשִׁיעָה נָּא","– שורה זו חוזרת לעניין מצוַת הערבה במקדש, בה היו זוקפים סביב המזבח מורביות של ערבה רעננה, ו'רוֹנְנִים' (=מתפללים): 'אני וָהוּ הושיעה נא', כדעת רבי יהודה במשנה: \"בכל יום מקיפין את המזבח פעם אחת ואומרים: \"אָנָּא ה' הוֹשִׁיעָה נָּא, אָנָּא ה' הַצְלִיחָה נָא\" (תהילים קיח כה). רבי יהודה אומר: \"אני וָהוּ הושיעה נא\". כאמור לעיל, ישנה דעה בגמרא שהכוהנים היו מקיפים את המזבח בהליכה כשהערבות בידיהם, ואף זה כלול במשמעות הביטוי: 'סוֹבְבִים בְּרַעֲנָנָה'. המזבח מכונה 'יֶקֶב מַחֲצָבֶיךָ', על פי דרשת התוספתא: \"'וַיִּבֶן מִגְדָּל בְּתוֹכוֹ, וְגַם יֶקֶב חָצֵב בּוֹ' (ישעיהו ה ב) – 'וַיִּבֶן מִגְדָּל בְּתוֹכוֹ' – זה היכל, 'יֶקֶב חָצֵב בּוֹ' – זה מזבח\", ופירשו ה'תוספות': \"וקרי [=וקרא] למזבח 'יֶקֶב', לפי שמנסכין עליו את היין שמוציאין מן היקבים\". ניתן גם להסביר, שהמזבח מכונה כך מכיוון שהוא המקור הרוחני של הברכה; כשם שהיקב הוא מקור היין, המביא שמחה לעולם, כך המזבח משפיע ברכה, הצלחה, ושמחה, לעולם כולו. משום כך השתמש כאן הפייטן בכינוי זה למזבח, שכן על ידי הקפת המזבח בערבות, ובאמצעות התפילות שהתפללו אז – \"רוֹנְנִים: אֲנִי וָהוּ הוֹשִׁיעָה נָּא\" – הקב\"ה השפיע לָעולם טובות אלו. 'מַחֲצָבֶיךָ' הם ה'שיתים' = נקבים ש'נחצבו' בתוך המזבח בפינתו הדרום-מערבית, מגגו עד תחתיתו, ולתוכם היו מנסכים את יינות הנסכים. לדעה אחת בגמרא, השיתים הסתיימו בחלל תת-קרקעי שבו הצטברו יינות הנסכים, ולדעה אחרת בגמרא השיתים הגיעו עד התהום, ונבראו מששת ימי בראשית, וכך נראה מלשון הפיוט: 'מַחֲצָבֶיךָ' – הקב\"ה הוא החוצב. הערות 449 כמו (תהילים קמב ז) \"הַקְשִׁיבָה אֶל רִנָּתִי כִּי דַלּוֹתִי מְאֹד\", ועוד. 450 מסכת סוכה, פרק ד, משנה ה. תפילה זו פורשה לעיל, עמ' 150-148 451 מסכת מעילה, פרק א, הלכה ח 452 סוכה מט. ד\"ה ויטעהו"],[1,"s18","סיכום","הערבה מכונה כאן 'רַעֲנָנָה', לא רק מפני שאכן ערבה יבשה פסולה למצוַה, אלא גם משום שהרעננות הוא מאפיין מהותי של הערבות, של ארבעת המינים, ושל חג הסוכות בכלל. בימי הדין שבראשית השנה, האדם שרוי במצב של יראה וכובד ראש, הגורמים במידה מסויימת לצמצום נפשי ולהתכנסות פנימית; זהו בסיס הכרחי לשנה העומדת בפתח ולהתנהלות האדם בה מתוך ביקורת עצמית ותשומת לב למצבו הרוחני. אך כדי לאזן את ההרגשה הנפשית, בסוכות אנו מדגישים את הצד ההפוך, שאף הוא בסיס הכרחי לעבודת ה' במשך השנה כולה: התרחבות הנפש מתוך שמחה, רעננות, וחיבור אל הטבע. הדבר מתבטא בכך שאנו יוצאים מהבית – המבטא את הקביעות והצמצום, אל החוץ והמרחב, דרים שם בסוכה המסוככת בגידולי קרקע טבעיים, ומתפללים בבית הכנסת – או, בזמן הבית – בבית המקדש, כשבידינו צמחים רעננים. וכך נאמר במדרש: \"תִּכָּתֶב זֹאת לְדוֹר אַחֲרוֹן, וְעַם נִבְרָא יְהַלֶּל יָהּ\" (תהילים קב יט) – אלו הדורות שחייבין במעשיהם הרעים, ובאין ועושין תשובה ומתפללין לפניך בראש השנה וביום הכיפורים. ולפי שהם מחדשים את מעשיהם – הקב\"ה בורא אותם ברייה חדשה. ומה להם לעשות? יש להם ליטול אתרוגיהן בידיהם, ולולביהן וערבי נחל והדסים, להלל אותך; הוֵי אומר: \"וְעַם נִבְרָא יְהַלֶּל יָהּ\". \"וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן\" – הדא הוא דכתיב: \"יַעֲלֹז שָׂדַי וְכָל אֲשֶׁר בּוֹ\" (תהילים צו יב); \"יַעֲלֹז שָׂדַי\" – זה העולם, [...] \"וְכָל אֲשֶׁר בּוֹ\" – אלו הבריות [...]. \"אָז יְרַנְּנוּ עֲצֵי הַיָּעַר\" (דברי הימים א' טז לג) – אמר רבי אחא: [...] \"עֲצֵי הַיָּעַר\" – אלו אילנות שעושין פירות, ו\"כָּל עֲצֵי יָעַר\" (תהילים שם) – אלו אילנות שאינן עושין פירות. לפני מי? \"לִפְנֵי ה'\", למה? \"כִּי בָא\" – בראש השנה וביום הכיפורים, מה לעשות? \"יִשְׁפֹּט תֵּבֵל בְּצֶדֶק וְעַמִּים בְּמֵישָׁרִים\" (שם צח ט). לאחר ימי הדין, בהם ישראל זוכו ונוקו מעוונותיהם, הם כביכול נבראים מחדש, ומתחדשים ומתרעננים יחד עם העולם כולו; ההתחדשות היא החזרה למצב הטבעי , שבו האדם נקי וזך, והחטאים אינם מהווים מחיצה בינו לבין בוראו. מתוך מצב זה, עם ישראל עושה את הפעולה הטבעית לו ביותר: מהלל את הקב\"ה. על ידי נטילת ארבעת המינים, מצרף הוא להילולו גם את עולם הטבע, ובנענועו בהם – כאילו נופח בתוכם נשמת חיים, עד שהם מתפללים ומהללים עימו; כך הבריאה המתחדשת כולה, על שני רבדיה: האדם והצומח, אומרת שירה לפני בוראה בטבעיות וברעננות, מתוך שמחת התחדשותה. רעיון זה עולה אף מבין השיטין של לשון הגמרא, בה אגודת ארבעת המינים מכונה 'הושענא', כביכול בעצם מציאותה ביד המתפלל הרי היא אומרת \"הוֹשַׁע נָא\". גם מדברי התלמוד הירושלמי, בו פְּסוּל 'יבש' בארבעת המינים נלמד מהפסוק: \"לֹא הַמֵּתִים יְהַלְלוּ יָהּ\" (תהילים קטו יז) – עולה מבט על ארבעת המינים כישויות עצמאיות המהללות את הקב\"ה יחד עם האדם. רעיון זה מתבטא גם בדברי המדרש, המשווה כל אחד מארבעת המינים לאחד מאברי האדם: לולב – לעמוד השדרה, אתרוג – ללב, הדס – לעין, וערבה – לפה. אגודת ארבעת המינים היא כעצם חי ה עומד לפני ה', רואה את המציאות עליה יש להתפלל ולהודות, ומודה ומתפלל לקב\"ה ב פיו , מתוך קירות ליבו . היא הנציג של עולם הצומח והטבע בבית המקדש ובבית הכנסת, ועל ידי נטילתה – האדם מתאחד עם עולם הטבע בעמידתו לפני ה'. על האדם לראות מעין הזדהות עם המינים שבידו, לקלוט מהם תחושת רעננות וטבעיות, ובכך להרחיב את כוחות נפשו ולהתפלל מתוך שמחה טבעית. הטבע הוא תוצר ישיר של הקב\"ה, וכשהאדם נחשף לטבע ומתחבר אליו, ממילא הוא קרוב יותר בהרגשתו לקב\"ה – מייצר הטבע, והרגש הטבעי והעמוק ביותר שבנפשו – המשיכה לקרבת אלוהים, עולה אל פני השטח ופועל בקרבו את פעולתו. מזמור סה בספר תהילים מתאר שני שלבים אלו. בתחילתו: את התפילה, היראה, וכפרת העוונות: שֹׁמֵעַ תְּפִלָּה, עָדֶיךָ כָּל בָּשָׂר יָבֹאוּ. דִּבְרֵי עֲוֹנֹת גָּבְרוּ מֶנִּי, פְּשָׁעֵינוּ אַתָּה תְכַפְּרֵם.[...] נוֹרָאוֹת בְּצֶדֶק תַּעֲנֵנוּ אֱלֹהֵי יִשְׁעֵנוּ, מִבְטָח כָּל קַצְוֵי אֶרֶץ וְיָם רְחֹקִים. מֵכִין הָרִים בְּכֹחוֹ, נֶאְזָר בִּגְבוּרָה. מַשְׁבִּיחַ שְׁאוֹן יַמִּים, שְׁאוֹן גַּלֵּיהֶם, וַהֲמוֹן לְאֻמִּים, וַיִּירְאוּ יֹשְׁבֵי קְצָוֹת מֵאוֹתֹתֶיךָ. ולאחר מכן, את שלב פריחת הטבע ושירתו: פָּקַדְתָּ הָאָרֶץ וַתְּשֹׁקְקֶהָ, רַבַּת תַּעְשְׁרֶנָּה, פֶּלֶג אֱלֹהִים מָלֵא מָיִם, תָּכִין דְּגָנָם כִּי כֵן תְּכִינֶהָ. תְּלָמֶיהָ רַוֵּה, נַחֵת גְּדוּדֶיהָ, בִּרְבִיבִים תְּמֹגְגֶנָּה, צִמְחָהּ תְּבָרֵךְ. עִטַּרְתָּ שְׁנַת טוֹבָתֶךָ, וּמַעְגָּלֶיךָ יִרְעֲפוּן דָּשֶׁן. יִרְעֲפוּ נְאוֹת מִדְבָּר, וְגִיל גְּבָעוֹת תַּחְגֹּרְנָה. לָבְשׁוּ כָרִים הַצֹּאן, וַעֲמָקִים יַעַטְפוּ בָר, יִתְרוֹעֲעוּ אַף יָשִׁירוּ. הערות 453 מדרש תהילים, מזמור קב, אות ג 454 ויקרא רבה, פרשה ל, אות ד 455 מסכת סוכה, פרק ג, הלכה א 456 ויקרא רבה, שם, אות יד 457 ראה בדברי 'ספר החינוך' (מצוה שכד): \"וידוע מצד הטבע, כי ארבעה המינים כולם [יחד] - משמחי לב רואיהם\". 458 פסוקים ג-ט 459 פסוקים י-יד"],[1,"s19","כְּהוֹשַׁעְתָּ חֵיל זְרִיזִים מְשָׁרְתִים בִּמְנוּחָה","– כשם שהושעת את חיל הכוהנים, שהם זריזים, המשרתים במקדש הנקרא 'מְנוּחָה', על פי לשון הכתוב: \"כִּי בָחַר ה' בְּצִיּוֹן, אִוָּהּ לְמוֹשָׁב לוֹ; זֹאת מְנוּחָתִי עֲדֵי עַד, פֹּה אֵשֵׁב כִּי אִוִּתִיהָ\" (תהילים קלב יג-יד). המילה 'מְנוּחָה' עשויה להתפרש גם ככינוי ליום השבת, בו הם הקריבו קָרְבַּן שַׁבָּת כָּפוּל – לעומת כל יום מימות השבוע, בו היו מקריבים שני כבשים לקורבן התמיד, אחד בבוקר ואחד בערב, בשבת היו מכפילים את מספר הכבשים ומוסיפים עוד שניים לקורבן המוסף; עוֹלָה וּמִנְחָה – קורבנות אלו – המוסף והתמיד – הם קורבנות 'עוֹלָה', ויחד עמהם, כמו עם כל קורבן, מביאים גם 'מִנְחָה', כמאמר הכתוב: \"וּבְיוֹם הַשַּׁבָּת שְׁנֵי כְבָשִׂים בְּנֵי שָׁנָה תְּמִימִם, וּשְׁנֵי עֶשְׂרֹנִים סֹלֶת ƒמ!¿»חה בְּלוּלָה בַשֶּׁמֶן וְנִסְכּוֹ. ע…לת שׁבּת בְּשַׁבַּתּוֹ, עַל עֹלַת הַתָּמִיד וְנִסְכָּהּ\" (במדבר כח ט-י). בניגוד לקורבנות המוסף של המועדים, בהם מקריבים שבעה כבשים ובהמות נוספות לעולה, ושעיר נוסף לחטאת – מוסף השבת הוא שני כבשים בלבד; בטעם הדבר כתב רבי עובדיה ספורנו: הנה במוסף השבת אין בו קורבן חטאת כלל, כי אם שני כבשים לכפל התמיד, להיות בו לחם משנה למזבח; להורות על מעלת השבת בברכה וקידוש על כל שאר הימים. עניינו של מוסף השבת אינו להוסיף, אלא להכפיל; כשם שבשבת יש לאדם 'נשמה יתירה', ובסעודות השבת בוצעים על לחם משנה, כך גם בקורבן המוסף, המבטא את עניינו של היום, באות לידי ביטוי ברכתו וקדושתו המיוחדות של יום השבת, באמצעות ההכפלה. הערות 460 ראה תלמוד בבלי, חולין קכג: \"כוהנים זריזין הם\". 461 פעל באיטליה (ר\"מ-ש\"י בקירוב), חיבר פירוש לחומש ולספרים נוספים מהתנ\"ך, פירוש לפרקי אבות, ואת הספר הפילוסופי 'אור עמים'. 462 מאמר 'כוונות התורה', מהדורת קופרמן, פרק יב"],[1,"s20","כְּהוֹשַׁעְתָּ לְוִיֶּךָ עַל דּוּכָנָם לְהַרְבָּת, אוֹמְרִים מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת","– כשם שהושעת את הלוויים כשעמדו על דוכנם להרבות בשיר; ה'דוכן' הוא שלוש המדרגות שבין 'עזרת כוהנים' ל'עזרת ישראל', ועליהן היו עומדים הלויים ושרים ומנגנים בעת הקרבת הקורבנות. בשבת – שהוזכרה בשורה הקודמת – היו אומרים את המזמור: 'מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת' (תהילים צב). הערות 463 מסכת מידות, פרק ב, משנה ו, כדעת רבי אליעזר בן יעקב; משנה תורה לרמב\"ם, הלכות בית הבחירה, פרק ו, הלכה ג 464 ראה לעיל עמ' 191-190"],[1,"s21","כְּהוֹשַׁעְתָּ נִחוּמֶיךָ בְּמִצְוֹתֶיךָ תָּמִיד יִשְׁתַּעַשְׁעוּן","– כשם שהושעת במשך הדורות את ישראל, המתנחמים מצרותיהם בהשתעשעותם בקיום מצוותיך ובלימוד הלכותיהן, כן הושע נא את ישראל שבדור זה, וּרְצֵם – רצה בהם, ועבודתם אותך תעלה לפניך לרצון, וְהַחֲלִיצֵם – תן בהם כוח כמו ליוצאים לקרב, מלשון: \"חֲלוּצֵי צָבָא\" (במדבר לא ה), וכן: \"וְעַצְמֹתֶיךָ יַחֲלִיץ\" (ישעיהו נח יא); בְּשׁוּבָה וָנַחַת יִוָּשֵׁעוּן – על פי לשון הכתוב: \"כִּי כֹה אָמַר אֲדֹנָי יֱהֹוִה קְדוֹשׁ יִשְׂרָאֵל: בְּשׁוּבָה וָנַחַת תִּוָּשֵׁעוּן, בְּהַשְׁקֵט וּבְבִטְחָה תִּהְיֶה גְּבוּרַתְכֶם\" (שם ל טו); אנו מתפללים לזכות לישועה מבלי להזדקק למלחמות, אלא 'בְּשׁוּבָה וָנַחַת' = \"עניין הַשְׁקֵט ומרגוע, וכן: 'נַפְשִׁי יְשׁוֹבֵב' (תהילים כג ג)\". הביטוי 'וּרְצֵם וְהַחֲלִיצֵם' מקביל לבקשה הנאמרת בשבת בברכת המזון: \"רְצֵה וְהַחֲלִיצֵנוּ ה' אֱלֹהֵינוּ בְּמִצְוֹתֶיךָ, וּבְמִצְוַת יוֹם הַשְּׁבִיעִי הַשַּׁבָּת הַגָּדוֹל וְהַקָּדוֹשׁ הַזֶּה\"; אנו מבקשים שבזכות שמירתנו את השבת, ה' ירצה בנו, יחזקנו ויאמצנו. בחתימת פיוט זה, העוסק בעניינה של השבת, אנו מתפללים שבזכות שמירתנו אותה נזכה במהרה לישועה העתידה, לא מתוך צרות של חבלי משיח, אלא בשובה ונחת. כך מסתיימת גם בקשה זו בברכת המזון: \"וְהַרְאֵנוּ ה' אֱלֹהֵינוּ בְּנֶחָמַת צִיּוֹן עִירֶךָ, וּבְבִנְיַן יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ, כִּי אַתָּה הוּא בַּעַל הַיְשׁוּעוֹת וּבַעַל הַנֶּחָמוֹת\". הערות 465 שורה זו היתה צריכה להיות מנוסחת כך: \"כְּהוֹשַׁעְתָּ נִחוּמֶיךָ בְּמִצְוֹתֶיךָ תָּמִיד יִשְׁתַּעַשְׁעוּן - כֵּן הוֹשַׁע נָא, וּרְצֵם וְהַחֲלִיצֵם, בְּשׁוּבָה וָנַחַת יִוָּשֵׁעוּן\", שהרי 'וּרְצֵם וְהַחֲלִיצֵם' היא בקשה נוספת ואינה המשך ל'כְּהוֹשַׁעְתָּ' כמו בשאר שורות הפיוט; אך כדי לא לשנות שורה זו מחברותיה, בחר הפייטן לנסחה כבפנים. 466 'מצודת ציון' על אתר"],[1,"s22","כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב וְהוֹשִׁיעָה נָּא.","כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי יְשׁוּעוֹת אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא – שורות אלו אינן חלק מהפיוט: השורה הראשונה לקוחה מסוף הפיוט 'כְּהוֹשַׁעְתָּ אֵלִים', הנאמר בכל יום לאחר הפיוט המיוחד לו, ובשבת הוא מוחלף בפיוט זה, שנתחבר בתקופה מאוחרת יותר. אך כדי לא לוותר לגמרי על אותו פיוט קדום – שובצה כאן השורה החותמת אותו. השורה השנייה לקוחה מהפיוט 'כְּהוֹשַׁעְתָּ אָב הֲמוֹן' (אמירתו אינה נהוגה כיום ברוב הקהילות), שחובר על ידי רבי שמואל החסיד בן רבי קלונימוס הזקן, ושמו רמוז בה: \" שׁ וֹמְרֵי ƒמ צְוֹת ו¿ חוֹכֵי יְשׁוּעוֹת ≈אל לְמוֹשָׁעוֹת\"; היא נאמרת גם בשאר ימי החג לאחר הפיוט 'כְּהוֹשַׁעְתָּ אֵלִים' – ראה שם ביאור שתי שורות אלו, וכן ביאור הפסוקים הנאמרים לאחריהן (עמ' 163-161). הערות 467 מראשוני חוג 'חסידי אשכנז' (חי סביב שנת ד'תת\"ק), כיהן כראש ישיבה בשפיירא ועסק בעיקר בתורת הנסתר. בנו הוא רבי יהודה החסיד, מחבר 'ספר חסידים'."],[1,"s23","סיכום","בפיוט זה ביקשנו על ישועות בתחומי חיינו השונים, בדומה לישועות שפעל הקב\"ה בעבר: אדם הראשון נושע בזכות השבת מהמיתה שהיתה ראויה לבוא עליו בעקבות האכילה מעץ הדעת טוב ורע, ואף אנו מתפללים להגנה על חיינו מפגעי הזמן, לסליחה, ולתיקון מערכת היחסים שביננו לבין הקב\"ה. עם ישראל נושע ממצרים, ואף אנו מתפללים להיות עם חופשי בארצנו, ללא שיעבוד לאומות העולם ולרצונותיהן. עם ישראל הונהג כצאן על ידי הקב\"ה ביציאתו ממצרים, נושע מפגעי המדבר 'הַגָּדוֹל וְהַנּוֹרָא הַהוּא' (דברים א יט), ומאיום הרעב, על ידי ירידת המן – ואף אנו מתפללים להינצל מכל פגע ולסיפוק צרכינו הכלכליים ברווח ובנחת. יהושע ועמו זכו לישועה ולניצחון בכיבוש יריחו, שהיתה \"סֹגֶרֶת וּמְסֻגֶּרֶת מִפְּנֵי בְּנֵי יִשְׂרָאֵל, אֵין יוֹצֵא וְאֵין בָּא\" (יהושע ו א), ולא ניתן היה לכובשה בדרך הטבע, ואף אנו מתפללים לישועה ולניצחון על אויבינו. קהלת ועמו נושעו בחנוכת בית המקדש מהמצוקה הנפשית שנגרמה מאותו חשש פן לא נהגו כשורה בכך שלא התענו ביום הכיפורים, ואף אנו מתפללים גם לישועה מסוג זה – לרוגע נפשי ותחושת ביטחון בדרכנו בעבודת ה'. עולי הגולה נושעו ונפדו מעול הגלות, חזרו לשמירת התורה והמצוות, ובנו את 'בִּנְיַן שֵׁנִי הַמְחֻדָּשׁ' – ואף אנו מתפללים להיוושע מעול הגויים, לראות בתשובתו השלימה של עם ישראל כולו, ולזכות במהרה לבניין הבית השלישי. המאורעות בפיוט מסודרים על פי סדרם הכרונולוגי: אדם הראשון, שיעבוד מצרים והיציאה ממנה, החנייה במרה, ירידת המן, ומעמד הר סיני. לאחר הכניסה לארץ: כיבוש יריחו, חנוכת בית ראשון, השיבה מגלות בבל, בנין בית שני, והעבודה בו. בכמה שורות בפיוט מופיע עניין הסגולה הפנימית שבישראל ובאדם: \"כְּהוֹשַׁעְתָּ אָדָם יְצִיר כַּפֶּיךָ לְגוֹנְנָה, בְּשַׁבַּת קֹדֶשׁ הִמְצֵאתוֹ כּוֹפֶר וַחֲנִינָה\" – מחמת ראיית נקודת הטוב שבתוככי האדם, שאינה נפגמת מהחטא; \"דֵּעָה כִּוְּנוּ לָבוּר שְׁבִיעִי לְנֹפֶשׁ\" – מכוח הסגולה הפנימית שבהם, שזיהתה את קדושתו של יום השבת, וכך בררו לעצמם באופן תת-מודע את השבת ליום המנוחה השבועי שאישר להם פרעה; \"חָכְמוּ וְלָקְטוּ בַּשִּׁשִּׁי לֶחֶם מִשְׁנֶה ... הוֹרוּ הֲכָנָה בְּמַדָּעָם, יִשַּׁר כֹּחָם וְהוֹדָה לָמוֹ רוֹעָם\" – גם בזה הצליחו ישראל לכוון מעצמם לרצון ה', וליבם הורה להם כי עבור השבת יש להכין מן מראש; \"קֹהֶלֶת וְעַמּוֹ בְּבֵית עוֹלָמִים, רִצּוּךָ בְּחָגְגָם שִׁבְעָה וְשִׁבְעָה יָמִים\" – גם אז, עם ישראל כולו הבין מדעתו, מנקודת האמת שבפנימיותו, שהאופן הנכון להעביר את אותו יום הכיפורים הוא דווקא על ידי שמחת אכילה ושתייה. מלבד דרשת ה'קל וחומר' ההלכתית שהתירה את הדבר, ההיתר התבסס, כפי שנתבאר לעיל, על ההנחה ש\"אין שמחה בלא אכילה ושתייה\" – הנחה הנובעת מהכרה פנימית בערכה העליון של אותה שמחה מיוחדת. מכוח סגולה פנימית זו של ישראל, העומדת תמיד בטהרתה בקרבו של כל יהודי באשר הוא, אנו מתפללים לישועה ולגאולה השלימה; אף אם איננו ראויים לכך מצד מעשינו – הרי שסגולתנו הפנימית כעם ה' מצדיקה זאת. סגנון הבקשה: \"כְּהוֹשַׁעְתָּ ... כֵּן הוֹשַׁע נָא\" אין עניינו, כמובן, 'להזכיר' לקב\"ה שהוא יכול לעשות זאת, אלא לקבוע בתודעת המתפלל – קודם שהוא ניגש לתוכן הבקשה עצמה – שאכן הקב\"ה הוא בעל היכולת הבלעדית לקיים את מבוקשו. על מנת לחזק הכרה זו, ולהמירה מאמונה שכלית גרידא להרגשה ברורה ומוחשית, אנו מזכירים ומציירים בדעתנו מאורעות שאירעו לאורך ההיסטוריה, ואת הישועות השונות שפעל בהם הקב\"ה. הערות 468 נושא זה התבאר באריכות לעיל, עמ' 135"],[1,"n390","הערה 390","(ד'תת\"כ-ד'תת\"צ, בקירוב) נין אחיו של רבינו גרשום מאור הגולה, כיהן כראש ישיבה בוורמייזא, וחיבר מספר פיוטים, ביניהם ידועה הקינה 'אבל אעורר' לתשעה באב, על מסע הצלב בשנת ד'תתנ\"ו."],[2,"piyut","נוסח הפיוט","הוֹשַׁע נָא לְמַעַן אֲמִתָּךְ. לְמַעַן לִמּוּדָךְ. לְמַעַן בְּרִיתָךְ. לְמַעַן מַלְכוּתָךְ. לְמַעַן גָּדְלָךְ וְתִפְאַרְתָּךְ. לְמַעַן נִצְחָךְ. לְמַעַן דָּתָךְ. לְמַעַן סוֹדָךְ. לְמַעַן הוֹדָךְ. לְמַעַן עֻזָּךְ. לְמַעַן וִעוּדָךְ. לְמַעַן פְּאֵרָךְ. לְמַעַן זִכְרָךְ. לְמַעַן צִדְקָתָךְ. לְמַעַן חַסְדָּךְ. לְמַעַן קְדֻשָּׁתָךְ. לְמַעַן טוּבָךְ. לְמַעַן רַחֲמֶיךָ הָרַבִּים. לְמַעַן יִחוּדָךְ. לְמַעַן שְׁכִינָתָךְ. לְמַעַן כְּבוֹדָךְ. לְמַעַן תְּהִלָּתָךְ. הוֹשַׁע נָא."],[2,"s1","על הפיוט","בפיוט זה אנו מפרטים את הערכים הרוחניים בהם חפץ הקב\"ה, ומדגישים כי תפילתנו לישועה אינה בעבור תועלתנו האישית, אלא למען כבוד ה' ומימוש מטרת הבריאה, על ידי הופעתם ומימושם של ערכים אלו. ואם יאמר אדם: מי אני ומה אני ספון [=חשוב], שאתפלל על הגלות ועל ירושלים? המפני תפילתי יכונסו הגלויות ותצמח הישועה? – תשובתו בצידו, כאותה ששנינו: \"לפיכך נברא אדם יחידי, כדי שכל אחד יאמר: בשבילי נברא העולם\". וכבר נחת רוח הוא לפניו יתברך, שיהיו בניו מבקשים ומתפללים על זאת; ואף שלא תֵעשה בקשתם מפני שלא הגיע הזמן, או מאיזה טעם שיהיה – הנה הם עשו את שלהם, והקב\"ה שמח בזה."],[2,"s2","לְמַעַן אֲמִתָּךְ","– למען התאמתותה וקבלתה של האמת האלוהית – ההשקפה הנכונה על המציאות – בקרב כל האנושות, במקום תיאוריות הכפירה הרווחות בעולם. דבר זה יוכל להתממש רק על ידי ישועתו הרוחנית והגשמית של עם ישראל, שכן רק כאשר יהיה ניצב ברום המעלה ותהיה לו יכולת השפעה על אומות העולם, יוכל ללמדן את האמת האלוהית ולהנחיל להן את ערכיה, כפי שמתאר הנביא ישעיהו את המציאות העתידית: \"וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ: לְכוּ וְנַעֲלֶה אֶל הַר ה', אֶל בֵּית אֱלֹהֵי יַעֲקֹב, וְיֹרֵנוּ מִדְּרָכָיו, וְנֵלְכָה בְּאֹרְחֹתָיו, כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה, וּדְבַר ה' מִירוּשָׁלִָם\" (ישעיהו ב ג)."],[2,"s3","לְמַעַן בְּרִיתָךְ","– למען קיום בריתך שכרתָּ עִם עם ישראל, כפי שנאמר בסוף פרשת התוכחה: \"וְזָכַרְתִּי לָהֶם בּ¿רƒית רִאשֹׁנִים, אֲשֶׁר הוֹצֵאתִי אֹתָם מֵאֶרֶץ מִצְרַיִם לְעֵינֵי הַגּוֹיִם, לִהְיוֹת לָהֶם לֵאלֹהִים\" (ויקרא כו מה), ופירש 'אבן עזרא': \"בְּרִית רִאשֹׁנִים – זאת הברית הכרותה בסיני\". בסיני, ישראל קיבלו על עצמם את חלקם בקיום הברית שבינם לבין הקב\"ה – שמירת המצוות; והקב\"ה, מצידו, הבטיח לישראל שחלקו בקיום הברית יהיה: \"וְעַתָּה אִם שָׁמוֹעַ תִּשְׁמְעוּ בְּקֹלִי וּשְׁמַרְתֶּם אֶת בְּרִיתִי – וִהְיִיתֶם לִי סְגֻלָּה מִכָּל הָעַמִּים\" (שמות יט ה). מובנה המקורי של המילה 'סגולה' הוא אוצר מיוחד, וכפי שפירש רמב\"ן (שם): \"שתהיו בידי סגולה, כדבר נחמד שלא ימסרנו המלך ביד אחר\". על פי פירושו, ברית זו כוללת שמירה והגנה מאת הקב\"ה על עם ישראל, ועל כך אנו מבקשים: \"הוֹשַׁע נָא לְמַעַן בְּרִיתָךְ\". הערות 71 כך פירש רש\"י על אתר: \"אוצר חביב, כמו 'וּסְגֻלַּת מְלָכִים' (קהלת ב ח) - כלֵי יְקר ואבנים טובות שהמלכים גונזים אותם, כך אתם תהיו לי סגולה משאר אומות\"."],[2,"s4","לְמַעַן גָּדְלָךְ וְתִפְאַרְתָּךְ","– כשעם ישראל יוושע, וגדולתו ותפארתו תופענה בגלוי לעיני כל האומות, תתבטא בכך הופעתן של גדולתו ותפארתו של הקב\"ה, שכן עם ישראל הוא המייצג אותו בעולם, כמבואר לעיל. בנוסף לכך, 'גודלו' של הקב\"ה מבטא את היותו מקור כל הדברים הקיימים, הגשמיים והרוחניים, שהוא עצמו 'גדול' וכולל את כל אלה בתוך עצמותו; משמעות המושג 'תפארת' היא מיזוג של מידות וערכים מנוגדים ליצירה שלישית המהווה שילוב של שניהם (בספרי הפנימיות: שילוב של מידות החסד והגבורה). על פי זה, משמעות התגלותן של גודלו ותפארתו של הקב\"ה היא, שהכול יכירו בכך שכל הפרטים הקיימים בבריאה הם חלק מה גודל האלוהי, וכן שיכירו ביופי ובָאמת הקיימים באופן הנהגתו את העולם, הנובעת מ שילוב של מידות החסד והדין, ושל מכלול השיקולים הגלויים לעיניו. הערות 72 ראה: משנה תורה לרמב\"ם, הלכות יסודי התורה, פרק ב, הלכה ט: \"כל הנמצאים חוץ מן הבורא, מצורה הראשונה עד יתוש קטן שיהיה בטבור הארץ – הכול מכוח אמיתתו נמצאו. ולפי שהוא יודע עצמו, ומכיר גדולתו ותפארתו ואמיתתו – הוא יודע הכול, ואין דבר נעלם ממנו\", וכן אורות הקודש, חלק ב, עמ' שצז: \"הכול הוא כלול באלוהים, והעצמיות הפרטית של כל פרט מפרטי ההוויה איננו כי אם התגלות אלוהית הזורחת בגוונים שונים לפנינו\"."],[2,"s5","לְמַעַן דָּתָךְ","– כדי שנוכל ללמוד את התורה ולקיים את מצוותיה כראוי, שכן לעיתים נבצר מהאדם – כפרט, או מהאומה – ככלל, לקיימן בשלימות, בשל צוק העיתים ומניעות שונות. 'דָּת' היא מצוות וחוקים, ודתו של הקב\"ה היא התורה, כפי שנאמר: \"מִימִינוֹ אשדת (קרֵי: אֵשׁ דָּת) לָמוֹ\" (דברים לג ב). הערות 73 כמו: \"וְיִכָּתֵב בְּדָתֵי פָרַס וּמָדַי\" (אסתר א יט)."],[2,"s6","לְמַעַן הוֹדָךְ","– כדי שיתגלה ויופיע בעולם הודו של הקב\"ה באמצעות עם ישראל, כמבואר לעיל. פירוש המושג 'הוד' הוא: יופי פנימי, חבוי, (לעומת המושג 'הדר' המבטא את הגילויים החיצוניים שלו). אנו מייחלים להתגלות עליונה ומשמעותית של הקב\"ה בעולם, שבה ניתן יהיה להעמיק את ההכרה בדעת אלוהים, עד לרמה של הכרה ברבדים הפנימיים והעמוקים ביותר שבה. הערות 74 מלבי\"ם, תהילים קד א"],[2,"s7","לְמַעַן וִעוּדָךְ","– 'ויעוד' הוא התוועדות, מפגש. אנו מתפללים לישועתו הרוחנית של עם ישראל, שבה תשוב השכינה לשרות בקרבנו בגלוי בבית המקדש, שהוא מקום המפגש, כביכול, בין ישראל לקב\"ה, כפי שנאמר: \"פֶּתַח אֹהֶל מוֹעֵד לִפְנֵי ה' אֲשֶׁר אִוָּעֵד לָכֶם שָׁמָּה [...] וְנֹעַדְתִּי שָׁמָּה לִבְנֵי יִשְׂרָאֵל\" (שמות כט מב-מג). ל'ויעוד' זה משמעות כפולה, שכן מלבד הציפייה למפגש בין הקב\"ה לכלל ישראל באמצעות השכינה במקדש, הרי שכל יחיד ויחיד שואף להגיע למפגש אישי עם הקב\"ה בתוך לבבו, ומייחל לקבל סיוע ממרום להשתדלותו לבוא לידי כך; וכדברי ה'אלשיך' על הפסוק: \"וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם\" (שם כה ח) – 'בתוכם' ולא 'בתוכו' [...] כי עיקר השכינה שורה באדם, ולא בבית [המקדש], כי 'הֵיכָל ה' הֵמָּה' [האנשים]\". וכך כתב הראי\"ה קוק: בית המקדש, בתור המרכז הרוחני של האומה, ומקור החיים הרוחניים של כל יחיד ממנה, מצד החיזיון המורגש המרהיב עין ביופיו [...] צריך הוא להיבנות ברוח בכל יום אצל כל יחיד מישראל. [...] אז ישובו ליחיד כוחותיו הנפשיים הרעננים, שחיי האמונה, וחום ההרגש ואורו, פורחים בהם כפרחי חמד של שלל צבעים נחמדים למאוד. הערות 75 רבי משה אלשיך (רס\"ז-ש\"ס), מחכמי צפת, דרשן ופוסק, כיהן בה כדיין וראש ישיבה, וחיבר פירוש לתורה ולרוב ספרי התנ\"ך. 76 כלשון הכתוב: \"אַל תִּבְטְחוּ לָכֶם אֶל דִּבְרֵי הַשֶּׁקֶר לֵאמֹר: 'הֵיכַל ה' הֵיכַל ה'', הֵיכַל ה' הֵמָּה\" (ירמיהו ז ד), וכפי שפירש שם ה'אלשיך' עצמו: \"אל תחשבו כי הוא יתברך קורא 'הֵיכָל ה'' לשכן שמו בבית, כי אם באנשים, כי בהיותם צדיקים – הם עצמם ההיכל\". 77 שמונה קבצים, קובץ א, קמד"],[2,"s8","לְמַעַן זִכְרָךְ","– כדי שכל באי עולם יכירו במלכות הקב\"ה, ויזכרוהו תמיד בליבם ובפיהם; לא זיכרון גרידא, אלא כזה הנובע מתוך הכרה עמוקה ומוחשית במציאותו, ומתוך הצבת האדם את הבורא במרכז חייו, כפי שאמר דוד: \"שִׁוִּיתִי ה' לְנֶגְדִּי תָמִיד\" (תהילים טז ח). כך זכרו אינו מש ממנו, שהרי כל פעולתיו מכוונות למטרה אחת: לקיים את רצונו ולדבוק בו."],[2,"s9","לְמַעַן חַסְדָּךְ","– כדי שתתגלה ותתממש בעולם מידת החסד של הקב\"ה, בה הוא מיטיב עם האדם מעבר לכפי הראוי לו על פי זכויותיו. זאת, באמצעות הטובות והישועות שאנו מבקשים שיעשה עימנו, על אף שאיננו ראויים לכך מצד מעשינו."],[2,"s10","לְמַעַן טוּבָךְ","– כדי שתתגלה בעולם מידת טובו של הקב\"ה. תוכן בקשה זו מצריך הבנה: הרי כל הפעולות שהקב\"ה פועל במציאות הן טוב מוחלט, אלא שבשכלנו המוגבל איננו יכולים להבין את דרכי הנהגתו; עצם היותו של הקב\"ה מציאות פשוטה (=לא מורכבת) שמגמתה היא להיטיב, מחייב שכל פעולותיו תהיינה אך ורק טוב מוחלט, שהרי אין לו רצונות שונים המנוגדים זה לזה, כמו אצל האדם. אף על פי שבשכל אנושי לא ניתן להבין כיצד הכול הוא טוב, מנקודת המבט האלוהית – ודאי שכך הוא, וכפי שביאר הרב יעקב משה חרל\"פ יסוד אמוני זה: [...] שכל מה שיש בעולם, בלי יוצא מן הכלל, נוצר ונברא אך ורק לטוב ולחסד לגלוֹת טוּב ה', ושאין שום דבר שהוא רע בהחלט, אלא הכול טוב; ולא רק שעתיד לצאת ממנו טובה, אלא הוא טוב בהחלט, בעבר, בהווה , ובעתיד [...] הכול טוב מוחלט שאין למעלה ממנו. אם כן, מהי משמעות הבקשה: \"הוֹשַׁע נָא לְמַעַן טוּבָךְ\", אם גם המציאות הנוכחית כפי שהיא מהווה טוב מוחלט? נראה לבאר, שעל אף שוודאי כל פעולותיו של הקב\"ה הן הטבה, לא הרי פעולתה של מידת טוב ה' בהסתר ובעקיפין כהרי פעולתה בגלוי ובאופן ישיר. לבני האדם קשה להכיר בכך שגם המאורעות הנראים לעינינו שליליים הם באמת טובים מנקודת המבט האלוהית, וממילא יש בכך פגם בהופעת ה' בעולם: הדימוי שלו אצל בני האדם לוקה בחסר בכך שהם מייחסים לו – בין אם בקביעה שכלית ובין אם בהרגשת הלב – פעולות רעות ושליליות. לפיכך אנו מבקשים: \"הוֹשַׁע נָא לְמַעַן טוּבָךְ\", כדי שמידת טובך תופיע בעולם בגלוי, וכך כל באי עולם יכירו באמיתתה המוחלטת. הערות 78 (תרמ\"ב-תשי\"ב) רב שכונת 'שערי חסד' בירושלים, עמד בראשות הישיבות 'מרכז הרב' ו'בית זבול'. תלמיד הראי\"ה קוק, ומחבר סדרת ספרי המחשבה 'מי מרום' וספרי ההלכה 'בית זבול'. 79 מי מרום – ממעייני הישועה, עמ' לב. הראי\"ה קוק מבאר רעיון זה בהרחבה ב'אורות הקודש', חלק ב, מאמר 'הטוב הכללי'. וראה עוד בעניין זה להלן, עמ' 207-206"],[2,"s11","לְמַעַן יִחוּדָךְ","– כדי שתתפשט בכל העולם האמונה במציאות ה' ואחדותו, כלומר: שהוא המציאות האמתית היחידה, וכל היישויות הקיימות בעולם והפעולות המתרחשות בו, כולן נאצלות ממנו ונפעלות על ידו. על ידי גאולתו של עם ישראל, כל האומות תלמדנה ממנו אמונה זו, ועל עידן זה נאמר: \"וְהָיָה ה' לְמֶלֶך עַל כָּל הָאָרֶץ, בַּיּוֹם הַהוּא יִהְיֶה ה' ∆א»חד וּשְׁמוֹ ∆א»חד \" (זכריה יד ט). הערות 80 כמבואר לעיל עמ' 50"],[2,"s12","לְמַעַן כְּבוֹדָךְ","– כדי שכבודך לא יהיה מחולל בגויים, בראותם את עמך נתונים לבז ולמשיסה בגלות, כמו שכתוב: \"לֹא לָנוּ ה', לֹא לָנוּ, כִּי לְשִׁמְךָ תֵּן »כּבוֹד [...] לָמָּה יֹאמְרוּ הַגּוֹיִם: אַיֵּה נָא אֱלֹהֵיהֶם\" (תהילים קטו א-ב). פירוש נוסף: כדי שיתגלה בעולם כבודו של הקב\"ה, באמצעות כבודו של עם ישראל. 'כבוד' הוא מלשון כובד וריבוי; כבודו של הקב\"ה, אם כן, הוא ריבוי המושגים הגשמיים והרוחניים שנבראו על ידו ודרכם הוא מתגלה בעולם. בעת הגאולה השלימה, בנוסף להופעת הכבוד הלאומי של עם ישראל, המבטא את כבוד ה', גם יכירו הכול במציאות ה' ואחדותו, ובכך שהוא ברא – בעבר, ומקיים – בהווה, את כל המציאות, ומתוך כך יראו בכל פרט הקיים בבריאה גילוי של כבוד ה'. הערות 81 ראה נחום ג ג"],[2,"s13","לְמַעַן לִמּוּדָךְ","– כדי שיתפשט בקרב האנושות 'לימוד ה''. ביטוי זה מבוסס על הפסוק: \"וְכָל בָּנַיִך לִמּוּדֵי ה'\" (ישעיהו נד יג), דהיינו בעלי הכרה וידיעה עמוקות בדעת אלוהים, וכפי שציין שם רד\"ק לפסוק: \"וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת רֵעֵהוּ וְאִישׁ אֶת אָחִיו לֵאמֹר: דְּעוּ אֶת ה', כִּי כוּלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָם וְעַד גְּדוֹלָם\" (ירמיהו לא לג). לשם כך אנו מתפללים לישועה, שכן מצב זה, שבו כל אחד מישראל יהיה 'לימוד ה'' – יהיה לעתיד לבוא, לאחר הישועה העתידה, שאז \"תִּמָּלֵא הָאָרֶץ לָדַעַת אֶת כְּבוֹד ה', כַּמַּיִם יְכַסּוּ עַל יָם\" (חבקוק ב יד). מלבד זאת, גם השגת 'דעת אלוהים' אליה אנו יכולים להגיע בעידן הנוכחי, תלויה במידה רבה בישועות הנקודתיות להן אנו זקוקים, כגון פרנסה ורפואה, שכן כששרויים במועקות ובטרדות הזמן קשה להתעמק בלימודים עמוקים ומופשטים."],[2,"s14","לְמַעַן מַלְכוּתָךְ","– זו עיקר משמעותה של הגאולה העתידה: הופעת מלכות ה', כפי שאנו אומרים בתפילת 'עלינו לשבח': \"וִיקַבְּלוּ כֻלָּם אֶת עֹל מל¿כוּ∆תךָ , ו¿ƒת¿מל…ךְ עֲלֵיהֶם מְהֵרָה לְעוֹלָם וָעֶד\". גם ישועות עם ישראל מהצרות העכשוויות המתרגשות ובאות עליהם מפעם לפעם, הן התחלה של הופעת מלכות ה', שכן הן מבטאות את שליטתו בבריאה ואת הכוונתו אותה ליעדה הסופי – הופעה מוחלטת של מלכותו; גם עליהן אנו מבקשים: \"הוֹשַׁע נָא לְמַעַן מַלְכוּתָךְ\"."],[2,"s15","לְמַעַן נִצְחָךְ","– כדי שתופיע בעולם יכולת הקב\"ה לנצח על כל הבריאה = לשלוט בה ולהנהיגה. ניתן גם לפרש: כדי שתתפשט בעולם ההכרה בכך שהקב\"ה הוא נצחי – מרומם ונבדל ממגבלות הזמן והחומר. הערות 82 כמו \"לַמְנַצֵּחַ\" שבספר תהילים, דהיינו: מנצח על מקהלה, וכן: \"לְנַצֵּחַ עַל עֹשֵׂה הַמְּלָאכָה\" (עזרא ג ט)."],[2,"s16","לְמַעַן סוֹדָךְ","– המושג 'סוד ה'' מופיע בפסוק: \"סוֹד ה' לִירֵאָיו, וּבְרִיתוֹ לְהוֹדִיעָם\" (תהילים כה טו). רק יראי ה' זוכים להבין ולדעת את תורת הסוד – פנימיות התורה. תחום זה אינו מכונה 'סוד' מפני שהוא קשה להבנה בשל המושגים הלא-מובנים המרכיבים אותו; דבר זה אינו מהווה סיבה לכנותו 'סוד', אלא 'שפה אחרת'. אם אדם יתקשה לקרוא מאמר הכתוב בשפה זרה, לא נכנה את אותו מאמר: 'סוד'. החכמה הפנימית נקראת 'סוד' מפני שכדי להבינה באמת לא די בכישורים אינטלקטואליים, אלא הלומד נדרש לחיבור נפשי-פנימי לעומק הדברים, להפנמת הדברים במארג הכללי של אישיותו, ולתִרגומם לקשר האישי שלו עם נותן התורה; משום כך, רק ליראי ה' קיימת גישה ל'סוד ה''. אנו מתפללים: \"הוֹשַׁע נָא לְמַעַן סוֹדָךְ\" – כדי שיתרחב המעגל של 'יראי ה'' המוכשרים לגשת ל'סוד ה'', ויהיה חלקנו עמהם, שלשם כך נצרכת הישועה, כמבואר לעיל. הִנֵּה יָמִים בָּאִים נְאֻם ה', וְכָרַתִּי אֶת בֵּית יִשְׂרָאֵל וְאֶת בֵּית יְהוּדָה בְּרִית חֲדָשָׁה. לֹא כַבְּרִית אֲשֶׁר כָּרַתִּי אֶת אֲבוֹתָם בְּיוֹם הֶחֱזִיקִי בְיָדָם לְהוֹצִיאָם מֵאֶרֶץ מִצְרָיִם, אֲשֶׁר הֵמָּה הֵפֵרוּ אֶת בְּרִיתִי וְאָנֹכִי בָּעַלְתִּי בָם נְאֻם ה'. כִּי זֹאת הַבְּרִית אֲשֶׁר אֶכְרֹת אֶת בֵּית יִשְׂרָאֵל אַחֲרֵי הַיָּמִים הָהֵם, נְאֻם ה', נָתַתִּי אֶת תּוֹרָתִי בְּקִרְבָּם וְעַל לִבָּם אֶכְתֳּבֶנָּה, וְהָיִיתִי לָהֶם לֵאלֹהִים, וְהֵמָּה יִהְיוּ לִי לְעָם. וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת רֵעֵהוּ וְאִישׁ אֶת אָחִיו לֵאמֹר: דְּעוּ אֶת ה', כִּי כוּלָּם יֵדְעוּ אוֹתִי לְמִקְטַנָּם וְעַד גְּדוֹלָם, נְאֻם ה'. הערות 83 עמ' 55 84 ירמיהו לא ל-לג"],[2,"s17","לְמַעַן עֻזָּךְ","– כדי שיופיע בעולם עוזו של הקב\"ה, באמצעות הניסים שיעשה לישראל. ביטוי זה גם רומז למלך המשיח, עליו נאמר: \"וְעָמַד וְרָעָה ¿בּע…ז ה' , בִּגְאוֹן שֵׁם ה' אֱלֹהָיו, וְיָשָׁבוּ, כִּי עַתָּה יִגְדַּל עַד אַפְסֵי אָרֶץ\" (מיכה ה ג) – לעתיד לבוא, בעת הישועה, ימלוך המשיח על העולם כולו – \"עַד אַפְסֵי אָרֶץ\", ומלכותו תבטא את עוז מלכות ה'."],[2,"s18","לְמַעַן פְּאֵרָךְ","– כדי שיתגלה בעולם פארו של הקב\"ה המשתקף בפרטי הבריאה כולה, דהיינו שיאמינו ויכירו בכך שכל היופי והפאר הנראים בבריאה הם אופן התגלות פאר הקב\"ה, ודרך מבט זה יתקרבו לדבקות בו. וכך כתב הראי\"ה קוק: השער [להשגת קרבת אלוהים] הוא האלוהות המתגלה בעולם; בעולם בכל יופיו והדרו, בכל רוח ונשמה, בכל חי ורמש, בכל צמח ופרח, בכל גוי וממלכה, בים וגליו, בשפרירי שחק ובהדרת המאורות, בכישרונות כל שיח, ברעיונות כל סופר, בדמיונות כל משורר ובהגיונות כל חושב, בהרגשת כל מרגיש ובסערת גבורה של כל גיבור. מודעות זו תתקבל בקרב האנושות לעתיד לבוא בעת הישועה השלימה, עליה נאמר: \"וְנִגְלָה כְּבוֹד ה', וְרָאוּ כָל בָּשָׂר יַחְדָּו, כִּי פִּי ה' דִּבֵּר\" (ישעיהו מ ה). הערות 85 אורות, מאמר 'צימאון לאל חי', וראה לעיל הערה 72"],[2,"s19","לְמַעַן צִדְקָתָךְ","– כדי שתתממש הנהגת צדקתו של הקב\"ה, בה עושה עם ברואיו צדקה = טובות לפנים משורת הדין (כמו צדקה הניתנת לעני); וכפי שאנו אומרים בתפילת 'אבינו מלכנו': \"אָבִינוּ מַלְכֵּנוּ, חָנֵּנוּ וַעֲנֵנוּ כִּי אֵין בָּנוּ מַעֲשִׂים, עֲשֵׂה עִמָּנוּ ¿צד»»קה וָחֶסֶד, וְהוֹשִׁיעֵנוּ\". הערות 86 ראה מלבי\"ם, תהילים עא יט"],[2,"s20","לְמַעַן קְדֻשָּׁתָךְ","– כדי שקדושתך תיוודע בעולם. 'קדושה' היא פרישות ונבדלות מהחומר, כפי שכתב רמב\"ן על הפסוק: \"קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה' אֱלֹהֵיכֶם\" (ויקרא יט ב) –\"שנהיה פרושים מן המותרות\". תוכן הציווי בפסוק הוא, שמוטל עלינו להידמות לקב\"ה, כביכול, במידה המתאפשרת לנו כבני אנוש, ולהיות פרושים ממותרות חומריים, כשם שהוא נבדל במהותו מהחומר ומגבלותיו. משמעות בקשה זו היא, איפוא, שתתקבל בקרב האנושות האמונה בעליונותו האין-סופית של הקב\"ה ובנבדלותו מהשגת השכל האנושי."],[2,"s21","לְמַעַן רַחֲמֶיךָ הָרַבִּים","– כדי שרחמיך הרבים יתממשו ויבואו לידי ביטוי בפועל. מידת הרחמים של הקב\"ה אין משמעותה ויתור, כדברי הגמרא: \"כל האומר: הקב\"ה ותרן הוא – יוותרו חייו\", שהרי: \"אֶת כָּל מַעֲשֶׂה – הָאֱלֹהִים יָבִא בְמִשְׁפָּט\" (קהלת יב יד), ומשפטו של הקב\"ה מכֻוון בהתאם למעשי האדם. הרמח\"ל מסביר כי תפקידה של מידת הרחמים הוא עצם נתינת האפשרות לאדם לשוב בתשובה, וכן דחיית ביצוע העונש הראוי לו, על מנת לתת לו שהות לעשות זאת. על כך אנו מבקשים: \"הוֹשַׁע נָא לְמַעַן רַחֲמֶיךָ הָרַבִּים\" – אף אם הקשיים הנוכחיים מהווים עונש ראוי ותיקון לחטאי העבר, דחה אותם מעלינו כעת עד שנשוב בתשובה וכבר לא יהיה צורך בהם; בקשה זו מתייחסת בין לצרות הפרט, ובין לצרות כלל-ישראל. הערות 87 תלמוד בבלי, בבא קמא נ. 88 מסילת ישרים, פרק ד"],[2,"s22","לְמַעַן שְׁכִינָתָךְ","– כדי שתשוב לשכון בתוכנו, בין ברמה הכלל-ישראלית ובין ברמה של כל יחיד, שישכון ה' בלבבו. חזרתה העתידית של שכינת ה' לתוכנו, לא תתבטא בבית המקדש בלבד, אלא במציאות כולה – שתהיה ניסית ומלאה התגלות אלוהית; כמאמר הנביא: \"וְהָיָה אַחֲרֵי כֵן אֶשְׁפּוֹך אֶת רוּחִי עַל כָּל בָּשָׂר וְנִבְּאוּ בְּנֵיכֶם וּבְנוֹתֵיכֶם, זִקְנֵיכֶם חֲלֹמוֹת יַחֲלֹמוּן, בַּחוּרֵיכֶם חֶזְיֹנוֹת יִרְאוּ\" (יואל ג א). הערות 89 כמבואר לעיל עמ' 52"],[2,"s23","לְמַעַן תְּהִלָּתָךְ","– כדי שעל ידי ישועתם של ישראל וחסד ה' שיושפע עליהם ממרום, יכירו כל האומות בגדולת ה' ויהללוהו, כמאמר הכתוב: \" הל¿לוּ אֶת ה' כָּל גּוֹיִם, שַׁבְּחוּהוּ כָּל הָאֻמִּים, כִּי גָבַר עָלֵינוּ חַסְדּוֹ\" (תהילים קיז א-ב). בעת הגלות, המצב הוא 'חילול השם': שמו של הקב\"ה, דהיינו אופן הופעתו בעולם, לוקה בחסר, שכן אינו מראה בגלוי את השגחתו על ישראל עם קרובו. אך בעת הישועה העתידה, וכן בכל ישועה מצרות אחרות המתרגשות על ישראל – \"חָשַף ה' אֶת זְרוֹעַ קָדְשׁוֹ לְעֵינֵי כָּל הַגּוֹיִם, וְרָאוּ כָּל אַפְסֵי אָרֶץ אֶת יְשׁוּעַת אֱלֹהֵינוּ\" (ישעיהו נב י); על כך בקשתנו: \"הוֹשַׁע נָא לְמַעַן תְּהִלָּתָךְ\"."],[2,"s24","סיכום","לאורך הפיוט, הופיע בכל שורה המסר המרכזי: כל תפילותינו אינן עבור עצמנו, אלא למען הקב\"ה והנחלת הערכים המייצגים את רצונו. כמובן שהבנת משמעותה של הנחה זו מצריכה העמקה: כיצד ייתכן ש'חסר' משהו לקב\"ה, הלוא כל פרט בבריאה מונהג על פי רצונו? מושג ה'חֶסֶר' של הקב\"ה, כביכול, מכונה בספרי הפנימיות: 'צער השכינה' – כלומר: שכינתו של הקב\"ה בעולם שרויה בצער, בחיסרון; הופעתו בעולם אינה מתממשת באופן הראוי והשלם. מגמת הבריאה היא התפשטות ההכרה האוניברסלית בקב\"ה, כדברי שלמה המלך בתפילתו: \"לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי ה' הוּא הָאֱלֹהִים אֵין עוֹד\" (מלכים א' ח ס), וכפי שאנו מתפללים בתפילת 'עלינו לשבח': עַל כֵּן נְקַוֶּה לְּךָ ה' אֱלֹהֵינוּ, לִרְאוֹת מְהֵרָה בְּתִפְאֶרֶת עֻזָּךָ [...] לְתַקֵּן עוֹלָם בְּמַלְכוּת שַׁדַּי, וְכָל בְּנֵי בָשָׂר יִקְרְאוּ בִשְׁמֶךָ [...] וִיקַבְּלוּ כֻלָּם אֶת עֹל מַלְכוּתֶךָ, וְתִמְלֹךְ עֲלֵיהֶם מְהֵרָה לְעוֹלָם וָעֶד. תעודתו של עם ישראל היא לייצג את הקב\"ה בעולם; לפיכך, כשהוא שרוי בגלות ומצבו הלאומי בשפל המדרגה, הרי זה 'צער השכינה'. הקב\"ה נמצא, כביכול, עִם ישראל בגלות, שהרי בזמן זה אינם מייצגים אותו כראוי. כשעם ישראל אינו ניצב בגאון בחזית במת ההיסטוריה – הרי שמטרת הבריאה אינה מתממשת. על פי זה נוכל להבין את הדברים שנאמרו לרבי יוסף קארו מפי השכינה ברוח הקודש: ואילו הייתם משערים אחד מאלף אלפי אלפים ורוב רבי רבבות מהצער אשר אני [=השכינה] שרויה בו – לא היתה נכנסת שמחה בלבבכם [...]. בהמשך לקו רעיוני זה, כתב הראי\"ה קוק: כל הצרות והמחשכים, כל נהרי נחלי הדמים הנשפכים, כל התלאות והנדודים, כל הבוז והמשטמה, כל הרשעה והזוהמה, אינם אלא תולדה קלושה מהד הקול של אותו הצער העליון, צער השמיים, צער השכינה, צער האידיאליות המהותית [...] היחס בין הסבל האנושי הקיים בעולם לבין 'צער השכינה' הוא מעבר לכל פרופורציה, שכן 'צער השכינה' הוא פגם בעצם מגמתו הרוחנית-מהותית של העולם, ומשמעותו עמוקה לאין ערוך ביחס לסבל האנושי הגשמי. ניתן לדמות זאת למחלת נפש של אדם לעומת פצע שטחי, או לתקלה בקודים הפנימיים של מחשב לעומת תקלה קטנה באחת מתוכנותיו. הראי\"ה לא כתב שתופעות הסבל האנושי הן רק קטנות ביחס ל'צער השכינה', אלא שהן תולדות שלה; הוֵי אומר – אם נמשיך את הקו של הדימוי האחרון – התקלה בהגדרות הבסיסיות של המחשב, היא הגורמת לתקלות הקטנות הנראות בפועל. תופעות הסבל האנושי הן רק הסימפטומים של ה'תקלה' בנשמת העולם, שהיא עיכוב מימוש מגמתו הרוחנית: הופעת כבוד ה'. ייתכן שמשום חשיבותו של עניין זה, מוקם הפיוט 'לְמַעַן אֲמִתָּךְ' בתחילת סדר ה'הושענות', ויועד להאמר דווקא ביום הראשון של החג (מלבד כשחל בשבת). שכן, לעומת שאר פיוטי ה'הושענות' בהם תוכן הבקשות והמושא שלהן מפורשים, הרי שבפיוט זה אנו מתמקדים במטרה: 'לְמַעַן', ללא בקשה מפורשת על צרכים כל שהם. בכך הוא מהווה הקדמה נחוצה לפיוטים שנסדרו אחריו, שעל ידה תפילותינו תנבענה מתוך הכרה עמוקה בגודל משמעות המטרה עבורה אנו מתפללים. אין כאן בקשות גשמיות גרידא לחיים נוחים, גשמי ברכה, פרנסה, ובריאות; מטרתן של בקשות אלו היא הרבה מעבר לכך: מימוש מגמתה האמיתית של הבריאה – הופעת כבוד ה'. כשעם ישראל יימצא במעמד לאומי וכלכלי יציב, בין בחיי הכלל ובין בחיי הפרט, יוכל לייצג את הקב\"ה באופן הנעלה ביותר. הערות 90 מובא בספר 'שני לוחות הברית' (של\"ה), מסכת שבועות, פרק נר מצוה, דף קפ. 91 שמונה קבצים, קובץ ז, יב; אורות, המלחמה, פרק י"],[2,"n68","הערה 68","ראה שמות רבה, פרשה כ, אות ז: \"כבוד היה לי [...] והיה זקוק לי, והייתי סָפוּן בפניו\"."],[2,"n69","הערה 69","על פי לשון המשנה במסכת סנהדרין, פרק ד, משנה ה"],[2,"n70","הערה 70","מסילת ישרים, פרק יט"],[3,"piyut","נוסח הפיוט","הוֹשַׁע נָא אֶבֶן שְׁתִיָּה. לִינַת הַצֶּדֶק. בֵּית הַבְּחִירָה. מָכוֹן לְשִׁבְתֶּךָ. גֹּרֶן אָרְנָן. נָוֶה שַׁאֲנָן. דְּבִיר הַמֻּצְנָע. סֻכַּת שָׁלֵם. הַר הַמּוֹרִיָּה. עֲלִיַּת שְׁבָטִים. וְהַר יֵרָאֶה. פִּנַּת יִקְרַת. זְבוּל תִּפְאַרְתֶּךָ. צִיּוֹן הַמְצֻיֶּנֶת. חָנָה דָוִד. קֹדֶשׁ הַקֳּדָשִׁים. טוֹב הַלְּבָנוֹן. רָצוּף אַהֲבָה. יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. שְׁכִינַת כְּבוֹדֶךָ. כְּלִילַת יֹפִי. תֵּל תַּלְפִּיּוֹת. הוֹשַׁע נָא."],[3,"s1","על הפיוט","בפיוט זה אנו מתפללים לישועת ציון והמקדש, על ידי השבת הקב\"ה את שכינתו אליהם. קיים קשר מיוחד בין חג הסוכות לבין בית המקדש, כדברי חז\"ל: \"בזכות: 'וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן [פְּרִי עֵץ הָדָר וגו']' (ויקרא כג מ) – אני בונה לכם 'ראשון' – זה בית המקדש, דכתיב ביה: 'כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן מְקוֹם מִקְדָּשֵׁנוּ' (ירמיהו יז יב)\". מהר\"ל מפראג מסביר את עניינו של קשר זה: ובזכות יום ראשון של סוכות יזכו לבניין בית הבחירה, שהוא סוכתו של הקב\"ה. שיש לו לקב\"ה סוכה, וכאשר ישראל מקיימים מצוַת סוכה לישב בסוכה – גם כן הקב\"ה משרה שכינתו במקדש שנקרא סוכה. והרי כי עיקר מצוַת סוכה הוא כמו שנאמר: \"כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל\" (ויקרא כג מג), וסוכות אלו היו ענני כבוד, שה' יתברך היה שכינתו בסוכה זאת, כי בענן כבודו היה הולך עמהם. לפיכך, בשביל [=בזכות] ראשון של סוכות יזכו ישראל לבנות להם בית המקדש שהוא ראשון. ומפני זה היה המקדש [הראשון] נבנה בסוכות. גם הסוכה וגם המקדש, עניינם הוא השראת השכינה בקרב ישראל; לפיכך, כשהם מקיימים את מצוַת הסוכה ובכך יוצרים קירבה ביניהם לבין השכינה, אף הקב\"ה עושה את חלקו ומקרב את בניין בית המקדש, בו השראת השכינה תתקיים בשלימות. וכתב הגר\"א שאף בניין בית המקדש השלישי יהיה בחג הסוכות."],[3,"s2","אֶבֶן שְׁתִיָּה","– האבן העומדת במקום קודש הקודשים, שעליה היה מונח ארון הברית בזמן המקדש. האבן נקראת כך, מכיוון שעל פי קבלת חז\"ל ממנה הושתת (=יוּסד, נברא) העולם: ו'שתייה' היתה נקראת – תנא: שממנה הושתת העולם. תנן כמאן דאמר [=שנינו כדעת מי שאומר]: מציון נברא העולם [...] שנאמר: \"מִזְמוֹר לְאָסָף, אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ, מִמִּזְרַח שֶׁמֶשׁ עַד מְבֹאוֹ\". ואומר: \"מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ\" (תהילים נ א-ב) – ממנו מוכלל יופיו של עולם. דעה זו בגמרא נוקטת שאבן השתייה נבראה בתחילת בריאת העולם, וממנה התפתח שאר העולם שהיה גנוז בתוכה, כעץ הצומח מתוך הגרעין. היא מביאה לכך ראיה מהפסוקים בתהילים, שמובנם – על פי פרשנות זו – הוא, שהקב\"ה \"דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבֹאוֹ\" – ברא את העולם כולו בקריאתו ודיבורו; \"מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ\" – מתוך אבן השתייה העומדת בציון, הקב\"ה ברא והופיע (פועַל יוצא) את העולם כולו. משום כך, ציון היא 'מִכְלַל יֹפִי' – בה כלול וגנוז יופיו של כל העולם. תיאוריה זו מבטאת, כמובן, רעיון רוחני: העולם כולו יונק את תוכנו ומשמעותו מן הקודש; ללא מגמת הקדושה וההתעלות, אין משמעות לעולם החומרי כפי שהוא. רק התקדשות העולם החומרי והופעת הקב\"ה בתוכו, שמקום התגלותה המרכזי הוא מקום אבן השתייה: בית המקדש – נותנות משמעות חיובית לקיומו. ערכו של היופי הגשמי בעולם, מתממש רק כאשר יוצקים לתוכו משמעות רוחנית – כשרואים בו הופעה של הקב\"ה. הערות 95 תלמוד בבלי, יומא נד:"],[3,"s3","בֵּית הַבְּחִירָה","– על פי לשון הכתוב: \"הַמָּקוֹם אֲשֶׁר יִבְחַר ה' אֱלֹהֵיכֶם\" (דברים יב ה). מבין כל המקומות האפשריים, הקב\"ה בחר במקום זה והעניק לו סגולה מיוחדת העושה אותו ראוי להשראת השכינה בו."],[3,"s4","גֹּרֶן אָרְנָן","– בית המקדש, שנבנה על מקום גורנו של ארוונה היבוסי (הנקרא בספר דברי הימים: 'אָרְנָן') שנקנה על ידי דוד, על פי ציוויו של גד החוזה (שמואל ב' כד). על משמעות הדבר שהפייטן מכנה כך את בית המקדש, כתב בעל הפירוש 'שיחה שלימה': וזה גם כן מורה על אמיתת ויקרת המקום ההוא, ושהוא המקום הנבחר באמת, מקום המקודש; דהלוא [...] לא היה המקום הזה מקום של משפחה המיוחסת שבישראל, רק [=אלא] גורן של גר תושב אשר לא מבני ישראל היה. ואם כן, הלוא לא היה שום טעם וסיבה לבוחרו, רק באשר שהוא הוא המקום המקודש. הערות 96 דברי הימים א', פרק כא 97 רבי שלום אלחנן הלוי יפה (תרי\"ח-תרפ\"ד), כיהן כרב בקהילות שונות ברוסיה, ולאחר מכן כראש ישיבה ואב בית דין בסנט-לואיס. חיבר את השו\"ת 'שואל כעניין', ואת הפירושים: 'תפילה שלימה' - על סידור התפילה, ו'שיחה שלימה' - על ההושענות, הסליחות, והיוצרות."],[3,"s5","דְּבִיר הַמֻּצְנָע","– 'דְּבִיר' הוא כינוי לקודש הקודשים, כמאמר הכתוב: \"וַיָּבִיאוּ הַכֹּהֲנִים אֶת אֲרוֹן בְּרִית ה' אֶל מְקוֹמוֹ, אֶל דְּבִיר הַבַּיִת אֶל קֹדֶשׁ הַקְּדָשִׁים\" (דברי הימים ב' ה ז). מדברי הגמרא עולה כי פירוש המילה 'דביר' הוא בית העשוי לשמור בתוכו ספר, כפי הנראה מהפסוק: \"וְשֵׁם דְּבִר לְפָנִים – קִרְיַת סֵפֶר\" (יהושע טו טו); אם כן, ייתכן שקודש הקודשים מכונה כך על שם לוחות הברית וספר התורה שהיו בתוכו. 'הַמּוּצְנָע' – כיוון שאין רואים אותו ואין נכנסים אליו. בית המקדש, ובפרט קודש הקודשים, הוא מקום הקשר הצנוע והאינטימי שבין הקב\"ה לישראל. בו היו הכרובים פונים זה אל זה כזכר ונקבה, לבטא את חיבתם של ישראל לפני המקום, ומשם היה דבר ה' יוצא אל משה בהצנע, כמו שכתוב: \"וּבְבֹא מֹשֶׁה אֶל אֹהֶל מוֹעֵד לְדַבֵּר אִתּוֹ, וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו מֵעַל הַכַּפֹּרֶת אֲשֶׁר עַל אֲרֹן הָעֵדֻת מִבֵּין שְׁנֵי הַכְּרֻבִים, וַיְדַבֵּר אֵלָיו\" (במדבר ז פט). צניעות זו היא מאפיין מהותי של המשכן ובית המקדש; וכך נאמר במדרש: \"וַיְדַבֵּר ה' אֶל משֶׁה בְּמִדְבַּר סִינַי\" (במדבר א א) – עד שלא עמד אוהל מועד – דיבר עימו בסנה, שנאמר: \"וַיִּקְרָא אֵלָיו אֱלֹהִים מִתּוֹךְ הַסְּנֶה \" (שמות ג ד). ואחר כך: \"וַיֹּאמֶר ה' אֶל משֶׁה וְאֶל אַהֲרֹן בְּאֶרֶץ מִצְרַיִם לֵאמֹר\" (שם יב א). ודיבר עימו במדיין, שנאמר: \"וַיֹּאמֶר ה' אֶל משֶׁה בְּמִדְיָן \" (שם ד יט). ודיבר עימו בסיני, שנאמר: וַיְדַבֵּר ה' אֶל משֶׁה בְּמִדְבַּר סִינַי לֵאמֹר\". וכיוון שעמד אוהל מועד, אמר: יפה היא הצניעות, שנאמר: \"וְהַצְנֵעַ לֶכֶת עִם אֱלֹהֶיךָ\" (מיכה ו ח), הרי הוא מדבר עימו באוהל מועד. במקום אחר מבאר המדרש רעיון זה באמצעות משל: אמר רבי יהודה ברבי אלעאי: [משל] למלך שהיתה לו בת קטנה; עד שלא הגדילה ובאת לידי סימנים – היה רואה אותה בשוק ומדבר עימה בפרהסיא במבוי ובחצר. כיוון שהגדילה ובאת לידי סימנים, אמר המלך: אין שבחה של בתי שאהא מדבר עימה בפרהסיא, אלא עשו לה פפיליון [=אוהל], וכשאהיה צריך לדבר עימה – אדבר עימה מתוך הפפיליון. כך כתיב: \"כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ\" (הושע יא א). במצרים ראו אותו בפרהסיא, שנאמר: \"וְעָבַר ה' לִנְגֹף אֶת מִצְרַיִם\" (שמות יב כג); בים ראו אותו בפרהסיא, שנאמר: \"וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדֹלָה\" (שם יד לא), והיו העוללים מראים אותו באצבען, ואומרים: \"זֶה אֵלִי וְאַנְוֵהוּ\" (שם טו ב); בסיני ראו אותו פנים בפנים, שנאמר: \"ה' מִסִּינַי בָּא\" וגו' (דברים לג ב). כיוון שעמדו ישראל על הר סיני וקיבלו את התורה, ואמרו: \"כֹּל אֲשֶׁר דִּבֶּר ה' נַעֲשֶׂה וְנִשְׁמָע\" (שמות כד ז) – נעשו לו אומה שלימה. אמר הקב\"ה: אין שִבחן של בנַי שאהא מדבר עימם בפרהסיא, אלא יעשו לי משכן, וכשאני צריך לדבר עמהם אדבר עמהם מתוך המשכן, הדא הוא דכתיב [=זהו מה שכתוב]: \"וּבְבֹא משֶׁה אֶל אֹהֶל מוֹעֵד לְדַבֵּר אִתּוֹ\" (במדבר ז פט). לכאורה, ההתגלות הגלויה לעיני כל – מעלתה גבוהה יותר מאשר התגלות בהצנע. אך המדרש מלמדנו כי לא כן הוא; רק לפני מתן תורה, טרם הגיעו ישראל למעלתם השלימה, נגלה אליהם הקב\"ה באופן גלוי; אך לאחריו, כשהגיעו למדרגה גבוהה ובוגרת יותר, דווקא משום כך – ערוץ הקשר בין הקב\"ה לבינם נהיה מוצנע ומוסתר. כמו במשל, בו רצון המלך לשוחח עם בתו הגדולה בתוך האוהל המוצנע, מבטא את הערך והחשיבות שהוא מייחס לבתו ולקיום הקשר והשיחה עימה, כך בנמשל – הצנעת הקשר בין הקב\"ה לישראל באמצעות המשכן והמקדש – מבטא את היותו עמוק ומשמעותי יותר משהיה קודם לכן. ככל שהדבר הוא חשוב ויקר ערך – כך הוא מוסתר יותר. זוהי המשמעות העמוקה הטמונה בכינוי 'דְּבִיר הַמּוּצְנָע'. הערות 98 תלמוד בבלי, עבודה זרה כד: 99 ראה תלמוד בבלי, בבא בתרא יד. 100 'שיחה שלימה' 101 ראה תלמוד בבלי, יומא נד. 102 במדבר רבה, פרשה א, אות ג 103 שיר השירים רבה, פרשה ג, אות טו"],[3,"s6","הַר הַמּוֹרִיָּה","– הר הבית נקרא 'הַר הַמּוֹרִיָּה' על שם צמח המור (מין בושם) שהיה גדל בו, כמו בפסוק: \"אֵלֶך לִי אֶל הַר הַמּוֹר וְאֶל גִּבְעַת הַלְּבוֹנָה\" (שיר השירים ד ז) – כך פירש רמב\"ן; ורש\"י פירש שכינוי זה הוא על שם המור שהקטירו בקטורת הסמים בבית המקדש שנבנה שם. לפי שני הפירושים ניתן לומר, שאותו מור מבטא את הרוחניות והקדושה שמושפעות מהמקדש לעולם כולו, שכן הריח מבטא רוחניות, באשר הוא \"דבר שהנשמה נהנית ממנו ואין הגוף נהנה ממנו\"; המקדש הוא מקום המפגש של הקב\"ה עם העולם הגשמי, ודרכו מושפעות מהקב\"ה הקדושה והרוחניות לעולם – \"כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה, חַיִּים עַד הָעוֹלָם\" (תהילים קלג ג). רמב\"ן (שם) פירש באופן נוסף, לפיו 'מוֹרִיָּה' הוא מלשון 'מורא' – \"ששם ייראו האלוהים ויעבדו לפניו\"; הר המוריה הוא המקום המיועד והמתאים ליראת ה' ועבודתו. זאת, על פי האמור במדרש: באצבע הראה הקב\"ה לאברהם אבינו את המזבח [שבהר המוריה, בעת עקידת יצחק], אמר לו: זהו המזבח שהיה אדם הראשון מקריב [עליו] מקדם, הוא המזבח שהקריבו בו קין והבל, הוא המזבח שהקריבו בו נח ובניו. שנאמר: \"וַיִּבֶן שָׁם אַבְרָהָם אֶת הַמִּזְבֵּחַ\" (בראשית כב ט) – 'מזבח' אין כתוב כאן, אלא 'המזבח' – הוא המזבח שהקריבו בו הראשונים. לפירוש זה, בהזכרת הכינוי 'הַר הַמּוֹרִיָּה' אנו רומזים לייחודיותו ההיסטורית-רוחנית של ההר; מקום זה היה מיועד לעבודת ה' ויראתו כבר מימי אדם הראשון. הערות 104 בראשית כב ב 105 שם 106 תלמוד בבלי, ברכות מו: 107 פרקי דרבי אליעזר, פרק ל"],[3,"s7","וְהַר יֵרָאֶה","– כינוי זה להר הבית מבוסס על הכתוב: \"וַיִקְרָא אַבְרָהָם שֵׁם הַמָּקוֹם הַהוּא: ה' יִרְאֶה, אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר ה' יֵרָאֶה\" (בראשית כב יד); ופירש רש\"י, שאברהם קרא להר המוריה 'ה' יִרְאֶה' – כלומר: \"ה' יבחר ויראה לו את המקום הזה להשרות בו שכינתו ולהקריב כאן קורבנות. 'אֲשֶׁר יֵאָמֵר הַיּוֹם בְּהַר ה' יֵרָאֶה' – שיאמרו לימי הדורות עליו: בהר זה יֵרָאֶה הקב\"ה לעמו\". מכיוון שאברהם הבחין בכך שהר המוריה הוא המקום הנבחר בעיני הקב\"ה להשרות שם את שכינתו, אמר ש'יֵאָמֵר הַיּוֹם' (דהיינו: \"הימים העתידין, שכל הדורות הבאים הקוראים את המקרא הזה אומרים: 'עד היום הזה'\") ששם תהיה השראת השכינה (המילה 'ה'' בסוף הפסוק משמשת פעמיים: \"בְּהַר ה' – ה' יֵרָאֶה\"). על פי זה, משמעות הכינוי הנזכר אצלנו הוא: ההר שעליו ה' יֵרָאֶה – יגלה את שכינתו. רש\"י מפרש באופן נוסף, לפיו 'יֵרָאֶה' מתייחס לאפרו של האיל שהקריב אברהם במקום יצחק, שייראה לעיני ה', ובזכות מסירות הנפש של אברהם ויצחק, יסלח לישראל – \"אפרו של יצחק צבור ועומד לכפרה\". שיבוץ כינוי זה בפיוט נועד להזכיר את זכות העקידה לפני ה', וכן לעורר את המתפלל עצמו להתחזק במסירותו לעבודת ה', לאור מסירות הנפש העצומה של האבות שהתגלתה במעשה זה. הערות 108 לשון רש\"י שם 109 לשון רש\"י שם. עוד בעניין זה ובמשמעות הביטוי 'אפרו של יצחק', ראה להלן עמ' 179-178"],[3,"s8","זְבוּל תִּפְאַרְתֶּךָ","– על פי לשון הכתוב: \"בָּנֹה בָנִיתִי בֵּית זְבֻל לָךְ, מָכוֹן לְשִׁבְתְּךָ עוֹלָמִים\" (מלכים א' ח יג). 'זבול' הוא בית מגורים, כמו שאמרה לאה: \"הַפַּעַם יִזְבְּלֵני אִישִׁי\" (בראשית ל כ), ופירש רש\"י: \"לא תהא עיקר דירתו אלא עימי\". הכינוי 'זְבוּל תִּפְאַרְתֶּךָ' רומז לספירת 'תפארת', שמשמעותה הוא שילוב; בית המקדש מהווה נקודת חיבור והשקה בין העולם הארצי לעולם הרוחני, ויופיו ותפארתו מהווים שילוב בין שניהם. תפארתו החיצונית של בית המקדש מבטאת את זו הפנימית-רוחנית, את היופי של עולם הרוח והאלוהות, ומעוררת בלב האדם את התשוקה לאותו יופי רוחני-אלוהי. וכך כתב הראי\"ה קוק: התפארת האלוהית – הכוללת בחטיבה אחת כל הדרת שמיים וארץ. היופי העליון, התפארת האלוהית, מושכת היא אליה את הנשמה, מעירה אותה מתרדמתה, ומקיצה לחיים את כל כוחותיה. מאירה היא עליה כאור שמש על צמחי חמד, ומפתחת אותה בכל ענפיה המלאים כוח, פאר, נועם, ורעננות. התשוקה לייחוסי בית המקדש, לבית ה' בראש ההרים, לכוהנים בעבודתם, לויים בשירם, וישראל במעמדם, וכל קישורי הנפש שבאומה כולה אל זבול קודשה, מעירה בכל יום נויו של עולם בליבן של ישראל, ומקימה מקדש עליון בנשמתו של כל יחיד [...]. הערות 110 שמונה קבצים, קובץ א, תתד 111 כינוי לבית המקדש, על פי תלמוד בבלי, זבחים נד: 112 שמונה קבצים, שם, תרו"],[3,"s9","חָנָה דָוִד","– כלשון הכתוב: \"הוֹי אֲרִיאֵל אֲרִיאֵל, קִרְיַת חָנָה דָוִד\" (ישעיהו כט א); 'אֲרִיאֵל' = בית המקדש, שבנוי בתוך \"קִרְיַת חָנָה דָוִד\" = ירושלים. כאן עובר הפייטן מהתארים של בית המקדש והר הבית (אף כי יוזכרו גם בהמשך) לתארים של העיר ירושלים; דוד כבש את ירושלים מידי היבוסים ו ח!ה בה = קבע בה את מקום מלכותו. לא בכדי, מכנה הפייטן את ירושלים על שם חניית דוד; קיים קשר מהותי והדוק בין ירושלים לבין מלכות בית דוד. לדעת התלמוד הירושלמי, בתפילת העמידה קיימת ברכה אחת לבניין ירושלים ולמלכות בית דוד (ולא כמנהגנו לחלקם לשתי ברכות: 'בונה ירושלים' ו'את צמח דוד'), וחותמים בה: \"אֱלֹהֵי דָּוִד וּבוֹנֶה יְרוּשָׁלַיִם\". אף לפי הנוסח הנהוג, קיים איזכור למלכות בית דוד בברכת 'בונה ירושלים': \"וְכִסֵּא דָּוִד עַבְדְּךָ מְהֵרָה לְתוֹכָה תָּכִין\". על חשיבותו של איזכור זה, וממילא על מהותיות הקשר הקיים בין שני הנושאים, יעיד המעשה הבא, עליו מעיד רבי חיים ויטאל: פעם אחת נכנס חכם אחד לפני מורי [=האר\"י] זלל\"ה, ונסתכל במצחו, ואמר לו שמימיו לא התפלל תפילה אחת כראוי. ושאלו החכם למה, ואמר לו: שלא אמר \"וְכִסֵּא דָּוִד עַבְדְּךָ מְהֵרָה לְתוֹכָה תָּכִין\". רבי יואל סירקיס בפירושו 'בית חדש' (ב\"ח) על ה'טור' עוסק בשאלת שייכותו של המשפט 'וכיסא דוד עבדך' לברכת 'בונה ירושלים' בה הוא משובץ; הוא מסביר \"כי אין כיסא ה' שלם אלא כשכיסא דוד על מכונו בירושלים\". השבת שכינת ה' לירושלים, עליה אנו מבקשים בתחילת הברכה, אינה יכולה להסתכם בפן הרוחני בלבד; היא מתבטאת בשלימות רק עם כינון מצבו הלאומי-פוליטי של עם ישראל, על ידי מלכות בית דוד. הלאומיות והרוחניות – הדת והמדינה – הן חטיבה אחת של הופעת שכינת ה' בקרב ישראל. עיקרון זה מתבטא גם בכך שבניין בית המקדש נעשה על ידי מלכי ישראל: דוד מצא את המקום המיועד וקנאו מאת ארוונה היבוסי, ושלמה בנאו בפועל. רעיון זה מתבטא גם בהלכה הקובעת: \"כל שלא אמר [...] מלכות בית דוד ב'בונה ירושלים' [שבברכת המזון] – לא יצא ידי חובתו\". ניתן להבחין ברעיון זה בנבואת הנחמה של ירמיהו: הִנֵּה יָמִים בָּאִים נְאֻם ה', וַהֲקִמֹתִי אֶת הַדָּבָר הַטּוֹב אֲשֶׁר דִּבַּרְתִּי אֶל בֵּית יִשְׂרָאֵל וְעַל בֵּית יְהוּדָה. בַּיָּמִים הָהֵם וּבָעֵת הַהִיא אַצְמִיחַ לְדָוִד צֶמַח צְדָקָה, וְעָשָׂה מִשְׁפָּט וּצְדָקָה בָּאָרֶץ. בַּיָּמִים הָהֵם תִּוָּשַׁע יְהוּדָה וִירוּשָׁלַםִ תִּשְׁכּוֹן לָבֶטַח, וְזֶה אֲשֶׁר יִקְרָא לָהּ ה' צִדְקֵנוּ. כִּי כֹה אָמַר ה': לֹא יִכָּרֵת לְדָוִד אִישׁ יֹשֵׁב עַל כִּסֵּא בֵית יִשְׂרָאֵל. וכך כתב הראי\"ה קוק: הנטייה הלאומית המעשית של כנסת ישראל היא לבושה החיצון של הנטייה הרוחנית שלה, והאחרונה היא אורה ונשמתה של הראשונה. שתיהן יחד ממקור אלוהים חיים הינן יוצאות, וממעיין האמת והאמונה האלוהית נובעות. הערות 113 על פי תרגום יונתן שם 114 ברכות, פרק ד הלכה ג, ופרק ה הלכה ג 115 פרי עץ חיים, שער העמידה, פרק יט 116 אורח חיים, סימן קיח, ד\"ה י\"ד 117 תלמוד בבלי, ברכות מט. 118 ירמיהו לג יד-יז 119 אורות, אורות ישראל, ו א"],[3,"s10","טוֹב הַלְּבָנוֹן","– על פי לשון הכתוב בתפילת משה: \"אֶעְבְּרָה נָּא וְאֶרְאֶה אֶת הָאָרֶץ הַטּוֹבָה אֲשֶׁר בְּעֵבֶר הַיַּרְדֵּן, הָהָר הַטּוֹב הַזֶּה וְהַלְּבָנֹן\" (דברים ג כה); ופירש שם רש\"י: \"הָהָר הַטּוֹב הַזֶּה – זו ירושלים, וְהַלְּבָנֹן – זה בית המקדש. על פי זה, פירוש הכינוי 'טוֹב הַלְּבָנוֹן' הוא: ירושלים, שנקראת 'הָהָר הַטּוֹב', שבה שוכן ה'לְבָנוֹן'. בספר מלכים, המקדש מכונה כך בפירוש: \"וַיִּבֶן אֶת בֵּית יַעַר הַלְּבָנוֹן\" (מלכים א' ז ב). על פי הפשט, הוא נקרא כך על שם 'יער הלבנון' שממנו הובאו העצים לבניינו (כמסופר שם, פרק ה). יער זה, שהיה בצפון הארץ (באזור לבנון של ימינו), ונזכר בגבולות הארץ בספר יהושע (ט א, ועוד), היה ידוע כמקום עצי ארזים גבוהים וחסונים (\"וְעַל כָּל אַרְזֵי הַלְּבָנָוןֹ הָרָמִים וְהַנִּשָּׂאִים\" – ישעיהו ב יג), כמקום גפנים מובחרים (\"זִכְרוֹ כְּיֵין לְבָנוֹן\" – הושע יד ח), פרחים (וּפֶרַח לְבָנוֹן\" – נחום א ד), ריח טוב (\"וְרֵיחַ שַׂלְמֹתַיִךְ כְּרֵיחַ לְבָנוֹן\" – שיר השירים ד יא), ומראה כללי מרשים (\"מַרְאֵהוּ כַּלְּבָנוֹן\" – שם ה טו). הכתוב בחר לכנות את המקדש דווקא על שם יער הלבנון, כדי לרמוז שקיים קשר בינו לבין מהותו של בית המקדש. על פי התיאור דלעיל של אותו יער, מובן מדוע המקדש מכונה על שמו – המקדש הוא מקור החיות, היופי, והרעננות, של העולם כולו; וכך נאמר בגמרא: אמר רבי יצחק בן טבלאי: למה נקרא שמו 'לבנון'? שמלבין עוונותיהם של ישראל. אמר רב זוטרא בר טוביה: למה נקרא שמו יער, דכתיב: \"בֵּית יַעַר הַלְּבָנוֹן\"? לומר לך: מה יער מלבלב, אף בית המקדש מלבלב; דאמר רב הושעיא: בשעה שבנה שלמה בית המקדש, נטע בו כל מיני מגדים של זהב והיו מוציאין פירות בזמניהן. בין אם נבין את דברי רב זוטרא כפשוטם ובין אם באופן אליגורי, נראה שזהו הרעיון הטמון בהם; בית המקדש אינו מקום עבודה גרידא של הקרבת קורבנות והקטרת קטורת. כמקום השראת השכינה בעולם, הוא מהווה צינור בין הקב\"ה – מקור השפע – לבין העולם, שמקבל אותו. עבודת המקדש היא 'הוראות ההפעלה' של מערכת החיבור הרוחני בין הבורא לברואיו, שמכוחה מושפעת לעולם כולו וליושביו גם ברכה גשמית, בבניין העולם וצמיחת הצומח. וכך מתאר הפייטן רבי משולם בן קלונימוס את השפעת החיות והרעננות לעולם כולו מחמת עבודת בית המקדש ביום הכיפורים: תְּלוּלֵי רוּם הִרְעִיפוּ זַרְזִיף טַלָּם / תַּלְמֵי שָׂדַי רַווּ תֵּת יְבוּלָם. תּוֹדָה נָתְנוּ אוֹסְפֵי זֶרַע שָׁלוֹם / תְּהִלָּה בִּשְּׂרוּ נוֹשְׂאֵי אַלֻמּוֹת בְּרֶנֶן. הערות 120 'הר' מופיע לפעמים במובן של אזור הררי; ראה מסכת שביעית, פרק ט, משנה ב 121 ומקור דבריו בתלמוד בבלי, ברכות מח:, יומא לט: 122 יומא שם 123 פוסק ופייטן בן תקופת הגאונים, פעל באזור גרמניה ואיטליה. 124 פיוט 'אמיץ כוח', מתוך תפילת מוסף ליום הכיפורים"],[3,"s11","יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ","– כינוי להר הבית, כלשון הכתוב: \"יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ, הַר צִיּוֹן יַרְכְּתֵי צָפוֹן\" (תהילים מח ג). פירושה המקורי של המילה 'נוף' הוא 'מחוז', ופירוש הביטוי 'יְפֵה נוֹף' הוא: המקום היפה ביותר במחוז, מחמת בית המקדש העומד בו. פירוש נוסף: 'יְפֵה נוֹף' מלשון תנופה והרמה, על שם גובהו של 'הַר צִיּוֹן', המבליט את יופיו של בית המקדש המתנוסס בראשו. גובה זה מבטא משמעות רוחנית: בית המקדש הוא המוקד הרוחני של העולם כולו, המאיר ומשפיע ברכה לכל יושביו. על הכינוי 'מְשׂוֹשׂ כָּל הָאָרֶץ' כתב רש\"י (שם): \"ששם שוחטין חטאות ואשמות, ומי שהיה עצב על עבירות שבידו – מביא חטאות ואשמות ומתכפר לו, והוא יוצא משם שמח\". אין שמחה כשמחת התשובה והכפרה, שעל ידן האדם מתנקה מזוהמת החטא שדבקה בנפשו ומתקרב לעצמיותו ולבוראו; וכך כתב הראי\"ה קוק: [...] והאדם שם חטאו נוכח פניו ומתחרט עליו, ומצטער על אשר נוקש בפח החטא, ונפשו מטפסת ועולה עד שהוא משתחרר מהעבדות החטאית, ומרגיש בקרבו את החירות הקדושה, הנעימה מאוד לנפשו הנהלאה [=העייפה]. והוא הולך ומתרפא, וזהרי אורה של שמש החסד, חסד עליון, שולחים אליו את קוויהם, והוא הולך ומתאשר, הולך ומתמלא עונג ודשן פנימי [...]. הערות 125 רד\"ק שם 126 בעניין חשיבות יופיו של בית המקדש, ראה לעיל עמ' 71 127 פירוש רשב\"ם לתהילים מכתב-יד, העומד לראות אור בקרוב בע\"ה על ידי סבי הרב פרופ' אהרון מונדשיין הי\"ו. 128 אורות התשובה, פרק ג"],[3,"s12","כְּלִילַת יֹפִי","– כינוי לירושלים, כלשון הכתוב: \"הֲזֹאת הָעִיר שֶׁיּאֹמְרוּ כְּלִילַת יֹפִי מָשׂוֹשׂ לְכָל הָאָרֶץ\" (איכה ב ו); ופירושו: שיא היופי, או: כוללת את כל מיני היופי, או: כולה יפה (כמו: \"וְעָשִׂיתָ אֶת מְעִיל הָאֵפוֹד כְּלִיל תְּכֵלֶת\" [שמות כח לא] – כולו תכלת). כינוי זה מופיע גם בנבואת יחזקאל, ביחס לעיר אחרת: וַיְהִי דְבַר ה' אֵלַי לֵאמֹר: וְאַתָּה בֶן אָדָם, שָׂא עַל צֹר קִינָה. וְאָמַרְתָּ לְצוֹר הישבתי (קרֵי: הַיֹּשֶׁבֶת) עַל מְבוֹאֹת יָם, רֹכֶלֶת הָעַמִּים אֶל אִיִּים רַבִּים; כֹּה אָמַר אֲדֹנָי יֱהֹוִה: צוֹר – אַתְּ אָמַרְתְּ: אֲנִי כְּלִילַת יֹפִי . בְּלֵב יַמִּים גְּבוּלָיִךְ, בֹּנַיִךְ כָּלְלוּ יָפְיֵךְ. ופירש רבי יוסף קרא: \"אַתְּ אָמַרְתְּ אֲנִי כְּלִילַת יֹפִי\" – אבל אחרים אין אומרים עלייך 'כלילת יופי'. אבל ירושלים הכול אומרים עליה 'כלילת יופי', הדא הוא דכתיב [=זהו מה שכתוב]: \"הֲזֹאת הָעִיר שֶׁיּאֹמְרוּ כְּלִילַת יֹפִי מָשׂוֹשׂ לְכָל הָאָרֶץ\". \"בְּלֵב יַמִּים גְּבוּלָיִךְ, בֹּנַיִךְ כָּלְלוּ יָפְיֵךְ\" – כלומר: מה תתהללי בכלילת יופייך, וכלילת יופייך אין יוצא ממך [...] אבל ירושלים הכול ממנה, לפיכך היא ראויה ליקרות 'כְּלִילַת יֹפִי'. אותה נבואה מתארת בססגוניות רבה את יופיה של צור, שנבע מכך שהיתה מלאה בסחורות רבות ומגוונות שהובאו אליה על ידי סוחרים מכל מדינות תבל, כמפורט שם. אך יופי זה – אומר הנביא – אינו שייך לצור באופן מהותי; הוא אינו נובע מתוכה, אלא מיובא מבחוץ – \"בֹּנַיִךְ כָּלְלוּ יָפְיֵךְ\"; הסוחרים הבונים את צור – דהיינו שמתחזקים אותה כלכלית על ידי המסחר, הם אלו שיוצקים לתוכה את כל יופיה. לעומת זאת, ירושלים – יופיה אינו חיצוני לה; זהו חן מיוחד הנסוך עליה מחמת קדושתה, המשתלב עם יופיה החיצוני. זהו הקשר הפנימי שבין 'כְּלִילַת יֹפִי' לבין 'מְשׂוֹשׂ כָּל הָאָרֶץ': סגולתה האלוהית הפנימית היא העושה אותה ל'כְּלִילַת יֹפִי', כשם שהיא עושה אותה למקום המתאים להקרבת קרבנות, שבעטיים נתכנתה 'מְשׂוֹשׂ כָּל הָאָרֶץ', כמבואר לעיל. הערות 129 רש\"י, יחזקאל כז ג 130 רד\"ק שם 131 יחזקאל שם, א-ד 132 מחכמי צרפת, (ד'תת\"י-ד'תת\"פ בקירוב). תלמיד רש\"י ופרשן מקרא ופיוטים."],[3,"s13","לִינַת הַצֶּדֶק","– כינוי לירושלים, על פי לשון הכתוב: \"אֵיכָה הָיְתָה לְזוֹנָה קִרְיָה נֶאֱמָנָה, מְלֵאֲתִי [=מלאת] מִשְׁפָּט, ∆צד∆ק י»לƒין בָּהּ, וְעַתָּה – מְרַצְּחִים\" (ישעיהו א כא). הנביא מוכיח את אנשי ירושלים על נטותם מדרך הצדק והמוסר שהצטיינו בה בעבר, והתדרדרותם המוסרית-חברתית עד כדי שפיכות דמים. איזכורו של כינוי זה, נועד להזכיר את ימיה הקדומים של ירושלים, בהם לן בה הצדק – דהיינו ששכן בה בקביעות כבן-בית, כאדם הלן בביתו; להזכיר לפני הקב\"ה זכות ראשונים, ולהזכיר לעצמנו את השאיפה לכינון מערכות משפט וחברה המיוסדות על אדני הצדק והמוסר."],[3,"s14","מָכוֹן לְשִׁבְתֶּךָ","– כלשון הכתוב בסוף 'שירת הים': \"תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךָ, מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ ה', מִקְּדָשׁ – אֲדֹנָי, כּוֹנְנוּ יָדֶיךָ\" (שמות טו יז). ניתן לפרש ש'הַר נַחֲלָתְךָ – מָכוֹן לְשִׁבְתְּךָ' הוא ירושלים, וניתן לפרש שהוא הר הבית; בין כך ובין כך פירוש הכינוי הוא: מקום המוכן ומיועד 'לְשִׁבְתְּךָ' = השראת שכינתך בקביעות."],[3,"s15","נָוֶה שַׁאֲנָן","– כינוי לירושלים, כלשון הכתוב: \"חֲזֵה צִיּוֹן קִרְיַת מוֹעֲדֵנוּ, עֵינֶיךָ תִרְאֶינָה יְרוּשָׁלַם נָוֶה שַׁאֲנָן\" (ישעיהו לג כ). פסוק זה מופיע בתוך נבואת ישעיהו על מפלת צבא אשור שצר על ירושלים בתקופת מלכות חזקיהו, ותוכנו הוא שלאחריה ירושלים תהיה נווה (=מקום מגורים) בטוח ושאנן מהאיום שריחף עליה מחמת צבא אשור. בתפילתנו על ירושלים בכינוי זה, אנו מזכירים לפני הקב\"ה את זכות דורו של חזקיהו, ומתפללים שתעמוד אף לנו כשם שהגנה על אותו דור מצבא אשור, כנבואת ישעיהו: וְהָיָה בַּיּוֹם הַהוּא יָסוּר סֻבֳּלוֹ מֵעַל שִׁכְמֶךָ, וְעֻלּוֹ מֵעַל צַוָּארֶךָ, וְחֻבַּל עֹל מִפְּנֵי שָׁמֶן . \"וְחֻבַּל עֹל\" – [של] סנחריב [...] מפני שמנו של חזקיהו שהיה דולק בבתי כנסיות ובבתי מדרשות, שהשיאם [=גרם להם, לבני דורו] לעסוק בתורה. אנו מזכירים גם לעצמנו את מעלתו של אותו דור ואת מסירותו לתורה ולמצוות, ומתוך כך מחזקים בקרבנו את השאיפה להידמות להם ובכך להיות אף אנו ראויים לישועה. הערות 133 ישעיהו כז י 134 רש\"י שם"],[3,"s16","סֻכַּת שָׁלֵם","– כינוי לבית המקדש, על פי לשון הכתוב:\" וַיְהִי בְשָׁלֵם [=בירושלים] סֻכּוֹ, וּמְעוֹנָתוֹ בְצִיּוֹן\" (תהילים עו ג). השם 'שָׁלֵם' הוא שמה הקדום של ירושלים, המופיע פעם אחת נוספת במקרא: \"וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן, וְהוּא כֹהֵן לְאֵל עֶלְיוֹן\" (בראשית יד יח); שם זה מבטא את שלימותה הרוחנית של ירושלים. לאחר מכן שמה השתנה ל'ירושלים' כצירוף של שני השמות שניתנו לה: השם 'יִרְאֶה' שניתן לה על ידי אברהם, כמו שכתוב: \"וַיִקְרָא אַבְרָהָם שֵׁם הַמָּקוֹם הַהוּא: ה' יִרְאֶה\" (שם כב יד), והשם 'שָׁלֵם' (ואכן הכתיב המקובל במקרא הוא 'ירושלם'). הכינוי 'סֻכַּת שָׁלֵם' מבטא, איפוא, את שכינת הקב\"ה בירושלים מאז ומעולם, כבר בזמן שבו עדיין היתה נקראת 'שלם'. משום כך אומר הפסוק: \"וַיְהִי בְשָׁלֵם סֻכּוֹ\" – הסוכה היא מקום מגורים ארעי, וכן שכינת הקב\"ה ב'שלם' היתה ארעית, כביכול, עד לשלב שנבנה בה המעון – בית המקדש, שאז שכן בה בקביעות, ועל זמן זה נאמר: \"וּמְעוֹנָתוֹ בְצִיּוֹן\". אפשר שזוהי כוונת המדרש: רבי ברכיה בשם רבי חלבו אמר: עד שהוא 'שלם' [=בזמן שהעיר עדיין נקראה 'שלם'], עשה לו הקדוש ברוך הוא סוכה והיה מתפלל בתוכה, שנאמר:\" וַיְהִי בְשָׁלֵם סֻכּוֹ, וּמְעוֹנָתוֹ בְצִיּוֹן\". ומה היה אומר? \"יהי רצון שאראה בבניין ביתי\". מדרש זה מלמדנו שאף טרם נבנה המקדש, שרתה השכינה בירושלים, אך ב'סוכה' – באופן ארעי. על גבי זאת, הוא מלמדנו דבר נוסף: בתוך הסוכה שעשה לו ב'שלם', הקב\"ה 'התפלל' וציפה לבניית בית המקדש. משמעות הדבר היא, שעל אף שהשכינה שרתה בירושלים קודם בניית המקדש ואף לפני שאברהם קידש את המקום, לא היה זה אלא בבחינת 'תפילה', דהיינו הכנה והכשרה – להתגלות האלוהית השלימה שתהיה בבית המקדש. מכל מקום, עצם העובדה ששרתה בה השכינה אף כשלא היתה מוכשרת לגילוי אלוהי באופן השלם, מראה שסגולתה וקדושתה של ירושלים טבועות במהותה מטבע בריאתה, ועל כך רומז הכינוי אותו אנו מזכירים כאן: 'סֻכַּת שָׁלֵם'. הערות 135 על פי מדרש בראשית רבה, פרשה נו, אות י 136 בראשית רבה, שם"],[3,"s17","עֲלִיַּת שְׁבָטִים","– כינוי לירושלים, על פי לשון הכתוב: \"יְרוּשָׁלִַם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ יַחְדָּו. שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, לְהֹדוֹת לְשֵׁם ה'\" (תהילים קכב ג-ד). פירוש הכתוב הוא, שבזמן שירושלים בנויה, כל שבטי ישראל עולים אליה יחדיו בשלושת הרגָלים, ודבר זה מעיד על אחדותו של עם ישראל: כל פרטיו הם כגוף אחד, וירושלים היא הלב של אותו גוף, המזרים חיוּת לכל אבריו. כשכל ישראל מתקבצים לירושלים לתכלית אחת – 'לְהֹדוֹת לְשֵׁם ה'' – אזי יונק הגוף – כלל ישראל, שפעת חיים מליבו, מקור הקודש – ירושלים, ואחדותו מתגלה במלוא תפארתה. כל אחד משבטי ישראל מגלם פן מיוחד מתוך האופי הכללי של האומה, ולכל שבט תפקיד שונה ודרך המיוחדת לו בעבודת ה'; כשם שבגוף קיימים איברים שונים ולכל אחד תפקיד ותכונות משלו, ואין זה פוגם באחדותו של הגוף, כך הוא גם ב'גוף' של עם ישראל. מה שמאחד את הפרטים בעם ישראל הוא שורש נשמתם האלוהי המשותף, כדברי בעל ה'תניא': \"ולכן נקראו כל ישראל אחים ממש, מצד שורש נפשם בה' אחד, רק שהגופים מחולקים\"; משום כך, כשמתקבצים כל 'שִׁבְטֵי יָהּ' לירושלים, כדי 'לְהֹדוֹת לְשֵׁם ה'' ולבטא בכך את הקשר שביניהם לבין הקב\"ה – מתחברים הם לנקודת האחדות השורשית – הקב\"ה, וכך מופיעה אחדותם הפנימית. זוהי מעלתה המיוחדת של ירושלים, הטמונה בכינוי 'עֲלִיַּת שְׁבָטִים'. הערות 137 על פי מלבי\"ם שם 138 רבי שניאור זלמן מלאדי (תק\"ה-תקע\"ג), מייסד חסידות חב\"ד, מחבר ספר ה'תניא' ו'שולחן ערוך הרב'. 139 תניא, פרק לב, ד\"ה והנה"],[3,"s18","פִּנַּת יִקְרַת","– כלשון הכתוב: \"הִנְנִי יִסַּד בְּצִיּוֹן אָבֶן, אֶבֶן בֹּחַן פִּנַּת יִקְרַת מוּסָד מוּסָד\" (ישעיהו כח טז). כוונת הפייטן היא לבית המקדש, מלשון: \"לִהְיוֹת עַל הַמִּגְדָּלִים וְעַל הƒפּנּוֹת \" (דברי הימים ב' כו טו) – דהיינו מבנה חזק ומבוצר, אך מאידך גיסא הוא גם 'יִקְרַת' – בעל מראה חזותי של יקר ופאר. הערות 140 המפרשים על אתר מסבירים שהפסוק מתייחס למלכות בית דוד, שהקב\"ה חיזקה אז ביד חזקיהו המלך. אך קשה לפרש שלכך כיוון הפייטן, מאחר ויתר הכינויים בפיוט מתייחסים לירושלים או לבית המקדש. ייתכן שבחר בכינוי זה כדי לרמוז על הקשר המהותי שבין מלכות בית דוד לירושלים, כמבואר לעיל (עמ' 72-71). 141 'מצודת ציון' על אתר ובצפניה א טז"],[3,"s19","צִיּוֹן הַמְצֻיֶּנֶת","– מלשון 'ציוּן' (=סימון) – מסומנת כדבר ייחודי (כמו שכתוב ב'הגדה של פסח': \"מְלַמֵּד שֶׁהָיוּ יִשְׂרָאֵל מְצֻיָּנִים שָׁם\", שפירושו – מסומנים כשונים מסביבתם המצרית, על ידי לבושם ושפתם הייחודיים). בשימוש במטבע זה של 'לשון נופל על לשון' הפייטן רומז על קשר בין שמה של העיר 'ציון' לבין אופייה המיוחד, שכן שם זה מציין את המרכז הרוחני של ירושלים, שהוא המייחד ומבדיל אותה משאר הערים – הלוא הוא מקום המקדש ומושב הסנהדרין (לעומת השם 'ירושלים', המציין את אזורי המגורים שבעיר). הראי\"ה קוק מבאר את ההבדל בין 'ציון' ל'ירושלים' באופן שונה: 'ציון' ו'ירושלים' הן זו אצל זו. מאז מראשית תולדותינו התבלט שם 'ציון' אצל ההבטאה של מלכותנו, כוחנו העולמי, שהוא הנהו גם כן ודאי קדוש מצד עצמו, והוא משמש את כל המטרות הקדושות של עמנו, שהוא הווה ויהיה לעד ממלכת הכוהנים וגוי הקדוש של העולם כולו. אמנם 'ירושלים' מבטאת בהבלטתה את המטרה של קדושתנו מצד עצמה בתור המגמה היותר גבוהה באידאליותה של הוויתנו הישראלית, בעד עצמנו ובעד האנושיות כולה. המקום של בית המקדש – בית תפילה העתיד של כל העמים, המקום שבו ישבו הסנהדריה הגדולה אשר ממנה יצאה ותצא תורה לכל ישראל – זה מציין השם 'ירושלים'. לדבריו, השם 'ציון' מבטא את הכוח המדיני-פוליטי של ישראל, והשם 'ירושלים' – את כוחו הרוחני. לפירוש זה, הכינוי 'צִיּוֹן הַמְצֻיֶּנֶת' מתייחס באופן מיוחד למלכות ישראל שמשכנה בציון, 'הַמְצֻיֶּנֶת' = מיוחדת ושונה ממלכויות אומות העולם: אצלן, מוסד המלכות או הממשלה מהווה אמצעי טכני, שתפקידו לטפל בצורכי העם; אך אצל ישראל תפקיד המלכות הוא ליישם את האידיאלים הרוחניים החרוטים על דגלו של עם ישראל, בקרבו ובקרב העולם כולו. הערות 142 מלבי\"ם, ישעיהו מא כז, ועוד. ניתן להביא סיוע לפירושו מנוסח ברכת המזון: \"וְעַל יְרוּשָׁלַיִם עִירֶךָ, וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ\". 143 אגרות הראי\"ה, חלק ג, אגרת תתסז, עמ' קמח"],[3,"s20","קֹדֶשׁ הַקֳּדָשִׁים","– הושע נא את קודש הקודשים, בכך שתבנהו ותשיב את שכינתך לתוכו. בקשה זו כוללת בתוכה משמעות עמוקה המתייחסת למדרגה מיוחדת של קדושה אותה מבטא בית קודש הקודשים: מדרגה רוחנית הנקראת 'קודש הקודשים', שעליונה היא יותר ממדרגת ה'קודש'. משמעות מדרגת 'קודש הקודשים' היא: קדושה המופיעה אף בתוך מדרגת החולין, המרוממת את החול ומעלה אותו אל הקודש, כפי שכתב הראי\"ה קוק: [...] יסוד קודש הקודשים, שהוא נושא בקרבו את הנושא של הקודש ואת הנושא של החול, את החומר ואת הצורה, בצורה עליונה אידיאלית, באחדות מעולה. בבית קודש הקודשים היו מונחים לוחות הברית וספר התורה; התורה היא זו שמדריכה את האדם ואת האומה כיצד לנהוג בחיי המעשה על כל פרטיהם, ובכך ליישם בחיי החולין את את האידיאלים האלוהיים והערכים הנשגבים השייכים ל'קודש'. על ידי קיום מצוות התורה והכוונת כל המעשים לשם שמיים – האדם מרומם את חייו הפרטיים, והאומה – את חייה הכלליים, למדרגת 'קודש קודשים'. בצורת חיים כזו, האדם אינו מפולג בין עולם הקודש לעולם החול, אלא כל כולו שייך לתחום הקדושה, ואליו הוא מרומם את כל רצונותיו ופעולותיו: כשיוצאים מעולם הקודש לעולם החול, או להיפך, בלא הדרגה, מתארע לנשמה מה שמתארע לגוף ולחושיו כשהם יוצאים מהיפוך אל ההיפוך: מאפילה לאורה, מחמה לצינה: – צער, ולפעמים גם נזק. שתי הגנות ישנן נגד היזק זה: או לסדר את היציאה בהדרגה מקודש עליון לקודש תחתון ממנו, וכן הלאה, עד שבאים אל התוכן של חול; זאת היא מידת כל אדם. אבל עוד מדרגה יותר עליונה נמצאת, והיא: הרמת החול כולו אל הקודש. זאת היא מדרגת המעולים שבצדיקים, והמידה הצפויה לָעולם בעתידו הנשגב, \"בַּיּוֹם הַהוּא יִהְיֶה עַל מְצִלּוֹת הַסּוּס קֹדֶשׁ לַה'\" (זכריה יד כ). לעתיד לבוא, מדרגת חיים עליונה זו – 'קודש הקודשים', שכעת היא נחלתם של 'המעולים שבצדיקים' – תהיה נחלת הכלל, ותתפשט בכל המציאות, כמתואר בפסוק המובא. בעידן הנוכחי, הכתובת 'קֹדֶשׁ לַה'' מופיעה על ציץ הזהב של הכוהן הגדול בלבד; אך בעת הגאולה השלימה, המציאות כולה תתקדש ותתעלה למדרגה נשגבה, ובכל פרט מפרטי הבריאה יתגלה האור האלוהי, כך שכביכול אפילו על 'מְצִלּוֹת הַסּוּס' (=פעמונים התלויים בצווארו) יהיה כתוב: 'קֹדֶשׁ לַה''. וכך מתוארת מציאות זו בדברי הרב יעקב משה חרל\"פ: הגאולה העתידה תהיה גאולה לכל העולמים כולם וכל הנמצא בהם, גם הכוכבים והגלגלים וצבא השמיים, וגם כל המינים שבבריאה: הדומם והצומח, החי והמדבר, כולם ייגאלו בחירות עולמים, וכולם יכירו את שם ה' בעומק החכמה הבינה והדעת, \"וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ\" (זכריה יד ט). \"אָז יְרַנְּנוּ כָּל עֲצֵי יָעַר\" (תהילים צו יב) – כל מה שבהוויה, אפילו גרגיר חול, ישיג צורה אחרת לגמרי; רוח הקודש והנבואה תשרה על הכול; ואור ה', על כל עומק הגילויים שלו ורוחבם – יתגלה בכול, עם הכול ועל הכול. אין הפה יכול לבטא ואין המוח יכול להשיג את הגדוּלה שתתגלה אז [...]. ואם כל כך גדוֹלה תהיה הברייה היותר קטנה, כל שכן שאין שיעור להשגת שאר היצורים ועלייתם, ועל אחת כמה וכמה עלייתם של ישראל עם קדושו. בשורה זו: 'הוֹשַׁע נָא קֹדֶשׁ הַקֳּדָשִׁים', מלבד תפילתנו על בניית קודש הקודשים הפיזי, אנו מתפללים על כך שנגיע יחד עם העולם כולו למציאות נשגבה זו, בה חיינו הפרטיים והלאומיים יהיו שייכים למדרגת 'קֹדֶשׁ הַקֳּדָשִׁים', והמציאות כולה תהיה מוארת באור ה'. הערות 144 אורות הקודש, חלק א, עמ' סד; וראה עוד: שם, חלק ג, עמ' רכח 145 הרצי\"ה קוק כותב בהקדמתו לספר 'אורות': \"שפע קודש הקודשים של ספר האורות הזה\", שכן נושא ספר זה הוא חייו הלאומיים של עם ישראל בצורתם האידיאלית, בה הוא מיישם את ערכי הקודש הנשגבים בחייו המעשיים. וראה גם: סידור 'עולת ראיה', חלק ב, עמ' ג-ד, לגבי מגילת 'שיר השירים', עליה נאמר במשנה: \"אמר רבי עקיבא: [...] אין כל העולם כולו כדאי כיום שניתן בו שיר השירים לישראל; שכל הכתובים קודש, ושיר השירים - קודש קודשים\" (מסכת ידיים, פרק ג, משנה ה). 146 עוד בעניין זה, ראה להלן עמ' 202-201 147 אורות הקודש, חלק ב, עמ' שיא (ההדגשה במקור). 148 מפרשים על אתר 149 'מי מרום' – 'ממעייני הישועה', עמ' לא"],[3,"s21","רָצוּף אַהֲבָה","– כלשון הכתוב: \"אַפִּרְיוֹן עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה מֵעֲצֵי הַלְּבָנוֹן. עַמּוּדָיו עָשָׂה כֶסֶף, רְפִידָתוֹ זָהָב, מֶרְכָּבוֹ אַרְגָּמָן, תּוֹכוֹ ר»צוּף אה»בה מִבְּנוֹת יְרוּשָׁלִָם\" (שיר השירים ג ט-י); על פי חלק מהמפרשים, הפסוק מתייחס לבית המקדש, ומדמה אותו לאפריון. לביטוי 'רָצוּף אַהֲבָה' המופיע בפסוק נאמרו שני הסברים: א. מלשון רצף ומילוי – בית המקדש מלא בדברים המבטאים את אהבת הקב\"ה לישראל. ב. מלשון גחלים (כמו בישעיהו ו ו: \"וַיָעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים וּבְיָדוֹ רִצְפָּה\" = גחלת, וכן במלכים א' יט ו: \"עֻגַת רְצָפִים\" = הנאפית על גחלים) – בית המקדש, מקום החיבור של הקב\"ה עם כלל ישראל, מלא באהבה היוקדת שביניהם, \"ודרך המקרא לכנות הפלגת האהבה באש הבוער ומתלהב, וכן: 'רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶתְיָה' (שיר השירים ח ו)\". המלבי\"ם מפרש, על פי דרך פרשנותו לאורך המגילה, שעל אף שהפסוק עוסק בבית המקדש, הנמשל שלו הוא נפש האדם; חלקי המקדש והפרטים שבו מקבילים לחלקי הנפש ותכונותיה (ראה שם בפירוט), והאש היוקדת על המזבח – מסמלת את אהבת ה' הבוערת בתוככי נפש האדם, אף כשאינה מורגשת בפועל; וכך כתב הראי\"ה קוק: שלהבת אש הקודש של אהבת ה' הלוא בתוך הנשמה היא, תמיד בוערת היא, מחממת היא את הרוח, מאירה היא את החיים, ועינוגיה אין להם סוף; אין מידה מתארת את נועמם ומתקם. ומה אכזרי הוא האדם על עצמו, שהוא משתקע במחשכי החיים, מטריד עצמו בחשבונות רבים, ואת חיי החיים, את עדן יסוד החיים – הוא משכיח מלבבו [...]. דבר זה נגד כל טבע הנפש ונגד טבע ההוויה כולה הוא. בשורה זו טמונה גם בקשה אישית של המתפלל על עצמו, לקבלת סיוע ממרום ללבות את גחלי אהבת ה' הלוחשות בתוככי נפשו, ולהושיע בכך את המקדש הפנימי שבליבו, ה'רָצוּף אַהֲבָה'. הערות 150 רש\"י 151 לשון 'מצודת ציון', שיר השירים ג י 152 מידות הראי\"ה, ערך 'אהבה', אות ד"],[3,"s22","שְׁכִינַת כְּבוֹדֶךָ","– שכינת כבוד ה' בבית המקדש, שמאז החורבן פסקה משם, במובן מסוים, כמו שראה יחזקאל הנביא: \"וַיֵּצֵא כְּבוֹד ה' מֵעַל מִפְתַּן הַבָּיִת, וַיַּעֲמֹד עַל הַכְּרוּבִים. וַיִּשְׂאוּ הַכְּרוּבִים אֶת כַּנְפֵיהֶם וַיֵּרוֹמּוּ מִן הָאָרֶץ לְעֵינַי בְּצֵאתָם\" (יחזקאל י יח-יט). הערות 153 וראה הרחבה בנושא 'צער השכינה' ב'במבט כללי' על הפיוט הקודם."],[3,"s23","תֵּל תַּלְפִּיּוֹת","– על פי לשון הכתוב: \"כְּמִגְדַּל דָּוִיד צַוָּארֵךְ בָּנוּי לְתַלְפִּיוֹת\" (שיר השירים ד ד). 'צַוָּארֵךְ' הוא כינוי לבית המקדש; כשם שהצוואר הוא החיבור בין הגוף לראשו, כך המקדש מהווה חיבור בין הגוף – עם ישראל, לבין ראשו – הקב\"ה. חיותו של עם ישראל תלויה בקב\"ה כתלות הגוף בראש, וכן הקב\"ה הוא המורה לישראל את הדרך אשר ילכו בה ואת המעשה אשר יעשון, כמוח המשדר הנחיות לכל חלקי הגוף. הפסוק מדמה את בית המקדש ל'מִגְדַּל דָּוִיד' – מגדל גבוה ונאה שבנה דוד, שהיה ידוע בזמנם, והיה 'בָּנוּי לְתַלְפִּיוֹת' – \"בָּנוּי לנוי, להיות הכול מסתכלין בו ללמוד צורותיו ונוי מלאכת תבניתו, והוא מגיזרת: 'מַלְּפֵנוּ [=מלמדנו] מִבַּהֲמוֹת אָרֶץ' (איוב לה יא)\"; או: \"הוא מצודת ציון הנבנה להתלמד להולכי אורח, כי לפי רוב הגובה היה נראה למרחוק, והיה סימן להם לדעת אנה יפנו\". ניתן לראות שני פירושים אלה למילה 'תַּלְפִּיּוֹת', כמשלימים זה את זה ביחס למשמעות הביטוי כלפי בית המקדש: לעתיד לבוא כל באי עולם יעלו אליו כדי ללמוד את תורת ה', כמאמר הנביא ישעיהו: \"וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ: לְכוּ וְנַעֲלֶה אֶל הַר ה', אֶל בֵּית אֱלֹהֵי יַעֲקֹב, וְיֹרֵנוּ מִדְּרָכָיו, וְנֵלְכָה בְּאֹרְחֹתָיו, כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה וּדְבַר ה' מִירוּשָׁלִָם\" (ישעיהו ב ג). הפסוק רומז לשני תחומים אותם ילמדו הגויים מתורת ה': האמוני והמעשי. \"וְיֹרֵנוּ מִדְּרָכָיו\" – את ענייני האמונה הכלליים ('דרך' היא דרך ראשית, לעומת 'אורח' שהוא השביל שמסתעף ממנה – מלבי\"ם שם), \"וְנֵלְכָה בְּאֹרְחֹתָיו\" – נלך – כלומר: ננהג בפועל, על פי המצוות המעשיות, שהן הפרטים המסתעפים מתוך יסודות האמונה הכלליים ומהוות יישום שלהם בפועל. הפירוש הראשון (\"הכול מסתכלין בו ללמוד צורותיו\") מתייחס ללימוד האמונה היהודית – שנמשל בפסוק ליופיו של מגדל דוד; היופי והנוי אינם מיועדים למטרה מעשית כל שהיא, אלא הם עצמם התכלית. הפירוש השני (\"הנבנה למתלמד לעוברי אורח\") מתייחס להוראת המצוות המעשיות, שנמשלה בפסוק להכוונת מגדל דוד את עוברי האורח לדרכם הנכונה. שימוש הפייטן במילה 'תֵּל' רומז לדרשת חז\"ל על פסוק זה, ממנה למדו את הדרישה ההלכתית לפנות לכיוון המקדש בעת תפילת העמידה: \"בָּנוּי לְתַלְפִּיוֹת – תל שכל פִּיות פונים בו [=אליו]\". דרשה זו משתלבת יפה עם הפירוש על דרך הפשט; בית המקדש הוא מוקד הפעילות הרוחנית – הן הלימוד הן התפילה, ומהווה צינור להשפעת התורה – האמונית והמעשית – מהקב\"ה, וכן בכיוון ההפוך – להעלאת תפילות ישראל לפני אביהם שבשמיים. הערות 154 רש\"י ומצודת דוד על אתר 155 רש\"י שם 156 מצודת דוד, שם 157 תלמוד בבלי, ברכות ל."],[3,"s24","סיכום","לאחר שבפיוט הראשון בררנו את המטרה שכלפיה אנו מכוונים את רצונותינו ותפילותינו, בפיוט זה אנו מתחילים בבקשות עצמן, ובראשן: החזרת שכינת ה' לציון ובניין המקדש. בהמשך נתפלל גם על עם ישראל וצרכיו; אך ראשית כל עלינו לזכור, כי תכליתו של עם ישראל היא גילוי שם ה' בעולם, וזה יוכל להתבצע בשלימות רק באמצעות בית המקדש ושכינת הקב\"ה בו. ניתן לזהות את קו הסדר הכרונולוגי הנמשך לאורך הפיוט (למעט חריגות מעטות הנובעות, ככל הנראה, ממחוייבות הפייטן לסדר הא\"ב): התחלתו בבריאת העולם –'אֶבֶן שְׁתִיָּה', שכבר אז נבחר אותו מקום על ידי הקב\"ה להשראת השכינה – 'בֵּית הַבְּחִירָה', לאחר מכן מוזכרים כינוייו מהתקופה בה טרם נבנה בו המקדש – 'הַר הַמּוֹרִיָּה' ו'וְהַר יֵרָאֶה' בזמן אברהם, ו'גֹּרֶן אָרְנָן' ו'חָנָה דָּוִד' בימי דוד, ובחציו השני של הפיוט מוזכרים הכינויים המתאימים לתקופה בה עמד המקדש על מכונו. הכינוי האחרון – 'תֵּל תַּלְפִּיּוֹת' – רומז לתקופת הגלות, בה נידחי ישראל הפזורים בארבע כנפות הארץ מכוונים את תפילתם ללב האומה והעולם, למקום המקדש שחרב ונעשה תל שממה – \"תל שכל פיות פונים בו\"."],[3,"n92","הערה 92","דהיינו שאז היתה חנוכת המקדש (ככתוב במלכים א' פרק ח)."],[3,"n93","הערה 93","סוף הדרוש לשבת הגדול"],[3,"n94","הערה 94","אבן שלימה פרק יא, אות א, מתוך ביאורו לתיקוני זוהר, דף קכה."],[4,"piyut","נוסח הפיוט","הוֹשַׁע נָא אֶעֱרוֹךְ שׁוּעִי. לְבַל עוֹד תַּרְשִׁיעִי. בְּבֵית שַׁוְעִי. מַהֵר אֱלֹהֵי יִשְׁעִי. גִּלִּיתִי בַצּוֹם פִּשְׁעִי. נֶצַח לְהוֹשִׁיעִי. דְּרַשְׁתִּיךָ בּוֹ לְהוֹשִׁיעִי. שָׂא נָא עֲוֹן רִשְׁעִי. הַקְשִׁיבָה לְקוֹל שַׁוְעִי. עֲבוֹר עַל פִּשְׁעִי. וְקוּמָה וְהוֹשִׁיעִי. פְּנֵה נָא לְהוֹשִׁיעִי. זְכוֹר וְרַחֵם מוֹשִׁיעִי. צוּר צַדִּיק מוֹשִׁיעִי. חַי כֵּן תְּשַׁעְשְׁעִי. קַבֵּל נָא שַׁוְעִי. טוֹב בְּאֶנֶק שְׁעִי. רוֹמֵם קֶרֶן יִשְׁעִי. יוּחַשׁ מוֹשִׁיעִי. שַׁדַּי מוֹשִׁיעִי. כַּלֵּה מַרְשִׁיעִי. תּוֹפִיעַ וְתוֹשִׁיעִי. הוֹשַׁע נָא."],[4,"s1","על הפיוט","בפיוט זה אנו מזכירים את התשובה שעשינו ביום הכיפורים, את התפילות שנשאנו אז, ואת ההתרוממות הרוחנית שחווינו, ומתפללים להצלחתנו ליישם את כל אלה במשך השנה כולה, וכן להיוושע מצרות החיים ומועקותיהם, ובפרט אלה הרוחניות – הפרעות היצר לאדם לקיים את רצון בוראו כראוי."],[4,"s2","אֶעֱרוֹךְ שׁוּעִי","– אסדר את שוועתי ותפילתי, בְּבֵית שַׁוְעִי – במקום המיועד לכך – בית הכנסת. עריכת התפילה בבית הכנסת אינה רק עניין טכני של נוחות; בית הכנסת הוא 'מקדש מעט': יש בו משהו מההופעה של בית המקדש – מקום השראת השכינה וקירבת האדם לבוראו. לפיכך, התפילה בו פועלת את פעולתה על האדם ביתר שאת, וממילא היא קרובה יותר להתקבל לפני הקב\"ה, כדברי הגמרא: תניא, אבא בנימין אומר: אין תפילתו של אדם נשמעת אלא בבית הכנסת, שנאמר: \"לִשְׁמֹעַ אֶל הָרִנָּה וְאֶל הַתְּפִלָּה\" (מלכים א' ח כח) – במקום רינה שם תהא תפילה. אמר רבין בר רב אדא אמר רבי יצחק: מניין שהקב''ה מצוי בבית הכנסת, שנאמר: \"אֱלֹהִים נִצָּב בַּעֲדַת אֵל\" (תהילים פב א). משום כך אנו מציינים את העובדה שתפילתנו נערכת 'בְּבֵית שַׁוְעִי', ומבקשים מהקב\"ה שבעבור זאת יקבלנה ברצון. הערות 159 ראה תלמוד בבלי, מגילה כט.: \"'וָאֱהִי לָהֶם לְמִקְדָּשׁ מְעַט' (יחזקאל יא טז): אמר רבי יצחק: אלו בתי כנסיות ובתי מדרשות\". 160 דהיינו שתפילה בבית הכנסת קרובה יותר להתקבל. 161 שם, ברכות ו."],[4,"s3","גִּלִּיתִי בַצּוֹם פִּשְׁעִי","– גיליתי לפניך את פשעי, והתוודיתי ושבתי עליהם, בצום יום הכיפורים שהיה לפני ימים מספר; מכוח זה, אני מתפלל לזכות לסליחה וישועה, כמאמר הכתוב: \"מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ, וּמוֹדֶה וְעֹזֵב יְרֻחָם\" (משלי כח יג). רִבּוֹנוֹ שֶׁל עוֹלָם, מִנְהַג בֵּית דִּינְךָ הַצֶּדֶק לֹא כְּמִנְהַג בָּתֵּי דִינִין שֶׁל בְּנֵי אָדָם; שֶׁמִּדַּת בְּנֵי אָדָם – כְּשֶׁהוּא תּוֹבֵעַ אֶת חֲבֵירוֹ בְּמָמוֹן אֶל בֵּית דִּין אוֹ אֶל הַשּׁוֹפֵט, אִם יִכְפּוֹר – יִנָּצֵל מִן הַמָּמוֹן, וְאִם יוֹדֶה – מִתְחַיֵּב לִתֵּן; וּבֵית דִּינְךָ הַצֶּדֶק לֹא כֵן הוּא, אֶלָּא אִם יִכְפּוֹר אָדָם – אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ, וְאִם מוֹדֶה וְעוֹזֵב – אַתָּה מְרַחֲמֵהוּ. הערות 162 וידוי רב ניסים גאון, מתוך תפילת יום כיפור קטן"],[4,"s4","דְּרַשְׁתִּיךָ בּוֹ לְהוֹשִׁיעִי","– מאחר ו'גִּלִּיתִי בַצּוֹם פִּשְׁעִי', 'דְּרַשְׁתִּיךָ' = ביקשתי ממך, 'בּוֹ' – ביום הכיפורים – 'לְהוֹשִׁיעִי'; הן ישועה בענייני הגשמיות, הן ישועה בענייני הרוחניות: שתושיעני מהמצב הרוחני הירוד אליו הגיעה נפשי כתוצאה מהחטאים, וכן שתעזרני לעמוד בקבלותַי ולא לשוב על מעשים אלו. לאורך כל הפיוט, הבקשות השונות לישועה עשויות להתפרש במשמעות כפולה זו – בתחום הגשמיות ובתחום הרוחניות. ניתן גם לפרש: 'דְּרַשְׁתִּיךָ' = דרשתי וביקשתי אותך, את קרבתך, ביום הכיפורים, 'לְהוֹשִׁיעִי' – כדי שעל ידי כך אוושע. קרבת ה' זו, היא עצמה התשועה; נשמת האדם שואפת תמיד להתקרב למקורה – הקב\"ה, ולפיכך קירבת ה' היא ישועה עבורה – ישועה ממצב של ריחוק מהקב\"ה ושקיעות בענייני העולם החומרי, שאינו טבעי לה. עשרת ימי התשובה, ובפרט יום הכיפורים, הם ימים המסוגלים לכך ביותר, כדברי הגמרא: \" 'דּƒר¿שׁוּ ה' בְּהִמָּצְאוֹ' (ישעיהו נה ו) – אמר רבה בר אבוה: אלו עשרה ימים שבין ראש השנה ליום הכיפורים\". הערות 163 כמו: \"בְּכָל לִבִּי דְרַשְׁתִּיךָ\" – תהילים קיט י 164 תלמוד בבלי, ראש השנה יח."],[4,"s5","הַקְשִׁיבָה לְקוֹל שַׁוְעִי","– לאחר שהזכרתי את עבודות התפילה והתשובה שעשיתי ביום הכיפורים, בו 'גִּלִּיתִי' לפניך את פשעַי ו'דְּרַשְׁתִּיךָ' להושיעני מהם ומתוצאתיהם, כעת – בהמשך הפיוט – אני מוסיף להתפלל על האיכות של חיַי הרוחניים מכאן ולהבא: 'הַקְשִׁיבָה לְקוֹל שַׁוְעִי'. בקשה זו לקוחה מלשון הכתוב: \"הַקְשִׁיבָה לְקוֹל שַׁוְעִי מַלְכִּי וֵאלֹהָי, כִּי אֵלֶיךָ אֶתְפַּלָּל\" (תהילים ה ג); על עומק משמעותה של בקשה זו ניתן ללמוד מדברי המבי\"ט על פסוק זה: ואמר: 'הַקְשִׁיבָה לְקוֹל שַׁוְעִי', כלומר: גם לא תהיה בכוונה שלימה כראוי, אלא ב'קוֹל' – ראוי שתקשיב, כיוון שאני מכיר שאתה 'מַלְכִּי וֵאלֹהָי', ואליך תפילתי [...] ולזה אמר 'כִּי אֵלֶיךָ אֶתְפַּלָּל' – כיוון שאני מתפלל אליך, ראוי שתקשיב לקולי גם אם לא אדע לכוון בה. מכיוון שעיקר עניינה של התפילה הוא עצם הפנייה לקב\"ה, אף כשאינה נערכת בכוונה שלימה, יש לה ערך מצד ה'קוֹל' – עצם התפילה, והיא מקובלת לפני הקב\"ה. הערות 165 רבי משה בן יוסף מטראני (ר\"ס-ש\"מ), מחכמי צפת, פוסק ומקובל, כיהן כראש ישיבה ואב בית דין. 166 בית אלוהים, שער התפילה, פרק ד"],[4,"s6","סיכום","השורות הבאות מפרטות את התוכן של 'קוֹל שַׁוְעִי', שהוזכר בשורה הקודמת: וְקוּמָה וְהוֹשִׁיעִי – הביטוי 'קוּמָה' רומז לסוג הישועה עליה אנו מבקשים: לא סיוע נקודתי, כזה שהקב\"ה יכול לבצע בעודו 'יושב' במקומו, כביכול, אלא ישועה כזו שצריך 'לקום' כדי לבצעה – שינוי מוחלט ומקיף של המציאות, שיעשה אותה לכזו שלא נזדקק בה לישועות נוספות. בתחום הרוחני, בקשה זו מבטאת את השאיפה להגיע למצב בו כבר לא תהיינה לנו ההתמודדויות עם היצר שהיו בעבר. לא לעמוד בנסיונות – אלא להתעלות מעליהם. על האדם לשאוף לרומם את עצם רצונו – כך שרצון למעשים שליליים לא יתפוס מקום כלל בעולם הרצונות שלו, כפי שמבאר הרב אליהו דסלר בספרו 'מכתב מאליהו': וזהו עיקר עבודת האדם: לצאת מן החופשיות, מן הבחירה, מן המצב אשר האמת והשקר שווים לפניו – אל ההכרח: שיכיר בליבו השתעבדותו אליו יתברך וחיובו לישא העול הזה. אמנם יש מדרגה עוד גבוהה מזו, היינו: שיכיר כל כך שהרע שקר הוא ואינו מציאות כלל, עד שלא יהיה לו שום רצון אליו, ויאהב את הטוב לבדו בכל לבבו. במדרגה זו איננו מרגיש עוד הכרח, כי אין הכרח אלא בדבר שיש לו ניגוד [=התנגדות], אבל מה שיאהב האדם – לא שייך לומר שהוא מוכרח אליו. וזוהי מדרגת העושים מאהבה. ובמדרגה זו האדם הנהו החופשי באמת. כמובן שיש מדרגות רבות במידה זו; אצל כל אחד ישנם תחומים שעשיית הדבר הנכון בהם הוא מובן מאליו, ותחומים בהם הוא צריך להתמודד מול יצרו. מטרת האדם היא לרומם את רצונו עוד ועוד, מִדרגה לדרגה, ולהרחיב אצלו את מעגל הבחירות בטוב שהן בִתחום ה'מובן מאליו'; על כך בקשתנו: \"וְקוּמָה וְהוֹשִׁיעִי\". הערות 167 הרב אליהו דסלר (תרנ\"ב-תשי\"ד), כיהן כרב באנגליה ולאחר מכן כמשגיח רוחני בישיבת פוניבז' בבני ברק. נחשב לאחד מהוגי הדעות המרכזיים בציבור החרדי. 168 מכתב מאליהו חלק א, מהדורת תש\"ן, עמ' 117. להרחבה בנושא ראה שם, עמ' 120-111."],[4,"s7","זְכוֹר וְרַחֵם מוֹשִׁיעִי","– זכור את מידת רחמנותך, כלומר: הוציאנה לפועל, כמאמר הכתוב: \"זְכֹר רַחֲמֶיךָ ה' וַחֲסָדֶיךָ, כִּי מֵעוֹלָם הֵמָּה\" (תהילים כה ו). ניתן גם לפרש על פי הכתוב: \"הֲבֵן יַקִּיר לִי אֶפְרַיִם, אִם יֶלֶד שַׁעֲשֻׁעִים, כִּי מִדֵּי דַבְּרִי בּוֹ ז»כ…ר ∆אז¿¿כּר∆נּוּ עוֹד, עַל כֵּן הָמוּ מֵעַי לוֹ, ר≈חם ארח∆מנּוּ נְאֻם ה'\" (ירמיהו לא יט) – הזכירה עליה מדובר בפסוק, ועליה אנו מבקשים, היא זכירת הקשר העמוק שבין הקב\"ה לבין עם ישראל, כקשר בין אב לבנו – 'הֲבֵן יַקִּיר לִי אֶפְרַיִם' – הקיים גם בעיתות משבר וריחוק. זכירה זו היא שגורמת ל'רַחֵם אֲרַחֲמֶנּוּ', ועל כך תפילתנו – 'זְכוֹר וְרַחֵם מוֹשִׁיעִי'."],[4,"s8","חַי","– אתה ה', שאתה חי וקיים לעד, ומקור החיים, כֵּן תְּשַׁעְשְׁעִי – כך תשעשעני, דהיינו באותה המידה ש'דְּרַשְׁתִּיךָ בּוֹ לְהוֹשִׁיעִי'; כשם שהרביתי לשוב מחטאַי, לדרוש את קרבתך, ולבקש ממך סליחה וישועה – כך תרבה לשעשע את נפשי בעונג רוחני. הבקשה הקודמת מבוססת על הכתוב בו נאמר שעם ישראל הוא 'יֶלֶד שַׁעֲשֻׁעִים' – ילד שאביו משתעשע עימו, ובה ביקשנו מהקב\"ה שיזכור זאת וירחם עלינו. כעת אנו מבקשים שבעקבות זאת יוציא לפועל את סגולתנו כ'יֶלֶד שַׁעֲשֻׁעִים' – 'ישתעשע' עימנו, וישעשע אותנו בעבודתו, כפי שיבואר. השעשוע הוא עיסוק המתאים למצב בו האדם אינו טרוד, ויש לו פנאי נפשי להשתעשע לשם ההנאה עצמה. על בסיס הבקשה: 'וְקוּמָה וְהוֹשִׁיעִי' – ישועה מהצורך בהתמודדות תמידית עם היצר, אנו מוסיפים לבקש שבמצב כזה, בו נהיה בני חורין הנמשכים מעצמם אל הטוב – עבודת ה' תהיה עבורנו כשעשוע; לא מתוך התמודדות ומתח, אלא מתוך נחת והנאה. כשם שהשעשוע אינו אמצעי להשגת דבר אחר, אלא הוא עצמו התכלית – כך לימוד התורה וקיום המצוות ייעשו על ידינו מתוך אהבתם ואהבת ה', ולא מתוך כפייה עצמית או רצון לשכר. עבודת ה' כזו ממלאת את האדם חיים, שמחה, ורעננות, ועל כן אנו פונים כאן לקב\"ה בתואר 'חַי' – מקור החיים והחיוּת – ומבקשים שימלא את חיינו בשמחה וחיוּת. על כך אמר דוד: \"לוּלֵי תוֹרָתְךָ שַׁעֲשֻׁעָי – אָז אָבַדְתִּי בְעָנְיִי\" (תהילים קיט צב); לא נאמר 'לוּלֵי תוֹרָתְךָ', אלא 'לוּלֵי תוֹרָתְךָ שַׁעֲשֻׁעָי': לולי שהייתי נהנה מהעיסוק בתורה כמו משעשוע, ודבר זה היה ממלא אותי חיות ושמחה, 'אָבַדְתִּי בְעָנְיִי' – הייתי שוקע ביגון מחמת הצרות הרבות שעברו עלי. מי שנהנה מעבודת ה' – הרי שבכל תנאי ובכל מצב היא ממלאת אותו חיות ומעניקה לו כוח להמשיך הלאה. מתוך רצוננו להגיע למדרגה זו, אנו מבקשים: \"חַי, כֵּן תְּשַׁעְשְׁעִי\"."],[4,"s9","סיכום","השורות הבאות מהוות בקשה על גאולת כלל-ישראל: טוֹב, בְּאֶנֶק שְׁעִי – אתה ה', שהינך טוב, בשעה שאני אונק (=זועק) – שעֵה (=פנֵה) אלי ולתפילתי. אנקה/נאקה היא זעקה מתוך מצב של קושי קיצוני וייאוש – כמצבו של עם ישראל בגלות, מתוכו אנו מתפללים לקב\"ה שימהר את ביאת המשיח, כמפורש בשורה הבאה: הערות 169 ראה שמות ו ה: \"וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִצְרַיִם מַעֲבִדִים אֹתָם\"; תהילים קב כא: \"לִשְׁמֹעַ אֶנְקַת אָסִיר\"; איוב כד יב: \"מֵעִיר מְתִים יִנְאָקוּ וְנֶפֶשׁ חֲלָלִים תְּשַׁוֵּעַ\"."],[4,"s10","יוּחַשׁ מוֹשִׁיעִי","– ישנו הבדל בין 'מהר' לבין 'חוש': המהירות היא הקדמת הפעולה, וההחשה היא ביצוע הפעולה עצמה בזמן קצר. אנו מבקשים שאף לאחר תחילת תהליך ביאת הגואל, הוא 'יוּחַשׁ' – התהליך יתרחש בזמן קצר, והגאולה השלימה תבוא במהרה. הערות 170 ספר 'יאיר אור' למלבי\"ם, ערך 'מהר' 171 וכך פירש רד\"ק את הפסוק: \"בְּעִתָּה אֲחִישֶׁנָּה\" (ישעיהו ס כב) – כשיגיע העת המיועד לגאולה, אבצענה בזמן קצר. בדומה לזה פירש הגר\"א (אדרת אליהו, דברים לב לה) את נוסח הקדיש: \"בַּעֲגָלָא\" – במהרה, \"וּבִזְמַן קָרִיב\" – שכל שלבי הגאולה יוחשו ויתקיימו בזמן קרוב."],[4,"s11","כַּלֵּה מַרְשִׁיעִי","– כלה את היצר הרע הגורם לנו לנהוג ברשעות ולחרוג מקיום רצונך בשלימות. לאחר ש'יוּחַשׁ מוֹשִׁיעִי' ותבוא הגאולה השלימה, יעבור היצר הרע מן העולם, וכל הברואים יקיימו את רצון ה' בלבד, כדברי הגמרא: \"לעתיד לבא מביאו הקב''ה ליצר הרע, ושוחטו בפני הצדיקים ובפני הרשעים\", וכמפורש בדברי הנביא יחזקאל: וְלָקַחְתִּי אֶתְכֶם מִן הַגּוֹיִם, וְקִבַּצְתִּי אֶתְכֶם מִכָּל הָאֲרָצוֹת, וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַתְכֶם. וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם, מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם. וְנָתַתִּי לָכֶם לֵב חָדָשׁ, וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם, וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן מִבְּשַׂרְכֶם, וְנָתַתִּי לָכֶם לֵב בָּשָׂר. וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם, וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וּמִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם. וִישַׁבְתֶּם בָּאָרֶץ אֲשֶׁר נָתַתִּי לַאֲבֹתֵיכֶם, וִהְיִיתֶם לִי לְעָם וְאָנֹכִי אֶהְיֶה לָכֶם לֵאלֹהִים. הערות 172 תלמוד בבלי, סוכה נב. 173 יחזקאל לו כד-כח"],[4,"s12","לְבַל עוֹד תַּרְשִׁיעִי","– כשתכלה את מרשיעי = היצר הרע, לא אחטא עוד, וכך לא תרשיעני = לא אצא מלפניך חייב בדין שאגיש על מעשַי."],[4,"s13","מַהֵר אֱלֹהֵי יִשְׁעִי","– האלוהים המושיע אותי, מהר את הישועה הסופית: ביאת הגואל, שתהיה 'בַּעֲגָלָא וּבִזְמַן קָרִיב' – במהרה ובזמן קרוב. בקשה זו משלימה את הבקשה: 'יוּחַשׁ מוֹשִׁיעִי' (על פי מה שנתבאר שם), ויחד הן מהוות תפילה להקדמת השלב הסופי של תהליך הגאולה וביאת המשיח. הערות 174 בלשון פנייה לנוכח"],[4,"s14","נֶצַח לְהוֹשִׁיעִי","– שורה זו היא המשך לקודמתה: 'מַהֵר אֱלֹהֵי יִשְׁעִי נֶצַח לְהוֹשִׁיעִי' – מהר להושיענו ישועה נצחית – סופית ומוחלטת. בקשה זו עשויה להתפרש על גאולתו הכללית של עם ישראל, וכן על ישועתו הפרטית של האדם, הן מהצרות הגשמיות הן מהצרות הרוחניות."],[4,"s15","שָׂא נָא עֲוֹן רִשְׁעִי","– שהרי מידת 'נושא עוון' היא אחת משלוש עשרה מידות רחמיך, כפי שכתוב: \"נֹצֵר חֶסֶד לָאֲלָפִים, !…≈שׂא »עוֹן וָפֶשַׁע וְחַטָּאָה\" (שמות לד ז). המידות הראשונות – \"אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת\", מטרתן היא להוציא את האדם החוטא זכאי בדינו ולהעניק לו זכות קיום למרות חטאו, כל אחת באופן פעולתה המיוחד. לעומת זאת, המידות שבפסוק השני – \"נֹצֵר חֶסֶד לָאֲלָפִים, נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה, וְנַקֵּה\" – מטרתן היא לתקן את הנזק הרוחני שהחטא יצר במציאות. הן אינן מבטאות רחמים, חנינה, חסד, וכד', מצד הקב\"ה על האדם, כמו המידות הראשונות, אלא את פעולת הקב\"ה ביחס לחטא עצמו, אותו הוא נושא ומנקה; אם כי באופן עקיף, מידות אלו מהוות חסד עם האדם החוטא, שכן הוא נושא באחריות לתוצאות חטאיו. על פי הבחנה זו, נוכל ללמוד את משמעותה המיוחדת של מידת 'נושא עוון' מתוך דברי הגמרא: [...] וחכמים אומרים: 'עוונות' – אלו הזדונות, וכן הוא אומר: \"הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִוא עֲוֹנָה בָהּ\" (במדבר טו לא). 'פשעים' – אלו המרדים, וכן הוא אומר: \"מֶלֶךְ מוֹאָב פָּשַׁע בִּי\" (מלכים ב' ג ז), ואומר: \"אָז תִּפְשַׁע לִבְנָה בָּעֵת הַהִיא\" (מלכים ב' ח כב). 'לכל חטאתם' – אלו השגגות, וכן הוא אומר: \"נֶפֶשׁ כִּי תֶחֱטָא בִשְׁגָגָה\" (ויקרא ד ב) [...] אלא מהו שאמר משה: \"נֹשֵׂא עָוֹן וָפֶשַׁע וְחַטָּאָה\"? אמר משה לפני הקב''ה: ריבונו של עולם, בשעה שישראל חוטאין לפניך ועושין תשובה – עשֵה להם זדונות כשגגות. לדעת חכמים בסוגיית הגמרא שם, נוסח הוידוי הוא: \"חטאתי עוויתי פשעתי\" – מן הקל אל החמור: שגגה, זדון, ומרד. לאור זאת, מקשה הגמרא: מדוע בשלוש עשרה מידות הרחמים הסדר אינו כך, אלא: \"עָוֹן, וָפֶשַׁע, וְחַטָּאָה\"? משיבה הגמרא: \"אמר משה לפני הקב''ה: ריבונו של עולם, בשעה שישראל חוטאין לפניך ועושין תשובה – עשה להם זדונות כשגגות\" – המילה 'חַטָּאָה' נזכרת לבסוף משום שהיא מבטאת את התוצאה של שתי המידות האחרות: 'נושא עוון' ו'נושא פשע'; הקב\"ה נושא את העוון והפשע בכך שמחשיב אותם כ'חַטָּאָה' = שגגות. עלינו להבין, מהי משמעות הדבר שהקב\"ה מחשיבן כשגגות? מהו פשר 'סליחה חלקית' זו? ניתן להסביר זאת על פי המבואר לעיל, שמידות אלו אינן מתייחסות ישירות לאדם עצמו, אלא לרושם השלילי שהחטא יצר במציאות הרוחנית בעולם. כל אחד משלושת סוגי החטאים יוצר רושם שלילי שונה, וסידורם בפסוק הוא על פי רמת חומרתו: העוון – הזדון, הרצון לבצע פעולה רעה – פוגם בטוב האלוהי הכללי הקיים בעולם, בכך שהוא יוצר בתוכו מציאות מטאפיזית של רע, שהרי האדם התכוון לבצע מעשה שלילי. הפשע – הנעשה מתוך כוו!ה למרוד בסמכותו הבלעדית של הקב\"ה – פוגם בהופעת מלכותו של הקב\"ה בעולם, המחייבת קבלת מרות מצד הברואים. לעומתם, החטא – השגגה, אינו גורם כל פגם מצד הכוונה, שהרי אינו נעשה מתוך כוונה רעה; אך כמעשה רע מצד עצמו – גורם הוא לכתם על נשמת האדם. זוהי, איפוא, משמעות דברי הגמרא שכשהאדם שב בתשובה – הקב\"ה מחשיב את פשעיו ומרדיו כשגגות; מתוך שהאדם משנה את רצונו ומתחרט על כוו!תו הרעה בעשייתם, הקב\"ה, מצידו, נוטל מהם את העוקץ שבהם – את הכוונה להרע, או למרוד, ובכך מתבטל הרושם שנוצר מחמתם במציאות הרוחנית. זאת, על ידי שהוא 'נושא' אותם, כביכול, על שכמו – הקב\"ה נוטל את המעשים השליליים מהמציאות הרוחנית בעולם, ומכניס אותם לעולם העליון, האלוהי, שם הם מתנדפים ומתפוגגים. זאת, משום שהפגמים הנוצרים בטוב הכללי ('עָוֹן') ובמלכות ה' ('פֶּשַׁע'), הם בעלי משמעות רק בעולם הזה; אך בעולם האלוהי העליון, האמיתי והשורשי, ערכים אלו קיימים בעינם ולא ניתן לפגוע בהם: מושג ה'טוב' עצמו אינו נפגע מהעבירה, אלא ההופעה שלו בעולם, וכן מלכות ה' היא מוחלטת ולא ניתן לפגום בה, אלא רק בהופעתה בקרב הברואים. כשהאדם שב בתשובה והקב\"ה נוהג עימו במידות אלו, הוא משנה את המציאות הרוחנית בעולם הזה בהתאם למבט העליון, בו הרע מתבטל בטוב האלוהי האין-סופי. הרע הוא העדר בלבד, ואין לו זכות קיום מצד עצמו; כשהקב\"ה נושא אותו על שכמו – הוא חולף ומתבטל מהמציאות, כצל עובר וכענן כלה. זוהי משמעותן של המידות 'נושא עוון' ו'נושא פשע', באמצעותן הקב\"ה מחשיב את העוונות והפשעים כשגגות. על גבי מידות אלו, באה המידה 'נושא חטאה' – גם את הרושם הרוחני של מעשה השגגה, המכתים את נשמת האדם, הקב\"ה 'נושא' אל העולם העליון, בו רושם זה מתנדף מהמציאות. נשמת האדם, מצד שהיא 'חלק אלוה ממעל' – מעשי האדם אינם יכולים לפגום בה באמת, שהרי שורשה הוא הקב\"ה עצמו, והיא שייכת במידה מסויימת לערכו הנצחי והמוחלט, החסין מפני כל שינוי. רק במימד של העולם הזה – נפגעת הנשמה מהחטא, אך מנקודת המבט האלוהית, המתבטאת במידה זו – הרי היא נותרת בטהרתה. בבקשתנו זו – 'שָׂא נָא עָוֹן רִשְׁעִי' – שחייבת להתלוות אליה, כמובן, תשובה – אנו מבקשים מהקב\"ה שיתקן את הפגמים שיצרו העוונות-הזדונות במציאות הרוחנית, להם אנו אחראים, ומתוך כך – 'הוֹשַׁע נָא'. הערות 175 תלמוד בבלי, יומא לו: 176 על פי הרב עזרא ביק, י\"ג מידות של רחמים, עמ' 109-97."],[4,"s16","עֲבוֹר עַל פִּשְׁעִי","– על פי לשון הכתוב: \"מִי אֵל כָּמוֹךָ נֹשֵׂא עָוֹן ו¿ע…≈בר על ∆פּשׁע לִשְׁאֵרִית נַחֲלָתוֹ\" (מיכה ז יח), ופירש ה'מצודת דוד': \"אינו עומד על הפשע להשגיח בו לשלם עליו גמול, אלא עובר על הפשע והולך להלאה, כאילו לא יראנו\". פסוק זה הוא משלושת הפסוקים החותמים את ספר מיכה, ובהם מפורטות שלוש עשרה מידות רחמים, המקבילות לשלוש עשרה מידות הרחמים הכתובות בתורה. המידה המקבילה ל'עוֹבֵר עַל פֶּשַׁע' היא מידת 'חַנּוּן'; על מנת להבין את הקשר ביניהן, יש לעמוד על משמעותה של מידה זו: 'חַנּוּן' – הוא בשעת הדחק לגאול הצועק, כדכתיב: \"חָנוֹן יָחְנְךָ לְקוֹל זַעֲקֶךָ\" (ישעיהו ל יט), ומידה זו, כביכול, שבעל כוח יש לו לחון על הצועק אף שלא כדין, כדכתיב: \"וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי\" (שמות כב כו) – כלומר: אף על פי שבדין בא העבוט לידך כי הלווית עליו מעותיך – אף על פי כן תשיבנו לו; כי אם יצעק אלי – המידה היא כך שאשמע צעקתו, לפי ש'חַנּוּן אָנִי' ואיני יכול לראות בעוניו. וגם יש בלשון 'חַנּוּן' מתנת חינם, כדאמרינן בברכות (ז.): \"'וְחַנֹּתִי אֶת אֲשֶׁר אָחֹן' (שם לג יט) – אף על פי שאינו הגון\". 'חנינה' היא מלשון 'חינם' – השופט, מלבד תפקידו כשופט, הוא גם אדם, ומחמת ה'אדם' שבו, עשוי הוא לחוש מעין שותפות ברגשותיו של הנאשם, שאף הוא אדם כמותו, ולהקל בעונשו בחינם. כך היא, כביכול, גם הנהגת הקב\"ה במידת 'חנון': כשם שכל יוצר חש קשר והזדהות עם יצירתו, כך הקב\"ה חש, כביכול, קשר רגשי והזדהות עם האדם יציר כפיו, רואה בעוניו ובשפלות מצבו, ו'לוקח ללב'; מתוך כך – תשובת האדם מתקבלת לפניו. גם במערכת המשפט כיום, המושג 'חנינה' משמש להקלה בעונש או לביטולו, שלא מחמת נימוקים פורמליים. זוהי גם משמעותה של מידת 'עוֹבֵר עַל פֶּשַׁע' שבספר מיכה, כדברי ה'מצודת דוד' שהוזכרו: \"כאילו לא יראנו\" – ללא טענת סנגוריה פורמלית, אלא חנינה הנובעת מעומק הקשר הקיים בין אלוהים ואדם. אנו מבקשים מהקב\"ה שינהג עימנו במידה זו: 'עֲבוֹר עַל פִּשְׁעִי', ומתוך כך: 'הוֹשַׁע נָא'. הערות 177 ראה: שער הכוונות, תחילת דרושי ראש השנה, ד\"ה עניין 178 ייתכן שיש כאן פתיחה מוטעית של ראשי התיבות: 'שבע\"כ', וצ\"ל: 'שבעל כורחו'. 179 הגהה על התוספות, ראש השנה יז: 180 על פי הרב עזרא ביק, שם, עמ' 49-39"],[4,"s17","פְּנֵה נָא לְהוֹשִׁיעִי","– על פי לשון הכתוב: \" ¿פּ!≈ה ≈אלי וְחָנֵּנִי, תְּנָה עֻזְּךָ לְעַבְדֶּךָ, ו¿הוֹƒשׁי»עה לְבֶן אֲמָתֶךָ\" (תהילים פו טז), ופירש רד\"ק: \"כאדם הפונה מעסקיו, ונותן עיניו בדבר אחד\". אנו מבקשים מהקב\"ה שכביכול 'יתמקד' בנו ובתפילותינו, ומתוך כך ימלא את מבוקשינו על הצד הטוב ביותר."],[4,"s18","צוּר צַדִּיק מוֹשִׁיעִי, קַבֵּל נָא שַׁוְעִי","– על פי לשון הכתוב: \" הצּוּר תָּמִים פָּעֳלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט, אֵל אֱמוּנָה וְאֵין עָוֶל, צַדִּיק וְיָשָׁר הוּא\" (דברים לב ד). התואר 'צוּר' ביחס לקב\"ה מבטא את חוזקו ויכולתו, שכן כינוי זה מושאל מ'צוּר' המופיע במקרא במובן של סלע – המבטא חוזק, או במובן של חוֹד – המבטא יכולת לפגוע בקמים מנגד. מכוח צירוף שתי מידות אלו: היות הקב\"ה 'צוּר', עם היותו 'צַדִּיק' = נוהג בכל מעשיו על פי הצדק, הוא 'מוֹשִׁיעִי', שכן יש לו רצון להושיעני ולהיפרע משונאי, כראוי על פי הצדק , ויש לו יכולת להושיעני – \"כִּי מִי אֱלוֹהַּ מִבַּלְעֲדֵי ה', וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ\" (תהילים יח לב). הערות 181 כמו: \"לָבוֹא בְּנִקְרוֹת הַצֻּרִים וּבִסְעִפֵי הַסְּלָעִים\" (ישעיהו ב כא). 182 כמו: \"אַף תָּשִׁיב צוּר חַרְבּוֹ\" (תהילים פט מד, ראה במפרשים שם)."],[4,"s19","רוֹמֵם קֶרֶן יִשְׁעִי","– על פי לשון הכתוב: \"וּבִרְצֹנְךָ תרים (קרֵי: תָּרוּם) קַרְנֵנוּ\" (תהילים פט יח). הקרן מסמלת תפארת וחוזק – \"בְּכוֹר שׁוֹרוֹ הָדָר לוֹ, וְקַרְנֵי רְאֵם קַרְנָיו, בָּהֶם עַמִּים יְנַגַּח יַחְדָּו\" (דברים לג יז); 'קֶרֶן יִשְׁעִי' היא תפארתו, חוזקו, כבודו, וגבורתו, של עם ישראל, וכל אלה יתגלו ויתממשו בעת הישועה. כפי שאנו אומרים בתפילת שמונה-עשרה, הקב\"ה הוא 'מַצְמִיחַ קֶרֶן יְשׁוּעָה' – בלשון הווה; בכל רגע הקב\"ה פועל לצמיחת ישועתו של עם ישראל, ומקדם את התהליכים המובילים אליה. כאן אנו מבקשים שמלבד עצם צמיחת קרן הישועה, הקב\"ה גם ירומם אותה – שכבודו וגבורתו של עם ישראל יתרוממו במהרה, ויופיעו במלואם לעיני העולם כולו."],[4,"s20","שַׁדַּי מוֹשִׁיעִי","– יש מפרשים שמובנו של השם 'שַׁדַּי' הוא: מְשַׁדֵּד (= שולט, מנהיג) את מערכות הטבע; אנו מתפללים שכשם שה' סובב את מערכות הטבע להושיענו בעבר, כך יעשה כעת, ויגאלנו בקרוב גאולה שלימה. רש\"י מפרש שמובן השם הוא: שֶׁדַּי בברכותיו וברחמיו לכל ברייה, דהיינו שבידו היכולת לתת לכל אחד את כל צרכיו. אנו מבקשים מהקב\"ה שישפיע עלינו מברכותיו ומרחמיו המרובים, יספק את כל צרכינו, ויושיענו במהרה. על דברי יעקב לבניו: \"וְאֵל שַׁדַּי יִתֵּן לָכֶם רַחֲמִים לִפְנֵי הָאִישׁ\" (בראשית מג יד), מביא רש\"י מהמדרש פירוש נוסף לשם זה: \"מי ש אמר לָעולם דּי (=שקבע בעולם גבולות), יאמר דַּי לצרותַי\"; אף לפירוש זה, שם 'שַׁדַּי' מתאים להאמר בבקשה זו, המתייחסת לישועתנו מהגלות ולאמירת הקב\"ה לצרותינו די. הערות 183 אבן עזרא, בראשית יז א ושמות ו ג; רמב\"ן שם 184 בראשית כח ג, מג יד"],[4,"s21","תּוֹפִיעַ וְתוֹשִׁיעִי","– כמאמר הכתוב: \"אֵל נְקָמוֹת ה', אֵל נְקָמוֹת הוֹƒפיע . הִנָּשֵׂא שֹׁפֵט הָאָרֶץ, הָשֵׁב גְּמוּל עַל גֵּאִים\" (תהילים צד א-ב). אנו מצפים ומתפללים למצב בו הקב\"ה יופיע, כלומר: ינהיג את העולם באופן גלוי, ישפיל את הרשעים וירומם את הצדיקים, וכן לכך שיופיע בעולם על ידי בית המקדש ובאמצעות השכינה בתוכו ובקרב ישראל."],[4,"s22","סיכום","בפיוט זה מודגש המבט על חג הסוכות כהמשך ליום הכיפורים; משום כך, בכל השנים הוא נאמר ביום השלישי של החג (אלא אם כן חל בשבת, שאז הוא נאמר למחרת), על מנת להסמיכו ככל האפשר ליום הכיפורים – לאחר הפיוטים 'לְמַעַן אֲמִתָּך' ו'אֶבֶן שְׁתִיָּה' המוכרחים להאמר דווקא בתחילת החג (כמבואר במבוא וב'במבט כללי' על פיוטים אלו). 'אֶעֱרוֹך שׁוּעִי בְּבֵית שַׁוְעִי' – אנו עורכים תפילה זו בבית הכנסת, המקום הקבוע לתפילותינו, שם עמדנו לפני כשבוע והתפללנו את תפילות יום הכיפורים, בהן 'גִּלִּיתִי בַצּוֹם פִּשְׁעִי, דְּרַשְׁתִּיךָ בּוֹ לְהוֹשִׁיעִי'. אנו מזכירים שוב את בקשתנו אז: 'דְּרַשְׁתִּיךָ' – דרשתי אותך, את קרבתך, שתושיע את נפשי ממצב הריחוק בינינו, ותתמיד בקרבי אף לאחר יום הכיפורים, כחלק בלתי נפרד מחיי. מחילת העוונות ביום הכיפורים, אינה אלא אמצעי להביא את האדם לקרבת ה' – \"כִּי אִם עֲוֹנֹתֵיכֶם הָיוּ מַבְדִּלִים בֵּינֵכֶם לְבֵין אֱלֹהֵיכֶם\" (ישעיהו נט ב). איננו משאירים מאחור את יום הכיפורים ואת התוכן שיצקנו לתוכו; אנו לוקחים איתנו את ההתעלות, השאיפות, והקַבלות, ומיישמים אותם בחיים השגרתיים, במשך השנה כולה. לפיכך אנו שבים ומזכירים כעת את כשלונות העבר – 'גִּלִּיתִי בַצּוֹם פִּשְׁעִי' – כדי לזכור שעלינו להתרחק מהם, ואת קרבת ה' והרוממות הרוחנית אליהן התעלינו ביום הכיפורים, ומתפללים להתמדתן – 'הַקְשִׁיבָה לְקוֹל שַׁוְעִי, וְקוּמָה וְהוֹשִׁיעִי'. כחלק מתהליך התשובה של יום הכיפורים, הצבנו לעצמנו מטרות ויעדים, וקיבלנו על עצמנו קבלות שתסייענה לנו להגיע אליהם. אך ללא עזרה מהקב\"ה, לא נוכל להצליח בכך: אמר רבי יצחק: יצרו של אדם מתגבר עליו בכל יום, שנאמר: \"[וְכָל יֵצֶר מַחְשְׁבֹת לִבּוֹ] רַק רַע כָּל הַיּוֹם\" (בראשית ו ה). אמר רבי שמעון בן לקיש: יצרו של אדם מתגבר עליו בכל יום ומבקש להמיתו, שנאמר: \"צוֹפֶה רָשָׁע לַצַּדִּיק וּמְבַקֵּשׁ לַהֲמִיתוֹ\" (תהילים לז לב), ואלמלא הקב''ה שעוזר לו – אינו יכול לו, שנאמר: \"ה' לֹא יַעַזְבֶנּוּ בְיָדוֹ וְלֹא יַרְשִׁיעֶנּוּ בְּהִשָּׁפְטוֹ\" (שם שם לג). אותו היצר של השנה שעברה ימשיך לפעול גם השנה; לפיכך – מלבד רעיונות ועצות שעלינו לטכס, כיצד נגרום לכך ששנה זו תהא טובה מקודמתה ונצליח לעמוד בה בקבלותינו, עלינו לבקש מהקב\"ה שיעזרנו בכך. מעבר לבקשתנו לסיוע שלא להיכשל בחטאי העבר, אנו מבקשים: 'וְקוּמָה וְהוֹשִׁיעִי' – ישועה מהמדרגה בה אנו נמצאים, והתעלות למדרגה גבוהה יותר, למעמד רוחני שבו מצבים שבעבר היוו עבורנו ניסיונות – מעתה נצליח לקיים בהם את רצון ה' בצורה טבעית, ללא צורך בהתמודדות עם היצר וכפייה עצמית. מתוך מצב זה, נוכל יותר להרגיש 'בבית' בעבודת ה', והיא תהיה עבורנו כשעשוע – 'חַי, כֵּן תְּשַׁעְשְׁעִי'. מתוך הבקשה על הפרט, אנו עולים שלב ומבקשים על ישועתו של כלל ישראל – שהקב\"ה ישמע את נאקתם ויחיש את ביאת הגואל – 'טוֹב, בְּאֶנֶק שְׁעִי – יוּחַשׁ מוֹשִׁיעִי', ועל גאולתם הרוחנית מכבלי החומר והיצר – 'כַּלֵּה מַרְשִׁיעִי, לְבַל עוֹד תַּרְשִׁיעִי'. בין על הפרט ובין על הכלל אנו מבקשים מהקב\"ה שישועתם תהיה מהירה ומוחלטת – 'מַהֵר אֱלֹהֵי יִשְׁעִי, נֶצַח לְהוֹשִׁיעִי', ושתוסרנה המחיצות המבדילות בינם לבין אביהם שבשמיים – 'שָׂא נָא עֲוֹן רִשְׁעִי, עֲבוֹר עַל פִּשְׁעִי', וחותמים בבקשה להרמת קרנם של ישראל והכנעת אויביהם בעת הגאולה העתידה – 'קַבֵּל נָא שַׁוְעִי, רוֹמֵם קֶרֶן יִשְׁעִי; שַׁדַּי מוֹשִׁיעִי – תּוֹפִיעַ וְתוֹשִׁיעִי'. הערות 185 תלמוד בבלי, סוכה נב.-נב:"],[4,"n158","הערה 158","ראה לעיל במבוא, עמ' 22-19, על הקשר בין ההקפות לבין יום הכיפורים."],[5,"piyut","נוסח הפיוט","הוֹשַׁע נָא אוֹם אֲנִי חוֹמָה. לוֹמֶדֶת יִרְאָתָךְ. בָּרָה כַּחַמָּה. מְרוּטַת לֶחִי. גּוֹלָה וְסוּרָה. נְתוּנָה לְמַכִּים. דָּמְתָה לְתָמָר. סוֹבֶלֶת סִבְלָךְ. הַהֲרוּגָה עָלֶיךָ. עֲנִיָּה סֹעֲרָה. וְנֶחֱשֶׁבֶת כְּצֹאן טִבְחָה. פְּדוּיַת טוֹבִיָּה. זְרוּיָה בֵּין מַכְעִיסֶיהָ. צֹאן קָדָשִׁים. חֲבוּקָה וּדְבוּקָה בָּךְ. קְהִלּוֹת יַעֲקֹב. טוֹעֶנֶת עֻלָּךְ. רְשׁוּמִים בִּשְׁמֶךָ. יְחִידָה לְיַחֲדָךְ. שׁוֹאֲגִים. כְּבוּשָׁה בַגּוֹלָה. תְּמוּכִים עָלֶיךָ. הוֹשַׁע נָא."],[5,"s1","על הפיוט","בפיוט זה אנו מתפללים על ישועת עם ישראל והצלתו מצרות הגלות ומאויביו הרבים, בזכות מעלותיו ומידותיו הטובות המפורטות בפיוט, בפירוש או ברמז, ובפרט בשל נאמנותו לקב\"ה ודבקותו בשמירת התורה והמצוות על אף קשיי הגלות."],[5,"s2","אוֹם אֲנִי חוֹמָה","– ישראל, שהם אומה האומרת: 'אֲנִי חוֹמָה'. לשם הבנת משמעותו של כינוי זה, נעיין במקורו, בסוף מגילת 'שיר השירים': אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ, מָה נַעֲשֶׂה לַאֲחוֹתֵנוּ בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ. אִם חוֹמָה הִיא – נִבְנֶה עָלֶיהָ טִירַת כָּסֶף, וְאִם דֶּלֶת הִיא – נָצוּר עָלֶיהָ לוּחַ אָרֶז. אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת, אָז הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. רש\"י מסביר שבפסוקים אלו הקב\"ה ובית דינו מתייעצים, כביכול, כיצד לנהוג ב'אחות הקטנה' – עַם ישראל: מָה נַעֲשֶׂה לַאֲחוֹתֵנוּ בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ – כשהאומות מתלחשים עליה להכחידה? אִם חוֹמָה הִיא – אם תחזק באמונתה וביראתה, להיות כנגדם כחומת נחושת, שלא יכנסו לתוכה, רוצה לומר: שלא תתחתן בם והם לא יבואו בה, ולא תתפתה להם – נִבְנֶה עָלֶיהָ טִירַת כָּסֶף – נהיה לה לעיר מבצר, ולכתר, ולנוי, ונבנה לה את עיר הקודש ובית הבחירה; וְאִם דֶּלֶת הִיא – הסובבת על צירה ובהיקש עליה היא נפתחת, אף היא – אם תפתח להם להיות הם באים בה והיא בהם – נָצוּר עָלֶיהָ לוּחַ אָרֶז – נשים בדלתה נסרים של עץ הנרקבים, והתולעת גוררתן ואוכלתן. וכנסת ישראל אומרת: אֲנִי חוֹמָה – חזקה באהבת דודי, וְשָׁדַי כַּמִּגְדָּלוֹת – אלו בתי כנסיות ובתי מדרשות; אָז – באמרי זאת, הָיִיתִי בְעֵינָיו ככלה הנמצאת שלימה, ו מוֹצְאֵת שָׁלוֹם בבית בעלה. הכינוי 'אוֹם אֲנִי חוֹמָה' מהווה, איפוא, פתיחה נאה לפיוט זה, המתאר את עם ישראל במצבו הלאומי הירוד מעת שגלה מארצו: על אף כל הצרות הגשמיות והרוחניות, הוא ניצב כחומה בצורה ושומר על נאמנותו לקב\"ה. אנו מתפללים שבזכות זו, נזכה ל'טִירַת כָּסֶף' – ישועה והגנה ממרום, כטירה שמגינה על יושביה, ולבניין עיר הקודש ובית הבחירה – טירת הכיסופים."],[5,"s3","בָּרָה כַּחַמָּה","– 'בָּרָה' מלשון 'ברור' – בעלת אור ברור (=בהיר וזך) כשל השמש; כלשון הכתוב: \"מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר, יָפָה כַלְּבָנָה, בָּרָה כַּחַמָּה\" (שיר השירים ו י), ומפרש ה'מצודת דוד': רְאו מי היא וכמה גדולה וחשובה היא זאת, אשר מִתחילה היתה נִּשְׁקָפָה ונראה כְּמוֹ כוכב ה שָׁחַר , ולאחר זה נתעלתה עד שנעשית יָפָה כַלְּבָנָה , ואחר זה הוסיפה עוד ביופי עד שנעשית בָּרָה כַּחַמָּה , לא כדרך שאר נשים שנכחש יופיין כשהן מזדקנות. והנמשל הוא, לומר: כמה גדולה האומה ההיא, שבכל פעם מוספת על עצמה גדרים וסייגים לעשות משמרת למשמרת התורה; לא כדרך האומות שאף המצוות שהחזיקו בהן המה פוחתין והולכין. לפירוש זה, הכינוי 'בָּרָה כַּחַמָּה' מציין את נקודת השיא של התעלותם הרוחנית של ישראל; התעלות שנבעה מכך שהוסיפו על עצמם מרצונם מצוות ותקנות, על מנת לחזק בכך את שמירת התורה. דבר זה מבטא את אהבתם של ישראל לקב\"ה ולתורתו, שכן הוא מראה שאינם מקיימים את התורה רק כדי לצאת ידי חובתם, אלא מתייחסים אליה כעניין שלהם; על כך נאמר בגמרא: מאי [=מהו פירוש הפסוק]: \"כִּי טוֹבִים דֹּדֶיךָ מִיָּיִן\" (שם א ב)? כי אתא [=כשבא] רב דימי, אמר: אמרה כנסת ישראל לפני הקב\"ה: ריבונו של עולם, ערֵבים עלַי דברי דודיך [=תקנות חכמי ישראל] יותר מיינה של תורה [=מצוות התורה]. אנו מזכירים לפני הקב\"ה, מעבר לזכותם של ישראל בשמירתם את התורה (הרמוזה ב'אוֹם אֲנִי חוֹמָה'), את זכותם בכך שהוסיפו על עצמם מצוות נוספות, ואת אהבתם לקב\"ה ולתורתו, ומכוח זכויות אלו מבקשים: 'הוֹשַׁע נָא'. הערות 187 תלמוד בבלי, עבודה-זרה לה."],[5,"s4","גּוֹלָה וְסוּרָה","– כלשון הכתוב: \"וְאָמַרְתְּ בִּלְבָבֵךְ [פנייה לציון]: מִי יָלַד לִי אֶת אֵלֶּה, וַאֲנִי שְׁכוּלָה וְגַלְמוּדָה גֹּלָה וְסוּרָה\" (ישעיהו מט כא), ופירש המלבי\"ם: \"שהייתי גּוֹל»ה ממקומי, וגם במקום שהייתי לא הניחו לי לשבת במנוחה, רק הייתי סוּר»ה [=מגורשת, מלשון הסרה] ממקום למקום\". בפסוק, ציון נקראת 'גּוֹלָה וְסוּרָה' על שם כך שבניה גלו וסרו ממנה, ובפיוט – אומת ישראל עצמה מכונה כך, כיוון שגלתה וסרה מארצה."],[5,"s5","דָּמְתָה לְתָמָר","– כלשון הכתוב: \"זֹאת קוֹמָתֵך דָּמְתָה לְתָמָר\" (שיר השירים ז ח), ופירש רש\"י: \"ראינו נוי קומתך בימי נבוכדנצר, שכל האומות היו כורעות ונופלות לפני הצלם, ואת עומדת בקומה זקופה כתמר הזה\". כוונתו למסופר בספר דניאל (פרק ג) שנבוכדנצר מלך בבל העמיד צלם בבקעת דורא וגזר על כל נתיניו להשתחוות לו בהינתן האות, והעובר על גזירתו – יושלך לכבשן האש; אף על פי כן, חנניה מישאל ועזריה סירבו להשתחוות. לדעת חלק מהמפרשים, צלם זה לא נעשה לשם עבודה זרה אלא לכבודו של נבוכדנצר, וממילא בהשתחוואה לו לא היה איסור ממשי; אף על פי כן, חנניה מישאל ועזריה רצו לקדש את שם ה' לעיני העמים ולהראות את ייחודו של עם ישראל בכך שעובד הוא את הקב\"ה בלבד ואינו סוגד למלכות בבל, ולפיכך מסרו את נפשם ולא השתחוו לצלם. לפירוש זה, הכינוי רומז לתכונתם המיוחדת של ישראל – שמוסרים את נפשם לקדש שם שמיים אף מעבר לדרישת ההלכה הפורמלית. קיים דמיון נוסף בין ישראל לעץ התמר: \"מה תמר אין לו אלא לב אחד [=לחלוחית היניקה שלו עולה בקו ישר לאורך הגזע ולא מתפצלת לתוך ענפיו], אף ישראל אין להם אלא לב אחד לאביהם שבשמיים\"; דרשה זו משתלבת עם הפירוש הקודם: כל רצונותיהם של ישראל מכוונים למטרה אחת: לעשות את רצון אביהם שבשמיים – אף במחיר חייהם, ואף מעבר לנדרש מהם. בבקשה זו אנו מזכירים לפני הקב\"ה את אותה זכות של ישראל, ומעוררים את עצמנו לשאוף להגיע למדרגה כזו שבה נחיה בפועל מתוך לב אחד לאבינו שבשמיים. בעל 'בני יששכר' מפרש כינוי זה, וכן את פשר סמיכותו ל'גּוֹלָה וְסוּרָה', על דרך הדרוש: יש לפרש: הכנסת ישראל הקדושה הלזו, הנה היא בדומה לתמר כלתו של יהודה: עם היות שנתגרשה מבית יהודה, עם כל זה היתה מהדרת ומחזרת אחריו להעמיד ממנו המלכות. כן כנסת ישראל הקדושה: עם היות שהיא גולה וסורה מבית אביה, עם כל זה היא מתדמה לתמר, שהיא מהדרת ומחזרת להעמיד מלכות שמיים, וזה מבוקשם כל הימים. הערות 188 ראה: תוספות, עבודה זרה ג. ד\"ה שלא; רמב\"ן, רשב\"א, ר\"ן, ו'שיטה מקובצת', על כתובות לג: 189 תלמוד בבלי סוכה מה:, מגילה יד. 190 רבי צבי אלימלך שפירא (תקפ\"ג-תר\"א), פעל בדינוב שבגליציה. ייסד את שושלת אדמו\"רי דינוב, חסידות שהתפצלה לאחר מכן למספר חצרות. כתב מספר ספרים בנגלה ובנסתר. 191 בני יששכר, מאמרי חודש תשרי, מאמר יב, אות יד"],[5,"s6","הַהֲרוּגָה עָלֶיךָ, וְנֶחֱשֶׁבֶת כְּצֹאן טִבְחָה","– על פי לשון הכתוב: \"כִּי עָלֶיךָ הֹרַגְנוּ כָל הַיּוֹם, נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה\" (תהילים מד כג). עם ישראל בגלות, ואף בארצו, נרדף ונהרג על ידי הגויים; 'עָלֶיךָ' – בגלל ה', כביכול, שהרי שנאתם העמוקה והתמידית של הגויים לישראל נובעת מהיותו מייצג את אמונת ה' ואת המוסר האלוהי בעולם; בפרט בזמנים בהם היהודים נרדפו באופן מוצהר בשל דבקותם באמונתם וסירובם להמירה בדת הגויים, היה זה 'עָלֶיךָ'. 'כְּצֹאן טִבְחָה' – מצבם של ישראל בגלות הגיע לרמה כה ירודה, עד שחייהם הם חסרי ערך בעיני הגויים, והם נחשבים בעיניהם כצאן המיועד לשחיטה, שאין לחייו כל משמעות."],[5,"s7","זְרוּיָה בֵּין מַכְעִיסֶיהָ","– אף כשישראל מפוזרים בין הגויים המתגרים בהם ולועגים להם על מצבם השפל, הם: חֲבוּקָה וּדְבוּקָה בָּךְ – דבקים בקב\"ה ובאמונה בו; התואר 'דְּבוּקָה' מוסיף על 'חֲבוּקָה', שכן הוא מבטא חיבור ממשי, לבלי הַפְרֵד. יש גורסים: זְרוּיָה בֵּין מַכְעִיסֶיךָ ; לעומת הגויים, שכביכול מכעיסים את הקב\"ה במעשיהם, היא חבוקה ודבוקה בך, ועל אף שהיא זרויה ביניהם – אינה לומדת ממעשיהם, ואינה נוטשת את אמונתה, על אף הקשיים הרבים הנופלים בחלקה. הערות 192 רוקח"],[5,"s8","טוֹעֶנֶת עֻלָּךְ","– נושאת על עצמה ברצון ובאהבה את עול התורה והמצוות, על אף קשיי הגלות."],[5,"s9","יְחִידָה לְיַחֲדָךְ","– עם ישראל הוא העם היחיד שנושא בעולם את דגל האמונה בייחוד ה'. אנו מתפללים לזכות לישועה בזכות דבר זה, שכן בעת ישועתו של עם ישראל, כל העמים ילמדו ממנו אמונה זו, כמבואר לעיל. הערות 193 עמ' 50, 54"],[5,"s10","כְּבוּשָׁה בַגּוֹלָה","– עם ישראל נשלט על ידי העמים בארצות הגולה, ואף על פי כן אינו נוטש את אמונתו בקב\"ה ואת יראתו ממנו, אלא אדרבה – לוֹמֶדֶת יִרְאָתָךְ – לומדים כיצד לירא את ה'. יראת ה' הוא נושא רחב המצריך לימוד ממש, כפי שכתב רמח\"ל בהקדמה לספרו 'מסילת ישרים': הוא מה שאמר שלמה: \"אִם תְּבַקְשֶׁנָּה כַכָּסֶף וְכַמַּטְמוֹנִים תְּחַפְּשֶׂנָּה, אָז תָּבִין יִרְאַת ה'\" (משלי ב ד-ה) – אינו אומר: אז תבין פילוסופיה, אז תבין תכונה, אז תבין רפואה, אז תבין דינים, אז תבין הלכות, אלא \"אָז תָּבִין יִרְאַת ה'\". הרי לך שכדי להבין היראה צריך לבקש אותה ככסף ולחפש אותה כמטמונים [...] והנה הכתוב אומר: \"הֵן יִרְאַת ה' הִיא חָכְמָה\" (איוב כח כח), ואמרו רז\"ל: \"הֵן – אחת\", הרי שהיראה היא 'חכמה', והיא לבדה 'חכמה', וודאי אין נקרא 'חכמה' מה שאין בו עיון. אך האמת הוא כי צריך עיון גדול על כל הדברים האלה, לדעת אותם באמת, ולא על צד הדמיון והסברה הכוזבת; כל שכן לקנות אותם ולהשיגם. בעל 'בני יששכר' מציע הסבר נאה לקשר שבין 'כְּבוּשָׁה בַגּוֹלָה' ל'לוֹמֶדֶת יִרְאָתָךְ': ידוע מה שכתבו בשם תלמידי הבעל שם טוב, דכל מה שיארע לאדם – יעלה במחשבתו לה' יתברך: רואה דבר הנאהב אשר נפשו של אדם משתוקק לדבר הזה ואוהבו – יבין שמזכירין לו מידת אהבה, ויעלה זאת במחשבתו לאהבת ה' יתברך, למידת אהבה וחסד, וידבק באהבתו יתברך שמו [...] וכן ברואה דבר מאויים [=מאיים], היינו ברואה איזה עכו\"ם או איזה סרדיוט [=שר] וכיוצא, המאיים עליו, יבין וילמוד על ידי זה יראתו יתברך שמו. על האדם לזהות בכל תכונה חיובית שהוא פוגש בחייו, את שורשה האלוהי. כל האובייקטים שהוא חש אהבה כלפיהם, או חש יראה מפניהם – הקב\"ה הוא זה שיצר אותם; ממילא, הרגש שהוא חש כלפי האובייקט שמולו, צריך להיות מופנה בעיקר למקור והשורש שלו – הקב\"ה. באופן זה, רגשי האהבה שהאדם רוחש לסובביו וכד', מעצימים את אהבתו לקב\"ה, והיראה שהוא חש מפני דברים מסויימים – מעצימים את יראת הרוממות בקרבו. ממשיך בעל 'בני יששכר': וזה שיש לפרש 'כְּבוּשָׁה בַגּוֹלָה': מה שכנסת ישראל הקדושה היא בגולה, ויש להם אימה ופחד מן הגויים הכובשין ודוחקין אותן – על ידי זה 'לוֹמֶדֶת יִרְאָתָךְ'. לא זו בלבד שעם ישראל אינו נוטש מחמת צרות הגלות את נאמנותו לקב\"ה ואת היראה ממנו, אלא אדרבה, הוא משתמש באימה וביראה שחש כלפי הגויים כדי להעמיק ולהעצים בקרבו את האימה והיראה מפני מלך מלכי המלכים, שהוא זה שברא – ומקיים בהווה – את הגויים המאיימים, והאימה שהם מטילים סביבם – מקורה בו. הערות 194 תלמוד בבלי, שבת לא: 195 בני יששכר, שם, אות יז. ראה גם: בעל שם טוב, פרשת בראשית, אות לו"],[5,"s11","מְרוּטַת לֶחִי, נְתוּנָה לְמַכִּים","– האומה הישראלית נמרטת ומוכה על ידי הגויים, והיא סוֹבֶלֶת סִבְלָךְ – נושאת על שכמה את משא הייסורים שמניח עליה הקב\"ה, ומקבלתם באהבה. ניתן גם לפרש: 'סוֹבֶלֶת סִבְלָךְ' – עם ישראל משתתף בנשיאת משא הצער שכביכול נושא הקב\"ה על עצמו; צערו של הקב\"ה על העדר גילוי שכינתו בעולם, גדול הוא לאין ערוך מכל צער אנושי, וכשישראל מתאבלים על החורבן ומצירים על צער השכינה, הרי הם משתתפים עם הקב\"ה, כביכול, בנשיאת משא צערו. הערות 196 לסבול = לשאת, בלשון המקרא, כמו: \"יִשָּׂאֻהוּ, עַל כָּתֵף יִסְבְּלוּהוּ\" (ישעיהו מו ז). 197 ראה הרחבה בנושא זה לעיל, ב'במט כללי' על הפיוט 'למען אמיתך'."],[5,"s12","עֲנִיָּה סֹעֲרָה","– כלשון הכתוב: \"עֲנִיָּה סֹעֲרָה לֹא נֻחָמָה\" (ישעיהו נד יא), ופירש רש\"י: \"שֶׁלִבָּהּ סוער בְּרֻבֵּי צרות\". מי שהוא מבוסס מבחינה כלכלית, אזי גם כשבאות עליו צרות, מעמדו נשאר יציב; אך העני, שבלאו הכי מעמדו מעורער, צרות נוספות שבאות עליו עלולות לערער את מצבו באופן קיצוני. עם ישראל נמשל ל'עֲנִיָּה סֹעֲרָה' – מלבד מעמדו הנחות ממילא כעם גולֶה, הוא נתון ברוחות הסערה של צרות הגלות."],[5,"s13","פְּדוּיַת טוֹבִיָּה","– עם ישראל, שנפדה ממצרים על ידי משה שנקרא 'טוביה', כדברי הגמרא: \"וַתֵּרֶא אֹתֹו כִּי טוֹב הוּא\" (שמות ב ב) – [...] רבי יהודה אומר: 'טוביה' שמו\" [אימו קראה לו כך כיוון שראתה ש'טוב הוא']. כשם שאז פדיתנו ממצרים על ידי משה, כך תפדנו ותושיענו במהרה מהגלות הנוכחית. הערות 198 תלמוד בבלי, סוטה יב."],[5,"s14","צֹאן קָדָשִׁים","– כלשון הכתוב: \"כֹּה אָמַר אֲדֹנָי יֱהֹוִה: עוֹד זֹאת אִדָּרֵשׁ לְבֵית יִשְרָאֵל, אַרְבֶּה אוֹתָם כַּצֹאן – אָדָם. כְּצֹאן קָדָשִׁים, כְּצֹאן יְרוּשָׁלִַם בְּמוֹעֲדֶיהָ, כֵּן תִּהְיֶינָה הֶעָרִים הֶחָרֵבוֹת מְלֵאוֹת צֹאן אָדָם, וְיָדְעוּ כִּי אֲנִי ה'\" (יחזקאל לו לז-לח). פסוקים אלו מהווים סיום לנבואה המתארת את חטאי ישראל בארצם ואת תהליך ההיטהרות שיעברו בגלות; בסיומו של התהליך, כשעם ישראל יהיה ראוי לכך, הוא ישוב לארצו, ל'עָרִים הֶחָרֵבוֹת', וירבה שם עד שימלא את הערים שיבנה, כמו הצאן הרב שמעלים לירושלים להקרבת הקורבנות בימי המועדים. בפיוט, 'צֹאן קָדָשִׁים' הוא כינוי לעם ישראל עצמו, (בשונה מבפסוק, שבו הוא משמש כדימוי בלבד), וייתכן שהוא רומז על כך שהם נהרגים – כמו 'צֹאן', על קידוש השם – כמו 'קָדָשִׁים' (=קרבנות). השימוש במטבע הלשון של הפסוק, טומן בתוכו כוונה נוספת: אנו מתפללים לזכות במהרה להתממשות אותה נבואה: לכך שכל ערי ארץ ישראל תהיינה מלאות באוכלוסיה יהודית, וכן למטרה הסופית – \"וְיָדְעוּ כִּי אֲנִי ה'\"."],[5,"s15","קְהִלּוֹת יַעֲקֹב","– על פי לשון הכתוב: \"תּוֹרָה צִוָּה לָנוּ מֹשֶׁה, מוֹרָשָׁה קְהִלַּת יַעֲקֹב\" (דברים לג ד) – התורה שציוה לנו משה, היא 'מוֹרָשָׁה' = ירושה, מסורת מדור לדור, ל'קְהִלַּת יַעֲקֹב' – עם ישראל. הכינוי 'קְהִלּוֹת יַעֲקֹב' רומז לשושלת הדורות (='קְהִלּוֹת') של עם ישראל, ששמר על קיום התורה ועל מסירתה לדורות הבאים, על אף הצרות והקשיים שעברו עליהם."],[5,"s16","רְשׁוּמִים בִּשְׁמֶךָ","– עם ישראל, ששמו רשום בשם ה': 'ישר אל '; בכך מתבטא עניינו המיוחד של עם ישראל – התגלות שם ה' דרכו בעולם, וכפי שציין ה'רוקח' בפירושו לשורה זו לדברי יהושע לאחר מפלת ישראל במלחמתם על העי: \"בִּי אֲדֹנָי, מָה אֹמַר אַחֲרֵי אֲשֶׁר הָפַךְ יִשְׂרָאֵל עֹרֶף לִפְנֵי אֹיְבָיו. וְיִשְׁמְעוּ הַכְּנַעֲנִי וְכֹל יֹשְׁבֵי הָאָרֶץ, וְנָסַבּוּ עָלֵינוּ, וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ, וּמה תּע≈שׂה ל¿ƒשׁ¿מךָ הגּ»דוֹל \". פירוש נוסף: 'רְשׁוּמִים בִּשְׁמֶךָ' – ששמות משפחות ישראל רשומים בתורה בין האותיות י ו-ה של שם 'יה', כמו: \"חֲנוֹך – מִשְׁפַּחַת ה חֲנֹכִ י , לְפַלוּא – מִשְׁפַּחַת ה פַּלֻּאִ י \" (במדבר כו ה), וכפי שכתב שם רש\"י: לפי שהיו האומות מבזין אותם ואומרים: מה אלו מתייחסין על שבטיהם, סבורים הם שלא שלטו המצרים באמותיהם?! אם בגופם היו מושלים – קל וחומר בנשותיהם! לפיכך הטיל הקב\"ה שמו עליהם: ה מצד זה ו-י מצד זה, לומר: מעיד אני עליהם שהם בני אבותיהם. וזהו שמפורש על ידי דוד: \"שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל\" (תהילים קכב ד) – השם הזה מעיד עליהם לשבטיהם. לפירוש זה, כינוי זה מזכיר את זכותם של ישראל, בין בתקופת שיעבוד מצרים ובין לאורך כל הדורות, שהזרם המרכזי בעם תמיד שמר על טהרתו ועל נבדלותו מהעמים ולא התבולל בהם. הערות 199 רוקח 200 על פי 'אוצר התפילות'"],[5,"s17","שׁוֹאֲגִים","– זוהי השורה היחידה ב'הושענות' שבה מילה אחת בלבד; בכך טמונה עוצמתה המיוחדת: 'שׁוֹאֲגִים' – השואג זועק ממעמקי ליבו, אוסף את כל הכוחות שעוד נותרו בו ומשלחם מחוצה לו בעוצמה, ללא חיתוך שפתיים ומלל; השאגה מבטאת הרגשה עמוקה של שבר וייאוש שמילים אינן יכולות לבטא. זהו מצבו של עם ישראל בסוף הגלות, ב'עִקבתא דמשיחא' – התקופה הקרובה לביאת המשיח, שבה מתגברים קשייו וצרותיו מבית ומחוץ, והוא נושא על גבו משא כבד של תלאות, משברים, ותקוות שנכזבו."],[5,"s18","תְּמוּכִים עָלֶיךָ","– זהו השלב האחרון, הבא אחרי 'שׁוֹאֲגִים' – מצב של אפיסת הכוחות; לעם ישראל אין כוח לעמוד עוד, והוא נתמך על ידי הקב\"ה על מנת שלא יתמוטט לגמרי. כוונת הדברים היא, שבדרך הטבע לא היתה לעם ישראל אפשרות לשרוד את הגלות הארוכה; רק השגחתו העל-טבעית של הקב\"ה היא הנותנת לו תמיכה וקיום. ביטוי זה כולל גם שבח לישראל, שהם נסמכים על הקב\"ה, בוטחים בו ומצפים לישועתו; מכוח זכותם זו אנו מבקשים: 'הוֹשַׁע נָא'."],[5,"s19","סיכום","לאורך הפיוט מתואר עם ישראל בהיותו בגלות, מתוך מבט מזוויות שונות השופכות אור על מצב פלאי זה, שבו, מתוך כל המחשכים, מיתמרת ועולה דמותו של עם ישראל במלוא תפארתה, בדבקותו בקב\"ה ובנאמנותו ומסירותו לקיום התורה והמצוות, חרף כל הקשיים והמניעות. הפיוט פותח בשני ביטויים המבטאים את נאמנותם המוצהרת של ישראל לשמירת התורה: 'אוֹם אֲנִי חוֹמָה', 'בָּרָה כַּחַמָּה', וחלקו המרכזי של הפיוט מתאר את הגלות עצמה, תוך התמקדות בשני מישורים ובהקבלה ביניהם: המישור האחד – תיאור הצרות, התלאות, המשברים, והרדיפות, שהם מנת חלקם בגלות, והשני – נאמנותם העיקשת לקב\"ה ולתורתו ומסירות נפשם עליה: 'גּוֹלָה וְסוּרָה', ועם זאת – 'דָּמְתָה לְתָמָר'; 'הַהֲרוּגָה עָלֶיךָ, וְנֶחְשֶׁבֶת כְּצֹאן טִבְחָה, זְרוּיָה בֵּין מַכְעִיסֶיהָ', ועם זאת – 'חֲבוּקָה וּדְבוּקָה בָּךְ, טוֹעֶנֶת עֻלָּך, יְחִידָה לְיַחֲדָךְ'; 'כְּבוּשָׁה בַּגּוֹלָה', ועם זאת – 'לוֹמֶדֶת יִרְאָתָךְ'; 'מְרוּטַת לֶחִי, נְתוּנָה לְמַכִּים', ועם זאת – 'סוֹבֶלֶת סִבְלָךְ'. הפיוט מסתיים בתיאור מצב אפיסת הכוחות בו מגיע עם ישראל לסוף הגלות: 'שׁוֹאֲגִים' – בתפילה נואשת לקב\"ה בשארית כוחותיהם; 'תְּמוּכִים עָלֶיךָ' – במצב התמוטטות מוחלטת, ואך הקב\"ה הוא התומך ומחזיק בהם, וכדברי המשנה המתארת את תקופת 'עקבתא דמשיחא': \"ועל מי יש לנו להישען? על אבינו שבשמיים\". הערות 201 מסכת סוטה, פרק ט, משנה טו"],[5,"n186","הערה 186","שיר השירים ח ח-י"],[6,"piyut","נוסח הפיוט","הוֹשַׁע נָא אֵל לְמוֹשָׁעוֹת. לְהָבִין שְׁמוּעוֹת. בְּאַרְבַּע שְׁבוּעוֹת. מִפִּיךָ נִשְׁמָעוֹת. גָּשִׁים בְּשַׁוְעוֹת. נוֹתֵן תְּשׁוּעוֹת. דּוֹפְקֵי עֶרֶךְ שׁוּעוֹת. סְפוּרוֹת מְשַׁמְּעוֹת. הוֹגֵי שַׁעְשְׁעוֹת. עֵדוּת מַשְׁמִיעוֹת. וְחִידוֹתָם מִשְׁתַּעְשְׁעוֹת. פּוֹעֵל יְשׁוּעוֹת. זוֹעֲקִים לְהַשְׁעוֹת. צַדִּיק נוֹשָׁעוֹת. חוֹכֵי יְשׁוּעוֹת. קָרֵב תְּשׁוּעוֹת. טְפוּלִים בְּךָ שְׁעוֹת. רֶגֶשׁ תְּשׁוּאוֹת. יוֹדְעֵי בִין שָׁעוֹת. שָׁלשׁ שָׁעוֹת. כּוֹרְעֶיךָ בְּשַׁוְעוֹת. תָּחִישׁ לִתְשׁוּעוֹת. הוֹשַׁע נָא."],[6,"s1","על הפיוט","בפיוט זה אנו מתפללים לגאולת ישראל מצרות הגלות בזכות תפילותיהם ועיסוקם בתורה, שכן אלו הם הדברים שבכוחם לקרב את הגאולה."],[6,"s2","אֵל לְמוֹשָׁעוֹת","– כלשון הכתוב: \"הָאֵל לָנוּ אֵל לְמוֹשָׁעוֹת\" (תהילים סח כא) – 'אֵל' הוא לשון חוזק; הקב\"ה מושיענו באמצעות חוזקו וגבורתו."],[6,"s3","בְּאַרְבַּע שְׁבוּעוֹת","– על פי האמור במדרש: \"רבי חלבו אומר: ארבע שבועות יש כאן\" – במגילת שיר השירים רמוזות ארבע שבועות שהשביע הקב\"ה את ישראל, בארבעת הפסוקים הפותחים במילים: \"הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלִַם\": א. \"השביע לישראל שלא ימרדו על המלכויות\" – גם מרידה שאינה כרוכה בעלייה לארץ. ב. \"ושלא ידחקו את הקץ\" – שלא יבצעו פעולות רוחניות, כמו שימוש בקבלה מעשית, כדי למהר את הגאולה. בגמרא מופיעה גירסה שונה: \"שלא ירחקו את הקץ\", ופירש רש\"י: \"בעוונם\". בספר 'אם הבנים שמחה' מפרש שאין כוונת רש\"י לסתם עוונות, שמאז ומעולם היו אסורים, אלא לעוון ההשתהות בגלות בשעה שהמציאות כבר מוכשרת לעלייה לארץ, שהוא מרחיק את קץ הגאולה, כמו בזמן עליית עזרא – שעלו עימו מעטים בלבד ורוב העם נשאר בבבל. ג. \"ושלא יגלו מסטירין [=מסתורין] שלהם לאומות העולם\" – שלא יגלו להן את ענייני סוד עיבור השנה וחישוב התקופות והמזלות, עליהם נאמר: \"כִּי הִוא חָכְמַתְכֶם וּבִינַתְכֶם לְעֵינֵי הָעַמִּים, אֲשֶׁר יִשְׁמְעוּן אֵת כָּל הַחֻקִּים הָאֵלֶּה, וְאָמְרוּ רַק עַם חָכָם וְנָבוֹן הַגּוֹי הַגָּדוֹל הַזֶּה\" (דברים ד ו). ד. \"ושלא יעלו חומה מן הגולה\" – שלא יעלו 'יחד ביד חזקה', במצב שבו פעולה כזו היא חסרת סיכוי, כמו בני אפרים שיצאו ממצרים לפני הזמן ונהרגו על ידי הפלישתים, או המעפילים בדור המדבר, שנהרגו על ידי העמלקים והכנענים. במאות האחרונות פג תוקפה של שבועה זו, בעקבות הכשרת המצב לתחייה לאומית בארץ, כפי שניתן לראות במציאות. 'שבועות' אלו אינן שבועות ממש, שהרי איש לא נשבע או ענה אמן על שבועה, אלא כוונת הגמרא והמדרש היא למציאות שיצר הקב\"ה, שבמשך הגלות לא יועילו פעולות התקוממות לאומית – גשמיות או רוחניות – פזיזות וחסרות סיכוי. הגלות נועדה כדי שעם ישראל יעבור תהליך תיקון רוחני הכרחי, וכל עוד לא הסתיים התהליך – כל ניסיון להחיש את הגאולה נידון לכישלון. הפסוקים בשיר השירים מהווים אזהרה שלא לבצע נסיונות כאלו. כאן אנו מבקשים שבזכות זאת שאנו שומרים את ארבע השבועות ואיננו מנסים לקטוע את תהליך התיקון, הקב\"ה יזרז אותו ויקרב את הקץ. הערות 203 שיר השירים רבה, פרשה ב, אות ז 204 ב ז, ג ה, ה ח, ח ד. 205 'יפה קול' על המדרש שם 206 שו\"ת חתם סופר, חלק ו סימן פו. הוא מציין דוגמא לכך: \"כגון יוסף די לה ריינא\"; יוסף די לה ריינא חי סביב תקופת גירוש ספרד וניסה לזרז את הגאולה על ידי שימוש בשמות הקודש ובהשבעות מלאכים. בסופו של דבר, נסיונו נכשל והסתיים באופן טראגי. 207 תלמוד בבלי, כתובות קיא.; בסוגיה שם מופיעים דברים דומים לדברי המדרש. 208 פרק ג סעיף יד. מחבר הספר הוא הרב יששכר שלמה טייכטל הי\"ד (תרמ\"ה-תש\"ה), ראש ישיבה ודיין בהונגריה, ומחבר שו\"ת 'משנה שכיר'. לנוכח אירועי השואה שינה את השקפתו האנטי-ציונית והחל לתמוך בציונות ובעלייה לארץ. את ספרו 'אם הבנים שמחה' כתב בתקופה בה הסתתר מאימת הנאצים, ובו הביע את השקפותיו הציוניות. סמוך לסוף המלחמה נרצח באושוויץ. 209 'מתנות כהונה' על המדרש שם 210 תלמוד בבלי, שבת עה. 211 לשון רש\"י, כתובות קיא. ד\"ה שלא 212 שם במדרש, על פי דברי הימים א' ז כא ותהילים עח ט 213 במדבר יד מ-מה 214 להרחבה בעניין שבועות אלו, משמעותן ותוקפן, ראה בספרו של הרב שלמה אבינר: 'עלֹה נעלה'. 215 על פי דברי הרמב\"ם באיגרת תימן. ראה איגרות הרמב\"ם, מהדורת הרב שילת חלק א עמ' קסו, ובהערתו שם"],[6,"s4","גָּשִׁים בְּשַׁוְעוֹת, דּוֹפְקֵי עֶרֶךְ שׁוּעוֹת","– ניגשים אליך בתפילה ומשוועים אליך, ודופקים על דלתך בתפילתם, בה הם עורכים את שוועותיהם."],[6,"s5","הוֹגֵי שַׁעְשְׁעוֹת","– עוסקים בדברי התורה שנקראו 'שעשועים', כפי שאומרת חכמת התורה בספר משלי: \"וָאֶהְיֶה אֶצְלוֹ אָמוֹן [=הקב\"ה גידלני כאומנת] וָאֶהְיֶה שַׁעֲשֻׁעִים יוֹם יוֹם, מְשַׂחֶקֶת לְפָנָיו בְּכָל עֵת. מְשַׂחֶקֶת בְּתֵבֵל אַרְצוֹ, וְשַׁעֲשֻׁעַי אֶת בְּנֵי אָדָם\" (ח ל-לא). כמבואר לעיל, השעשוע הוא דבר שאינו נעשה כאמצעי להשגת דבר אחר, אלא לשם ההנאה ממנו עצמו. כך גם דברי התורה חביבים על לומדיהם כשעשוע, ולפיכך הם הוגים בהם בכל עת. הפועל 'להגות' מציין דיבור שיש בו מחשבה ותבונה, בין דיבור בפה – \"פִּי צַדִּיק יֶהְגֶּה חָכְמָה\" (תהילים לז ל), ובין דיבור בלב – \"יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי\" (שם יט טו). הערות 216 בפירוש השורה 'חי כן תשעשעי', עמ' 93 217 ספר 'יאיר אור' למלבי\"ם, ערך 'הגה'"],[6,"s6","וְחִידוֹתָם מִשְׁתַּעְשְׁעוֹת","– על פי לשון הכתוב: \"לְהָבִין מָשָׁל וּמְלִיצָה, דִּבְרֵי חֲכָמִים וְחִידֹתָם\" (משלי א ו) – לומדי התורה משתעשעים בפיענוח החלקים הסתומים והקשים להבנה כחידות. היה מקום לומר שדווקא חלקים אלו בתורה, שהבנתם מצריכה עמל רב ויגיעה ממושכת, אינם בגדר 'שעשוע', אלא החלקים הקלים והנוחים יותר להבנה. אך לא כן הדבר: דווקא העמל, העיון, וההעמקה, משעשעים את הלומד במידה רבה יותר מאשר לימוד שטחי וקל; מי שחש קשר ואהבה לתורה ולנותנה, נהנה מעצם ההשקעה בלימודה, שכן היא זו שמחזקת ומעמיקה את הקשר האישי ביניהם. עמל התורה אינו רק אמצעי הכרחי כדי להבין דברים קשים, אלא בעל ערך מצד עצמו; הוא הכרחי כדי שיווצר קשר נפשי עמוק בין הלומד לבין הקב\"ה ותורתו."],[6,"s7","זוֹעֲקִים לְהַשְׁעוֹת","– זועקים אליך בתפילה ומבקשים שתשעה אליה = שתפנה אליה ותרצנה, כמו: \"וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ\" (בראשית ד ד). הערות 218 'לְהַשְׁעוֹת' – פועל יוצא בבניין הפעיל: לבקש ממך לשעות."],[6,"s8","חוֹכֵי יְשׁוּעוֹת","– מחכים לישועותיך, כלשון הכתוב: \"אַשְׁרֵי כָּל חוֹכֵי לוֹ\" (ישעיהו ל יח). בתקופה בה ממלכת יהודה היתה נתונה תחת איום ממלכת אשור, אמר ישעיהו פסוק זה כניגוד לאלו שהלכו לבקש ממלך מצרים שיעזור ליושבי יהודה ויגן עליהם מאשור; דבר זה נעשה בניגוד לציווי ה', שהורה לעם על ידי ישעיהו להיטיב את מעשיהם כדי להינצל מאשור, ולא להמשיך בדרכיהם הרעות ולבטוח במצרים. לעומת אנשים אלו \"הַהֹלְכִים לָרֶדֶת מִצְרַיִם וּפִי לֹא שָׁאָלוּ, לָעוֹז בְּמָעוֹז פַּרְעֹה וְלַחְסוֹת בְּצֵל מִצְרָיִם\", שלהם יהיה \"מָעוֹז פַּרְעֹה – לְבֹשֶׁת, וְהֶחָסוּת בְּצֵל מִצְרַיִם – לִכְלִמָּה\" (שם שם ב-ג), אלה המחכים לישועת ה' ומיטיבים את דרכיהם כך שיהיו ראויים לה – יזכו לראות בנחמה. כשם שבאותו זמן 'חוכי הישועות' שמעו לקול הנביא והיטיב את דרכיהם, כך גם בימינו – הציפייה לישועה הנדרשת מהאדם אין משמעותה רצון לבואה מתוך המתנה בחיבוק ידיים, אלא ביצוע הפעולות הנדרשות לשם קירובה: בין פעולות רוחניות – תשובה והשתפרות אישית, ובין פעולות מעשיות הנצרכות לפי הזמן והמציאות. הערות 219 ראה סידור 'עולת ראיה', חלק א, עמ' רעט; מאמרי הראי\"ה, עמ' 257"],[6,"s9","טְפוּלִים בְּךָ שְׁעוֹת","– דבקים בך ונצמדים אליך, על אף צרותיהם הרבות. 'טְפוּלִים' – מלשון ציפוי ודיבוק; 'שְׁעוֹת' הוא הנמשל: ישראל דבקים בקב\"ה בכך שהם שועים (=פונים) אליו בתפילה ובתקווה. ניתן גם לפרש ש'שְׁעוֹת' הוא אופן הדבקוּת ואיכותה – דבקות איתנה כמו טיח הדבוק על בית, כפי שתרגם אונקלוס את המילים: \"וְטָח אֶת הַבָּיִת\" (ויקרא יד מב) – \"וִישׁוּעַ יָת בֵּיתָא\". הערות 220 ראה תלמוד בבלי, שבת פ: \"בנות עניים טופלות אותן בסיד, בנות עשירים טופלות אותן בסולת\", ובהשאלה מכך המושג 'טפל' לעומת 'עיקר'. 221 כמו: \"בַּיּוֹם הַהוּא יִשְׁעֶה הָאָדָם עַל עֹשֵׂהוּ, וְעֵינָיו אֶל קְדוֹשׁ יִשְׂרָאֵל תִּרְאֶינָה\" (ישעיהו י ז ז)."],[6,"s10","יוֹדְעֵי בִין שָׁעוֹת","– יודעים את 'בינת השעות' – סוד עיבור השנה וחישוב התקופות והמזלות. על חשיבות ידיעת עניינים אלו והבנתם, נאמר בגמרא: אמר רבי שמעון בן פזי אמר רבי יהושע בן לוי משום בר קפרא: כל היודע לחשב בתקופות ומזלות ואינו חושב, עליו הכתוב אומר: \"וְאֵת פֹּעַל ה' לֹא יַבִּיטוּ, וּמַעֲשֵׂה יָדָיו לֹא רָאוּ\" (ישעיהו ה יב). אמר רבי שמואל בר נחמני אמר רבי יוחנן: מניין שמצוַה על האדם לחשב תקופות ומזלות? שנאמר: \"וּשְׁמַרְתֶּם וַעֲשִׂיתֶם כִּי הִוא חָכְמַתְכֶם וּבִינַתְכֶם לְעֵינֵי הָעַמִּים\" (דברים ד ו); איזו חכמה ובינה שהיא לעיני העמים [=שאף העמים מכירים בערכה]? הוֵי אומר: זה חישוב תקופות ומזלות. הראי\"ה קוק מסביר שחשיבות העיסוק בתחום זה נובעת מכך שהוא חושף את האדם לגדולת הבריאה והדרה, תכנונה המדוייק, ואופן הנהגתה המחושב. כל זה מעמיק בנפשו את ההכרה בגדולת ה' ובחכמתו, וכך הוא מתעלה למדרגה רוחנית גבוהה יותר. בכך הוא מסביר את ההבדל הקיים בעניין זה בין ישראל לעמים; העמים רואים בסדרי הבריאה רק את הצד החיצוני הנראה לעין, ואינם מעמיקים להכיר דרכם את המשמעות הפנימית שלהם. ישראל, לעומת זאת, מלבד בקיאותם בעניינים אלו בחיצוניותם, הם מכירים אף את משמעותם הפנימית – התגלות הקב\"ה באמצעות מרחבי הבריאה העצומים ואופן מהלכם המחושב לפרטי פרטים. הערות 222 תלמוד בבלי, שבת עה. 223 בפירושו 'עין איה' על אתר"],[6,"s11","כּוֹרְעֶיךָ בְּשַׁוְעוֹת","– כורעים לפניך בעת תפילותיהם ושוועותיהם. הכריעה מבטאת הכנעה והתבטלות כלפי הקב\"ה, ובכך היא מהווה מרכיב מהותי בתפילה, שעניינה הוא ההתבטלות בפני הקב\"ה, והכרה בכך שכל צרכינו מגיעים ממנו וקיומנו והוויתנו תלויים בו."],[6,"s12","לְהָבִין שְׁמוּעוֹת מִפִּיךָ נִשְׁמָעוֹת","– הושיענו בכך שתסייע לנו להבין את דברי התורה, שהם 'שְׁמוּעוֹת מִפִּיךָ נִשְׁמָעוֹת', באופן אמיתי, נכון, וישר, כפי שהיו אילו היו נשמעים מפיך; על פי לשון הכתוב: \"אֶת מִי יוֹרֶה דֵעָה, וְאֶת מִי י»ƒבין ¿שׁמוּ»עה \" (ישעיהו כח ט). ניתן גם לפרש שורות אלו כהמשך לשורה שלפניהן: 'כּוֹרְעֶיךָ בְּשַׁוְעוֹת לְהָבִין שְׁמוּעוֹת' – ישראל כורעים בתפילתם ומבקשים בה חכמה בינה ודעת, כדי להבין את שמועות התורה. הערות 224 סידור 'בית יעקב'"],[6,"s13","נוֹתֵן תְּשׁוּעוֹת","– על פי לשון הכתוב: \"הַנּוֹתֵן תְּשׁוּעָה לַמְּלָכִים\" (תהילים קמד י). ישנה גירסה נוספת, המתאימה יותר לסדר הדברים: נְפָשׁוֹת צַו שׁוֹמְעוֹת – שורה זו ממשיכה בעניין התורה שהוזכרה בשורות שלפניה, והיא מהווה בקשה לתשועת ישראל שהם 'נְפָשׁוֹת' ש'שׁוֹמְעוֹת' ולומדות את ציוויי התורה ומקיימות אותם ('שׁוֹמְעוֹת' במובן של לימוד, כמו: \"יִשְׁמַע חָכָם וְיוֹסֶף לֶקַח\" [משלי א ה], וגם במובן של עשייה, כמו: \"וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ אֶל מִצְוֹתַי\" [דברים יא יג]). הערות 225 כך מופיע ברוקח, בסידור רש\"ס, ובמחזור רומא."],[6,"s14","סְפוּרוֹת מְשַׁמְּעוֹת","– שורה זו, וכן זו שלאחריה, מתייחסות לנפשות ישראל שהוזכרו בשורה הקודמת, ומתארות את דבקותן בתורה; הן 'מְשַׁמְּעוֹת' (=מקבצות ואוספות) 'סְפוּרוֹת'; ה'סְפוּרוֹת' הן דברי תורה המנוסחים בצורה ממוספרת, כדברי הגמרא: אמר רבי אבהו: כתיב: \"וּמִשְׁפְּחוֹת סֹפְרִים יֹשְׁבֵי יַעְבֵּץ\" (דברי הימים א' ב נה); מה תלמוד לומר 'סֹפְרִים' [=לשם מה ציין זאת הכתוב]? אלא שעשו את התורה ספורות ספורות: \"חמישה לא יתרומו תרומה\", \"חמישה דברים חייבין בחלה\", \"חמש עשרה נשים פוטרות צרותיהן\", \"שלושים ושש כריתות בתורה\", \"שלושה עשר דבר נאמרו בנבלת העוף הטהור\", \"ארבעה אבות נזיקין\", \"אבות מלאכות ארבעים חסר אחת\". החשיבות של עריכת דיני התורה בצורה של רשימות ממוספרות, נובעת מכך שהיא מבטאת הסתכלות כללית על התורה, מתוך מבט מקיף ורחב, בו אפשר לקבץ הלכות שונות מנושאים שונים ולקבצם תחת כותרת אחת. כך תחומי התורה השונים מתלכדים זה עם זה ויוצרים תמונה כללית יותר המאפשרת להבין את עקרונותיה היסודיים של התורה. עריכה כזו גם מאפשרת לזכור היטב את הדינים בצורה מסודרת, ומבטאת את האחריות האישית שהלומד רואה לעצמו על ידיעתו את התורה היטב, לכל פרטיה. ה'סְפוּרוֹת' הן גם ספירות אותיות התורה, מילותיה, ופסוקיה, כדברי הגמרא: לפיכך נקראו ראשונים 'סופרים': שהיו סופרים כל האותיות שבתורה. שהיו אומרים: ו' ד\"גָּחוֹן\" (ויקרא יא מב) – חציין של אותיות של ספר תורה, \"דָּרֹשׁ דָּרַשׁ\" (שם י טז)– חציין של תיבות, \"וְהִתְגַּלָּח\" (שם יג לג) – של פסוקים, \"יְכַרְסְמֶנָּה חֲזִיר מִיָּעַר\" (תהילים פ יד) – ע' ד\"יָּעַר\" – חציין של תהלים, \"וְהוּא רַחוּם יְכַפֵּר עָוֹן\" (שם עח ל) – חציו דפסוקים. חשיבותה של ספירה זו נעוצה בכך שהיא מבטאת את ערכה העליון והאלוהי של התורה – לא תוכנהּ בלבד הוא בעל משמעות, אלא אף הפרטים הקטנים ביותר שבה, כמו מספר האותיות והמילים, ואלו אותיות נבחרו להופיע באמצעיתו של הספר – הם בעלי משמעות. התורה, כדבר שנכתב ברוח הקודש על פי הקב\"ה – מוכרחת להיות מושלמת בתכלית, וודאי שכל פרט שבה – בין גדול ובין קטן – טומן בחובו כוונה ותוכן נסתרים. הערות 226 כמו: \"וַיְשַׁמַּע שָׁאוּל אֶת הָעָם\" (שמואל א' טו ד). 227 תלמוד ירושלמי, שקלים, פרק ה, הלכה א 228 תלמוד בבלי, קידושין ל."],[6,"s15","עֵדוּת מַשְׁמִיעוֹת","– נפשות ישראל משמיעות את דברי התורה, שנקראו 'עֵדוּת', כמו שכתוב: \"תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ, ≈עדוּת ה' נֶאֱמָנָה מַחְכִּימַת פֶּתִי\" (תהילים יט ח). החלק הסיפורי שבתורה מהווה 'עֵדוּת' על העבר, והחלק ההלכתי מהווה 'עֵדוּת' מלשון אזהרה, כמו: \"רֵד »ה≈עד בָּעָם פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת\" (שמות יט כא). קיימת חשיבות מיוחדת ללימוד החלק הסיפורי שבתורה, שכן דרכו מעבירה התורה מסרים ועקרונות כלליים בתחומי האמונה, המידות, והמוסר, וכך הלומד משפר את אישיותו באופן ממשי כתוצאה מהלימוד. התורה לא נועדה להוסיף באדם ידיעות, אלא לשפר את אישיותו ומידותיו של הלומד; מתוך העיסוק בסיפורי התורה, מטרה זו מתממשת."],[6,"s16","פּוֹעֵל יְשׁוּעוֹת","– כלשון הכתוב: \"וֵאלֹהִים מַלְכִּי מִקֶּדֶם, פֹּעֵל יְשׁוּעוֹת בְּקֶרֶב הָאָרֶץ\" (תהילים עד יב). תוכן המזמור כולו הוא תפילה לקב\"ה לגאולת ישראל והכנעת אויביהם: מַשְׂכִּיל לְאָסָף, לָמָה אֱלֹהִים זָנַחְתָּ לָנֶצַח, יֶעְשַׁן אַפְּךָ בְּצֹאן מַרְעִיתֶךָ. זְכֹר עֲדָתְךָ קָנִיתָ קֶּדֶם, גָּאַלְתָּ שֵׁבֶט נַחֲלָתֶךָ, הַר צִיּוֹן זֶה שָׁכַנְתָּ בּוֹ. [...] שִׁלְחוּ בָאֵשׁ מִקְדָּשֶׁךָ, לָאָרֶץ חִלְּלוּ מִשְׁכַּן שְׁמֶךָ. [...] עַד מָתַי אֱלֹהִים יְחָרֶף צָר, יְנָאֵץ אוֹיֵב שִׁמְךָ לָנֶצַח. [...] וֵאלֹהִים מַלְכִּי מִקֶּדֶם, פֹּעֵל יְשׁוּעוֹת בְּקֶרֶב הָאָרֶץ. [...] זְכָר זֹאת אוֹיֵב חֵרֵף ה', וְעַם נָבָל נִאֲצוּ שְׁמֶךָ. [...] קוּמָה אֱלֹהִים רִיבָה רִיבֶךָ, זְכֹר חֶרְפָּתְךָ מִנִּי נָבָל כָּל הַיּוֹם. אַל תִּשְׁכַּח קוֹל צֹרְרֶיךָ, שְׁאוֹן קָמֶיךָ עֹלֶה תָמִיד. אף שורה זו בפיוט פותחת את יחידת השורות החותמות אותו, שתוכנן הוא תפילה לקירוב הגאולה האחרונה והכנעת אויבי ישראל במלחמת גוג ומגוג."],[6,"s17","צַדִּיק נוֹשָׁעוֹת","– הושע נא את צדיק הנושעות = מלך המשיח, בכך שימלא את שליחותו וילחם מלחמות ישראל, ובהן תעזור לו ותושיענו; על פי לשון הכתוב: \"גִּילִי מְאֹד בַּת צִיּוֹן, הָרִיעִי בַּת יְרוּשָׁלִַם, הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ, צדּƒיק ו¿!וֹ»שׁע הוּא, עָנִי וְרֹכֵב עַל חֲמוֹר וְעַל עַיִר בֶּן אֲתֹנוֹת\" (זכריה ט ט), ופירש 'מצודת דוד': \"'הִנֵּה מַלְכֵּךְ' – זה מלך המשיח; 'צַדִּיק' – במעשיו יהיה צדיק, ובמלחמותיו יהיה נוֹשָׁע ומוצלח\". לפי זה, משמעות התואר 'צַדִּיק נוֹשָׁעוֹת' הוא: צדיק שהקב\"ה פועל דרכו ישועות והצלחות."],[6,"s18","קָרֵב תְּשׁוּעוֹת","– קרב במהרה בימינו את התשועות שהובטחו על ידי הנביאים לעת הגאולה העתידה. יש גורסים: קִרְיַת תְּשׁוּעוֹת – הושע נא את ירושלים, שהיא הקריה שבה מיועדות התשועות העתידיות להתחולל. הערות 229 רוקח"],[6,"s19","רֶגֶשׁ תְּשׁוּאוֹת","– על פי לשון הכתוב לגבי מלחמת גוג ומגוג: \"לָמָּה ר»ג¿שׁוּ גוֹיִם, וּלְאֻמִּים יֶהְגּוּ רִיק. יִתְיַצְּבוּ מַלְכֵי אֶרֶץ, וְרוֹזְנִים נוֹסְדוּ יָחַד, עַל ה' וְעַל מְשִׁיחוֹ\" (תהילים ב א-ב). 'רֶגֶשׁ' הוא קיבוץ ואסיפה; בפסוק – אסיפת הגויים, ובפיוט – אסיפת ה'תְּשׁוּאוֹת' = קולות המלחמה. אנו מתפללים להיוושע באותה מלחמה – 'רֶגֶשׁ תְּשׁוּאוֹת': להיוושע על ידה מצרות הגלות והאויבים העכשוויים, וכן להיוושע ולהינצל בה עצמה, שהרי עלולה היא לגבות קורבנות גם מעם ישראל. הערות 230 ראה תלמוד בבלי, ברכות ז:, י. 231 רש\"י ומצודת ציון שם 232 תשואות = קולות, כמו: \"תְּשֻׁאוֹת מְלֵאָה עִיר הוֹמִיָּה\" (ישעיהו כב ב), ובענייננו – של מלחמה."],[6,"s20","שָׁלשׁ שָׁעוֹת","– שורה זו היא המשך לקודמתה: אנו מתפללים לישועה במלחמת גוג ומגוג, שתימשך שלוש שעות, כדברי המדרש: אמר רבי ברכיה: בשלוש שעות הקב\"ה פורע מן עשו הרשע ומאלופיו. מה טעם? – \"עַתָּה אָקוּם יֹאמַר ה', עַתָּה אֵרוֹמָם, עַתָּה אֶנָּשֵׂא\" (ישעיהו לג י). המדרש לומד משלושת הפעלים שמזכיר הנביא: \"אָקוּם, אֵרוֹמָם, אֶנָּשֵׂא\" – שמלחמה זו, בה הקב\"ה יקום להשמיד את אויביו, ועל ידי כך יתרומם ויתנשא – תימשך שלוש שעות. ה'טור' כותב בשם רב האי גאון שמלחמת גוג ומגוג עתידה להיות בתשרי, ובספר 'פרי עץ חיים' נאמר שתתקיים ב'הושענא רבה', וכן ישנה מסורת בשם הגר\"א. גם מפשט הפסוקים בספר זכריה נראה שמלחמה זו תהיה בסוכות, ולפיכך הגויים שיוותרו לאחריה יעלו לירושלים מידי שנה לחוג את חג הסוכות. ניתן לבסס הנחה זו על הנבואה שנמסרה לחגי ביום הושענא רבה, המתארת בקצרה את מלחמה זו: בַּשְּׁבִיעִי בְּעֶשְׂרִים וְאֶחָד לַחֹדֶשׁ, הָיָה דְּבַר ה' בְּיַד חַגַּי הַנָּבִיא לֵאמֹר: [...] כִּי כֹה אָמַר ה' צְבָאוֹת עוֹד אַחַת מְעַט הִיא, וַאֲנִי מַרְעִישׁ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ וְאֶת הַיָּם וְאֶת הֶחָרָבָה. וְהִרְעַשְׁתִּי אֶת כָּל הַגּוֹיִם, וּבָאוּ חֶמְדַּת כָּל הַגּוֹיִם, וּמִלֵּאתִי אֶת הַבַּיִת הַזֶּה כָּבוֹד, אָמַר ה' צְבָאוֹת. לִי הַכֶּסֶף וְלִי הַזָּהָב, נְאֻם ה' צְבָאוֹת. גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן, אָמַר ה' צְבָאוֹת, וּבַמָּקוֹם הַזֶּה אֶתֵּן שָׁלוֹם, נְאֻם ה' צְבָאוֹת. את הזיקה בין מלחמה זו לבין חג הסוכות ניתן להסביר על פי מה שכתב ה'טור', שחג הסוכות הוא הרגל שכנגד יעקב אבינו; יעקב מסמל את המלחמה בעשו ובצאצאיו – רומא – המלכות הרביעית, הלוא היא הנצרות והעמים שתחתיה, ששולטים בעולם ונלחמים בתקומת ישראל ובהופעת שם ה' על ידו, ולעתיד לבוא יבואו עם גוג למלחמת מחץ על ישראל. יעקב מסמל את ה'עָקֵב' – הסוף, סופו של השלב הנוכחי בהיסטוריה, והתעלות המציאות למצב מרומם יותר. גם מצוַת הישיבה בסוכה קשורה לעניינה של מלחמה זו, שכן הסוכה מסמלת את הגנת הקב\"ה על עמו: בזכות הסתופפותם בצל הסוכה, בה הם חוסים בצילו של הקב\"ה – זוכים הם לשמירה והגנה, כדברי המדרש: \"וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב\" (ישעיהו ד ו) – כל מי שמקיים מצוַת סוכה בעולם הזה הקב\"ה מסיך [=מסוכך, מגן] עליו מן המזיקין שלא יזיקו אותו, שכן הוא אומר: \"בְּאֶבְרָתוֹ יָסֶךְ לָךְ וְתַחַת כְּנָפָיו תֶּחְסֶה\" (תהילים צא ד). גם באותה מלחמה יגן הקב\"ה על ישראל הנאמנים לו וחוסים בצילו, כמאמר הכתוב: \"וַה' מַחֲסֶה לְעַמּוֹ וּמָעוֹז לִבְנֵי יִשְׂרָאֵל\" (יואל ד טז). וְהָיָה בַּיּוֹם הַהוּא בְּיוֹם בּוֹא גוֹג עַל אַדְמַת יִשְׂרָאֵל – נְאֻם אֲדֹנָי יֱהֹוִה – תַּעֲלֶה חֲמָתִי בְּאַפִּי. וּבְקִנְאָתִי בְאֵשׁ עֶבְרָתִי דִּבַּרְתִּי: אִם לֹא בַּיּוֹם הַהוּא יִהְיֶה רַעַשׁ גָּדוֹל עַל אַדְמַת יִשְׂרָאֵל. וְרָעֲשׁוּ מִפָּנַי דְּגֵי הַיָּם, וְעוֹף הַשָּׁמַיִם, וְחַיַּת הַשָּׂדֶה, וְכָל הָרֶמֶשׂ הָרֹמֵשׂ עַל הָאֲדָמָה, וְכֹל הָאָדָם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה, וְנֶהֶרְסוּ הֶהָרִים וְנָפְלוּ הַמַּדְרֵגוֹת, וְכָל חוֹמָה לָאָרֶץ תִּפּוֹל. וְקָרָאתִי עָלָיו לְכָל הָרַי חֶרֶב – נְאֻם אֲדֹנָי יֱהֹוִה – חֶרֶב אִישׁ בְּאָחִיו תִּהְיֶה. וְנִשְׁפַּטְתִּי אִתּוֹ בְּדֶבֶר וּבְדָם, וְגֶשֶׁם שׁוֹטֵף וְאַבְנֵי אֶלְגָּבִישׁ, אֵשׁ וְגָפְרִית – אַמְטִיר עָלָיו וְעַל אֲגַפָּיו, וְעַל עַמִּים רַבִּים אֲשֶׁר אִתּוֹ. וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי לְעֵינֵי גּוֹיִם רַבִּים, וְיָדְעוּ כִּי אֲנִי ה'. הערות 233 שיר השירים רבה, פרשה ד, אות ח 234 אורח חיים, סימן תצ 235 לאר\"י ז\"ל, שער הלולב, סוף פרק ה: \"'גוג ומגוג' עולה שבעים [בגימטריה] כנגד שבעים אומות; כי אז ימלוך גוג על שבעים אומות ויבואו יחד על ישראל, וכשיגאלו מידם אז יהיה תשועה רבה. כי עתה שנגאלו ממדי ויוון - גלו לאדום, וכן בכל יום ויום: ניצולו מיד זה, ונופלים ליד זה. ויום הזה ניצולו מיד כולם; לכן הוא [נקרא] יום 'הושענא רבה'\". 236 מובא בספר 'שלמי תודה' עמ' תתקלז, ועוד 237 ראה זכריה יד טז, ורד\"ק שם 238 כך פירשו מלבי\"ם ומצודת דוד (בשונה ממפרשים אחרים שפירשו נבואה זו כמתייחסת למלחמות בזמן בית שני), וכך נראה גם מדברי המדרש (שמות רבה, פרשה יח, אות יב; דברים רבה, פרשה א, אות כג). 239 חגי ב א-ט 240 אורח חיים, סימן תיז: \"לפי שהמועדים נתקנו כנגד האבות: פסח כנגד אברהם, דכתיב: \"לוּשִׁי וַעֲשִׂי עֻגוֹת\" (בראשית יח ו), ופסח היה; שבועות כנגד יצחק, שתקיעת שופר של מתן תורה היה בשופר מאילו של יצחק; סוכות כנגד יעקב, דכתיב: \"וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת\" (שם לג יז). 241 ראה רש\"י בראשית לו מג: \"'אַלּוּף מַגְדִּיאֵל' – 'הוא רומי'\". 242 פסיקתא דרב כהנא, פיסקה כט 243 יחזקאל לח יח-כג"],[6,"s21","תָּחִישׁ לִתְשׁוּעוֹת","– שורה זו חותמת את הפיוט בבקשה להחיש את התשועות של תהליך הגאולה; כמבואר לעיל, ה'החשה' היא שהפעולה עצמה נעשית בזמן קצר. אנו נמצאים כבר בתוך תהליך הגאולה, הרצוף תשועות גדולות וקטנות, גלויות ונסתרות, ובמקביל להן מתרחשים גם מאורעות קשים – 'חבלי משיח'; אנו מתפללים שהקב\"ה יחיש תהליך תשועות זה, ויקרב במהרה את הקץ. הערות 244 בביאור השורה יוחש מושיעי', עמ' 94"],[6,"s22","סיכום","פיוט זה מתמקד בתיאור שבחם של ישראל ודבקותם בקב\"ה, המתבטאת בשני הערוצים המרכזיים המיועדים לכך: התורה והתפילה. שני אלה מקיפים את חיי היהודי, וכשהוא מקיימם באופן הנכון, הם יוצרים בנפשו קירבה לקב\"ה באמצעות שני כוחותיו המרכזיים: השכל והרגש. תחילת הפיוט מורכבת מבקשות על הגאולה מהגלות: 'אֵל לְמוֹשָׁעוֹת, בְּאַרְבַּע שְׁבוּעוֹת' – לעם ישראל אין יכולת להיוושע בכוחות עצמו מן הגלות, בעקבות ה'שבועות' – המציאות הכפויה עליו, ולא נותר לו אלא להתפלל לקבלת סיוע אלוהי לשיבתו לארץ ולתחייתו הלאומית. כך אנו ניגשים לתפילה זו – כמו לכל תפילה – מתוך הכרה שאין לנו יכולת לעשות או להשיג דבר ללא עזרת הקב\"ה. ליבו של הפיוט, מתאר את הקשר המיוחד שבין ישראל לבין הקב\"ה, המתבטא בתורתם ובתפילתם, על הופעותיו השונות: בתפילה – 'גָּשִׁים בְּשַׁוְעוֹת, דּוֹפְקֵי עֶרֶךְ שׁוּעוֹת', ובתורה – 'הוֹגֵי שַׁעְשְׁעוֹת, וְחִידוֹתָם מִשְׁתַּעְשְׁעוֹת' – הם כה דבקים בתורה וקשורים בה בנפשם, עד שהוגים בה בכל עת כשעשוע, ומשתעשעים בעמלם על הבנת דבריה הקשים והעמוקים, כגון ענייני עיבור השנה וחישוב התקופות – 'יוֹדְעֵי בִין שָׁעוֹת'; לומדים את ההלכות המעשיות על מנת לקיימן – 'נְפָשׁוֹת צַו שׁוֹמְעוֹת'; עורכים ומסדרים את דיניה ברשימות מסודרות ומרחיבים את הכרתם אותה עד לפרטי הפרטים, מספרי המילים והאותיות – 'סְפוּרוֹת מְשַׁמְּעוֹת'; ולומדים את החלק הסיפורי שבה – 'עֵדוּת מַשְׁמִיעוֹת', תוך קליטת המסרים האלוהיים המועברים בהם: אמונה, מוסר, ומידות. תיאור תורתם ותפילתם של ישראל מהווה חלק מהותי מהבקשה לגאולה, משום שהם הגורמים המהווים הצדקה לבואה. זאת, מכיוון שבזמן הגאולה עם ישראל יהיה 'אור לגויים', כדברי הנביא: \"בַּיָּמִים הָהֵמָּה אֲשֶׁר יַחֲזִיקוּ עֲשָׂרָה אֲנָשִׁים מִכֹּל לְשֹׁנוֹת הַגּוֹיִם, וְהֶחֱזִיקוּ בִּכְנַף אִישׁ יְהוּדִי לֵאמֹר: נֵלְכָה עִמָּכֶם, כִּי שָׁמַעְנוּ אֱלֹהִים עִמָּכֶם (\"זכריה ח כג), ולפיכך – כדי להיות מוכשר לתפקידו בעת הגאולה, עליו לחיות באופן שבו הוא מייצג את הקב\"ה כראוי: דבק בערכים האלוהיים, ומיישם אותם בחייו. אנו פונים לקב\"ה, וטוענים כלפיו, כביכול, שעם ישראל כבר עומד במצב הנדרש כדי לגאלו: הוא דבק בתורה – הופעת דבר ה' בעולם, ובתפילה – עבודת ה' ברגשות הלב. באמצעות תפילה זו, אנו מזכירים לעצמנו את מטרתנו בעולם – כיחיד וכאומה, ואת הדרישה האלוהית מאיתנו להתאים את אורח חייינו ומעשינו לאופן שבו הם צריכים להתנהל על פי רצון ה', וכך נהיה זכאים להיגאל. משום כך, לעתיד לבוא, רק אלו שעמדו במבחן של השלב הראשון – העולם הזה, וצורת חייהם תואמת לזו הנדרשת – יוכלו לעבור ל'שלב הבא'; וכך ניבא הנביא יואל על מלחמת גוג ומגוג, שתתקיים לפני הגאולה האחרונה: וְנָתַתִּי מוֹפְתִים בַּשָּׁמַיִם וּבָאָרֶץ, דָּם וָאֵשׁ, וְתִימֲרוֹת עָשָׁן. הַשֶּׁמֶשׁ יֵהָפֵךְ לְחֹשֶׁךְ, וְהַיָּרֵחַ לְדָם, לִפְנֵי בּוֹא יוֹם ה' הַגָּדוֹל וְהַנּוֹרָא. וְהָיָה כֹּל אֲשֶׁר יִקְרָא בְּשֵׁם ה' – יִמָּלֵט, כִּי בְּהַר צִיּוֹן וּבִירוּשָׁלַםִ תִּהְיֶה פְלֵיטָה כַּאֲשֶׁר אָמַר ה', וּבַשְּׂרִידִים אֲשֶׁר ה' קֹרֵא . כֹּל אֲשֶׁר יִקְרָא בְּשֵׁם ה' יִמָּלֵט – רוצה לומר: הקוראים בשם ה' המה ימלטו מן הצרה הבאה על העכו''ם, כִּי בְּהַר צִיּוֹן – רוצה לומר: כי הפליטה תהיה בהר ציון לבד, כמו שהבטיח ה', וגם שָׁם – לא לכולם, כי [=אלא] רק בנשארים המבוררים שבהם, אשר כל אחד מהם קורא אל ה' וצועק אליו ומשים בו בטחונו. אנו חותמים את הפיוט בציפייתנו לביאת המשיח – 'צַדִּיק נוֹשָׁעוֹת', ולמלחמת גוג ומגוג, בו תמוגר הרִשעה מן העולם, וכל באי עולם – ישראל והעמים – יקבלו עליהם עול מלכות ה' ויעבדוהו – \"כִּי לִי תִּכְרַע כָּל בֶּרֶךְ, תִּשָּׁבַע כָּל לָשׁוֹן\" (ישעיהו מה כג) – 'קָרֵב תְּשׁוּעוֹת: רֶגֶשׁ תְּשׁוּאוֹת, שָׁלשׁ שָׁעוֹת – תָּחִישׁ לִתְשׁוּעוֹת, הוֹשַׁע נָא!\" לָכֵן חַכּוּ לִי נְאֻם ה' לְיוֹם קוּמִי לְעַד, כִּי מִשְׁפָּטִי לֶאֱסֹף גּוֹיִם לְקָבְצִי מַמְלָכוֹת, לִשְׁפֹּךְ עֲלֵיהֶם זַעְמִי כֹּל חֲרוֹן אַפִּי, כִּי בְּאֵשׁ קִנְאָתִי תֵּאָכֵל כָּל הָאָרֶץ. כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה, לִקְרֹא כֻלָּם בְּשֵׁם ה', לְעָבְדוֹ שְׁכֶם אֶחָד. וְהָיָה יוֹם אֶחָד, הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לָיְלָה, וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר. [...] וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ, בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. הערות 245 יואל ג ג-ה 246 מצודת דוד, שם 247 צפניה ג ח-ט 248 זכריה יד ז,ט"],[6,"n202","הערה 202","ראה בראשית לא כט: \"יֶש לְאֵל יָדִי לַעֲשׂוֹת עִמָּכֶם רָע\"; יחזקאל יז יג: \"וְאֵת אֵילֵי הָאָרֶץ לָקָח\"."],[7,"piyut","נוסח הפיוט","הוֹשַׁע נָא אָדוֹן הַמּוֹשִׁיעַ. לְגֵיא בַּל תַּרְשִׁיעַ. בִּלְתְּךָ אֵין לְהוֹשִׁיעַ. מְגָדִים תַּמְתִּיק וְתוֹשִׁיעַ. גִּבּוֹר וְרַב לְהוֹשִׁיעַ. נְשִׂיאִים לְהַסִּיעַ. דַּלֹּתִי וְלִי יְהוֹשִׁיעַ. שְׂעִירִים לְהָנִיעַ. הָאֵל הַמּוֹשִׁיעַ. עֲנָנִים מִלְּהַמְנִיעַ. וּמַצִּיל וּמוֹשִׁיעַ. פּוֹתֵחַ יָד וּמַשְׂבִּיעַ. זוֹעֲקֶיךָ תּוֹשִׁיעַ. צְמֵאֶיךָ תַּשְׂבִּיעַ. חוֹכֶיךָ הוֹשִׁיעַ. קוֹרְאֶיךָ תּוֹשִׁיעַ. טְלָאֶיךָ תַּשְׂבִּיעַ. רְחוּמֶיךָ תּוֹשִׁיעַ. יְבוּל לְהַשְׁפִּיעַ. שׁוֹחֲרֶיךָ הוֹשִׁיעַ. כָּל שִׂיחַ תַּדְשֵׁא וְתוֹשִׁיעַ. תְּמִימֶיךָ תּוֹשִׁיעַ. הוֹשַׁע נָא."],[7,"s1","על הפיוט","הפיוט הבא מורכב מבקשות לישועה באופן כללי, ובפרט לריבוי גשמים, להצלחת החקלאות, ולשפע כלכלי."],[7,"s2","אָדוֹן הַמּוֹשִׁיעַ","– הפיוט פותח, לפני הצגת הבקשות עצמן, בהכרה ביכולתו של הקב\"ה להושיע; מבחינה זו, הפיוט דומה לתפילת העמידה, הפותחת אף היא בשלוש ברכות של שבח, המקדימות את ברכות הבקשה. הגמרא לומדת את הצורך בפתיחה כזו מתפילתו של משה: דרש רבי שמלאי: לעולם יסדר אדם שבחו של הקב''ה ואחר כך יתפלל. מנלן [=מניין]? ממשה, דכתיב: \"וָאֶתְחַנַּן אֶל ה' בָּעֵת הַהִוא\", וכתיב: \"אֲדֹנָי יֱהֹוִה, אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ אֶת גָּדְלְךָ וְאֶת יָדְךָ הַחֲזָקָה, אֲשֶׁר מִי אֵל בַּשָּׁמַיִם וּבָאָרֶץ אֲשֶׁר יַעֲשֶׂה כְמַעֲשֶׂיךָ וְכִגְבוּרֹתֶךָ\", וכתיב בתריה [=וכתוב אחריו]: \"אֶעְבְּרָה נָּא וְאֶרְאֶה אֶת הָאָרֶץ הַטּוֹבָה אֲשֶׁר בְּעֵבֶר הַיַּרְדֵּן, הָהָר הַטּוֹב הַזֶּה וְהַלְּבָנֹן\" (דברים ג כג-כה). חשיבותה של פתיחה מעין זו נעוצה בעצם עניינה של התפילה: התפילה לא נועדה כדי 'לשכנע' את הקב\"ה, כפי שאפשר לחשוב בתפיסה שטחית. מטרת התפילה היא להעלות ולרומם את מעמדו הרוחני של המתפלל; בתפילה, האדם משריש ומעמיק בתודעתו את תלותו המוחלטת בקב\"ה, ומפנים את הידיעה על כך שאין לו יכולת לעשות דבר לולי עזרתו. ממילא נגזרות מכך הרגשה של הכרת הטוב כלפיו, הרגשה של מחוייבות טבעית למצוותיו, אהבתו, ויראה מרוממותו. בדומה ללב האדם, המזרים דם וחיות לכל אברי הגוף, כך התפילה מזרימה חיות לכל מידותיו והרגשותיו החיוביות של האדם, ועל ידי כך עושה אותו ראוי יותר לקבל את מבוקשו; לא כשכר חיצוני על השתפרותו הרוחנית, אלא כתוצאה טבעית שלה: ככל שהאדם קרוב יותר לקב\"ה – מקור הברכות והמשאלות, כך גישתו אליהן ויכולתו להשיגן – קלות יותר. כדי שהתפילה אכן תוכל לפעול את פעולתה בלב האדם, ראשית כל – עליו להיפגש עם יכולתו וגדולתו של הקב\"ה ולהכיר בהן, וכהמשך טבעי להכרה זו – לבקש ממנו את בקשותיו. משום כך, תפילת העמידה, וכן פיוט זה – פותחים בדברי שבח לקב\"ה. ניתן לראות הקבלה בין שורה זו, הראשונה בפיוט, לבין הברכה הראשונה בתפילת העמידה: 'מגן אברהם'. בברכה זו אנו מזכירים, לפני תיאור מידותיו של הקב\"ה (המופיע בשתי הברכות שלאחריה), שני עקרונות יסודיים: עצם בעלותו של הקב\"ה על העולם, המתחייבת מכך שהוא בראו , ו הקשר הקיים בינו לבין עולמו: \"אֱלֹהֵי אַבְרָהָם, אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב\" – שפרסמו בעולם את האמונה בקב\"ה, \"אֵל עֶלְיוֹן\" – למעלה מכל השגה שכלית ומכל יכולת תיאור, שהרי הוא עצמו ברא את העולם ועומד מחוץ לו, \"גּוֹמֵל חֲסָדִים טוֹבִים\" – מקיים קשר עם העולם ואכפת לו מהנעשה בו, \"וְקוֹנֵה הַכֹּל\" – בורא הכול. זהו גם תוכנה של שורה זו בפיוט – 'אָדוֹן הַמּוֹשִׁיעַ': 'אָדוֹן' – בעליה של כל המציאות, שהרי הוא בראה , 'הַמּוֹשִׁיעַ'– מקיים קשר עם ברואיו ומושיעם בעת צרה. שני עקרונות אלו הם מיסודות האמונה היהודית, והם מהווים פתיחה הכרחית לתפילה ראויה. ניתן למצוא רמז להקבלה זו בדברי הגמרא: \"מיום שברא הקב\"ה את עולמו לא היה אדם שקראו להקב\"ה 'אדון', עד שבא אברהם וקראו 'אדון' \"."],[7,"s3","בִּלְתְּךָ אֵין לְהוֹשִׁיעַ, גִּבּוֹר וְרַב לְהוֹשִׁיעַ","– כהמשך לרעיון ההקבלה שהוצג בביאור השורה הקודמת, את שתי שורות אלו ניתן להקביל לברכה השנייה בתפילת העמידה: 'גבורות'; עניינה של ברכה זו הוא לתאר את יכולתו האין-סופית והבלעדית של הקב\"ה, ולהעמיק זאת בתודעת המתפלל: אַתָּה, גִּבּוֹר לְעוֹלָם, אֲדֹנָי. מְחַיֵּה מֵתִים אַתָּה, רַב לְהוֹשִׁיעֵ . בהמשך הברכה מפורט כיצד כל הפעולות המניעות את העולם ומיטיבות עם יושביו, מקורן בקב\"ה: מוֹרִיד הַטָּל \\ מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם. מְכַלְכֵּל חַיִּים בְּחֶסֶד, מְחַיֵּה מֵתִים בְּרַחֲמִים רַבִּים, סוֹמֵךְ נוֹפְלִים, וְרוֹפֵא חוֹלִים, וּמַתִּיר אֲסוּרִים, וּמְקַיֵּם אֱמוּנָתוֹ לִישֵׁנֵי עָפָר. הרשימה מסתיימת בהכרזה על בלעדיותו של הקב\"ה כמנהיג העולם: מִי כָמוֹךָ בַעַל גְּבוּרוֹת, וּמִי דוֹמֶה לָּךְ? מֶלֶךְ מֵמִית וּמְחַיֶּה, וּמַצְמִיחַ יְשׁוּעָה. כשם שברור לנו שרק הקב\"ה יכול לקיים אמונתו לישני עפר = להחיות מתים, כך צריך להיות ברור לנו שכל הפעולות שפורטו לפני כן, מקורן אך ורק בו. כשם שרק הוא 'מֵמִית וּמְחַיֶּה', כך רק הוא 'מַצְמִיחַ יְשׁוּעָה': אף את הישועות הטבעיות, כהורדת גשמים, רפואת חולים, והתרת אסורים. בברכת 'גבורות' ובשתי שורות אלו של הפיוט, טמונים שני עקרונות נוספים מיסודות האמונה היהודית: יכולתו הבלתי-מוגבלת של הקב\"ה – \"גִּבּוֹר וְרַב לְהוֹשִׁיעַ\", והבלעדיות שלה, הקשורה באמונה באחדות ה' – \"בִּלְתְּךָ אֵין לְהוֹשִׁיעַ\", \"מִי כָמוֹךָ בַעַל גְּבוּרוֹת, וּמִי דוֹמֶה לָּךְ\"."],[7,"s4","דַּלֹּתִי וְלִי יְהוֹשִׁיעַ","– כלשון הכתוב: \"שֹׁמֵר פְּתָאיִם ה', דַּלֹּתִי וְלִי יְהוֹשִׁיעַ\" (תהילים קטז ו); ופירש המלבי\"ם: אנשים שאינם נוהגים בחכמה ולא הולכים בדרך הראויה (='פתיים'), הקב\"ה מביא עליהם ייסורים כדי להחזירם למוטב, ועל ידי כך שומר עליהם מלהיענש בעולם הבא, ולכן: 'דַּלֹּתִי' (=חליתי), כדי שאתקן את מעשַי, וכיוון שעשיתי זאת, 'לִי יְהוֹשִׁיעַ' – יושיעני מהמחלה. ניתן לפרש באופן נוסף: 'דַּלֹּתִי' – הכנעתי את רוחי בענווה ושפלות לפני ה' (מלשון 'דל' = עני) בחרטה על מעשַי, וכיוון שכך – 'לִי יְהוֹשִׁיעַ'. כאן הפיוט עובר מתארים כלליים של הקב\"ה, לביטוי שמתייחס באופן אישי למתפלל; לאחר שזה הכיר באדנותו המוחלטת של הקב\"ה על העולם וביכולתו האין-סופית, הוא מביע את אמונתו בכך שתכונות כלליות אלה תמומשנה כלפיו באופן אישי. הפסוק מתהילים שהוזכר, לא נאמר כבקשה, אלא כהבעת אמונה; כיוון שהאדם נכנע לפני הקב\"ה ומתקן את מעשיו, בטוח הוא בכך שיזכה לישועה. גם אם הישועה לא תבוא באופן שבו הוא מצפה, הרי הוא סמוך ובטוח שהקב\"ה יסדר את העניינים עבורו על הצד הטוב ביותר, כיוון שהוא עשה את המצופה ממנו. גם עיקרון זה – האמונה בהתקבלותן הוודאית של התפילה והתשובה לפני ה', היא מיסודות האמונה היהודית, ונחוץ שהמתפלל יכיר בו בטרם ייגש לשטוח את בקשותיו בתפילתו. הערות 251 כמו: \"מַדּוּעַ אַתָּה כָּכָה דַּל בֶּן הַמֶּלֶךְ\" (שמואל ב' יג ד)."],[7,"s5","הָאֵל הַמּוֹשִׁיעַ","– כלשון חתימת ברכת 'הרב את ריבנו' הנאמרת לאחר קריאת המגילה: \"הַנִּפְרָע לְעַמּוֹ יִשְׂרָאֵל מִכָּל צָרֵיהֶם, הָאֵל הַמּוֹשִׁיעַ\". 'אֵל' הוא לשון חוזק; אנו מבקשים מהקב\"ה שיחשוף את חוזקו וגבורתו על ידי ישועתנו. הערות 252 ראה לעיל הערה 202"],[7,"s6","וּמַצִּיל וּמוֹשִׁיעַ","– 'הצלה' היא הוצאת האדם מתוך הצרה, ו'ישועה' היא מניעת הצרה מלבוא עליו. פעמים שהקב\"ה מציל ופעמים שהוא מושיע, בהתאם לראוי להעשות בכל מקרה לגופו. הערות 253 להציל = לקחת ולהוציא, כמו: \"כִּי כָל הָעֹשֶׁר אֲשֶׁר הִצִּיל אֱלֹהִים מֵאָבִינוּ - לָנוּ הוּא וּלְבָנֵינוּ\" (בראשית לא טז). 254 מלבי\"ם, ירמיהו טו כ, תהילים ז ב. וראה לעיל (עמ' 43) ביאור נוסף להבדל שבין שני המושגים."],[7,"s7","זוֹעֲקֶיךָ תּוֹשִׁיעַ, חוֹכֶיךָ הוֹשִׁיעַ","– כאן הפיוט עובר מתארי הקב\"ה – לבקשות עצמן; הבקשות פותחות בשתי שורות אלו, המהוות בקשות כלליות לישועה, ולאחריהן סודרו הבקשות המתייחסות לדברים ספציפיים. 'זוֹעֲקֶיךָ' – ישראל, הזועקים אליך בתפילה; 'חוֹכֶיךָ' – המחכים ומצפים לך ולישועתך, כמו בפסוק: \"אַשְׁרֵי כָּל חוֹכֵי לוֹ\" (ישעיהו ל יח). הערות 255 ראה עוד לעיל עמ' 121-120"],[7,"s8","טְלָאֶיךָ תַּשְׂבִּיעַ","– כאן מתחילות הבקשות המתייחסות בפירוש לירידת הגשמים ולהצלחה החקלאית, שתופסות מקום מרכזי בתפילות חג הסוכות ובפיוטי ה'הושענות'. עם ישראל מדומה לטלאים – קטנים וחסרי אונים, שחייהם תלויים בגשמים ובברכה שמשפיע עליהם הקב\"ה."],[7,"s9","יְבוּל לְהַשְׁפִּיעַ","– 'יְבוּל' הוא התבואה בזמן צמיחתה, מלשון 'הובלה' = הבאת הדבר אל יעדו הסופי; כשהאדמה מצמיחה את התבואה, היא 'מובילה' אותה אל האדם (לעומת השם 'תבואה', המציין את השלב שלאחר גמר הגידול, כשהאדמה 'מביאה' אותה אל האדם). אנו מתפללים על גידולי שנה זו, שבשלב ה'יבול' יצמחו בשפע. הערות 256 ספר 'יאיר אור' למלבי\"ם, ערך 'תבואה'"],[7,"s10","כָּל שִׂיחַ תַּדְשֵׁא","– שהקב\"ה ידשא את השיחים, דהיינו שיצמיחו את עליהם ופרותיהם. בלשון המקרא, 'שיח' הוא אילן, כמו בפסוק: \"תַּחַת אַחַד הַשִּׂיחִים\" (בראשית כא טו), ופירש שם 'אבן עזרא' שהכוונה לאילנות. 'דשא' הוא שם למראה הכללי של הקרקע כשהיא מכוסה בעשבים, וכאן הוא מובא בהשאלה ככינוי לצמחיית השיחים, עליהם אנו מתפללים שיתברכו עד שמראם הכללי יהיה ירוק כדשא, מלא בעלים רעננים. וְתוֹשִׁיעַ – ניתן לפרש באופן פשוט: תושיע אותנו על ידי ש'כָּל שִׂיחַ תַּדְשֵׁא'; אך לפי הסבר זה לא מובן במה התייחדה שורה זו שדווקא אליה התווספה הבקשה: 'וְתוֹשִׁיעַ'. ניתן להסביר באופן אחר, לפיו הבקשה 'וְתוֹשִׁיעַ' מוסבת על 'כָּל שִׂיחַ' – הצמחת השיחים היא ה'ישועה' שלהם, שכן כל פרט בבריאה צריך למלא את תפקידו על הצד הטוב ביותר, ואם השיחים אינם צומחים כראוי הרי שהם חסרים ממצבם השלם. הערות 257 אם כי ייתכן ששם זה כולל גם את הנקרא כיום 'שיח'. 258 רש\"י, בראשית א יא 259 ניתן למצוא רמז לרעיון זה בכתוב: \"הַנֹּתֵן מָטָר עַל פְּנֵי אָרֶץ, וְשֹׁלֵחַ מַיִם עַל פְּנֵי חוּצוֹת. לָשׂוּם שְׁפָלִים לְמָרוֹם, וְקֹדְרִים שָׂגְבוּ יֶשַׁע\" (איוב ה יא). ופירש שם המלבי\"ם: \"'לָשׂוּם שְׁפָלִים לְמָרוֹם' - להעלות הצמחים והאילנות מן השפל אל הרום, לרומם אותם ולהצמיחם\". על פי זה ניתן לפרש כך גם את המשך הפסוק: \"וְקֹדְרִים שָׂגְבוּ יֶשַׁע\" – הצמחים הקודרים (דימוי מטאפורי ליבשותם, כמו: \"וַאַקְדִּר עָלָיו [עצי] לְבָנוֹן\" [יחזקאל לא טו]) יישגבו (=יגבהו ויתחזקו) על ידי הגשמים, ובכך תהיה להם ישועה."],[7,"s11","לְגֵיא בַּל תַּרְשִׁיעַ","– הושע נא את ה'גֵּיא' – כינוי כללי לאדמת העולם, שלא 'תַּרְשִׁיעַ' – תתנהג ברשעות, כביכול, ולא תצמיח כראוי את יבולה. פירוש נוסף: אל תרשיע את האדמה – אל תוציא אותה חייבת בדין, כביכול, ותענישנה שלא להצמיח כראוי את יבולה. הערות 260 מדרש משלי, פרשה ח סימן ט; רוקח"],[7,"s12","מְגָדִים תַּמְתִּיק וְתוֹשִׁיעַ","– כמבואר לעיל, המתקת המגדים (=שם כללי לפירות מתוקים) היא ה'ישועה' שלהם, שכן הם צריכים לממש את ייעודם באופן שלם. ככל שהפירות מתוקים ואיכותיים יותר, כך הם מבטאים בעולם באופן טוב יותר את הטוּב האלוהי. הערות 261 רמב\"ן, דברים לג יג-יד"],[7,"s13","נְשִׂיאִים לְהַסִּיעַ","– שהעננים ייסעו למקומות הזקוקים לגשמים. העננים נקראים 'נשיאים', כמו שכתוב: \"מַעֲלֶה נְשִׂאִים מִקְצֵה הָאָרֶץ\" (תהילים קלה ז), על שם כך שהם מתנשאים בגובהם."],[7,"s14","שְׂעִירִים לְהָנִיעַ","– 'שְׂעִירִים' הם רוחות, מלשון 'סערה' – אנו מבקשים מהקב\"ה שיניע לכיווננו רוחות שתביאנה עימן ענני מטר. הערות 262 רש\"י, דברים לב ב. 'אבן עזרא' מפרש ש'שְׂעִירִים' הם טיפות גשם דקות, אך מהפועל 'לְהָנִיעַ' נראה שכוונת הפייטן היתה כפירוש רש\"י."],[7,"s15","עֲנָנִים מִלְּהַמְנִיעַ","– שהקב\"ה לא יגרום לעננים למנוע מהגשמים האצורים בהם לרדת ולהשקות את העולם, כמאמר הכתוב: \"וְגַם אָנֹכִי מָנַעְתִּי מִכֶּם אֶת הַגֶּשֶׁם\" (עמוס ד ז). הערות 263 'לְהַמְנִיעַ' – בניין הפעיל, לגרום לאחר למנוע."],[7,"s16","פּוֹתֵחַ יָד וּמַשְׂבִּיעַ, צְמֵאֶיךָ תַּשְׂבִּיעַ","– על פי לשון הכתוב: \"פּוֹתֵחַ אֶת יָדֶךָ, וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן\" (תהילים קמה טז) – הקב\"ה פותח את ידו המשפיעה שפע וברכה לעולם, ועל ידי כך 'מַשְׂבִּיעַ לְכָל חַי', באופן של 'רָצוֹן' = הארת פנים, כלומר: בכבוד וברווח. לאחר שביקשנו על העננים והרוחות, הגשמים והצמחים, כאן אנו מזכירים בבקשתנו את התכלית של כל האמצעים הללו – שעל ידם יהיה לנו, הצמאים לחסדו, שָׂבָע ושפע כלכלי. מבין כל שורות הפיוט שתוכנן הוא בקשה, החל מהשורה 'זוֹעֲקֶיךָ תּוֹשִׁיעַ' ועד סופו, יחידה היא השורה 'פּוֹתֵחַ יָד וּמַשְׂבִּיעַ' שתוכנה הוא שבח ולא בקשה. לאור זאת, ניתן לראות את צמד השורות 'פּוֹתֵחַ יָד וּמַשְׂבִּיעַ – צְמֵאֶיךָ תַּשְׂבִּיעַ' כיחידה עצמאית, שעניינה הוא, כמבואר לעיל, בקשת התכלית של הבקשות המופיעות בשורות שלפניה: השָׂבָע עצמו; משום כך היחידה פותחת בשבח ומסיימת בבקשה, כמו המבנה הכללי של הפיוט. גם בתחילת הבקשות בפיוט זה מופיעה בקשת התכלית – 'טְלָאֶיךָ תַּשְׂבִּיעַ'; הבקשה המפורשת על השָׂבָע מהווה גם הקדמה לבקשות על האמצעים המביאים אליו, על מנת להבהיר מהי מטרת הבקשה עליהם, וגם כחתימה הנאמרת בסופן, כשם שבפועל התכלית מתממשת לאחר התממשות האמצעים. הבקשה 'צְמֵאֶיךָ תַּשְׂבִּיעַ', כוללת כוונה נוספת: ישראל, הצמאים צמא רוחני לקרבתך, תשביע אותם ותרווה את צמאונם זה על ידי שתושיעם ושכינתך תופיע בקרבם."],[7,"s17","סיכום","הפיוט מסתיים בארבע שורות הסיכום הבאות, שתוכן הבקשה בהן זהה – בקשה כללית לישועה. בכל שורה עַם ישראל מתואר באופן מסויים, שממנו עולה זכותם של ישראל; אנו מתפללים שבעבור זכויות אלו, תתקבלנה הבקשות שביקשנו לאורך הפיוט. קוֹרְאֶיךָ תּוֹשִׁיעַ – תושיע את ישראל הקוראים לך בִּתפילה, שהרי \"קָרוֹב ה' לְכָל קֹרְאָיו – לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת\" (תהילים קמה יח). לעיתים, הקב\"ה מביא צרות או קשיים – על האדם או על הציבור – כדי לעוררם להתפלל אליו ומתוך כך לשפר את דרכיהם; מכיוון שזוהי המטרה, כשהם קוראים אליו הצורך באותו קושי מתבטל מאליו, וממילא נִהְיִים הם זכאים לישועה."],[7,"s18","רְחוּמֶיךָ תּוֹשִׁיעַ","– תושיע את עם ישראל, שכן מנהגך הוא לרחם עליהם, כמו שכתוב: \"וְנָתַן לְךָ רַחֲמִים וְרִחַמְךָ וְהִרְבֶּךָ כַּאֲשֶׁר נִשְׁבַּע לַאֲבֹתֶיךָ\" (דברים יג יח)."],[7,"s19","שׁוֹחֲרֶיךָ הוֹשִׁיעַ","– הושיע את עם ישראל, בזכות שהם משחרים את פניך; ל'שיחור' זה משמעות כפולה: א. מלשון תפילה, כמו: \"אִם אַתָּה תְּשַׁחֵר אֶל אֵל\" (איוב ח ה). ב. מלשון חיפוש, כמו: \"וּמְשַׁחֲרַי יִמְצָאֻנְנִי\" (משלי ח יז) – עם ישראל דורש ומחפש את הקירבה לקב\"ה. בעומק הדברים, שתי המשמעויות אחת הן: התפילה לקב\"ה ממעמקי בלב, היא עצמה הדרך להגיע לקרבתו; וכך כתב הראי\"ה קוק: המצוות כולן והתפילות, הינן המכשירים היותר טובים להרחיב את הנטייה של קירבת אלוהים ולהרחיב את צעדיה במעמקי הנפש. על כן גדול ורם הוא מאוד ערך כל תפילה בכוונה, כל ברכה ותהילה, כל מצווה וכל מנהג טוב, שהם הם הינן האמצעים לייסד את הרגשת קירבת אלוהים בליבו של אדם בדרך יסוד מוּסד. אומללים הם האנשים אשר לא ידעו את ה', אשר לא יתפללו [...]. ההכשר שבנשמה לתביעת קירבת אלוהים מבקשת מהם את תפקידה, והם באשר אינם ממלאים חובתם לנפשם נשארים הם על ידי זה אומללים, יבשים מכל טל טוהר. ומשום כך: הרבה יותר מכל משאלות הלב שיתמלאו מכל הבקשות של התפילה, יקרה היא התפילה בעצמה. על כן שמחת התפילה והעונג שלה צריך הוא להיות בעצמות התפילה, באופן שבע ומרווה עונג הרבה יותר מהעונג והשמחה המשוערת במילוי המשאלות המבוטאות בתפילה. כי עצם התפילה הוא הרבה יותר יקר, יותר נכבד במציאותו, מכל מיני המשאלים בעצמם. הערות 264 ראה בביאור השורה הראשונה בפיוט זה 265 שמונה קבצים, קובץ א, כ 266 שם, קובץ ו, רלד"],[7,"s20","תְּמִימֶיךָ תּוֹשִׁיעַ","– ניתן לפרש 'תְּמִימֶיךָ' בשתי משמעויות: א. שהולכים לפניך בתמימות ובהכנעה, כציווי התורה: \"תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךָ\" (דברים יח יג), וכפי שפירש רש\"י: \"התהלך עימו בתמימות ותצפה לו, ולא תחקור אחר העתידות, אלא כל מה שיבוא עליך – קבל בתמימות\". ב. שלֵמים, כמו: \" »תּƒמים יִהְיֶה לְרָצוֹן, »כּל מוּם ל…א יƒ¿הי∆ה בּוֹ \" (ויקרא כב כא), וכפי שאכן נאמר ביחס לעם ישראל: \"אֲחֹתִי רַעְיָתִי יוֹנָתִי ת»מּƒתי \" (שיר השירים ה ב), שהרי: \"כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם ≈אין בּ»ךְ \" (שם ד ז). הפגמים הקיימים בעם ישראל אינם עצמיים לו, ואינם פוגמים בקדושתו העצמית; הם אינם כ'מום' שהוא חיסרון בגוף עצמו, אלא כמו כתם על בגד, שניתן להסירו על ידי ניקוי. וכך כתב הראי\"ה קוק: האהבה הגדולה, שאנחנו אוהבים את אומתנו, לא תסמא את עינינו מלבקר את כל מומיה, אבל הננו מוצאים את עצמיותה, גם אחרי הביקורת היותר חופשית, נקייה מכל מום. \"כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ\". הערות 267 שם, קובץ ג, שמה; ערפלי טוהר, קל"],[7,"s21","סיכום","בביאור השורות הבחנו באופן ברור בצורת המבנה של הפיוט – כלל ופרט וכלל. הוא פותח בשש שורות המתארות תכונות ותארים שונים של ה', שנחוץ שהמתפלל יכיר בהם בטרם יבקש את בקשותיו, על מנת שתפילתו תמלא את תפקידה כראוי: בריאת ה' את העולם, הקשר המתמיד שהוא מקיים עם יושביו, יכולתו הבלעדית והבלתי-מוגבלת, וקבלתו את תפילתם ותשובתם הכֵּנוֹת של בני האדם. חלקו של הפיוט שלאחר שורות אלו (א-ו), ממוסגר בשתי מסגרות של בקשות: א. המסגרת החיצונית, המורכבת משתי השורות הראשונות (ז-ח) וארבע השורות האחרונות (ק-ת), והיא מכילה בקשות לישועה באופן כללי. ב. המסגרת הפנימית, המורכבת מהשורה השלישית (ט) ושתי השורות שלפני הארבע האחרונות (פ-צ), והיא מכילה בקשות על שָׂבָע באופן כללי. ליבו של הפיוט, הממוקם בתוך שתי המסגרות, מכיל בקשות שונות על הצלחת החקלאות בענפיה השונים: יבול הארץ, השיחים, ופירות העץ, על ידי הגורמים השונים: עננים, רוחות, וגשמים. המסגרת הפנימית מבטאת את התכלית של הבקשות שבלב הפיוט, הלוא היא השבע עצמו; אף אם החקלאות תצליח, עדיין יש מקום לתפילה על כך שלכל אדם תהיינה היכולות הכלכליות ליהנות מהשבע הקיים, ולא יסבול ממחסור. על כך אנו מבקשים: 'טְלָאֶיךָ תַּשְׂבִּיעַ' – כרועה צאן המטפל בכל טלה מעדרו באופן אישי, ומשתמשים בתואר 'פּוֹתֵחַ יָד וּמַשְׂבִּיעַ', המבטא את ידו הפתוחה של הקב\"ה, שבאמצעותה הוא 'מַשְׂבִּיעַ לְכָל חַי' – היד פתוחה וכל אחד יכול ליטול ממנה את ברכת ה'. המסגרת החיצונית מבטאת את תכליתה של אותה תכלית – גם השבע לכל חי אינו תכלית לעצמו, אלא אמצעי לישועה, עליה אנו מבקשים במסגרת זו. בדומה לישועה שאנו מבקשים עבור הצומח, שעניינה הוא התממשות הייעוד שלו, גם הישועה שאנו מבקשים עבור עצמנו היא מימוש הפוטנציאל הרוחני אליו אנו מסוגלים להגיע, כיחידים וכאומה. מצב כלכלי מבוסס הוא דבר נחוץ כדי להתעלות ברוחניות – בלעדיה האדם נאלץ להשקיע את כוחותיו ומרצו בעצם הישרדותו הקיומית, ואינו יכול לעסוק בבניין הקומות הנוספות של אישיותו; וכדברי חז\"ל: \"אם אין קמח – אין תורה\". כך הוא גם בחיי האומה: עם ישראל יכול לייצג את שם ה' בעולם רק מתוך שלימות רוחנית וגשמית גם יחד. משום כך, כבר בתחילת הבקשות מוצגת הבקשה לתכלית הסופית: הישועה, ורק לאחריה מופיעה הבקשה על האמצעי המביא אליה: השבע. זאת, כדי שכבר מתחילת התפילה יהיה ברור למתפלל לשם מה הוא מבקש ברכה גשמית (תרתי משמע); הגשמיות, לְעולם אינה מהווה תכלית לעצמה, אלא אמצעי להשתלמות והתעלות רוחנית. לפני הבקשות המפורטות על הצלחת היבול וירידת הגשמים, אנו מבהירים את התכלית הרצויה כתוצאה מהם: מצב של שבע, שבו יהיה לכל אחד ואחד כדי צורכו. לאחר הבקשות המפורטות, שבים ומזכירים את המטרה שלהן: השבע, שהיא עצמה אמצעי למטרה הסופית, המוזכרת בשורות שלאחריה, החותמות את הפיוט: הישועה הרוחנית. הערות 268 ראה בביאור השורות \"כָּל שִׂיחַ תַּדְשֵׁא וְתוֹשִׁיעַ\", ו\"מְגָדִים תַּמְתִּיק וְתוֹשִׁיעַ\". 269 מסכת אבות, פרק ג, משנה יז"],[7,"n249","הערה 249","תלמוד בבלי, ברכות לב."],[7,"n250","הערה 250","שם, ז:"],[8,"piyut","נוסח הפיוט","אֲנִי וָהוּ הוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ אֵלִים בְּלוּד עִמָּךְ, בְּצֵאתְךָ לְיֵשַׁע עַמָּךְ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ גּוֹי וֵאלֹהִים, דְּרוּשִׁים לְיֵשַׁע אֱלֹהִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ הֲמוֹן צְבָאוֹת, וְעִמָּם מַלְאֲכֵי צְבָאוֹת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ זַכִּים מִבֵּית עֲבָדִים, חַנּוּן בְּיָדָם מַעֲבִידִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ טְבוּעִים בְּצוּל גְּזָרִים, יְקָרְךָ עִמָּם מַעֲבִירִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ כַּנָּה מְשׁוֹרֶרֶת וַיּוֹשַׁע, לְגוֹחָהּ מְצֻיֶּנֶת וַיִּוָּשַׁע, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מַאֲמַר וְהוֹצֵאתִי אֶתְכֶם, נָקוּב וְהוּצֵאתִי אִתְּכֶם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ סוֹבְבֵי מִזְבֵּחַ, עוֹמְסֵי עֲרָבָה לְהַקִּיף מִזְבֵּחַ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ פִּלְאֵי אָרוֹן כְּהֻפְשַׁע, צִעֵר פְּלֶשֶׁת בַּחֲרוֹן אַף וְנוֹשַׁע, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ קְהִלּוֹת בָּבֶלָה שִׁלַּחְתָּ, רַחוּם לְמַעֲנָם שֻׁלַּחְתָּ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב, וְהוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי יְשׁוּעוֹת, אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא. תהילים הוֹשִׁיעָה אֶת עַמֶּךָ, וּבָרֵךְ אֶת נַחֲלָתֶךָ, וּרְעֵם וְנַשְּׂאֵם עַד הָעוֹלָם. מלכים וְיִהְיוּ דְּבָרַי אֵלֶּה אֲשֶׁר הִתְחַנַּנְתִּי לִפְנֵי יְהֹוָה, קְרוֹבִים אֶל יְהֹוָה אֱלֹהֵינוּ יוֹמָם וָלָיְלָה, לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל דְּבַר יוֹם בְּיוֹמוֹ. לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי יְהֹוָה הוּא הָאֱלֹהִים, אֵין עוֹד."],[8,"s1","על הפיוט","בפיוט זה אנו מתפללים שעם ישראל יוושע, מכוח זאת שאף שכינת ה' נמצאת עימו בגלותו, כביכול, ובגאולתו תיגאל אף היא."],[8,"s2","אֲנִי וָהוּ הוֹשִׁיעָה נָּא","– בתיאור המשנה את סדר העבודה במקדש בחג הסוכות, נאמר: \"בכל יום מקיפין את המזבח פעם אחת, ואומרים: 'אָנָּא ה' הוֹשִׁיעָה נָּא, אָנָּא ה' הַצְלִיחָה נָא' (תהילים קיח כה). רבי יהודה אומר: 'אֲנִי וָהוּ הוֹשִׁיעָה נָּא'\". הפייטן נקט כדעת רבי יהודה, שזהו נוסח הבקשה שהיה נאמר במקדש, ולפיכך שיבצו בתחילת פיוט זה ובסופו. פירוש בקשה זו על דרך הפשט הוא: הושיעה נא את 'אֲנִי' = ישראל, ואת 'הוּא' = הקב\"ה עצמו, שכן הוא נמצא, כביכול, עִם ישראל בגלותם, כמו שכתוב: \"בְּכָל צָרָתָם לא (קרֵי: לוֹ) צָר\" (ישעיהו סג ט), וכן: \"עִמּוֹ אָנֹכִי בְצָרָה\" (תהילים צא טו); תפקידם של ישראל הוא לייצג את הקב\"ה בעולם, וכשהם בגלות ומצבם הלאומי בשפל המדרגה, הרי שגם שכינת הקב\"ה בעולם אינה מופיעה ומיוצגת כראוי. רעיון זה הוא החורז את הפיוט, וייתכן שהסיבה שהוא נאמר בכל יום היא, שהמסר היסודי שהוא מעביר צריך ללוות אותנו בתפילותינו לאורך כל ימי החג; הדבר העיקרי שצריך לעמוד לנגד עינינו אינו מטרותינו האישיות, אלא גאולת השכינה – הגדלת כבוד ה' בעולם. בעניין השילוב הבולט של לשון נוכח ונסתר בנוסח זה, כתב רבינו בחיי: \"אֲנִי וָהוּ\" [...] – מפני שהוא יתברך נסתר ונעלם מהשגת כל משיג, ו\"הוֹשִׁיעָה נָּא\" – לנוכֵחַ , לבאר שאף על פי שהוא נסתר ונעלם – נגלה הוא ונמצא בלבבות, והוא כעניין נוסח הברכות שתיקנו \"בָּרוּך אַתָּה\" – לנוכח, ו\"אֲשֶׁר קִדְּשָׁנוּ\" – נסתר. וגם בכאן: \"הוֹשִׁיעָה נָּא\" –לנוכח, \"אֲנִי וָהוּ\" – נסתר, לפי שאין ידוע מקומו, כעניין שכתוב: \"בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ\" (יחזקאל ג יב). בעל 'ספר חרדים' כתב פירוש נוסף לתפילה זו, על דרך הדרוש והמוסר: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\" – רוצה לומר: כי כשאני והוא לבדנו בהתבודד לעת מצוא [אז זוכים ל'הושיעה נא'], כדכתב בספר חובת הלבבות; דבר אחר: אפילו כשאני בין העם – כיוון שאין רואה סתר לבבי אלא הוא לבדו, ועוד אין משגיח בי להיטיב לי אלא הוא לבדו, ואין מי שיוכל להציל אותי מצרתי זולתו – לכן לא יפסיקו ביני לבינו הנבראים, כי כולם כאין נגדו ואני הוא לבדו עומדים, והיינו דכתיב: \"חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו \" (מלכים ב' ה טז), וכתיב: \"הִתְהַלֵּךְ לְפָנַי\" (בראשית יז א). בנוסף לפירושים אלו, הראשונים פירשו נוסח זה באופנים שונים על דרך הרמז והסוד, לפיהם 'אֲנִי' ו'וָהוּ' הם שמות ה' (וכך מובן מדוע המילה 'וָהוּ' נכתבת ללא א'), ואף בספר הזוהר מופיעה התייחסות להזכרת שמות אלו בעת ההקפות. שמות אלו הם שניים מבין שבעים ושניים שמות הקודש היוצאים משלושת הפסוקים המופיעים בעניין קריעת ים-סוף: \"וַיִסַּע\", \"וַיָּבֹא\", \"וַיֵּט\" (שמות יד יט-כא), כשאותיותיהם נכתבות בסדר מסויים המשלב את הפסוקים יחד (וישנן כמה שיטות מהו אותו סדר). אנו פונים לקב\"ה בשני שמותיו אלו, ומבקשים: 'הוֹשִׁיעָה נָא'. בטעם הדבר שנבחרו דווקא שמות אלו נאמרו מספר טעמים (מלבד הטעם הפשוט – שכך הנוסח יכול להתפרש גם כבקשה על 'אני והוא', כמבואר לעיל): א. 'אֲנִי וָהוּ' עולה בגימטריה: \"אָנָּא ה'\" (כך שהנוסח של רבי יהודה כולל באופן זה גם חלק מהנוסח של חכמים). ב. שני שמות אלו כוללים את משמעותם הרוחנית של שאר שבעים השמות הרמוזים באותם שלושה פסוקים. ג. כתב רבינו בחיי: מוּדעת זאת לכל בעלי השמות, כי שם בן ע\"ב נחלק לחלקים ידועים, ויש לכל חלק וחלק כוח ידוע לפעולה ידועה. [...] ושני שמות אלו, כל אחד ראש לחלקו הידוע להם: זה לקרב פזורים, וזה לאהבה. וכיוון שכן, מה נעים ומה טוב שנזכירם בתוך תפילתנו, לבקש בהם רחמים מאת ה' יתברך, שיקרב את פזורינו ושיאהב אותנו כימי קדם. ונסיים בדברי בעל ה'רוקח' בפירושו ל'הושענות': \"יש לכוון לומר יותר בכוונה: 'אֲנִי וָהוּ הוֹשִׁיעָה נָּא', כי הוא עיקר התפילה\"."],[8,"s3","כְּהוֹשַׁעְתָּ אֵלִים בְּלוּד","– כשם שהושעת את ישראל ממצרים עִמָּךְ – שכביכול אף אתה היית עימם בגלות זו, בְּצֵאתְךָ לְיֵשַׁע עַמָּךְ – כשיצאת לחולל ישועה לעמך. ישראל מכונים כאן 'אֵלִים' = חזקים; על פי דברי הגמרא שישראל הם העזים שבאומות. לכאורה, דווקא כינוי זה אינו מתאים לזמן יציאת מצרים, שכן אז ישראל היו בעלי אופי של עבדים, הכפופים ומשועבדים לאדוניהם; אך מצד האמת – טבע זה של העזות המוטבע בעם ישראל היה קיים גם אז, אלא שלא יכל לצאת אל הפועל. עזות זו היא שאיפשרה לעם ישראל לדבוק באמונתו ובתורתו על אף הקשיים הרבים שהיו מנת חלקו לאורך ההיסטוריה. 'לוּד' – כינוי לארץ מצרים, על פי הכתוב: \"וּמִצְרַיִם יָלַד אֶת לוּדִים\" (בראשית י יג). 'בְּצֵאתְךָ לְיֵשַׁע עַמָּךְ' – על פי לשון הכתוב: \"יָצָאתָ לְיֵשַׁע עַמֶּךָ\" (חבקוק ג יג); 'יציאה' זו היא יציאה מהנהגה במידת הדין להנהגה במידת הרחמים, כדברי הגמרא: \"'כִּי הִנֵּה ה' יֹצֵא מִמְּקוֹמוֹ' (ישעיהו כו כא) – תני בשם רבי מאיר: יוצא לו ממידה למידה: יוצא ממידת הדין, למידת רחמים על ישראל\". הערות 281 ראה לעיל הערה 202 282 תלמוד בבלי, ביצה כה: 283 כפי שבא לידי ביטוי, לדוגמה, במעשהו הנועז של נחשון בן עמינדב. 284 תלמוד ירושלמי, תענית, פרק ב הלכה א 285 על פי ה'רוקח'. רש\"י בישעיהו שם כתב: \"יוֹצֵא – ממידת הרחמים למידת הדין\", וכוונתו היא - ביחס לגויים."],[8,"s4","כְּהוֹשַׁעְתָּ גּוֹי וֵאלֹהִים","– שורה זו, וכן שלוש השורות שלאחריה, מתארות אף הן את גאולת מצרים: כשם שהושעת את עם ישראל ויחד עימו הושעת את עצמך, כביכול, כמאמר הכתוב: \"וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ, אֲשֶׁר הָלְכוּ אֱלֹהִים לִפְדּוֹת לוֹ לְעָם וְלָשׂוּם לוֹ שֵׁם, וְלַעֲשׂוֹת לָכֶם הַגְּדוּלָּה וְנֹרָאוֹת לְאַרְצֶךָ, מִפְּנֵי עַמְּךָ אֲשֶׁר פָּדִיתָ לְּךָ מִמִּצְרַיִם, גּוֹיƒם ו≈אל…»היו \" (שמואל ב' ז כג) – הקב\"ה פדה ממצרים את ישראל, הנקראים 'גּוֹיִם' = עמים, כלומר שבטים, 'וֵאלֹהָיו' – אותו עצמו, שהיו דְּרוּשִׁים (=נצרכים) לְיֵשַׁע אֱלֹהִים – על פי לשון הכתוב: \"אַרְאֶנּוּ בְּיֵשַׁע אֱלֹהִים\" (תהילים נ כג). הפייטן מדגיש כי עם ישראל היה זקוק דווקא 'לְיֵשַׁע אֱלֹהִים', דהיינו ישועה הנעשית באופן ישיר על ידי הקב\"ה, ולא כזו הנעשית בדרך טבעית. זאת, משום שעם ישראל היה שקוע בטומאת מצרים, ואילו היה נגאל באופן טבעי – אף על פי שהיה יוצא לחירות פיזית, לא היה יכול לממש את תפקידו כעם ה', בהיותו דבוק בטומאת מצרים. משום כך, הוא נזקק גם לגאולה רוחנית שתגאל את נשמתו ותטהרנה מהסיגים הרוחניים שדבקו בה בהיותו במצרים; פעולה רוחנית זו, יכולה להעשות רק על ידי הקב\"ה עצמו. על פי זה, ניתן לראות קשר הדוק בין תחילתה של שורה זו לבין סופה: 'כְּהוֹשַׁעְתָּ גּוֹי וֵאלֹהִים' – אלוהים עצמו נזקק, כביכול, לישועה ממצרים, שכן הופעתו בעולם תלויה בעם ישראל; מחמת סיבה זו, היו 'דְּרוּשִׁים לְיֵשַׁע אֱלֹהִים' – נזקקו דווקא לישועה רוחנית, כדי שיהיו זכים וטהורים, וכך שם ה' יוכל להופיע על ידם בעולם. הערות 286 מפרשי ההושענות ציינו פסוק זה כמקור, אך יש לציין כי פירוש זה לפסוק הוא בדרך דרש. על פי הפשט, \"וֵאלֹהָיו\" הם השופטים והמנהיגים של ישראל, או ש\"פָּדִיתָ לְּךָ מִמִּצְרַיִם גּוֹיִם וֵאלֹהָיו\", היינו: הוצאת את ישראל ממצרים: מהגויים ששם, ומהאלוהים של אותם גויים – העבודה הזרה (רד\"ק)."],[8,"s5","כְּהוֹשַׁעְתָּ הֲמוֹן צְבָאוֹת, וְעִמָּם מַלְאֲכֵי צְבָאוֹת","– כשם שהושעת ממצרים את המוני צבאות ישראל, ויחד עימם הושעת את מלאכיך ('צְבָאוֹת' השני – שם ה'); על פי לשון הכתוב: \"וְהוֹצֵאתִי אֶת ƒצב¿א…תי אֶת עַמִּי בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרַיִם בִּשְׁפָטִים גְּדֹלִים\" (שמות ז ד), וכן: \"וַיְהִי בְּעֶצֶם הַיּוֹם הַזֶּה יָצְאוּ »כּל ƒצ¿באוֹת ה' מֵאֶרֶץ מִצְרָיִם\" (שם יב מא). על הפסוק השני נאמר במדרש: \"'צִבְאוֹת' – אלו ישראל, 'כָּל' – לרבות מלאכי השרת\". את משמעות יציאת המלאכים עם ישראל ממצרים, ניתן לבאר על פי פתגמו של הראי\"ה קוק לחודש ניסן: \"יציאת מצרים תישאר לעד האביב של העולם כולו\", וכפי שביאר בנו הרצי\"ה בשמו רעיון זה: [\"וְאִלּוּ לֹא הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אֲבוֹתֵינוּ מִמִּצְרָיִם, הֲרֵי אָנוּ וּבָנֵינוּ וּבְנֵי בָנֵינוּ מְשֻׁעְבָּדִים הָיִינוּ לְפַרְעֹה בְּמִצְרָיִם \"] – אאמו\"ר זצ\"ל היה אומר, כי אילו לא הוציא הקב\"ה את אבותינו ממצרים לחירות עולם, למתן תורה, הרי כל העולם כולו, וכל סדר חיי האדם – היו נשארים על מקומם בלי השתנות, וכן היה נשאר השיעבוד לאותו פרעה במצרים. כל ההתקדמות המוסרית והתרבותית שהתקדם העולם במשך אלפי השנים שעברו מאז יציאת מצרים – לא היתה מתרחשת לולא יצא עם ישראל לחירות וקיבל את התורה. כל ערכי החופש והשיוויון, המוסר והצדק, שבמהלך ההיסטוריה קנו להם שביתה בתודעת האנושות, בחוקי אומות העולם ובמוסכמותיהן החברתיות – לא באו אלא מכוחם של ישראל, של התורה, ושל דברי הנביאים. השפעה זו נעשתה גם באופן רוחני ונסתר, וגם באופן גלוי, כפי שניתן לזהות בשלבי התפתחות ההיסטוריה: בימי קדם שלטה בעולם האלילות, שבהשפעתה חיי החברה התקיימו מתוך שחיתות מוסרית, גסות ופראיות; האלילות חלפה מרוב העולם בהשפעתן של שתי הדתות הגדולות – הנצרות והאיסלאם, שקידמו בכך את העולם כברת דרך משמעותית. שתי דתות אלו, שאבו את יסודותיהן מהיהדות; שכן, מתוך עולם אלילי לא יכלו לצמוח דתות אלו, המתבססות על 'נבואה' ועל 'רוח הקודש'. וכך כתב הרמב\"ם: אך מחשבות בורא העולם אין כוח באדם להשיגם, כי לא דרכינו דרכיו ולא מחשבותינו מחשבותיו. וכל הדברים האלו של ישוע הנוצרי ושל הישמעאלי שעמד אחריו – אינן אלא ליישר דרך למלך המשיח ולתקן את העולם כולו לעבוד את ה' ביחד, שנאמר: \"כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה, לִקְרֹא כֻלָּם בְּשֵׁם ה', לְעָבְדוֹ שְׁכֶם אֶחָד\" (צפניה ג ט). כיצד? כבר נתמלא העולם מדברי המשיח ומדברי התורה ומדברי המצוות, ופשטו דברים אלו באיים רחוקים ובעמים רבים ערלי לב, והם נושאים ונותנים בדברים אלו ובמצוות התורה [...]. וכשיעמוד מלך המשיח באמת, ויצליח וירום ונישא – מיד הם כולן חוזרין ויודעים ששקר נחלו אבותיהם, ושנביאיהם ואבותיהם הטעום. גם ספר התנ\"ך, שהוא הספר הנפוץ ביותר בעולם, השפיע על התקדמות האנושות; רבים מאנשי הרוח, הוגי הדעות, האמנים, הסופרים, והמשוררים, שקמו לאומות העולם ועיצבו את פני החברה – הושפעו ממנו, ובהשראתו הגו את רעיונותיהם. וכך כתב רמב\"ן: יש לידע, שכל מה שהנבראים יודעים ומבינים – כולם פירות התורה או פירי פירות שלה. [...] וכן תראה היום באומות הרחוקות מארץ התורה והנבואה, יושבי הקצוות [...] שאינם מכירים את הבורא, וסבורים שהעולם קדמון, וגם אינם מחשבין כלל: לא בקדמותו ולא בחידושו, ואם הגלגל מניע עצמו או זולתו מניעו. [...] ואל תשתבשו באומות שאף הם נוחלי תורה, הם הקרובים לאמצע היישוב [=העולם המיושב], כי טוב, כגון הנוצרים והישמעאלים, לפי שהעתיקו התורה ולמדוה, וכשגברה רומי על קצת הקצוות [=הארצות הרחוקות] למדו ממנה תורה, ועשו חוקים ומשפטים דוגמה של תורה [...] והאומות מתחילה כך אמרו, שנאמר: \"וּמִי גּוֹי גָּדוֹל אֲשֶׁר לוֹ חֻקִּים וּמִשְׁפָּטִים צַדִּיקִם כְּכֹל הַתּוֹרָה הַזֹּאת\" – למדנו שלא היה באותו זמן אומה ולשון בעולם שיהא להם נימוסים טובים וישרים יישובי המדינות כישראל, [...] וכל שכן ה'חֻקִּים' שהם המצוות החקוקות בעולם. על פי זה יובן, שה'מלאכים' שיצאו עִם ישראל ממצרים הם אותם האידיאלים האלוהיים והערכים המוסריים והחברתיים שהתקבלו בעולם בעקבות גאולתו של עם ישראל, שנשאה עימה את הבשורה הגדולה של תיקון העולם והאנושות. הערות 287 מדרש 'שכל טוב' על אתר 288 מאמרי הראי\"ה, מגד ירחים, עמ' 501 289 הערה על הגדה של פסח, בתוך סידור 'עולת ראיה' חלק ב, עמ' רסח 290 משנה תורה, הלכות מלכים, פרק יא, הלכה ד (בדפוסים שאינם מצונזרים) 291 פירוש: אל תטעו לומר על אומות אלו: 'כי טוב', שהרי נוחלי התורה הם – מפני שאין תורתם אלא 'דוגמה' (=חיקוי) של תורת ישראל. 292 דברים ד ח 293 תחילת דרשת 'תורת ה' תמימה', בתוך: כתבי רמב\"ן, חלק א, הוצאת מוסד הרב קוק 294 בעניין 'מלאכים' ככוחות או רעיונות רוחניים, ראה 'מורה נבוכים', חלק ב, פרק ו; שיחות הרב צבי יהודה, בראשית, עמ' 294-286."],[8,"s6","כְּהוֹשַׁעְתָּ זַכִּים מִבֵּית עֲבָדִים","– כשם שהושעת ממצרים את ישראל, שהיו זכים וטהורים, ועל אף שהיו ב'בֵּית עֲבָדִים' – משועבדים למצרים ומוקפים בתרבותם הקלוקלת – שמרו על זַכּוּתָם ועל נאמנותם לקב\"ה. רובו הגדול של עם ישראל, שלא שמר על זַכּוּתוֹ ונטמע בין המצרים, מת בשלושת ימי מכת החושך, ואלו שבפועל יצאו ממצרים היו 'זַכִּים'. אף בין היוצאים היו כאלו שלמדו ממעשי המצרים, ואף עבדו עבודה זרה (כפי שיבואר בשורה הבאה), אך גם הם – בפנימיותם היו 'זַכִּים'. אלו שמתו לפני היציאה ממצרים היו הרשעים חסרי התקנה, ואלו שהיו בעלי פוטנציאל לעזוב את מעשיהם הרעים בעתיד – נחשבו מכלל ה'זַכִּים' ויצאו ממצרים. חַנּוּן בְּיָדָם מַעֲבִידִים – המצרים העבידו בידם, כביכול, את ה'חַנּוּן' = הקב\"ה, שהרי הוא משתתף עם ישראל בצרתם וצערם, כדברי המדרש על התגלות הקב\"ה למשה מתוך הסנה: \"בְּכָל צָרָתָם לוֹ צָר\" (ישעיהו סג ט) – אמר לו הקב\"ה למשה: אי אתה מרגיש שאני שרוי בצער כשם שישראל שרויים בצער, הוֵי יודע: ממקום שאני מדבר עימך מתוך הקוצים, כביכול אני שותף בצערן. הקב\"ה מכונה כאן כך, כיוון שהשתתפותו בצערם של ישראל נובעת מכוח מידת 'חַנּוּן', כפי שהתבאר לעיל. הערות 295 מכילתא, פתיחתא לפרשת בשלח, על הפסוק \"וַחֲמֻשִׁים עָלוּ\" 296 שמות רבה, פרשה ב, אות ה, וכעין זה ברש\"י על שמות ג ב 297 עמ' 99-98"],[8,"s7","כְּהוֹשַׁעְתָּ טְבוּעִים בְּצוּל גְּזָרִים","– כשם שהושעת את ישראל מהמצרים שרדפו אחריהם, בכך שבקעת להם את הים, ולאחר מכן הושעתם מתוך 'צוּל גְּזָרִים' = מצולות הים שבין גזרי ים-סוף. מכיוון שבכל רגע המים היו עשויים ליפול עליהם, הרי שכאילו היו 'טְבוּעִים' בתוך הים; מַעֲבָר ישראל בשלום בים-סוף לא היה מובן מאליו, כדברי המדרש: והיו מלאכי השרת תמהין לומר: בני אדם עובדים עבודה זרה מהלכין ביבשה בתוך הים?! ומניין שאף הים נתמלא עליהם חימה? שנאמר: \"וְהַמַּיִם לָהֶם חֹמָה\" (שמות יד כט) – אל תקרי 'חֹמָה' אלא 'חֵימָה'. מי גרם להם לישראל להינצל? \"מִימִינָם וּמִשְּׂמֹאלָם\" (שם) – 'מִימִינָם' – בזכות התורה שעתידין לקבל, שנאמר: \"מִימִינוֹ אשדת (קרֵי: אֵשׁ דָּת) לָמוֹ\" (דברים לג ב), 'וּמִשְּׂמֹאלָם' – זו תפילה. דבר אחר: 'מִימִינָם' – זו מזוזה, 'וּמִשְּׂמֹאלָם' – זו תפילין. מלאכי השרת מייצגים כאן (כמו גם במקומות נוספים בהם הם טוענים כלפי הקב\"ה), את העמדה הפשוטה והישירה ביחס למציאות: רבים מעם ישראל הם עובדי עבודה זרה, חייהם אינם מכוונים לעבודת ה' – וממילא הם חסרי ערך; הואיל וכך, אינם ראויים להצלה זו. \"אין השטן מקטרג אלא בשעת הסכנה\" – לאחר שנבקע הים, והם היו \"מהלכין ביבשה בתוך הים\", במצב מסוכן ולא טבעי, יכל הקיטרוג להשפיע בשיתוף פעולה עם הנסיבות של המציאות המסוכנת. ממשיך המדרש: \"ומניין שאף הים נתמלא עליהם חימה? שנאמר: 'וְהַמַּיִם לָהֶם חֹמָה' – אל תקרי 'חֹמָה' אלא 'חֵימָה'\" – מלבד הקיטרוג שהתעורר עליהם מחמת שהיו עובדי עבודה זרה, גם הטבע עצמו היה נגדם; שכן, לא בקיעת הים לבדה היתה מוגדרת כנס, אלא אף כל רגע ורגע שהים המשיך לעמוד כחומה מימינם ומשמאלם, שהרי מצד חוקי הטבע המים היו עשויים לשוב למקומם ברגע שתיפסק התערבותו הניסית של הקב\"ה. המדרש מוסיף בכך, שאף ללא קיטרוג המלאכים על כך שבני ישראל ראויים לטבוע מחמת מצבם הרוחני הירוד, היה ראוי להיות כך על פי הטבע – שהרי ללא סיבה מוצדקת להמשיך להעמיד את חומות המים, היו טובעים לאחר שכוח המשיכה היה משיב את המים למקומם הטבעי. ה'חימה' מופיעה אצל אדם בזמן שהמציאות אינה תואמת לרצונו, והיא הכעס האצור בלב, אף אם אינו מתבטא בפועל. הים 'נתמלא חימה' על ישראל, דהיינו שכל רגע שהוא עמד כחומות, היה זה נגד רצונו וטבעו – ולפיכך בכל רגע ישראל היו מצויים בסכנה מתמדת; רק הנס הוא שהמשיך להעמידו, ובכך גרם ל'חימה' של הים להישאר אצורה בתוכו, ולא לצאת לפועל בנפילת חומות המים. על פי הסבר זה, מובנת הזיקה בין המילה המקורית ('חֹמָה') לבין אופן הניקוד שלה על פי הדרשה ('חֵימָה'): עמידת המים כ'חֹמָה' בניגוד לטבעם, היא זו שגרמה לכך שהים 'יתמלא עליהם חֵימָה'. עד כאן עסקנו בחלקו הראשון של המדרש, ממנו ניתן להבין מדוע ישראל מכונים בפיוט 'טְבוּעִים', וכן מדוע יציאתם בשלום מתוך הים נחשבת 'ישועה'. חלקו השני של המדרש מסביר מדוע אכן הם זכו לישועה זו. ההסבר הראשון הוא: בזכות 'מִימִינָם' – התורה שעתידים לקבל ולקיים, ובזכות 'מִשְּׂמֹאלָם' – התפילה, הנובעת מקירות הלב הממוקם בשמאלו של גוף האדם. ההסבר השני הוא: בזכות 'מִימִינָם' – המזוזה, הנקבעת בימין הפתח, ובזכות 'מִשְּׂמֹאלָם' – התפילין, הנקשרים על יד שמאל. אף הפייטן הזכיר את הסיבה שגרמה להם להינצל: יְקָרְךָ עִמָּם מַעֲבִירִים – ישראל הם המייצגים את הקב\"ה, ולפיכך כשעברו את הים העבירו עימם, כביכול, את יקרו וכבודו; אילו היו טובעים ואובדים אז, גם יקרו של הקב\"ה לא היה יכול להופיע בעולם. ייתכן שזוהי גם כוונת המדרש: עם ישראל מייצג את הקב\"ה ומפרסם את שמו בעולם, באמצעות ארבעת הדברים המוזכרים: א. על ידי התורה, כמאמר הכתוב: \"וּשְׁמַרְתֶּם וַעֲשִׂיתֶם, כִּי הִוא חָכְמַתְכֶם וּבִינַתְכֶם לְעֵינֵי הָעַמִּים, אֲשֶׁר יִשְׁמְעוּן אֵת כָּל הַחֻקִּים הָאֵלֶּה וְאָמְרוּ: רַק עַם חָכָם וְנָבוֹן הַגּוֹי הַגָּדוֹל הַזֶּה\" (דברים ד ו), וכן: \"וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ: לְכוּ וְנַעֲלֶה אֶל הַר ה' אֶל בֵּית אֱלֹהֵי יַעֲקֹב, וְיֹרֵנוּ מִדְּרָכָיו וְנֵלְכָה בְּאֹרְחֹתָיו, כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה וּדְבַר ה' מִירוּשָׁלִָם\" (ישעיהו ב ג). ב. על ידי התפילה – שילמד את העמים לפנות אל הקב\"ה בתפילה, כמאמר הכתוב: \"וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי, עוֹלֹתֵיהֶם וְזִבְחֵיהֶם לְרָצוֹן עַל מִזְבְּחִי, כִּי בֵיתִי בֵּית תְּפִלָּה יִקָּרֵא לְכָל הָעַמִּים\" (שם נו ז). ג. על ידי התפילין, כמאמר הכתוב: \"וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךָ\" (דברים כח י), \"ותניא: רבי אליעזר הגדול אומר: אלו תפילין שבראש\". ד. על ידי המזוזה, הקבועה בפתח הבית מבחוץ, ובכך מהווה מעין אמירה של הבית היהודי כלפי כל רואה – אמירה של אמונה, של קבלת עול מלכות שמיים ועול מצוות. ההסבר הראשון במדרש מדגיש את הצד הרוחני המופשט: התורה והתפילה, וההסבר השני מדגיש את ההתבטאות שלו ברמה המעשית: התפילין והמזוזה. הערות 298 מכילתא, פרשה ו, על הפסוק \"וּבְנֵי יִשְׂרָאֵל\" 299 ומשום כך עונשו של העובד עבודה זרה הוא מיתה בבית דין. 300 בראשית רבה, פרשה צא, אות ט 301 מלבי\"ם, ישעיהו יב א, ועוד. 302 תלמוד בבלי, ברכות ו."],[8,"s8","כְּהוֹשַׁעְתָּ כַּנָּה","– כשם שהושעת את עם ישראל המכונים 'כַּנָּה', מלשון כַּן (=בסיס), כיוון שהם הבסיס הרוחני של העולם כולו, כלשון הכתוב: \"וְכַנָּה אֲשֶׁר נָטְעָה יְמִינֶךָ\" (תהילים פ טז); מְשׁוֹרֶרֶת וַיּוֹשַׁע – לאחר שנושעו מהמצרים ומִסַכָּנַת ים-סוף, שוררו את שירת הים, המכונה 'שירת ויושע' על שם תחילת הפסוק של ההקדמה לשירה: \"וַיּוֹשַׁע ה' בַּיּוֹם הַהוּא אֶת יִשְׂרָאֵל מִיַּד מִצְרָיִם\" (שמות יד ל). לְגוֹחָהּ מְצֻיֶּנֶת – 'כַּנָּה' זו, היתה מצויינת (=מסומנת) לקב\"ה, שהוא גוחהּ = מוציאהּ ממצרים, כלומר שהיה ניכר עליה שהיא שייכת לו ומייצגת אותו (כחפץ המסומן על ידי בעליו, שכך ניכר שהוא שייך לו), ולפיכך: וַיִּוָּשַׁע – הקב\"ה עצמו נושע, כביכול, בישועה זו של ישראל, שהרי הוא מייצג אותו; דבר זה רמוז במילה \"וַיּוֹשַׁע\", שאפשר לנקדה: \"וַיִּוָּשַׁע\". הערות 303 'שיחה שלימה', וראה עוד להלן עמ' 112 304 כך שירת הים מכונה בלשון הראשונים, ראה למשל ספר האגור סימן תתמט, שיבולי הלקט סימן רסט. 305 ראה לעיל עמ' 79 306 כמו: \"כִּי אַתָּה גֹחִי מִבָּטֶן\" (תהילים כב י)."],[8,"s9","כְּהוֹשַׁעְתָּ מַאֲמַר וְהוֹצֵאתִי אֶתְכֶם","– כשם שהושעת את ישראל ממצרים, והבטחת להם על ידי משה: \"לָכֵן אֱמ…ר לִבְנֵי יִשְׂרָאֵל: אֲנִי ה', ו¿הוֹ≈צאƒתי ∆א¿תכ∆ם מִתַּחַת סִבְלֹת מִצְרַיִם, וְהִצַּלְתִּי אֶתְכֶם מֵעֲבֹדָתָם, וְגָאַלְתִּי אֶתְכֶם בִּזְרוֹעַ נְטוּיָה וּבִשְׁפָטִים גְּדֹלִים\" (שמות ו ו). נָקוּב וְהוּצֵאתִי אִתְּכֶם – 'מַאֲמַר וְהוֹצֵאתִי אֶתְכֶם' כולל משמעות נוספת, כשהוא 'נָקוּב' (=מפורש) על פי ניקוד שונה: 'וְהוּצֵאתִי אִתְּכֶם' – הקב\"ה עצמו יוצא מגלות מצרים יחד עִם ישראל. הערות 307 כמו: \"וְנֹקֵב שֵׁם ה' מוֹת יוּמָת\" (ויקרא כד טז) – \"אינו חייב עד שיפרש את השם\" (מסכת סנהדרין, פרק ז, משנה ה)."],[8,"s10","כְּהוֹשַׁעְתָּ סוֹבְבֵי מִזְבֵּחַ, עוֹמְסֵי עֲרָבָה לְהַקִּיף מִזְבֵּחַ","– כשם שהושעת את ישראל, על ידי עבודת המקדש שהורידה לישראל ולעולם שפע ברכה וישועה; העבודה הנזכרת כאן היא ההקפות שעשו במקדש בכל יום מימי חג הסוכות סביב המזבח (בדומה למה שאנו נוהגים להקיף את הבימה בבית הכנסת), ואחזו אז בידיהם את אגודת ארבעת המינים, או – לדעה אחרת בגמרא – ענפי ערבות ארוכים; לאחר ההקפה היו זוקפים את הערבות סביב המזבח. 'עוֹמְסֵי עֲרָבָה' – שהיו עומסים (=נושאים) ערבות, 'לְהַקִּיף מִזְבֵּחַ' – לזוקפן סביבו כך שיהיה מוקף בהן. לפי הדעה שבזמן ההקפות אחזו בערבות, ניתן גם לפרש: עומסים את הערבות בידיהם, 'לְהַקִּיף מִזְבֵּחַ' – ללכת עימן סביב המזבח. וכך מתוארת במשנה מצוַת הערבה: מצוַת ערבה כיצד? מקום היה למטה מירושלים, ונקרא 'מוצא'. יורדים לשם ומלקטים משם מורביות של ערבה, ובאין וזוקפין אותן בצדי המזבח וראשיהן כפופין על גבי המזבח. תקעו והריעו ותקעו. בכל יום מקיפין את המזבח פעם אחת, ואומרים: \"אָנָּא ה' הוֹשִׁיעָה נָּא, אָנָּא ה' הַצְלִיחָה נָא\" (תהילים קיח כה). רבי יהודה אומר: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\". ואותו היום [=הושענא רבה] מקיפין את המזבח שבע פעמים. נוסח התחינה שהיו אומרים בזמן ההקפות לדעת רבי יהודה: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\", מבטא את הרעיון החורז פיוט זה: 'אֲנִי' – ישראל, 'וָהוּ[א]' – הקב\"ה עצמו – את שניהם 'הוֹשִׁיעָה נָּא'; וזוהי השייכות של שורה זו לפיוט. הראשונים נחלקו בשאלה מי היו המקיפים: לדעת רש\"י ו'תוספות' רק הכוהנים היו מקיפים, אך לשאר ישראל אסור היה להיכנס לשטח שבין אולם המקדש למזבח, ואילו לדעת רי\"ץ גיאת, 'חזקוני', ו'אור זרוע', וכך משמע גם בדברי הרמב\"ם – כל ישראל השתתפו בהקפות. הערות 308 מסכת סוכה, פרק ד, משנה ה 309 סוכה מג: ד\"ה שלוחי בית דין 310 שם, ד\"ה והביאו; שם מד. ד\"ה ואמר ליה 311 הלכות לולב 312 על התורה, שמות כ כ 313 סימן שטו 314 משנה תורה, הלכות שופר סוכה ולולב, פרק ז, הלכה כג 315 וראה להלן עוד בעניין ההקפות במקדש ומצות הערבה (עמ' 205-203)."],[8,"s11","סיכום","לשם הבנת השורה הבאה יש להקדים את המסופר בספר שמואל (פרקים ד-ו), שישראל לקחו עימם את ארון הברית למלחמה בפלישתים, מתוך הנחה שבכך הם 'מכריחים' את הקב\"ה לעזור להם לנצח. אך תוחלתם נכזבה, והם הובסו בקרב; ארון הברית נשבה בידי הפלישתים, שהציבוהו באשדוד, בתוך בית דגון אלוהיהם. למחרת ראו הפלישתים שפסל דגון נפל לפני הארון, והעמידוהו במקומו; כעבור יום נוסף ראו ששוב נפל פסל דגון לפני הארון, וראשו ושתי כפות ידיו כרותים. לאחר מכן תושבי אשדוד לקו במחלת הטחורים, ובשל כך העבירו את הארון לעיר גת; כשאף תושבי גת לקו במחלה זו, העבירוהו לעיר עקרון; משתושבי עקרון נזעקו מיד: \"הֵסַבּוּ אֵלַי אֶת אֲרוֹן אֱלֹהֵי יִשְׂרָאֵל לַהֲמִיתֵנִי וְאֶת עַמִּי\" (שם ה י) – החזירו את הארון בכבוד לבית שמש היהודית. על פי זה יתפרש: כְּהוֹשַׁעְתָּ פִּלְאֵי אָרוֹן כְּהֻפְשַׁע – כשם שהושעת את ארון הברית על ידי הפלאות שחוללת על ידו, בזמן ש'הֻפְשַׁע' = שפשעו בו: ישראל – בכך שלקחוהו למלחמה, והפלישתים – בכך שלקחוהו אליהם; צִעֵר פְּלֶשֶׁת בַּחֲרוֹן אַף וְנוֹשַׁע – הארון נושע מהפלישתים על ידי שציערם במחלת הטחורים, בחרון אפו של הקב\"ה. בשונה משאר השורות בפיוט, בהן מוזכרות ישועות שנעשו לישראל מצרותיהם והימצאותו של הקב\"ה עמהם, כאן מוזכרת ישועה שעשה הקב\"ה לעצמו – לארון הברית שמייצג אותו. לאור זאת ניתן לשאול, מדוע אכן נכתבה בפיוט שורה זו, שאינה נושאת עימה את המסר המשותף לכל שאר השורות? ייתכן שמטרתה של שורה זו היא להמחיש את המסר של הפיוט: כשם שבשביית ארון ה' על ידי הפלישתים ניתן לראות בבירור את חילול השם הכרוך בכך, כך גם כשישראל נמצאים בגלות הרי זה חילול שם שמיים, שכן עם ישראל מייצג את הקב\"ה בעיני העמים לא פחות מאשר ארון הברית; על כן אנו מתפללים: 'כֵּן הוֹשַׁע נָא' – אותנו מהגלות, ועל ידי כן יתקדש שמך; וכך ניבא יחזקאל: וָאָפִיץ אֹתָם בַּגּוֹיִם וַיִּזָּרוּ בָּאֲרָצוֹת, כְּדַרְכָּם וְכַעֲלִילוֹתָם שְׁפַטְתִּים. וַיָּבוֹא אֶל הַגּוֹיִם אֲשֶׁר בָּאוּ שָׁם וַיְחַלְּלוּ אֶת שֵׁם קָדְשִׁי, בֶּאֱמֹר לָהֶם: עַם ה' אֵלֶּה וּמֵאַרְצוֹ יָצָאוּ. וָאֶחְמֹל עַל שֵׁם קָדְשִׁי, אֲשֶׁר חִלְּלוּהוּ בֵּית יִשְׂרָאֵל בַּגּוֹיִם אֲשֶׁר בָּאוּ שָׁמָּה. לָכֵן אֱמֹר לְבֵית יִשְׂרָאֵל: כֹּה אָמַר אֲדֹנָי יֱהֹוִה: לֹא לְמַעַנְכֶם אֲנִי עֹשֶׂה בֵּית יִשְׂרָאֵל, כִּי אִם לְשֵׁם קָדְשִׁי אֲשֶׁר חִלַּלְתֶּם בַּגּוֹיִם אֲשֶׁר בָּאתֶם שָׁם. וְקִדַּשְׁתִּי אֶת שְׁמִי הַגָּדוֹל הַמְחֻלָּל בַּגּוֹיִם אֲשֶׁר חִלַּלְתֶּם בְּתוֹכָם, וְיָדְעוּ הַגּוֹיִם כִּי אֲנִי ה' נְאֻם אֲדֹנָי יֱהֹוִה בְּהִקָּדְשִׁי בָכֶם לְעֵינֵיהֶם. וְלָקַחְתִּי אֶתְכֶם מִן הַגּוֹיִם, וְקִבַּצְתִּי אֶתְכֶם מִכָּל הָאֲרָצוֹת, וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַתְכֶם. הערות 316 יחזקאל לו יט-כד"],[8,"s12","כְּהוֹשַׁעְתָּ קְהִלּוֹת בָּבֶלָה שִׁלַּחְתָּ","– כשם שהושעת את קהילות שבטי יהודה ובנימין שגלו לבבל לאחר חורבן בית ראשון, בכך שחזרו לארץ ברשיון כורש מלך פרס ובנו את בית המקדש השני. ישועה זו היתה, כביכול, אף עבורך, שכן: רַחוּם לְמַעֲנָם שֻׁלַּחְתָּ – אתה ה' הרחום, נשלחת עִם ישראל לגלות בבל, כדברי הגמרא: תניא, רבי שמעון בן יוחאי אומר: בוא וראה כמה חביבין ישראל לפני הקב''ה, שבכל מקום שגלו – שכינה עמהן. גלו למצרים – שכינה עמהן, שנאמר: \"הֲנִגְלֹה נִגְלֵיתִי אֶל בֵּית אָבִיךָ בִּהְיוֹתָם בְּמִצְרַיִם\" וגו' (שמואל א' ב כז). גלו לבבל – שכינה עמהן, שנאמר: \"לְמַעַנְכֶם שִׁלַּחְתִּי בָבֶלָה\" (ישעיה מג יד). ואף כשהן עתידין ליגאל – שכינה עמהן, שנאמר: \"וְשָׁב ה' אֱלֹהֶיךָ אֶת שְׁבוּתְךָ\" (דברים ל ג), \"והשיב\" לא נאמר, אלא \"וְשָׁב\" – מלמד שהקב''ה שב עמהן מבין הגלויות. רבי שמעון בן יוחאי דורש את הפסוק: \"לְמַעַנְכֶם שִׁלַּחְתִּי בָבֶלָה\", כאילו כתוב \"שֻׁלַּחְתִּי\"; כאן מופיע פן נוסף במשמעותה של גלות הקב\"ה עִם ישראל: לא העדר הופעת השכינה בלבד, אלא השגחה פרטית מאת הקב\"ה לשמרם ולהיטיב להם. בכך ניכרת חביבותם לפניו – אף כשהם גולים מפני רוע מעשיהם, עינו עליהם לטובה; וכך ניבא ירמיהו: כֹּה אָמַר ה' אֱלֹהֵי יִשְׂרָאֵל: כַּתְּאֵנִים הַטֹּבוֹת הָאֵלֶּה, כֵּן אַכִּיר אֶת גָּלוּת יְהוּדָה אֲשֶׁר שִׁלַּחְתִּי מִן הַמָּקוֹם הַזֶּה אֶרֶץ כַּשְׂדִּים, לְטוֹבָה. וְשַׂמְתִּי עֵינִי עֲלֵיהֶם לְטוֹבָה, וַהֲשִׁבֹתִים עַל הָאָרֶץ הַזֹּאת, וּבְנִיתִים וְלֹא אֶהֱרֹס, וּנְטַעְתִּים וְלֹא אֶתּוֹשׁ. וְנָתַתִּי לָהֶם לֵב לָדַעַת אֹתִי כִּי אֲנִי ה', וְהָיוּ לִי לְעָם וְאָנֹכִי אֶהְיֶה לָהֶם לֵאלֹהִים, כִּי יָשֻׁבוּ אֵלַי בְּכָל לִבָּם. על כך יסד הפייטן: \"רַחוּם, לְמַעֲנָם שֻׁלַּחְתָּ\" – מכוח מידת רחמנותך, שילחת את עצמך עמהם לבבל. הערות 317 תלמוד בבלי, מגילה כט. 318 ירמיהו כד ה-ז"],[8,"s13","כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב, וְהוֹשִׁיעָה נָּא","– כשם שהושעת את 'שִׁבְטֵי יַעֲקֹב' שגלו לבבל, הלוא הם יהודה ובנימין, והשבת אותם לארץ בימי עזרא, כך 'תָּשׁוּב' בעצמך כביכול, מהגלות הנוכחית, על ידי שתָשִׁיב את 'אָהֳלֵי יַעֲקֹב' = כל שבטי ישראל, לארצם; בין את אלו מיהודה ובנימין שטרם שבו לארץ, ובין את עשרת השבטים, כלשון נבואת ירמיהו על הגאולה העתידה: \"כֹּה אָמַר ה': הִנְנִי שָׁב שְׁבוּת »א√הל≈י יעקוֹב וּמִשְׁכְּנֹתָיו אֲרַחֵם, וְנִבְנְתָה עִיר עַל תִּלָּהּ, וְאַרְמוֹן עַל מִשְׁפָּטוֹ יֵשֵׁב\" (ירמיהו ל יח). הערות 319 הפייטן השתמש בביטוי זה ביחס לשבטי יהודה ובנימין, בעקבות לשון הכתוב: \"לְהָקִים אֶת שִׁבְטֵי יַעֲקֹב\" (ישעיהו מט ו), המתייחס לשבטים אלו (לפי רש\"י ומצודת דוד)."],[8,"s14","כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי","(=מְחַכֵּי) יְשׁוּעוֹת אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא – כשם שהושעת לאורך הדורות את שומרי המצוות, שכן \"שׁוֹמֵר מִצְוָה לֹא יֵדַע דָּבָר רָע\" (קהלת ח ה), ו\"שֹׁמֵר מִצְוָה שֹׁמֵר נַפְשׁוֹ\" (משלי יט טז), וכן את הבוטחים בך ומחכים לישועותיך, שכן \"הַבּוֹטֵחַ בַּה' חֶסֶד יְסוֹבְבֶנּוּ\" (תהילים לב י) – \"אפילו רשע בוטח בה' – חֶסֶד יְסוֹבְבֶנּוּ\" – כך היֵה גם לנו 'אֵל לְמוֹשָׁעוֹת', 'וְהוֹשִׁיעָה נָּא'. הערות 320 שורה זו היא תוספת מאוחרת, ראה להלן עמ' 212. 321 מדרש תהילים על אתר 322 ראה לעיל עמ' 117"],[8,"s15","הוֹשִׁיעָה אֶת עַמֶּךָ, וּבָרֵךְ אֶת נַחֲלָתֶךָ","– עם ישראל, שהוא נחלתו של הקב\"ה, וּרְעֵם – רעֵה אותם, וְנַשְּׂאֵם – נשא ורומם אותם, עַד הָעוֹלָם – לעולם. פסוק זה חותם את מזמור כח בספר תהילים, ופירש שם המלבי\"ם: הוֹשִׁיעָה אֶת עַמֶּךָ – שתעשה זה בעבור ישראל להושיע אותם, וגם ברכם בתוספת ברכה מצד שהם נַחֲלָתֶךָ , ששם 'נחלה' מציין שבחרם לנחלה לו לדור דורים, ועל ידי כך הם קדושים ומיוחדים לאלוהיהם וצריך הוא לברכם בברכה יתירה, וּרְעֵם – מצד שהם 'עמך', וְנַשְּׂאֵם עוד יותר מצד שהם 'נחלתך', וזה יהיה עַד הָעוֹלָם . בסוף סדר אמירת ה'הושענות', בהן התפללנו רבות על הישועה, כאן אנו מבקשים על קומה נוספת, עליונה יותר: לא רק הצלה וישועה מן הצרות ההוות או העלולות לבוא בעתיד, אלא תוספת ברכה והתנשאות כבודם הלאומי של ישראל. הערות 323 כמו שכתוב: \"עַל עַמִּי וְנַחֲלָתִי יִשְׂרָאֵל אֲשֶׁר פִּזְּרוּ בַגּוֹיִם\" (יואל ד ב)."],[8,"s16","וְיִהְיוּ דְּבָרַי אֵלֶּה אֲשֶׁר הִתְחַנַּנְתִּי לִפְנֵי ה', קְרוֹבִים אֶל ה' אֱלֹהֵינוּ יוֹמָם וָלָיְלָה, לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל דְּבַר יוֹם בְּיוֹמוֹ","– פסוק זה ושלאחריו מופיעים בברכה שבירך שלמה את העם במעמד חנוכת בית המקדש: וַיְהִי כְּכַלּוֹת שְׁלֹמֹה לְהִתְפַּלֵּל אֶל ה' אֵת כָּל הַתְּפִלָּה וְהַתְּחִנָּה הַזֹּאת, קָם מִלִּפְנֵי מִזְבַּח ה' מִכְּרֹעַ עַל בִּרְכָּיו, וְכַפָּיו פְּרֻשׂוֹת הַשָּׁמָיִם. וַיַּעְמֹד וַיְבָרֶךְ אֵת כָּל קְהַל יִשְׂרָאֵל קוֹל גָּדוֹל לֵאמֹר: בָּרוּךְ ה' אֲשֶׁר נָתַן מְנוּחָה לְעַמּוֹ יִשְׂרָאֵל כְּכֹל אֲשֶׁר דִּבֵּר, לֹא נָפַל דָּבָר אֶחָד מִכֹּל דְּבָרוֹ הַטּוֹב אֲשֶׁר דִּבֶּר בְּיַד מֹשֶׁה עַבְדּוֹ. יְהִי ה' אֱלֹהֵינוּ עִמָּנוּ כַּאֲשֶׁר הָיָה עִם אֲבֹתֵינוּ, אַל יַעַזְבֵנוּ וְאַל יִטְּשֵׁנוּ. לְהַטּוֹת לְבָבֵנוּ אֵלָיו, לָלֶכֶת בְּכָל דְּרָכָיו, וְלִשְׁמֹר מִצְוֹתָיו וְחֻקָּיו וּמִשְׁפָּטָיו אֲשֶׁר צִוָּה אֶת אֲבֹתֵינוּ. וְיִהְיוּ דְבָרַי אֵלֶּה אֲשֶׁר הִתְחַנַּנְתִּי לִפְנֵי ה', קְרֹבִים אֶל ה' אֱלֹהֵינוּ יוֹמָם וָלָיְלָה; לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל, דְּבַר יוֹם בְּיוֹמוֹ. לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי ה' הוּא הָאֱלֹהִים אֵין עוֹד. וְהָיָה לְבַבְכֶם שָׁלֵם עִם ה' אֱלֹהֵינוּ, לָלֶכֶת בְּחֻקָּיו וְלִשְׁמֹר מִצְוֹתָיו כַּיּוֹם הַזֶּה. שלמה מתפלל ש'הַתְּפִלָּה וְהַתְּחִנָּה הַזֹּאת' שנשא קודם לכן, תהיינה קרובות אל הקב\"ה יומם ולילה, כלומר שהן תפעלנה תמיד את פעולתן כאילו הוא ממשיך להתפלל אותן בכל רגע, וכך יספק הקב\"ה את צרכיהם הרוחניים והגשמיים של 'עַבְדּוֹ' – שלמה, ושל 'עַמּוֹ יִשְׂרָאֵל', 'דְּבַר יוֹם בְּיוֹמוֹ' – שבכל יום יבחן מחדש למה הם זקוקים. אף אנו, בסיום תפילת ה'הושענות', מתפללים שדברינו אלה אשר התחנַנּוּ לפני ה', יפעלו תמיד את פעולתם כאילו הם נישאים תמיד על שפתינו, ומכוחם נקבל מאת ה' את צרכינו דבר יום ביומו, הן את הצרכים הקבועים, הן את הצרכים המתחדשים. אמירה זו בסיום התפילה, מבטאת את עומק רצונו של המתפלל: אילו היה יכול – היה מתפלל בכל עת, וכך היה דבק באלוהיו תמיד ומשפיע על נפשו את ההשפעות החיוביות שיוצרת התפילה, כדברי רבי יוחנן בגמרא: \"ולוואי שיתפלל אדם כל היום כולו\". כשהמתפלל נותן ביטוי לרצונו באמירה מעין זו, הרי שהיא עצמה מעמיקה בתודעתו ובנפשו את הרוממות, ההתעלות, והמבט האמיתי על חייו, אותם חווה בתפילה. כך, במובן מסויים, הוא מתקרב למצב של 'יתפלל אדם כל היום כולו', אף על פי שבשאר זמנו הוא עוסק בחובותיו האחרות. כשהאדם משתדל שהתפילה תעמוד במרכז חייו ותקרין על שאר הזמנים והמצבים שבסדר יומו, בבית ומחוץ לו, בלילה וביום – היא אכן יכולה להיות קרובה אל ה' יומם ולילה, 'דְּבַר יוֹם בְּיוֹמוֹ'. הערות 324 מלכים א' ח נד-סא 325 'משפט' במובן של צרכים, ראה שמות כא ט, מלכים א' ה ח 326 ראה לעיל עמ' 134 327 תלמוד בבלי, ברכות כא."],[8,"s17","לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי ה' הוּא הָאֱלֹהִים, אֵין עוֹד","– כאן מציין שלמה את המטרה של הבקשות שהזכיר לפני כן: על הרוחניות – \"יְהִי ה' אֱלֹהֵינוּ עִמָּנוּ כַּאֲשֶׁר הָיָה עִם אֲבֹתֵינוּ, אַל יַעַזְבֵנוּ וְאַל יִטְּשֵׁנוּ; לְהַטּוֹת לְבָבֵנוּ אֵלָיו, לָלֶכֶת בְּכָל דְּרָכָיו, וְלִשְׁמֹר מִצְוֹתָיו וְחֻקָּיו וּמִשְׁפָּטָיו אֲשֶׁר צִוָּה אֶת אֲבֹתֵינוּ\", ועל הצרכים הגשמיים – \"מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל\". על ידי דבקותו של עם ישראל בדרכי ה', ועל ידי סיפוק צרכיו הגשמיים שיסייעו לו בכך – הוא ייצג כראוי את שם ה' בעולם, וכך ידעו כל עמי הארץ: \"כִּי ה' הוּא הָאֱלֹהִים, אֵין עוֹד\". בקשה זו מתאימה במיוחד לחג הסוכות, שאחד ממאפייניו הוא ההשפעה על אומות העולם; בין השפעה הפועלת באופן רוחני – הקרבת שבעים הפרים עבורם, ובין השפעה מעשית – בזמן בית ראשון, האומות היו עולות לרגל בחג הסוכות ולומדות מישראל את תורת האמונה היהודית, וכך יהיה גם בבית המקדש השלישי, כמתואר בנבואת זכריה, וכפי שכותב הנצי\"ב: כתב בספר זכריה (יד) דלעתיד יהיו גם אומות העולם באים בחול המועד סוכות לעמוד על קורבנם, היינו בשביל שיכירו גם המה את 'מֶלֶךְ ה' צְבָאוֹת', ויהיו יודעים דפרנסתם תלויה במוספי החג שישראל מביאים בשבילם, ואם לא יעלו – לא יבוא עליהם הגשם. וכך היה המנהג בימי שלמה, ומשום הכי [=ומשום כך] היה שלמה מגיד קהלת בחול המועד סוכות לפני חכמי אומות העולם, [...] ומזה אנו נזהרים דור דור לקרוא קהלת בחג הסוכות. סיום זה של סדר תפילת ה'הושענות' נעוץ בתחילתו, והוא סוגר את המעגל – המטרה שניצבת נגד עינינו היא: \"לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי ה' הוּא הָאֱלֹהִים, אֵין עוֹד\" – \"לְמַעַנְךָ אֱלֹהֵינוּ הוֹשַׁע נָא\". הערות 328 הרב נפתלי צבי יהודה ברלין (תקע\"ז–תרנ\"ג), בנו של רבי חיים מוולוז'ין וראש ישיבת וולוז'ין. חיבר את הפירושים 'העמק דבר' על התורה, 'העמק שאלה' על ספר 'השאילתות' לרב אחאי גאון, 'מרומי שדה' על התלמוד, ושו\"ת 'משיב דבר'. 329 פסוקים טז-יז: \"וְהָיָה כָּל הַנּוֹתָר מִכָּל הַגּוֹיִם הַבָּאִים עַל יְרוּשָׁלִָם, וְעָלוּ מִדֵּי שָׁנָה בְשָׁנָה לְהִשְׁתַּחֲוֹת לְמֶלֶךְ ה' צְבָאוֹת וְלָחֹג אֶת חַג הַסֻּכּוֹת. וְהָיָה אֲשֶׁר לֹא יַעֲלֶה מֵאֵת מִשְׁפְּחוֹת הָאָרֶץ אֶל יְרוּשָׁלִַם לְהִשְׁתַּחֲוֹת לְמֶלֶךְ ה' צְבָאוֹת - וְלֹא עֲלֵיהֶם יִהְיֶה הַגָּשֶׁם\". 330 'העמק דבר', במדבר כט יב, ב'הרחב דבר'"],[8,"n270","הערה 270","מסכת סוכה, פרק ד, משנה ה"],[8,"n271","הערה 271","ראה לעיל עמ' 61-60 ביאור רעיון זה באריכות."],[8,"n272","הערה 272","פירוש על התורה, שמות טו ג"],[8,"n273","הערה 273","רבי אלעזר אזכרי (רצ\"ג-ש\"ס), מקובל, דרשן, ומשורר, מחכמי צפת. חיבר את 'ספר חרדים' העוסק במניין המצוות ובענייני מוסר, פירוש למסכתות אחדות מן התלמוד הבבלי והירושלמי, וכן את הפיוט הידוע 'ידיד נפש'."],[8,"n274","הערה 274","ראה שם, שער אהבת ה' פרק ו: \"שיתייחד בזכר האלוהים ויתבודד בו, כעת התייחד כל אוהב באוהבו והתבודד כל חושק עם חשוקו, כמו שנאמר: \"נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה\" (ישעיהו כו ט), ואמר:\"עַל מִשְׁכָּבִי בַּלֵּילוֹת\" (שיר השירים ג א)."],[8,"n275","הערה 275","ספר חרדים, פרק סו, אות צז (ההדגשות אינן במקור)."],[8,"n276","הערה 276","יש סידורים בהם מנוקד 'וָהוֹ'."],[8,"n277","הערה 277","תיקוני הזוהר, תיקון ו, דף כג."],[8,"n278","הערה 278","על פי רש\"י, סוכה מה., ועוד"],[8,"n279","הערה 279","ביאור הגר\"א לשיר השירים א ב, על פי הזוהר ח\"ב, דף נב."],[8,"n280","הערה 280","שם"],[9,"piyut","נוסח הפיוט","הוֹשַׁע נָא אוֹם נְצוּרָה כְּבָבַת. לְבוּשׁ וּכְסוּת מַחְלֶפֶת בַּשַּׁבָּת. בּוֹנֶנֶת בְּדַת נֶפֶשׁ מְשִׁיבַת. מַאֲכָל וּמִשְׁתֶּה מְכִינָה לַשַּׁבָּת. גּוֹמֶרֶת הִלְכוֹת שַׁבָּת. נֹעַם מְגָדִים מַנְעֶמֶת לַשַּׁבָּת. דּוֹרֶשֶׁת מַשְׂאַת שַׁבָּת. סְעוּדוֹת שָׁלשׁ מְקַיֶּמֶת בַּשַּׁבָּת. הַקּוֹבַעַת אַלְפַּיִם תְּחוּם שַׁבָּת. עַל שְׁתֵּי כִכָּרוֹת בּוֹצַעַת בַּשַּׁבָּת. וּמְשִׁיבַת רֶגֶל מִשַּׁבָּת. פּוֹרֶטֶת אַרְבַּע רְשׁוּיוֹת בַּשַּׁבָּת. זָכוֹר וְשָׁמוֹר מְקַיֶּמֶת בַּשַּׁבָּת. צִוּוּי הַדְלָקַת נֵר מַדְלֶקֶת בַּשַּׁבָּת. חָשָׁה לְמַהֵר בִּיאַת שַׁבָּת. קִדּוּשׁ הַיּוֹם מְקַדֶּשֶׁת בַּשַּׁבָּת. טוֹרַחַת כֹּל מִשִּׁשָּׁה לַשַּׁבָּת. רֶנֶן שֶׁבַע מְפַלֶּלֶת בַּשַּׁבָּת. יוֹשֶׁבֶת וּמַמְתֶּנֶת עַד כְּלוֹת שַׁבָּת. שִׁבְעָה בַדָּת קוֹרְאָה בַשַּׁבָּת. כָּבוֹד וָעֹנֶג קוֹרְאָה לַשַּׁבָּת. תַּנְחִילֶנָּה יוֹם שֶׁכֻּלּוֹ שַׁבָּת. הוֹשַׁע נָא."],[9,"s1","על הפיוט","בפיוט זה אנו מתפללים לישועתו של עם ישראל בזכות שמירתו את השבת."],[9,"s2","אוֹם נְצוּרָה כְּבָבַת","– ישראל, שהם אומה הנצורה על ידי הקב\"ה כבבת (=אישון) העין, כמאמר הכתוב: \"יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ\" (דברים לב י), וכן: \"כִּי הַנֹּגֵעַ בָּכֶם – נֹגֵעַ בְּבָבַת עֵינוֹ\" (זכריה ב יב). שמירה זו שזוכים לה ישראל, רומזת לשמירתם את השבת, שכן על ידה שמירת הקב\"ה והגנתו עליהם מתחזקת, כפי שכתוב בספר הזוהר: כשמתקדש היום בערב שבת, סוכת שלום שורה ונפרסת בעולם [...] ואז העולם בשמירה עליונה ואיננו צריכים להתפלל על שמירה כגון: \"שׁוֹמֵר עַמּוֹ יִשְׂרָאֵל לָעַד\", שהרי זה ביום חול נתקן, שהעולם צריך שמירה; אבל בשבת – סוכת שלום נפרסת על העולם, ולכן בברכת היום מברכים: \"הַפּוֹרֵשׂ סֻכַּת שָׁלוֹם עָלֵינוּ וְעַל כָּל עַמּוֹ יִשְׂרָאֵל וְעַל יְרוּשָׁלָיִם\"."],[9,"s3","בּוֹנֶנֶת בְּדַת נֶפֶשׁ מְשִׁיבַת","– מתבוננת בתורה, הנקראת 'דָּת', שהיא 'נֶפֶשׁ מְשִׁיבַת' – משיבה את נפש הלומד, כמאמר הכתוב: \"תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ\" (תהילים יט ח). יום השבת נועד כדי שלאדם העובד במשך ימות השבוע, תהיה עצירה ממהלך חייו השוטף, בה יוכל 'להתאפס' על עצמו ועל מטרת חייו, ולהיפגש עם תוכן חייו האמיתי: הרוחניות. העבודה במשך השבוע אינה אלא אמצעי כדי להתקיים; אך תכלית החיים עצמה, עימה נפגש האדם בשבת, היא ההתקרבות לקב\"ה. זאת, מתוך שבשבת, שהיא 'זכר למעשה בראשית', האדם נזכר בבריאת העולם, וזכירה זו מבהירה לו את משמעות חייו ואת מטרת מעשיו במשך ימי המעשה: קיום רצון ה' ומימוש מטרת הבריאה. מתוך העיסוק וההתבוננות 'בְּדַת נֶפֶשׁ מְשִׁיבַת' – יֵדע כיצד ליישם זאת בפועל. בפרט התורה שנלמדת בשבת היא 'נֶפֶשׁ מְשִׁיבַת'; במשך השבוע האדם טרוד בחייו המעשיים, ונפשו כאילו מתרחקת ממנו – הוא שקוע בענייני הגוף ואינו חש את נפשו, את הצד הרוחני שבו. בשבת, האדם עוצר משטף החיים ומפנה את מחשבתו לתורה ולרוחניות, וכך נפשו 'שבה' אליו – היא יכולה להרגיש אצלו בנוח, בהיותו עסוק בדברים המתאימים לה; וכך כתב מהר\"ל מפראג: כי השבת ניתן [כדי] שהאדם יהיה פנוי מן המלאכה, ויהיה פנוי אל התורה שהוא השלמת הנפש, כי בתורה ימצא הנפש מרגוע. ולכך הכול מודים שבשבת ניתנה תורה לישראל, וזה להשלמת נפש ישראל. ולכך אמרו: נשמה יתירה ניתנה לאדם בשבת, ומכוח זה יש לאדם הַשְׂכֵּל יותר. הערות 333 לעיל עמ' 51 334 ראה תלמוד בבלי, שבת פו: 335 ראה שם, ביצה טז. 336 חידושי אגדות, גיטין לח:"],[9,"s4","גּוֹמֶרֶת הִלְכוֹת שַׁבָּת","– לומדת הלכות שבת (הפועל 'גּוֹמֶרֶת' אינו מלשון גמר וסיום, אלא נגזר מהפועל הארמי 'למיגמר' = ללמוד). מכיוון ש\"הלכות שבת [...] הרי הן כהררים התלויים בשערה, שהן מקרא מועט והלכות מרובות\" [=פסוקי התורה העוסקים באיסורי מלאכות שבת הם מועטים, בעוד שההלכות שבתורה שבעל פה העוסקות בכך הן מרובות] – השתמש הפייטן בפועל 'גּוֹמֶרֶת', המתייחס בעיקר ללימוד תורה שבעל פה. הערות 337 מסכת חגיגה, פרק א, משנה ח 338 'דובר שלום' (פירוש על סידור התפילה מאת רבי יצחק אליהו לנדא [תקס\"א–תרל\"ז], כיהן כרב בוילנא)."],[9,"s5","דּוֹרֶשֶׁת מַשְׂאַת שַׁבָּת","– נושאת בשבת דרשות בהלכות השבת, כדברי המדרש: אמר הקב\"ה [למשה]: עשה לך קהילות גדולות ודרוש לפניהם ברבים הלכות שבת, כדי שילמדו ממך דורות הבאים להקהיל קהילות בכל שבת ושבת ולכנוס בבתי מדרשות, ללמד ולהורות לישראל דברי תורה. פירוש נוסף: דורשת מפסוקי התורה את האיסור לשאת משא בשבת ברשות הרבים, וכן את האיסור להוציא משא מרשות הרבים לרשות היחיד ולהיפך. איסור זה אינו מפורש בכתוב, אלא נדרש מהפסוק: \"וַיְצַו מֹשֶׁה וַיַּעֲבִירוּ קוֹל בַּמַּחֲנֶה לֵאמֹר: אִישׁ וְאִשָּׁה אַל יַעֲשׂוּ עוֹד מְלָאכָה לִתְרוּמַת הַקֹּדֶשׁ, וַיִּכָּלֵא הָעָם מֵהָבִיא\" (שמות לו ו) – משה מצווה את העם לחדול מהבאת תרומות לצורך המשכן, ועל פי דרשת חז\"ל ציווי זה נאמר לפני יום השבת, ומשום האיסור לשאת בו משא. יש מפרשים שהאיסור נלמד גם מהפסוק: \"אַל יֵצֵא אִישׁ מִמְּקֹמוֹ בַּיּוֹם הַשְּׁבִיעִי\" (שם טז כט) – משה מצווה את העם לא לצאת בשבת ללקוט מן, וטעם ציווי זה הוא האיסור הכרוך בהוצאת הכלי מביתם לרשות הרבים ובנשיאתו שם. הערות 339 'מַשְׂאַת' מלשון נשיאת דברים. 340 ילקוט שמעוני, שמות, רמז תח 341 על פי ה'רוקח' ו'דובר שלום' 342 תלמוד בבלי, שבת צו:, ראה שם אופן הדרשה. 343 שם, עירובין יז: לפי פירוש התוספות שם ד\"ה לאו"],[9,"s6","הַקּוֹבַעַת אַלְפַּיִם תְּחוּם שַׁבָּת","– שקבעה את האיסור לצאת בשבת מחוץ לתחום, שהוא אלפיים אמה סביב העיר. הפייטן נקט כדעת רבי אליעזר בנו של רבי יוסי הגלילי, הסבור כי איסור זה אינו מן התורה, אלא !קבע על ידי חכמי ישראל. הערות 344 ראה תלמוד בבלי, סוטה כז:, ל:"],[9,"s7","וּמְשִׁיבַת רֶגֶל מִשַּׁבָּת","– על פי לשון הכתוב: \"אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךָ\" (ישעיהו נח יג); הנביא מזהיר את ישראל להשיב את רגלם מהשבת, כלומר: לסלק מיום השבת הליכה שהיא לצורך עסקים וענייני חולין (כגון בשביל לראות דבר-מה כדי להחליט אם לקנותו לאחר השבת), על אף שאין בהליכה זו איסור מן התורה. בדבריו שם מתאר הנביא את צביונה הראוי של השבת: אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךָ, עֲשׂוֹת חֲפָצֶיךָ בְּיוֹם קָדְשִׁי, וְקָרָאתָ לַשַּׁבָּת עֹנֶג, לִקְדוֹשׁ ה' מְכֻבָּד, וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךָ, מִמְּצוֹא חֶפְצְךָ, וְדַבֵּר דָּבָר. אָז תִּתְעַנַּג עַל ה', וְהִרְכַּבְתִּיךָ עַל במותי (קרֵי: בָּמֳתֵי) אָרֶץ, וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ, כִּי פִּי ה' דִּבֵּר. מפסוקים אלו נלמדים רבים מדיני השבת שאינם נובעים מאיסורי המלאכות הרגילים, אלא מהמטרה לשמר על צביונה הראוי, ואחדים מהם יוזכרו בהמשך הפיוט. מטרת דין זה, המורה להימנע מהליכה לצורך ענייני חולין, היא שהאדם יישאר בתוך אווירת הקדושה של השבת, וינצל את הזמן בו הוא שובת ממלאכה כדי לתת לנפשו את המזון הרוחני שהיא זקוקה לו, כמבואר לעיל. אם גם בשבת הוא יהיה עסוק בעניינים בהם הוא עסוק בימות החול, הרי שהוא מפספס את עניינה המרכזי של השבת. המלבי\"ם מפרש את המילים: \"אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךָ\" – אם הימנעותך מעסקים תהיה 'מִשַּׁבָּת' – מחמת מצוַת השבת, ולשם שמיים, ולא מחמת הרצון למנוחה גופנית גרידא – רק אז תזכה להבטחות האמורות. דבר זה אמור גם ביחס למצוַת עונג שבת הנזכרת בהמשך הפסוק, שאף היא צריכה להיעשות לשם שמיים, כדי להרחיב את הלב בעונג ושמחה ומתוך כך לחוש התרוממות רוחנית. לשון חז\"ל היא: \"המענג את השבת\", ולא: \"המתענג בשבת\" – ללמדך, שעניינה של מצווה זו הוא לעשות את השבת עצמה ליום של עונג ורוממות. 'הַשָׁבַת הרגל' משבת, הנזכרת בפיוט, עשויה להתפרש גם כמתייחסת לאופן ההליכה הנדרש בשבת, כמבואר ב'שולחן ערוך': \"אסור לרוץ בשבת אלא אם כן הוא לדבר מצוה, כגון לבית הכנסת וכיוצא בו. הגהת רמ\"א: ואסור לפסוע יותר מאמה בפסיעה אחת, אם אפשר לו בפחות\". בשבת על האדם לעצור משטף מרוצת החיים, ולהיות במצב של עמידה והתבוננות. קצב הליכה מהיר משפיע על תחושת האדם ומכניס אותו לתודעה של עשייה והתקדמות; לעומת זאת, קצב הליכה איטי ונינוח, משרה על האדם רוגע ושלווה, ומאפשר לו להיות נתון במצב של חשיבה והתבוננות. אך הריצה לדבר מצוה מותרת, שכן המצוה עצמה שייכת לעשייה הרוחנית של האדם, והריצה אליה אינה משרה על האדם את התחושה של שטף חיי החול. הערות 345 ישעיהו נח יג-יד 346 תלמוד בבלי, שבת קיח.-קיח: 347 אורח חיים, סימן שא, סעיף א"],[9,"s8","זָכוֹר וְשָׁמוֹר מְקַיֶּמֶת בַּשַּׁבָּת","– בעשר הדיברות שבפרשת יתרו כתוב: \"זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\" (שמות כ ח), ובאלו שבפרשת ואתחנן כתוב: \"שָׁמוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\" (דברים ו יב) – ואמרו חז\"ל שבפועל שתי המילים נאמרו במקביל: \"זכור ושמור בדיבור אחד נאמרו\". לכל אחד מהציווים משמעות שונה: 'זָכוֹר' – להזכיר את יום השבת על ידי אמירת הקידוש, ו'שָׁמוֹר' – להישמר בו מעשיית מלאכה. במדרש ה'מכילתא' למדו דין נוסף מפסוקים אלו: \"זָכוֹר וְשָׁמוֹר\" – 'זָכוֹר' מלפניו ו'שָׁמוֹר' מלאחריו. מכאן אמרו: מוסיפין מחול על הקודש. כוונת המדרש היא למצות 'תוספת שבת': על האדם לומר בפיו זמן מה לפני כניסת השבת בשקיעת החמה, שהוא מקבל עליו את קדושת השבת, ולהימנע מאז מעשיית מלאכה; דין זה נלמד מ'זָכוֹר' – על האדם לזכור את בואה של השבת ולקבלה עליו קודם כניסתה. כמו כן, ישנו חיוב להוסיף על השבת ביציאתה, דהיינו להמשיך לשבות ממלאכה זמן מה לאחר צאת השבת; דין זה נלמד מ'שָׁמוֹר' – על האדם לשמור (=לחכות) ולהמתין בשביתה ממלאכה עד לאחר הזמן שעליו להוסיף ליום השבת. קדושת השבת היא כה עוצמתית עד שהיא מתפשטת גם לזמן שלפניה ולאחריה, וכפי שמבטא זאת המדרש בהמשך דבריו: \"משל לזאב שהוא טורף מלפניו ומלאחריו\". הערות 348 תלמוד בבלי, ראש השנה כז. 349 שם, ברכות כ:, שבועות כ: 350 יתרו, פרשת בחודש, פרשה ז 351 ראה שולחן ערוך אורח חיים, סימן רסא, סעיף ב, וסימן רצג, סעיף ב, ובמשנה ברורה שם 352 כמו: \"וְאָבִיו שָׁמַר אֶת הַדָּבָר\" (בראשית לז יא). 353 על פי פירוש 'ברכת הנצי\"ב' על אתר"],[9,"s9","חָשָׁה לְמַהֵר בִּיאַת שַׁבָּת","– כמבואר לעיל, ישנו הבדל בין 'מהר' לבין 'חוש': המהירות היא הקדמת הפעולה, וההחשה היא ביצוע הפעולה עצמה בזריזות. עם ישראל מזדרז בהכנותיו לשבת, כדי שיוכל להקדים את כניסתה ולקיים בכך את דין 'תוספת שבת', כמבואר בשורה הקודמת. הערות 354 עמ' 94"],[9,"s10","טוֹרַחַת כֹּל מִשִּׁשָּׁה לַשַּׁבָּת","– טורחת ומכינה את כל צורכי השבת בששת ימי השבוע, כמו שמסופר על שמאי הזקן: \"כל ימיו היה אוכל לכבוד שבת: מצא בהמה נאה, אומר: זו לשבת. מצא אחרת נאה הימנה, מניח את השנייה ואוכל את הראשונה\"; ו\"לא היה זכרון השבת זז מתוך פיו: לקח חפץ טוב, אמר: זה לשבת; כלי חדש, אמר: זה לשבת\". הערות 355 תלמוד בבלי, ביצה טז.. בהמשך הגמרא שם נאמר: \"אבל הלל הזקן מדה אחרת היתה לו, שכל מעשיו לשם שמים\", ופירש רש\"י שלא היה שומר את המציאה לשבת, כיוון שהיה בוטח בקב\"ה שיזמן לו אחרת נאה הימנה. אף על פי שבדרך כלל ההלכה היא כבית הלל, כאן נקט הפייטן כדעת בית שמאי, משום שסבר שגם לדעת בית הלל טוב יותר לנהוג בזה כבית שמאי, אלא שאין חיוב בכך; וכך כתב ה'אור זרוע' (הלכות שבת, סימן יח, אות ג): \"הלכך, הרוצה לעשות כבית שמאי – עושה, דבית הלל מודים לבית שמאי דהכי עדיף טפי\". כדעה זו משמע גם ב'טור' (סוף סימן רמב), וכך פסק גם הב\"ח (שם), והובאו דבריהם בט\"ז (שם, סוף ס\"ק א), ובמגן אברהם (סימן רנ ס\"ק א). זאת, בניגוד לדעת רמב\"ן (שמות כ ח), שפסק כבית הלל. 356 מכילתא דרשב\"י, פרק כ, פסוק ח"],[9,"s11","יוֹשֶׁבֶת וּמַמְתֶּנֶת עַד כְּלוֹת שַׁבָּת","– יושבת וממתינה מלעשות מלאכה עד שתכלה השבת כולה, לרבות זמן תוספת השבת שצריך להוסיף ביציאתה."],[9,"s12","כָּבוֹד וָעֹנֶג קוֹרְאָה לַשַּׁבָּת","– על פי לשון הכתוב: \"וְקָרָאתָ לַשַּׁבָּת ע…!∆ג , לִקְדוֹשׁ ה' ¿מÀכ»בּד \" (ישעיהו נח יג, הובא לעיל במלואו). 'עונג שבת' מתקיים במאכל, במשתה, ובמנוחת הגוף; 'כבוד שבת' מתקיים בלבישת בגדים מיוחדים, עריכת השולחן, הצעת המיטות, וכדומה. הפייטן הקדים 'כָּבוֹד' ל'עֹנֶג' אף על פי שבפסוק הסדר הוא הפוך, משום שדין 'עונג שבת' מתקיים רק ביום השבת עצמו, אך דין 'כבוד שבת' מתקיים כבר בערב השבת, בלבישת בגדי השבת וביצוע שאר ההכנות הנחוצות. הערות 357 ראה שולחן ערוך, אורח חיים, סימן רסב"],[9,"s13","לְבוּשׁ וּכְסוּת מַחְלֶפֶת בַּשַּׁבָּת","– כדברי הגמרא: \"שלא יהא מלבושך של שבת כמלבושך של חול\". 'לבוש' הוא הבגדים הפנימיים, ו'כסות' הוא הבגד העליון, שמכסה גם על שאר הבגדים, ואכן כתבו הפוסקים בשם האר\"י שטוב שלא ילבש האדם בשבת בגדים שלובשם בימות החול, לרבות הלבוש הפנימי. הערות 358 תלמוד בבלי, שבת קיג. 359 ראה מלבי\"ם, איוב כד יז 360 פרי עץ חיים, שער השבת, פרק ד"],[9,"s14","מַאֲכָל וּמִשְׁתֶּה מְכִינָה לַשַּׁבָּת, נֹעַם מְגָדִים מַנְעֶמֶת לַשַּׁבָּת","– מכינה מאכל ומשתה ומיני מתיקה נעימים וערבים לצורך השבת. מושם כאן דגש על עצם פעולת ההכנה: הכנת צרכי השבת אינה רק אמצעי הכרחי כדי שהם יהיו קיימים, אלא בעלת ערך כשלעצמה, מפני שטירחת האדם בהכנות לשבת מבטאת את כבודה ואת חביבותה עליו; וכך כתב ה'שולחן ערוך': ישכים בבוקר ביום שישי להכין צרכי שבת. ואפילו יש לו כמה עבדים לשמשו – ישתדל להכין בעצמו שום דבר לצרכי שבת כדי לכבדו, כי רב חסדא היה מחתך הירק דק דק, ורבה ורב יוסף היו מבקעים עצים, ורבי זירא היה מדליק האש, ורב נחמן היה מתקן [=מסדר] הבית ומכניס כלים הצריכים לשבת ומפנה כלי החול. ומהם ילמד כל אדם, ולא יאמר: \"לא אפגום כבודי\", כי זה הוא כבודו – שמכבד את השבת. הערות 361 אורח חיים, סימן רנ, סעיף א"],[9,"s15","סְעוּדוֹת שָׁלשׁ מְקַיֶּמֶת בַּשַּׁבָּת","– חיוב אכילת שלוש סעודות בשבת נלמד מהכתוב לגבי המן: \"וַיֹּאמֶר מֹשֶׁה אִכְלֻהוּ היּוֹם , כִּי שַׁבָּת היּוֹם , לַה', היּוֹם לֹא תִמְצָאֻהוּ בַּשָּׂדֶה\" (שמות טז כה) – מהחזרה המשולשת על המילה 'היום', דורשת הגמרא שישנו חיוב לאכול בשבת שלוש סעודות, כאילו כתוב: \"אכלוהו היום\", ושוב \"[אכלוהו] היום\", ושוב \"[אכלוהו] היום\". בהמשך הסוגיה שם נאמר: \"כל המקיים שלוש סעודות בשבת ניצול משלוש פורענויות: מחבלו של משיח, ומדינה של גיהנם, וממלחמת גוג ומגוג\". אנו מתפללים שבזכות קיומנו את שלוש סעודות השבת, נזכה להיוושע, בפרט מדברים אלו. הערות 362 תלמוד בבלי, שבת קיז:"],[9,"s16","עַל שְׁתֵּי כִכָּרוֹת בּוֹצַעַת בַּשַּׁבָּת","– דין זה הוא זכר למן, עליו נאמר: \"וַיְהִי בַּיּוֹם הַשִּׁשִּׁי לָקְטוּ לֶחֶם מִשְׁנֶה, שְׁנֵי הָעֹמֶר לָאֶחָד\" (שם טז כב); אחד מהניסים שאירעו בירידת המן הוא שביום השישי ירדה כמות מן כפולה, וביום השבת לא ירד כלל, כמפורש בפסוקים שם, וזכר לנס זה בוצעים בכל אחת מסעודות השבת על שני כיכרות. רבי נתן מברסלב מסביר את הזיקה המהותית שבין המן לבין סעודות השבת: שלוש סעודות של שבת הן בחינת התגלות הרצון, כי שלוש סעודות הן נלמדות מפסוק \"אִכְלֻהוּ הַיּוֹם\" וגו' הנאמר במן. נמצא שאכילת שבת הוא זכר למן, שמשם אנו למדין השלוש סעודות. וכמבואר ב'שולחן ערוך' שראוי לעשות בסעודות שבת זכר למן, כגון לאכול מולייתא, וכן הפת בין שתי מפות כמו המן. נמצא, כשאנו אוכלין בשבת – אנו מעידין שאכלו ישראל את המן, שהיו בו אותות נוראות, שירד בששת ימים ובשבת לא ירד. ועל כן, על ידי אכילת שבת נתגלה הרצון – שהכול ברצונו יתברך , כי עיקר קדושת שבת הוא האכילה של שבת [...] ושבת הוא התגלות הרצון, כי שבת מורה על חידוש העולם, שה' יתברך ברא את העולם כרצונו [...] כי על ידי ביטול מלאכה לבד, אין ניכר כבוד שבת כל כך על ידי 'שב ואל תעשה', [אלא] רק על ידי כבוד שבת, דהיינו שלוש סעודות [...]. השבת והמן נושאים מסר משותף: המן, בכך שירד רק בימות החול ולא בשבת, מעיד על כך שהקב\"ה שולט על העולם ומנהיגו כרצונו. לסעודות השבת ישנם דינים שנועדו ליצור דמיון ביניהן לבין המן, כדי שעל ידן ניזכר במן ובמסר שהוא מביע בכך שירד במיוחד לצורך עם ישראל, ובפרט בכך שלא ירד בשבת: השגחת ה' על העולם. זהו גם המסר של השבת: \"בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִוא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ\" (שמות לא יז). מתוך שביתתנו ביום השבת, אנו זוכרים את שביתת הקב\"ה ביום השביעי לבריאה, ומחזקים אמונתנו בכך שהקב\"ה ברא את העולם ומנהיגו כרצונו. המלבי\"ם מסביר שזכירת שביתת הקב\"ה ביום השביעי מחזקת את האמונה בהשגחתו על העולם, משום שבששת ימי המעשה נבראה מערכת הטבע, הפועלת על פי סדריה ללא קשר למעשי בני האדם, ובשבת – על ידי עצם השביתה בה – נבראה מערכת ההשגחה הניסית. מערכת זו, היא המשנה את מערכת הטבע ויכולה להשבית אותה ולשנותה בהתאם למעשי בני האדם. למשל, אף בזמן שבני האדם אינם זכאים לגשמים מכוח מעשיהם – מערכת הטבע עשויה להוריד גשמים כמנהגה, בזמנים המיועדים לכך; אך מערכת ההשגחה הניסית משביתה אותה מפעולתה ומונעת את הגשמים, כמאמר הכתוב: \"וְחָרָה אַף ה' בָּכֶם, וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר\" (דברים יא יז). משום כך, גם המזמור 'מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת' (תהילים צב) עוסק בעניין השגחת הקב\"ה על עולמו, ענישת הרשעים ומתן השכר לצדיקים. הערות 363 תלמוד בבלי, ברכות לט:, שבת קיז: 364 רבי נתן שטרנהרץ (תק\"מ-תר\"ה), תלמידו של רבי נחמן מברסלב וכותב תורותיו. פעל בנמירוב ובברסלב שבאוקראינה, והנהיג את חסידות ברסלב לאחר פטירת רבו. 365 כוונתו למובא בסימן רמב בהגהת רמ\"א: \"יש שכתבו שבמקצת מקומות נהגו לאכול מולייתא שקורין פשטידה בליל שבת, זכר למן שהיה מכוסה מלמעלה ומלמטה\" (-\"בטָל, ואף זה מכוסה בשר בין דפי העיסה\" – משנה ברורה שם). 366 ליקוטי הלכות, אורח חיים, שבת ב 367 בראשית ב א 368 מלבי\"ם על תהילים שם"],[9,"s17","פּוֹרֶטֶת אַרְבַּע רְשׁוּיוֹת בַּשַּׁבָּת","– מפרטת בדיני הוצאה מרשות לרשות האסורה בשבת, ארבעה סוגי רשויות שהעברת חפץ מאחת מהן לחברתה עשויה להיות אסורה: רשות היחיד, רשות הרבים, כרמלית, ומקום פטוֹר. רשות היחיד – מקום הרחב לפחות ארבעה על ארבעה טפחים, וגבוה עשרה טפחים או מוקף מחיצות בגובה זה. רשות הרבים – דרך העשויה להילוך הרבים, ורוחבה הוא שש עשרה אמה או יותר. העברת חפץ מרשות היחיד לרשות הרבים או להיפך – אסורה מן התורה. כרמלית – מקום שאינו מוקף מחיצות ואינו עשוי להילוך הרבים, כגון ים או מדבר. מן התורה אין איסור בהעברת חפץ מרשות אחרת לכרמלית או להיפך, אך מפני דמיונה לרשות הרבים, תיקנו חכמים שדינה יהא כרשות הרבים, ואסרו להעביר חפץ ממנה לרשות היחיד או להיפך, וכן לטלטל חפץ ארבע אמות בתוכה. מקום פטוֹר – מקום ברשות הרבים שאין בשטחו ארבעה על ארבעה טפחים, וגבוה מקרקעה שלושה טפחים או שהוא מוקף מחיצות, וכן אויר של כרמלית ושל רשות הרבים מעל גובה עשרה טפחים מהקרקע. ההעברה ממקום פטור לרשות אחרת או להיפך, וכן הטלטול בתוכו ארבע אמות (כגון במקרה ששטחו ארוך מארבע אמות ורחב פחות מארבעה טפחים) – מותרים. מבין שלושים ותשע המלאכות האסורות בשבת, הפייטן מזכיר רק את מלאכת ההוצאה (בשורה זו, ובשורות ד,ה,ו), הכוללת את איסור ההוצאה מרשות לרשות, טלטול ברשות הרבים, ויציאה מחוץ לתחום; גם בפיוט זה וגם בפיוט שלאחריו, מלאכה זו זוכה למקום בולט במיוחד. בטעם הדבר ניתן להסביר, שמלאכה זו – דווקא משום שאינה מלאכה ממשית, שהרי אין בה יצירה כל שהיא – מבטאת את גודל קדושתה של השבת. אילו השבת היתה רק זכר לכך שהקב\"ה שבת ממלאכה ביום השביעי, אכן לא היה מקום לאסור מלאכה זו. רק מחמת קדושת השבת, המחייבת מנוחה שלימה מצד האדם, נאסרה אף היא; דבר זה מלמד על כל שאר המלאכות, שאף איסורן אינו רק 'זכר', אלא ביטוי לקדושתה המוחלטת של השבת. ניתן לבאר זאת באופן נוסף, על פי הסברו של רש\"ר הירש למלאכת ההוצאה וליחס שבינה לבין שאר המלאכות האסורות בשבת: אם נתבונן בסוגי המלאכות האלה, הרי מתברר שכולן פעולות יצרניות, כלומר: פעולות המביאות שינוי ממשי בדבר מסוייים. ביצירה מכוונת של שינוי זה מתגלה שלטון האדם על כל דבר גשמי, וההימנעות מיצירה זו ביום השבת עשויה, איפוא, לגלות את ההשתעבדות תחת עול הבורא והריבון האחד והיחיד, שהאדם השולט בעולמו אינו אלא ואסאל שלו הכפוף לו והעובד אותו. אפילו לֶקֶט פירות מהארץ וצֵיד חיות בר, אם כי אינם מביאים שינוי בפרי ובחיה עצמם, הרי תוצאתם היא מַעֲבָר ממצב טבעי וחופשי אל תחום שלטונו וחזקתו של האדם, ודבר זה הוא עיקר מהותו ומשמעותו של מושג המלאכה, כפי שהסברנו. כל מלאכות השבת – מלבד מלאכת ההוצאה – מבטאות את שלטון האדם על הבריאה בפועל; מטרתה של השביתה ממלאכות אלו בשבת היא להזכיר לאדם כי הוא כפוף לקב\"ה, ועל כל פעולותיו להיות מכוונות לקיום רצונו. רק האחרונה מבין ל\"ט המלאכות – הוצאה מרשות לרשות: מרשות היחיד לרשות הרבים ולהיפך, וכן המעביר ארבע אמות ברשות הרבים, 'מלאכה גרועה' היא וקשה לכלול אותה במושג המלאכות היצרניות. מלאכה זו לא היתה נלמדת ממלאכת המשכן אלמלא נדרשה בדרשה מיוחדת, ולא רק לגבי סוג המלאכה בכלל, אלא גם לגבי התולדות הנגררות אחריו. אף על פי כן, דווקא מלאכה זו, שהיא גרועה כל כך בחיצוניותה הממשית – רבה חשיבותה עד כדי כך שירמיהו הנביא, כאשר נצטווה בימי אחרית המדינה היהודית לבשר על דבר ישועתה, אף פריחתה ושגשוגה, בזכות שמירת השבת, תבע – מלבד השמירה הכללית של מצוות השבת – לשמור במיוחד על איסור ההוצאה: כֹּה אָמַר ה' אֵלַי: הָלֹךְ וְעָמַדְתָּ בְּשַׁעַר בְּנֵי עם (קרֵי: הָעָם) אֲשֶׁר יָבֹאוּ בוֹ מַלְכֵי יְהוּדָה וַאֲשֶׁר יֵצְאוּ בוֹ וּבְכֹל שַׁעֲרֵי יְרוּשָׁלָםִ. וְאָמַרְתָּ אֲלֵיהֶם שִׁמְעוּ דְבַר ה' מַלְכֵי יְהוּדָה וְכָל יְהוּדָה וְכֹל יֹשְׁבֵי יְרוּשָׁלָםִ הַבָּאִים בַּשְּׁעָרִים הָאֵלֶּה. כֹּה אָמַר ה': הִשָּׁמְרוּ בְּנַפְשׁוֹתֵיכֶם וְאַל תִּשְׂאוּ מַשָּׂא בְּיוֹם הַשַּׁבָּת וַהֲבֵאתֶם בְּשַׁעֲרֵי יְרוּשָׁלָםִ. וְלֹא תוֹצִיאוּ מַשָּׂא מִבָּתֵּיכֶם בְּיוֹם הַשַּׁבָּת, וְכָל מְלָאכָה לֹא תַעֲשׂוּ, וְקִדַּשְׁתֶּם אֶת יוֹם הַשַּׁבָּת, כַּאֲשֶׁר צִוִּיתִי אֶת אֲבוֹתֵיכֶם. וְלֹא שָׁמְעוּ וְלֹא הִטּוּ אֶת אָזְנָם, וַיַּקְשׁוּ אֶת עָרְפָּם לְבִלְתִּי שומע (קרֵי: שְׁמוֹעַ) וּלְבִלְתִּי קַחַת מוּסָר. וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּן אֵלַי נְאֻם ה' לְבִלְתִּי הָבִיא מַשָּׂא בְּשַׁעֲרֵי הָעִיר הַזֹּאת בְּיוֹם הַשַּׁבָּת, וּלְקַדֵּשׁ אֶת יוֹם הַשַּׁבָּת לְבִלְתִּי עֲשׂוֹת בה (קרֵי: בּוֹ) כָּל מְלָאכָה. וּבָאוּ בְשַׁעֲרֵי הָעִיר הַזֹּאת מְלָכִים וְשָׂרִים יֹשְׁבִים עַל כִּסֵּא דָוִד רֹכְבִים בָּרֶכֶב וּבַסּוּסִים הֵמָּה וְשָׂרֵיהֶם אִישׁ יְהוּדָה וְיֹשְׁבֵי יְרוּשָׁלָםִ, וְיָשְׁבָה הָעִיר הַזֹּאת לְעוֹלָם. וּבָאוּ מֵעָרֵי יְהוּדָה וּמִסְּבִיבוֹת יְרוּשָׁלַםִ וּמֵאֶרֶץ בִּנְיָמִן וּמִן הַשְּׁפֵלָה וּמִן הָהָר וּמִן הַנֶּגֶב מְבִאִים עוֹלָה וְזֶבַח וּמִנְחָה וּלְבוֹנָה וּמְבִאֵי תוֹדָה בֵּית ה'. וְאִם לֹא תִשְׁמְעוּ אֵלַי לְקַדֵּשׁ אֶת יוֹם הַשַּׁבָּת וּלְבִלְתִּי שְׂאֵת מַשָּׂא וּבֹא בְּשַׁעֲרֵי יְרוּשָׁלַםִ בְּיוֹם הַשַּׁבָּת – וְהִצַּתִּי אֵשׁ בִּשְׁעָרֶיהָ, וְאָכְלָה אַרְמְנוֹת יְרוּשָׁלַםִ, וְלֹא תִכְבֶּה. העתקנו כאן את כל דברי הנביא כדי להמחיש את המשקל הגדול שהנביא משווה לאיסור ההוצאה בשבת, ובמיוחד כדי שניווכח שאיסור הוצאה נראה כאן לא כחלק בלתי נפרד מאיסור מלאכה, כי אם כמושג העומד מצידו של איסור מלאכה הכולל. שמירת השבת מקיפה – לדברי הנביא – איסור הוצאה ואיסור מלאכה: \"וְלֹא תוֹצִיאוּ מַשָּׂא מִבָּתֵּיכֶם [...] וְכָל מְלָאכָה לֹא תַעֲשׂוּ\" (פסוק כב). איסור הוצאה מבטא רעיון נפרד, שיחד עם הרעיון שמבטאים איסורי שאר המלאכות, משלים את תמונתה הכללית של מטרת השביתה בשבת. אם נבקש את המושג הכולל את כל שאר המלאכות, הרי כולן מציינות את מעמד השליט של האדם כלפי הדברים שבעולם הגשמי, ואילו עניין ההוצאה הוא אך ורק בתחום החברתי. דומה שאין לתאר את מלוא חיי המדינה תיאור שלם יותר מאשר זה: יחס היחיד אל כלל החברה, יחס כלל החברה אל היחיד, כלומר: תרומת היחיד לטובת הכלל ותרומת הכלל לטובת היחיד, ולבסוף – קידום ענייני החברה בתחום החברה. הרי אלו יחסים הבאים לידי ביטוי קולע בהוצאה ובהכנסה מרשות הרבים לרשות היחיד ומרשות היחיד לרשות הרבים, ובהעברה ארבע אמות ברשות הרבים. לפיכך, אם איסור שאר המלאכות משעבד את האדם לה' במעמדו בעולם הגשמי, הרי נראה שאיסור הוצאה מבטא את שיעבודו של האדם לה' במעמדו בעולם החברה. הראשון הוא ההשתעבדות לה' בטבע, והשני הוא ההשתעבדות בהיסטוריה. הראשון מעמיד תחת ריבונות הבורא את פועַל האדם בטבע, והשני – את פועַל האדם במדינה. כשם שרק הטבע והמדינה ביחד מהווים את המושג 'עולם', כן מצרף המושג של 'ריבונות ה' בעולם' את השגחתו ופקודתו בטבע ובהיסטוריה. מלכות ה' עלי אדמות שעל האדם לקיימה על ידי שמירת השבת, שלימה וממשית רק אם ישתעבד לרצון ה' בחייו הטבעיים והמדיניים כאחד. מלאכות ההוצאה השונות מסמלות את הפעילות החברתית והמדינית. השביתה מהן בשבת, מבטאת את השתעבדותה של החברה ככלל – לקב\"ה. ועתה אפשר לראות גם את שתי העובדות שהתורה מזכירה אותן כטעמים של מצוות השבת – בריאת שמיים וארץ, ויציאת מצרים – כעובדות המשלימות זו את זו במשמעותן העיקרית. בריאת העולם היא העובדה המעידה על ריבונות הבורא בטבע, ודבר זה בא לידי ביטוי בכל שאר המלאכות. יציאת מצרים היא העובדה המעידה על ריבונות הבורא בחיי המדינות, ודבר זה בא לידי ביטוי באיסור הוצאה. איסור הוצאה מעמיד, איפוא, את המדינה היהודית: את מעשי היחיד בישראל לטובת הכלל, את מעשי הכלל לטובת היחיד, וכן את מעשי המושלים בתחום המדינה – תחת ריבונות הבורא התובע ציות. מכאן אנו מבינים מדוע דברי הנביא שהבאנו למעלה, מתנים את קיום המדינה בראש ובראשונה בשמירת השבת על ידי איסור הוצאה, ומבשרים את חורבן המדינה בגלל חילול השבת על ידי הוצאה. איסור הוצאה מטביע את חותם ה' על כל חיי המדינה, והוצאה ביום השבת קורעת 'פרוטומה של מלך' מעל פני המדינה ומעל פני חיי החברה במדינה. לאור דברים אלו ניתן להסביר, שעם בקשתנו לישועה ולהשבת סדרינו הלאומיים על כנם, אנו מזכירים את זכותנו בהימנעות ממלאכות ההוצאה, ובמשמעות העומדת מאחוריהן – שיעבודנו לקב\"ה כאומה, והתמסרותנו לקיום רצונו גם במישור הציבורי. הערות 369 משנה תורה לרמב\"ם, הלכות שבת, פרק יד 370 הליכות יצחק, פתיחה למסכת עירובין (לרבי יצחק ירוחם בורודיאנסקי, משגיח רוחני בישיבת 'קול תורה' וראש כולל 'ישיבת הר\"ן' בירושלים). 371 רבי שמשון רפאל הירש (תקס\"ח-תרמ\"ט), מנהיג הזרם הניאו-אורתודוכסי בגרמניה. חיבר בין היתר פירוש לחומש ולספר תהילים, ואת הספר 'חורב' על טעמי המצוות. 372 איכר צמית המשועבד לבעל האחוזה 373 פירוש על התורה, שמות לה ב 374 על פי לשון ה'תוספות', שבת ב. ד\"ה פשט 375 ירמיהו יז יט-כז 376 שם 377 שם 378 פסל-דיוקן 379 שם"],[9,"s18","צִוּוּי הַדְלָקַת נֵר מַדְלֶקֶת בַּשַּׁבָּת","–כדברי הגמרא: \"הדלקת נר בשבת – חובה\". בעל השל\"ה מבאר שבריאת האור הקדום ביום הראשון של הבריאה – \"וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, וַיְהִי אוֹר\" (בראשית א ג) – כוללת בתוכה את כל הדברים שנבראו לאחר מכן, וכולם כלולים באותו אור; בשאר ימי הבריאה הדברים רק יצאו אל הפועל באופן סופי וקיבלו את צורתם המוגמרת. בדומה לזה כתב רש\"י: \"וכן כל תולדות שמיים וארץ נבראו ביום ראשון, וכל אחד ואחד נקבע ביום שנגזר עליו\". על פי זה מסביר השל\"ה, שנר השבת רומז לאותו אור קדום, הכולל את כל הבריאה; בכניסתה של השבת, שהיא עדות ואות על בריאת העולם, אנו מציינים זאת על ידי הדלקתו. הערות 380 תלמוד בבלי, שבת כה: 381 רבי ישעיהו הלוי הורביץ (שי\"ח-ש\"צ), פוסק ומקובל, כיהן כרב בערים שונות בפולין ובליטא, ובעשור האחרון לחייו עלה לארץ וקבע את מושבו בירושלים, לאחר מכן בצפת, ובשנותיו האחרונות בטבריה. ספרו 'שני לוחות הברית' (של\"ה) עוסק בפרשנות התורה, בהלכה, בקבלה, ובמוסר. 382 בראשית א יד 383 של\"ה, מסכת שבת, פרק תורה אור, דף קלו:-קלז:"],[9,"s19","קִדּוּשׁ הַיּוֹם מְקַדֶּשֶׁת בַּשַּׁבָּת","– מצוַת קידוש יום השבת נלמדת מהכתוב: \"זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\" (שמות כ ח), ודרשו חז\"ל בברייתא: \"זוכרהו על היין\". באמירת הקידוש אנו מעידים על בריאת העולם, בפרשת 'וַיְכֻלּוּ', ומצהירים על היות השבת 'זִכָּרוֹן לְמַעֲשֶׂה בְרֵאשִׁית' ו'זֵכֶר לִיצִיאַת מִצְרָיִם'. בכך אנו מממשים את מטרתה של השבת, שהיא להוות עדות על חידוש העולם ועל יציאת מצרים, כך שמתוך קיומה – עם ישראל לדורותיו יזכור יסודות אמונה אלו: חידוש העולם, כמו שכתוב: \"בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִוא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ\" (שמות לא יז), ויציאת מצרים, כמו שכתוב: \"וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּאֶרֶץ מִצְרַיִם וַיֹּצִאֲךָ ה' אֱלֹהֶיךָ מִשָּׁם בְּיָד חֲזָקָה וּבִזְרֹעַ נְטוּיָה, עַל כֵּן צִוְּךָ ה' אֱלֹהֶיךָ לַעֲשׂוֹת אֶת יוֹם הַשַּׁבָּת\" (דברים ה טו). בעדותה של השבת על מציאות ה' ועל חידוש העולם, הרי היא מקדמת את מטרת הבריאה, שהיא הכרת הברואים את בוראם; אם הם שוכחים זאת או שאינם מכירים בכך, הרי שמטרה זו מוחטאת. כשאנו מעידים בפינו על בריאת העולם – אנו משתתפים עם השבת בעדות זו, ובכך מממשים את אותה מטרה. על ידי כן נעשים אנו, כביכול, שותפים לקב\"ה במעשה בראשית; על כך נאמר בגמרא: אמר רב המנונא: כל המתפלל בערב שבת ואומר 'וַיְכֻלּוּ' – מעלה עליו הכתוב כאילו נעשה שותף לקב''ה במעשה בראשית, שנאמר 'וַיְכֻלּוּ' – אל תקרֵי: 'וַיְכֻלּוּ', אלא: 'וַיְכַלּוּ' [הקב''ה, וזה שמספר בשבחו של מקום ובשבח של שבת – רש\"י]. תפקיד השלמת מעשה הבריאה מוטל על בני האדם; על ידי הכרתם את הקב\"ה באמצעות הופעתו בפרטי הבריאה, ועבודתם אותו – הרי הם מכלים ומשלימים את בריאת העולם, בכך שמממשים את מטרתה. הערות 384 תלמוד בבלי, פסחים קו. 385 תלמוד בבלי, שבת קיט:"],[9,"s20","רֶנֶן שֶׁבַע מְפַלֶּלֶת בַּשַּׁבָּת","– מתפללת בתפילת העמידה של שבת, שבע ברכות שהן רננות ושבחים, ולא בקשות. בשבת על האדם להסיח את דעתו מטרדותיו ומצרכיו הגשמיים, להתעלות מעל רובד החומר בו הוא עסוק במשך השבוע, ולהתמקד בצד הרוחני של חייו. משום כך, תפילת העמידה בשבת אינה כוללת את ברכות הבקשה השגרתיות של ימות החול, וכל הברכות עוסקות בשבח לקב\"ה; אף הבקשות שבסוף הברכה האמצעית, אינן מתייחסות לצרכים גשמיים אלא לשאיפות רוחניות: \"רְצֵה נָא בִּמְנוּחָתֵנוּ, קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ, וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ, שַׂבְּעֵנוּ מִטּוּבָךָ, וְשַׂמֵּחַ נַפְשֵׁנוּ בִּישׁוּעָתֶךָ, וְטַהֵר לִבֵּנוּ לְעָבְדֶּךָ בֶּאֱמֶת\"."],[9,"s21","שִׁבְעָה בַדָּת קוֹרְאָה בַשַּׁבָּת","– קוראת בתורה, הקרויה 'דָּת', את פרשת השבוע עם שבעה עולים. תקנת קריאת התורה בשבת נקבעה על ידי משה רבינו, וקריאתה על ידי שבעה עולים היא תקנת חז\"ל. מספר זה של העולים לתורה הוא הגדול ביותר מבין הימים בהם קוראים בתורה; דבר זה מבטא את מעלתה של קדושת השבת על פני קדושת שאר המועדים, שכן מספר העולים נתקן בהתאם למעלתו של היום. הערות 386 ראה לעיל עמ' 51 387 משנה תורה לרמב\"ם, הלכות תפילה, פרק יב, הלכה א, על פי תלמוד בבלי, בבא קמא פב. ותלמוד ירושלמי, מגילה, פרק ד, הלכה א 388 תלמוד בבלי, מגילה כב:"],[9,"s22","תַּנְחִילֶנָּה יוֹם שֶׁכֻּלּוֹ שַׁבָּת","– בקשה זו מבוססת על לשון המשנה בסוף מסכת תמיד (הנאמרת בנוסח האשכנזים לאחר סדר פיטום הקטורת במוסף של שבת), המפרטת את המזמורים שהיו נאמרים על ידי הלווים במקדש בכל אחד מימי השבוע: \"[...] בשבת היו אומרים: 'מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת' – מזמור שיר לעתיד לבוא, ליום שכולו שבת ומנוחה לחיי העולמים\". המשנה מסבירה כי 'יוֹם הַשַּׁבָּת' האמור במזמור הוא המציאות העתידית, שבה העולם יגיע לשלמותו הרוחנית וכולו יהיה קודש לערכים אלוהיים, בדומה ליום השבת, שעניינו הוא שביתה מחיי החולין ועיסוק בענייני הרוח; אז יאבדו כל אויבי ה' והצדיקים יפרחו וישגשגו, כמתואר באותו מזמור (תהילים צב). בסיום פיוט זה, המתאר את שמירת עם ישראל על קיום דיני השבת, שהיא מעין התגלות בזעיר אנפין של אותה מציאות נעלית, בתוך המציאות ההווית – אנו מוסיפים בקשה זו, בה אנו מבקשים שהאומה תזכה במהרה להגיע לאותה מציאות עתידית, ושבניה יהיו זכאים וראויים לחיות בו."],[9,"s23","סיכום","הציר המרכזי של הפיוט הוא תיאור הקפדת עם ישראל על שמירת דיני השבת: ההכנות לקראתה, לימוד הלכותיה, הימנעות מעשיית מלאכות, עינוגה, וכיבודה. אנו מתפללים שבזכות זאת נזכה לישועה במהרה. לשמירת השבת סגולה מיוחדת לקרב את הגאולה, כדברי הגמרא: אמר רבי יוחנן משום רבי שמעון בן יוחאי: אלמלי משמרין ישראל שתי שבתות כהלכתן – מיד נגאלים שנאמר: \"כִּי כֹה אָמַר ה' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי\" וגו', וכתיב בתריה [=וכתוב אחריו]: \"וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי [וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי, עוֹלֹתֵיהֶם וְזִבְחֵיהֶם לְרָצוֹן עַל מִזְבְּחִי, כִּי בֵיתִי בֵּית תְּפִלָּה יִקָּרֵא לְכָל הָעַמִּים]\" (ישעיה נו ד,ז). כפי שראינו, השבת היא הלב הרוחני של השבוע כולו, המשפיעה מאורה על האדם גם במשך ימי המעשה, ומכוונת את חייו לכיוון הנכון. לפיכך, כשישראל שומרים את השבת כהלכתה, הרי שכל חייהם ופעלם מתעלים, והם מתקרבים יותר למצב בו הם יהיו מתאימים ברמתם הרוחנית למציאות המרוממת שתהיה בעת הגאולה; על ידי כך, מכשירים הם את ביאתה. הערות 389 תלמוד בבלי, שבת קיח:"],[9,"n331","הערה 331","פירוש 'אערוך שועי' על ההושענות"],[9,"n332","הערה 332","ח\"א, דף מח. בתרגום מארמית"],[10,"main","","אודה ה' בכל לבב, על שזיכני להיות מיושבי בית המדרש, ולהוציא לאור עולם חיבור זה; אודה על שעבר, ואתפלל על העתיד לבוא – יהי רצון שספר זה יממש את מטרתו, ויפתח לקוראים צוהר לעומק המופלא הגנוז בתפילות ה'הושענות'. במשך למעלה מאלף שנים, נוהגים יהודי קהילות אשכנז מדי שנה בשנה, במעמד המיוחד והמרומם של ההקפות בחג הסוכות, לומר פיוטי הושענות אלו, שחוברו על ידי גדול הפייטנים רבי אלעזר הקליר. בשונה מההושענות הנהוגות בקרב עדות המזרח, המנוסחות בשפה קלה ונוחה להבנה, הרי שבהושענות הקליריות רב הנסתר על הנגלה, ופעמים שאף הרובד הבסיסי של פירוש התיבות אינו נהיר למתפלל. באשר נשמתה של התפילה היא הכוונה, הרי שבהעדר הבנה בהירה של נוסח הפיוטים הנאמרים - העיקר חסר מן הספר. אף על פי שכבר נכתבו מספר פירושים על ההושענות על ידי רבותינו הראשונים והאחרונים, נראה כי התעורר צורך בפירוש המנוסח בלשון עכשווית, וערוך בצורה נוחה ונגישה. ספר זה נועד להוות מענה לכך, ועל גבי זאת גם להרחיב ולהעמיק, בפרט על ידי התחקות אחר המקורות שמהם שאב הפייטן את הביטויים המשובצים בהושענות, אם במקרא ואם בדברי חז\"ל; מתוך בחינת המקורות והתבוננות בהם, ניתן לחשוף את הכוונות הנסתרות והמשמעויות העמוקות הטמונות בפיוט עצמו. בכתיבת הפירוש עמדו לנגד עיניי מספר מטרות: ראשית כל, כאמור, לפרש את נוסח הפיוטים באופן עקבי ורציף ובלשון קלה ומובנת, למען ירוץ קורא בו. המטרה השנייה היא לזהות את הרעיון העומד בבסיס מבנה הפיוט, ואת חוט השני המקשר את חרוזיו זה לזה; מתוך כך ניתן לראות כיצד קיימת התפתחות לאורך הפיוט, שלב אחר שלב, נדבך על גבי נדבך. המטרה השלישית היא, להדגיש את האופנים בהם המתפלל עצמו יכול להתעלות ולהעצים את אישיותו מתוך תפילות אלו. זאת, בהתאם לדברי בעלי המחשבה לדורותיהם שהסבירו - כל אחד בסגנונו הוא - כי מטרת התפילה היא העלאת מדרגתו הרוחנית של המתפלל וזיכוך רצונותיו, ומתוך כך תפילתו פועלת את פעולתה ומזכה אותו בקבלת משאלותיו. כך תפילות מיוחדות אלה שיועדו לחג הסוכות - ממשיכות את ההתעלות וההשתפרות האישית שנעשו במהלך ימי התשובה, ומהוות בסיס רוחני איתן לעבודת ה' במשך השנה כולה. המטרה הרביעית היא, מעבר לעיסוק בשאלת ה'מה כתוב', לעסוק גם בשאלת ה'למה כתוב', הווי אומר: מדוע בחר הפייטן להשתמש דווקא באותם ביטויים אותם שיבץ בפיוט, מדוע הדברים סודרו דווקא באופן כזה ולא אחר, ועוד כהנה וכהנה שאלות ודקדוקים; מתוך כך, נחשפים ועולים רבדים עמוקים הגנוזים בפיוט, המתפרשׂים על פני תחומים רבים ומגוונים, ומאירים אותם באור חדש: יסודות האמונה היהודית, אורחות עבודת ה' הפרטית, משמעות חיי האדם והעולם הסובב אותו, התפקיד הרוחני של עם ישראל ושל המדרגות שתחתיו – הדומם, הצומח, החי, והמדבר, מטרת הבריאה, ותיקון העולם. מעל כל אלו, לאורך כל ההושענות ניצבות לנגד עינינו הכמיהה לגאולתו השלימה של עם ישראל, והציפייה לתיקון העולם במלכות שדי; ההתבוננות בשורות המתייחסות לכך חושפת טפח ממשמעותה ואופייה המופלאים של אותה מציאות עתידית לה אנו מייחלים. נושאים אלה מוסברים בליווי מובאות מן המקרא, התלמוד, והמדרשים, מדברי גדולי החסידות ובעלי המוסר, ומרעיונותיהם של גדולי האמונה והמחשבה, השופכות אור על אותם נושאים ומבהירות את עומק משמעותם. תודתי העמוקה נתונה להורַי היקרים, אאמו\"ר הרב פנחס שליט\"א ומרת רחל שתחי', ולסבַי וסבתותי היקרים, הרב פרופ' אהרון ומרת איילה מונדשיין הי\"ו, פרופ' ר' מנחם ומרת נעמי נהיר הי\"ו; על הטובות הרבות מספור שגמלוני בכל צעד ושעל, בגשמיות וברוחניות, ובפרט על הסיוע בהוצאת ספר זה. יהי רצון שיזכו לרוות נחת מכל צאצאיהם, לראות בנים ובני בנים, שִׁלֵּשִים וְרִבֵּעִים, עוסקים בתורה ובמצוות, מתוך בריאות איתנה ונהורא מעליא, בכל אשר יפנו ישכילו, וְחֵפֶץ ה' בידם יצלח. כמו כן תודתי נתונה לכל המסייעים במלאכה: לסבַי היקרים על שהקדישו מזמנם לקרוא את הפירוש, והעירו הערות והארות רבות וחשובות ששובצו בגוף הדברים; לר' משה קפלן הי\"ו על העימוד הנאה; ולר' נתנאל ומרת רחל וייס על העיצוב המושקע של הכריכה והשערים; ברך ה' חילם ופועל ידם תרצה. כצאתי את העיר אפרוש כפי אל ה', שהדברים שבספר זה יהיו לברכה לחפצים ללמוד את פיוטי ההושענות, ומתוך כך לשאת תפילות אלו על שפתותיהם מתוך עומק רגשי קודש, ערגה וכיסופים; ויהי רצון שנזכה להיכתב ולהחתם לחיים טובים ולשלום בתוך כל בית ישראל, לראות בבניין אריאל, לשיר על גאולתנו שיר חדש, וליטול לולב כל שבעה במקדש. אלול תשע\"ו, ירושלים עיה\"ק תובב\"א שלמה מונדשיין"],[10,"n1","הערה 1","ראה להלן במבוא (עמ' 27-26), שם הארכנו על פי דברי גדולי הדורות בעניין חשיבותם ועומקם של פיוטי רבי אלעזר הקליר."],[11,"main","","מנהג ההקפות, בו המתפללים מקיפים את הבימה בבית הכנסת, כשבידיהם ארבעת המינים, ונושאים תפילות על הישועה – מנהג קדום הוא, שנהג בכל תפוצות ישראל. אף כי לא נזכר בתלמוד שבידינו, מופיע הוא כבר בספרות הגאונים, וכן במדרש 'ילקוט שמעוני': \"אֶרְחַץ בְּנִקָּיוֹן כַּפָּי, וַאֲסֹבְבָה אֶת מִזְבַּחֲךָ ה'\" (תהילים כו ו) - כדתנינן: \"בכל יום היו מקיפין את המזבח פעם אחת\". וכיצד הוא סדר ההקפה? כל ישראל, גדולים וקטנים, נוטלים את לולביהם בידיהם הימנית, ואתרוגיהם בידיהם השמאלית, ומקיפין פעם אחת. ואותו היום [=הושענא רבה] היו מקיפין שבע פעמים. אמר רבי חייא: זכר ליריחו. הא תינח [=דבר זה אפשרי] בזמן שיש מזבח; בזמן הזה - חזן הכנסת עומד כמלאך האלוהים, וספר תורה בזרועו, והעם מקיפין אותו דוגמת מזבח. על פי המדרש, מנהג זה נתקן כזכר, או כהמשך, למנהג ההקפות סביב המזבח שהתקיים בזמן המקדש. וכך מתארת המשנה הקפות אלו: בכל יום מקיפין את המזבח פעם אחת, ואומרים: \"אָנָּא ה' הוֹשִׁיעָה נָּא, אָנָּא ה' הַצְלִיחָה נָא\" (תהילים קיח כה). רבי יהודה אומר: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\". ואותו היום [=הושענא רבה] מקיפין את המזבח שבע פעמים. אך מהו יסוד מנהג ההקפות בבית המקדש? התשובה שמביא המדרש בשם רבי חייא היא: \"זכר ליריחו\". בכיבוש העיר יריחו בזמן הכניסה לארץ, הקיפו ישראל - על פי ציווי ה' - את חומת יריחו במשך שבעה ימים, כשבששת הימים הראשונים הקיפוה פעם אחת, וביום השביעי – שבע פעמים. בתום ההקפה האחרונה ביום השביעי נפלה החומה, וכך התאפשר כיבוש העיר. רבינו בחיי מסביר את הקשר בין אותן הקפות לבין ההקפות שנעשו במקדש כזכר להן: וידוע כי [...] שבעים פרים [שמקריבים בסוכות] - כנגד שבעים אומות עכו\"ם, שיהיו מתמעטים והולכים, והנה ההקפה לרמוז להם כלייה והכרתה מן העולם. רֶמז לַדָבר: יריחו, וכן אמר שבכל יום ויום היו מקיפין את העיר פעם אחת, וכתיב: \"וַיְהִי בַּיּוֹם הַשְּׁבִיעִי, וַיַּשְׁכִּמוּ כַּעֲלוֹת הַשַּׁחַר וַיָּסֹבּוּ אֶת הָעִיר כַּמִּשְׁפָּט הַזֶּה שֶׁבַע פְּעָמִים, רַק בַּיּוֹם הַהוּא סָבְבוּ אֶת הָעִיר שֶׁבַע פְּעָמִים ... וַיָּרִיעוּ הָעָם תְּרוּעָה גְדוֹלָה, וַתִּפֹּל הַחוֹמָה תַּחְתֶּיהָ\" (יהושע ו טו,כ). ובזמן שהיה בית המקדש קיים, היו מקיפין את המזבח בכל יום פעם אחת, ובשביעי שבע פעמים. [...] נמצאת למד, שההקפה שהיו ישראל מקיפים את יריחו בכל יום פעם אחת ובשביעי שבע פעמים - הכול היה רמז לשכינה שהיא כלולה משש קצוות, ולכך חלה מידת הדין על יריחו ונפלה החומה תחתיה. וכן היו ישראל במקדש מתכפרים על ידי המזבח, ומידת הדין היתה חלה על האויבים ולא היה להם רשות לבוא כנגד ישראל. וכן לעתיד, תחזור השכינה לבית קודשי הקודשים, ותחול מידת הדין בשונאיהן של ישראל אשר הציקום ושיעבדו בהם. וההקפה שאנו עושין בזמן הזה, הוא סימן ורמז לעתיד שתיפול חומת אדום, ויהיו כלים ואבודים מן העולם. על פי הסבר רבינו בחיי, מספר ההקפות שהקיפו ישראל את יריחו, רומז לשכינה; באמצעותן הם כביכול 'מיקדו' את השכינה, דהיינו את מבט ההשגחה האלוהית - על יריחו, ובכך עוררו עליה את מידת הדין. זוהי אף מטרתן של ההקפות שנערכו בבית המקדש: החלת מידת הדין על שונאיהם של ישראל, וממילא – הגנה על ישראל עצמם. גם ההקפות שאנו עורכים היום בבתי הכנסת, נועדו לעורר את מידת הדין על אומות העולם המצרות לישראל, ומתוך כך – להחיש את ישועתנו השלימה. הרדב\"ז, בהמשך לקו רעיוני זה, מרחיב יותר את משמעותן של ההקפות: וכן בכל מקום שתמצא בדברי רבותינו ז\"ל הקפה, כגון הקפת המזבח שהיו מקיפין בכל יום פעם אחת ובשביעי שבע פעמים, וכן עשה יהושע בעיר יריחו, וכן אנו מקיפין את התיבה והתורה בתוכה בחג הסוכות בכל יום פעם אחת ובשביעי שבע פעמים, [...] והכול רמז אחד ועניין אחד [...] - להבריח כוחות הטומאה. שני הסברים אלו אחוזים הם זה בזה, שכן כוחות הטומאה והרוע העולמיים פועלים באמצעות אומות העולם, ובהכנעתם אנו מבטלים את כוחן הרוחני של האומות המצרות לישראל. בעל 'ילקוט מעם לועז' אכן כורך את הדברים יחד: הטעם להקפות אלו, כדי להצילנו משִבעים השרים. כי לכל אחת משבעים האומות יש שר למעלה, ושבעת ימי המועד הם כנגד שבעים האומות, שכל יום כנגד עשר אומות. ובכל ימי הסוכות אנו מתפללים ואומרים: \"אָנָּא ה' הוֹשִׁיעָה נָּא\", ועושים הקפה אחת, שיושיענו ושיצילנו מעשרה שרים שלמעלה. ובהקפות אלו אנו ניצולים גם מן החיצונים והקליפות הרעות של שבעת כוחות הטומאה. [...] ולכן ישתדל האדם לומר התפילות בחג הסוכות בהכנעה, ויועילו לו להינצל באותה שנה מהרבה פורענויות רעות. מהרי\"ץ מסביר מדוע חג הסוכות הוא העיתוי המתאים לפעולה רוחנית זו: כמו שחומת יריחו הפילוה על ידי ההקפות, שהיתה בנויה על ידי כישוף וכוחות הטומאה, וכדי להפילה ראתה חכמתו יתברך שיעשו ישראל שבע הקפות, שאז הכוחות הטמאים ההם יכרעו ויפולו לארץ ויתבטלו לגמרי. [...] וזה עצמו טעם הקפות דסוכות [... כי] בהיות כשאדם חוטא בשאר ימות השנה - נברא קטיגור אחד ורוח רע מאותו עוון או פשע למעלה; וביום הכיפורים, שנתכפרו ישראל ודחו הקטיגורים וכוחות הטומאה ההם - נדחו מלמעלה. אולם עדיין נשארו באוויר, לפי שעדיין לא נחתמו ישראל עד יום 'הושענא רבה', ועדיין יסברו ויחשבו לעלות למעלה לקטרג כבראשונה. וכדי להפילם למטה לארץ ולבטלם מכל וכול - על כן נקיף הבימה עם הספר תורה בכל יום פעם אחת כמו שעשו ביריחו [...] ועל כן ננענע ב\"הושיעה נא\" ונצעק לקב\"ה שיושיענו מהם. לדבריו, פעולת ההקפות מהווה המשך למחילת העוונות ביום הכיפורים. העוונות הם אלו שמעוררים את כוחות הרוע והטומאה בעולם, ועל ידי הכפרה הכללית לעם ישראל ביום הכיפורים – מאבדים הם את כוחם. אך מכיוון שהדין אינו נחתם לגמרי עד יום 'הושענא רבה', אותם כוחות שליליים שנבראו מהעוונות עודם קיימים במציאות, ועל ידי ההקפות ותפילות ה'הושענות' אנו מבטלים אותם מכל וכול. משמעותם המעשית של דברים אלו תובן על פי דברי ה'שם משמואל', המדגיש את הפן המוסרי שבהשוואה בין הקפות החג להקפות יריחו: ונראה לפרש, דהנה יריחו נקראת על שם הריח [...] וריח הוא פנימיות הדבר [...] וחומת יריחו היא קליפה קשה שאינה מנחת לבוא אל הפנימיות. [...] ודוגמא לזה הוא שמיני עצרת, שהוא הנקודה הפנימית מכל הימים שעברו: ראש השנה, יום הכיפורים, וסוכות, והוא קבלת עול מלכות שמיים באמת ובלב תמים ובייחוד הכוונה לה' יתברך בלי שום עירוב כוונה, וזה תכלית הכול. וכבוד קדושת זקני זצללה\"ה מקוצק הגיד, כי יותר נוח לגוף לקבל על עצמו כל מיני סיגופים שבעולם מלקבל על עצמו עול מלכות שמיים, ואין סיגוף גדול לגוף יותר מלהיות תחת עול מלכות שמיים להתנהג בכל ענייניו רק על פי התורה - עד כאן תורף דבריו. ובאשר שזה תכלית הכול, עומדים כנגד זה כל כוחות החיצונים לבלבלו לערבו להממו ולהבהילו, והם סובבים את זו הנקודה מכל צד בכל טצדקי, למנוע את האדם מלזכות לנקודה זו. וזוהי דוגמת חומת יריחו. ובהקפות של סוכות, וב'הושענא רבה' שבע פעמים – מפילין את החומה, ובא הזמן היותר נכון לקבל עליו עול מלכות שמיים שלימה. לדבריו, ההקפות מבטאות את השאיפה להגיע לנקודה הפנימית של עבודת ה', המאחדת ומלכדת סביבה את כל הפרטים: קבלת האדם על עצמו שיעבוד מוחלט לקיום רצון ה', והקדשת כל מעשיו וכל רגע מרגעי חייו למטרה זו. גם אם בימי אלול ובעשרת ימי התשובה האדם תיקן את מעשיו ושב מחטאיו, עדיין נדרש ממנו לתקן את השורש של כל אותם הכישלונות: חסרונה של נקודה פנימית זו. בהקפות אנו יכולים להפיל את החומות החוצצות בינינו לבין הקב\"ה, על ידי שנקבל על עצמנו להפנים נקודה יסודית זו בתוכנו ולכוון את כל חיינו על פיה. מתוך אותה עבודה רוחנית, נגיע ביום 'שמיני עצרת' לתכלית תהליך ההתעלות של מערכת מועדים זו, ולכך ש'יתייחד העובד עם המלך במסיבו'. נוכל להסביר שזוהי אף כוונת הדברים שהביא מהרי\"ץ: אם האדם תיקן את חטאיו בפועל, אך לא את השורש שלהם, הרי שאותם מקטרגים שנבראו מהם 'עדיין עומדים באוויר', כלשונו, והם יכולים לקטרג בעת חתימת הדין הסופי ביום 'הושענא רבה'. על ידי ההקפות, והעבודה המוסרית שהן מבטאות, כפי שביאר ה'שם משמואל' – אותם מקטרגים נעלמים כליל מן המציאות, שהרי השורש ממנו נבראו אינו קיים עוד, ואין להם כל מקור רוחני לינוק ממנו את כוחם. הערות 6 תשובה זו מופיעה גם בתלמוד הירושלמי שבידינו, סוכה, פרק ד, הלכה ג. 7 רבינו בחיי בן אשר (ה'ט\"ו-ה'ק' בקירוב), מחכמי ספרד, חיבר פירוש על התורה ועל מסכת אבות, ואת ספר הדרשות 'כד הקמח'. 8 על פי הסברו ושאר ההסברים דלקמן (מלבד זה של ה'ערוך לנר'), משמעות הביטוי 'זכר ליריחו' אינה: כדי לזכור את הקפות יריחו, אלא: שההקפות של יריחו ושל המקדש – עניין אחד להן. 9 הרמז להתמעטות הוא מכך שבכל יום מתמעט מספר הפרים המוקרבים: ביום הראשון-שלושה עשר, בשני – שנים עשר, וכן הלאה. דברי רבינו בחיי מבוססים על דברי הגמרא: \"הני שבעים פרים כנגד מי? כנגד שבעים אומות\" (תלמוד בבלי, סוכה נה:); אך לכאורה מהמשך הסוגיה עולה הבנה הפוכה מדבריו: \"אמר רבי יוחנן: אוי להם לגויים שאיבדו ואין יודעין מה שאיבדו: בזמן שבית המקדש קיים – מזבח מכפר עליהן, ועכשיו מי מכפר עליהן?\" – הרי שאותם פרים נועדו לכפר על האומות, ולא להכניע את כוחן. וכך כתב שם רש\"י (ד\"ה שבעים): \"שיֵרדו גשמים בכל העולם\", ובפירושו על התורה: \"ובימי המקדש היו [הפרים] מגינין עליהם מן הייסורין\" (במדבר כט יח). ניתן ליישב זאת ולומר שאין סתירה בין הדברים: הקרבת הפרים לא נועדה להכניע אלא את הכוח הרע והשלילי שבאומות, אך את מערכת חייהם הטבעית ואת הופעת החיובי והטוב שבהן – היא מחזקת. 10 כד הקמח, ערך 'ערבה' 11 רבי דוד בן זמרא (רל\"ט-של\"ד), שימש כמנהיגה הרוחני של יהדות מצרים, ובעשורים האחרונים לחייו חי בצפת. רבו של רבי בצלאל אשכנזי, מחבר ה'שיטה מקובצת'. 12 מגן דוד, אות ק 13 רבי יעקב כולי (תמ\"ט–תצ\"ד, בקירוב), חיבר את הפירוש 'ילקוט מעם לועז' על התנ\"ך, וערך את כתביו של סבו רבי משה בן חביב, ואת החיבור 'משנה למלך' - פירושו של רבי יהודה רוזאניס על משנה תורה לרמב\"ם. 14 מעם לועז, יהושע ו ד 15 רבי יחייא צאלח (תע\"ד-תקס\"ה), מגדולי רבני תימן. 16 שו\"ת פעולת צדיק, חלק ג, סימן צ, בשם 'גדול אחד' 17 רבי שמואל בורנשטיין (תרט\"ז-תרפ\"ו), האדמו\"ר השני מסוכוצ'וב, בנו של רבי אברהם מסוכוצ'וב מחבר שו\"ת 'אבני נזר', ונכדו של רבי מנחם מנדל מקוצק. 18 שם משמואל, הושענא רבה, תרע\"ד 19 רעיון זה רמוז כבר בדברי האר\"י: \"והקפה, להפיל חומת ברזל המפסקת בינינו לבין אבינו שבשמיים, כעניין הקפת יריחו להפיל החומה\" (ליקוטי תורה, פרשת אמור). 20 מתוך הפיוט 'ישאלוני רעיוני' לרבי יהודה הלוי 21 ובהמשך דבריו כתב שההקפות שבשמיני עצרת נועדו לבסס את השגת אותה נקודה, עיין שם. ראינו, איפוא, שלושה הסברים להשוואה בין הקפות יריחו לבין הקפות החג: הכנעת כוח האומות, ביטול המלאכים המקטרגים וכוחות הרוע העולמיים, והפלת החומות המבדילות בינינו לבין הנקודה הפנימית של עבודת ה' שאליה אנו שואפים להגיע. שלושה דברים אלו תלויים הם זה בזה: על ידי עבודתם המוסרית של ישראל וקבלתם על עצמם עול מלכות שמיים בשלימות – הרי הם מבטלים את המקטרגים ואת כוחות הרוע והטומאה; מתוך ביטולם של אלו – לא יהיה כוח לאומות העולם להרע לישראל. אליבא דשיטה זו, הטעם לנטילת ארבעת המינים בעת ההקפות מתבאר היטב על פי דברי המדרש: משל לשניים שנכנסו אצל הדיין, ולית אנן ידעין מאן הוא נוצח, אלא מאן דנסב באיין בידיה אנן ידעין דהוא נצוחייא [=ואיננו יודעים מי ניצח, אלא מי שאוחז כידון בידו – אנו יודעים שהוא המנצח]. כך ישראל ואומות העולם באין ומקטרגים לפני הקב\"ה בראש השנה, ולית אנן ידעין מאן נצח, אלא במה שישראל יוצאין מלפני הקב\"ה ולולביהן ואתרוגיהן בידן, אנו יודעים דישראל אינון נצוחייא. לפיכך משה מזהיר לישראל ואומר להם: \"וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן\" (ויקרא כג מ). על פי המדרש, ארבעת המינים מסמלים את ניצחונו של עם ישראל על אומות העולם ושריהן המקטרגים עליו. לאור זאת, נטילתם בעת ההקפות מתבקשת מאליה, שכן הן מהוות הכנעה סופית של האומות, של כוחות הרע והטומאה, ושל היצר הרע, השייכים כולם לאותו מחנה, כמבואר לעיל. בטעם הדבר שההקפות נעשו דווקא סביב המזבח ניתן לומר, שמכיוון שעליו הוקרבו שבעים הפרים הרומזים להתמעטות כוחן של אומות העולם, כמבואר בדברי רבינו בחיי, מקומו מסמל – לצורך העניין – את האומות, וכך ההקפות סביבו הן כעין ההקפות סביב יריחו; אלו ואלו נועדו להכניע את כוח הרע שניצב במרכזן. ניתן גם להסביר, שההקפות סביב המזבח מזכירות לפני הקב\"ה את זכות עבודת המקדש והקרבת הקורבנות, ומכוחה אנו מייחלים לזכות לישועה ולהגנה מפני אומות העולם. על פי הסבר זה ניתן לומר, שמנהגנו כיום להקיף את הבימה כשעל ידה ספר התורה, נועד להזכיר לפני הקב\"ה את זכות לימוד התורה ושמירתה, ומכוח זאת לזכות לאותם דברים. הערות 22 ויקרא רבה, פרשה ל, אות ב 23 כעין זה כתב הב\"ח: \"אולי שאנו תופסין עיקר כי שמיעת התורה היא מכפרת עלינו כמו המזבח\" (סימן תרס, ד\"ה 'ומ\"ש ונוהגין'). בעל ה'ערוך לנר' מסביר באופן נוסף את ה'זכר ליריחו' שבהקפות: משום שעיקר שמחת החג היא להודות ולהלל לקב\"ה על חסדיו ונפלאותיו [...] ועיקר שבח הקב\"ה הוא על הניסים שנעשו בארץ ישראל, שלכך אמרינן: \"אין אומרים הלל על נס שבחוצה לארץ\". ולכן מזכירין נס זה של יריחו, שהיה נס ראשון שעשה הקב\"ה לישראל אחר שעברו הירדן ונכנסו לארץ ישראל. לעומת ההסברים דלעיל, שהדגישו את מימד התפילה וההשפעה על העתיד שבהקפות, הסבר זה מדגיש את מימד ההודאה על העבר הרמוז בהן. ההקפות, שהן מעין שחזור של טקס כיבוש יריחו, מסמלות את שמחתנו והודאתנו לקב\"ה על כל הטובות והניסים שעשה עימנו מאז ועד עתה, ובפרט בארץ ישראל. דברים אלו משתלבים יפה עם דברי הרמב\"ם, המפרש כי נטילת ארבעת המינים (שאותם אנו אוחזים בעת ההקפות) מסמלת את שמחתנו על כך שזכינו לשבת בארץ ישראל: ואשר נראה לי בארבעת מינים שבלולב, שהיא שמחה וששון על יציאתם מן המדבר, שהיה \"לֹא מְקוֹם זֶרַע וּתְאֵנָה וְגֶפֶן וְרִמּוֹן וּמַיִם אַיִן לִשְׁתּוֹת\" (במדבר כ ה), אל מקום עצי פרי ונהרות. לפיכך נלקח לזיכרון לכך: הנאֶה שבפירותיה ובעל הריח הטוב, והעלים הנאים, וגם הנאה שבעשבותיה, כלומר: ערבי נחל. הערות 24 רבי יעקב אטלינגר (תקנ\"ח-תרל\"א), ממנהיגי היהדות האורתודוכסית בגרמניה. כיהן בה כרב במספר ערים, וחיבר את ה'ערוך לנר' - פירוש על התלמוד, 'ביכורי יעקב' על הלכות סוכה, ושו\"ת 'בניין ציון'. 25 תלמוד בבלי, מגילה יד. 26 ערוך לנר, סוכה מה. 27 מורה נבוכים, חלק ג, פרק מג מלבד הטעם שהובא בירושלמי – 'זכר ליריחו', מצינו טעם נוסף למנהג ההקפות, בדברי ה'לבוש': ונוהגים להקיף המגדל פעם אחת בכל יום ומניחים ספר התורה על התיבה כשמקיפין אותה כדי להקיף הספר תורה, משום שמחה [...]. וביום השביעי מקיפין שבע פעמים [...] משום שמחת החג, שנקרא 'זמן שמחה'. לפי טעם זה, ההקפות הן כעין ריקודים ומחולות של שמחה, בהם התנועה היא סיבובית, וכך מופיע בצורה מפורשת ב'תרגום שני' על אסתר, בתוך דברי המן לאחשוורוש (בתרגום מארמית): בחמישה עשר בו [...] באין לבתי כנסיות שלהם [...] ושמחים ומתפללים ומקיפים ב'הושענא', ומרקדים כגדיים. לפי שיטה זו ניתן לומר, שההקפות נעשו דווקא סביב המזבח, משום שהשמחה המיוחדת בחג הסוכות נובעת מהיות ישראל זכים וטהורים לאחר מחילת עוונותיהם ביום הכיפורים, וכפרה זו באה על ידי עבודת הכוהן הגדול, שכללה הקרבת קורבנות על המזבח. הקפות אלו ביטאו את השמחה על כפרה זו, ועל מה שמכפרים המזבח והקורבנות על ישראל במשך השנה כולה. על פי הסבר זה ניתן לומר, שמנהגנו כיום להקיף את הבימה כשעל ידה ספר התורה, מבטא את שמחתנו בתורה ובמצוותיה. אין במבט זה על ההקפות, הרואה בהן מחולות של שמחה, בכדי לגרוע ממימד התפילה שבהן; ההקפות ואמירת ה'הושענות' מהוות שילוב של שמחה ותפילה, המעצימות זו את זו. כל אחת מהן מרוממת את נפש האדם בנתיבה המיוחד, ויחד הן משתלבות ומביאות את האדם להתעלות וקירבת ה'. בגמרא נאמר כי \"אין עומדין להתפלל [...] אלא מתוך שמחה של מצוה\", וכתב על כך הראי\"ה קוק: \"השמחה היא השלימות הפנימית שנפש הישר מרגשת בהיותה משגת שהיא הולכת בדרך ישרה וטובה, וההשלמה הפנימית היא תכלית לתפילה\". לאחר שהאדם תיקן את מעשיו ואת דרכיו בימי התשובה, בחג הסוכות נפשו יודעת 'שהיא הולכת בדרך ישרה וטובה', ואת השמחה הגדולה שהיא חשה בעקבות זאת, מבטא האדם בהקפות שמחה אלו; מתוך שמחה עליונה זו – הוא נושא על שפתיו את תפילות ה'הושענות' המרוממות. הערות 28 לרבי מרדכי יפה (ר\"צ-שע\"ב), תלמיד הרמ\"א ומהרש\"ל, כיהן כרב בפראג ובערים נוספות בפולין, וחיבר את סדרת ספרי ה'לבושים', העוסקים בהלכה, בפרשנות המקרא, ובקבלה. 29 לבוש החור, סימן תרס, סעיף ב 30 מבט זה על ההקפות מתבטא גם במנהג שמציין הרמ\"א (אורח חיים, סימן תרס, סעיף ב), שהאבל אינו משתתף בהקפות, וכתבו הב\"ח, הגר\"א, וה'ביכורי יעקב' על אתר, שטעם המנהג הוא משום השמחה שבהקפות. 31 אסתר ג ח 32 על תיאור המשנה את סיום מעמד ההקפות: \"בשעת פטירתן מה הם אומרים? 'יופי לך מזבח, יופי לך מזבח'!\" כתב רש\"י: \"יופי לך - היופי הזה אנו עושין לך שאתה מכפר עלינו\". 33 תלמוד בבלי, ברכות לא. 34 'עין איה' על אתר, אות י פיוטי ה'הושענות' הנאמרים בעת ההקפות, הרי הם כעין התפילות על הישועה שנאמרו במקדש בעת ההקפות סביב המזבח: \"אָנָּא ה' הוֹשִׁיעָה נָּא, אָנָּא ה' הַצְלִיחָה נָא\", ולדעת רבי יהודה: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\". בדברי ה'ילקוט שמעוני' שהובאו לעיל, 'חזן הכנסת' העומד במרכז ואוחז בספר התורה מדומה ל'מלאך האלוהים', ומהווה 'תחליף' למזבח שאותו הקיפו בבית המקדש; הוא מייצג את השכינה המצויה עימנו בעת זו, שכביכול מצויה יחד איתנו בצרותינו, ואף עליה אנו מתפללים: \"אֲנִי וָהוּ הוֹשִׁיעָה נָּא\" – את 'אֲנִי' = ישראל, 'וָהוּא' = הקב\"ה, 'הוֹשִׁיעָה נָּא'. וכך כתב ה'מחזור ויטרי': \"מקיפין את הבימה [...] ונותנין עליה ספר תורה, לומר: שֵם שמיים אנו סובבים\". מלבד זאת, יש מהראשונים שכתבו שאמירת פיוטים אלו מהווה גם זכר למצוַת 'ניסוך המים'. על פי דברי הגמרא, מטרתה של מצוַה זו היא להשפיע ברכה בגשמי השנה: \"ומפני מה אמרה תורה: נַסְּכוּ מים בחג? אמר הקדוש ברוך הוא: נסכו לפני מים בחג, כדי שיתברכו לכם גשמי שנה\". פיוטי ה'הושענות', בכך שמכילים הם בקשות על המים, אם בפירוש ואם בכלל הבקשה הכללית לישועה, מהוות זכר למצוַה זו. וכך כתב ב'מחזור ויטרי': \"כל ימות החג מתפללים 'הושענות' לאחר תפילה, זכר לניסוך המים שהיה בא כל שבעה לרַצות על המים\". הערות 35 ראה להלן עמ' 61-60, ועמ' 148 36 לרבינו שמחה ב\"ר שמואל, תלמיד רש\"י 37 סדר תפילת סוכות, אות יב 38 תלמוד בבלי, ראש השנה טז. 39 סימן שפא (במהד' גולדשמיט עמ' תתעא), וכן מופיע בסידור רש\"י סימן רכד. כעין זה כתב גם בספר 'המחכים', סדר תפילת סוכות. פיוטי ה'הושענות' הנהוגים בקרב קהילות אשכנז, חוברו על ידי גדול הפייטנים רבי אלעזר הקליר, כפי שעולה מדברי רבותינו הראשונים. מאות פיוטים חוברו על ידו, לתפילות של הימים הנוראים, שלושת הרגלים, שבתות מיוחדות, פורים, ותשעה באב; סליחות וקינות, ופיוטי גשם וטל. בשאלת זהותו וזמן פעילותו רבו הדעות; לא נאריך בנושא זה, שכבר נכתב עליו רבות, ונסתפק בסקירה כללית: הראשונים שיערו שרבי אלעזר הקליר הוא תנא: ה'תוספות' והרא\"ש נקטו שהוא התנא רבי אלעזר בנו של רבי שמעון בר יוחאי, והרשב\"א כתב ש\"אומרים עליו שהוא רבי אלעזר בן ערך\". יש מרבותינו האחרונים שהקשו על זיהויים אלו, והוכיחו כי חי סביב תקופת הגאונים; כך היא הגישה הרווחת כיום, גם בקרב החוקרים. רבי יעקב עמדין כותב בשם האר\"י כי ברבי אלעזר הקליר היה ניצוץ מנשמתו של רבי אלעזר בן רבי שמעון. על פי דעה זו ניתן לגשר בין שתי הגישות הנזכרות, ולומר כי אף שבפועל חי בתקופה מאוחרת, מעלת נשמתו היתה גבוהה במיוחד, והיה בה ניצוץ ממדרגתם של התנאים. להלן מובאות מדברי גדולי הדורות בדבר גודל מעלתו וחשיבות פיוטיו: ושמעתי מאבא מרי זלה\"ה, ששמע מרבותיו: כשפייט רבי אלעזר קליר: \"וְחַיּוֹת אֲשֶׁר הֵנָּה מְרֻבָּעוֹת לַכִּסֵא\" – ביַעַר היה, וליהטה אש סביבותיו, ומפי רבותיו גאוני לותיר העיד כן. דע לך כי מורי [האר\"י] ז\"ל לא היה אומר שום פזמון ושום פיוט ובקשה מאלו שסידרו האחרונים [...] אבל היה אומר התפילות והבקשות ופזמונים שתיקנו הראשונים [...] וכן היה אומר כל הפיוטים ופזמונים שתיקן רבי אלעזר הקליר, הלוא המה במחזור האשכנזים, לפי שכל אלו הראשונים תיקנו דבריהם על פי חוכמת האמת. וכל דבריו מיוסדים על פי מדרשות, אגדות, ורזי התורה, וגדולי רבותינו רש\"י ו'תוספות' סמכו דבריהם עליו. מי שיש לו עיניים לראות ואוזניים לשמוע, עיניו תראינה ובלבבו יבין שכל דברי הקליר מלאים זיו החוכמה ומפיקים נוגה התבונה, וברוח פיו אגדות ומדרשות סתומות ומפורשות [...] ומה שכל דבריו מלאים אגדות וחוד חידות - הן הן גבורותיו הן הן נוראותיו, ערבים עליו דברי דודים רבותינו בעלי האגדה, והתעטף באורם הגדול כשַׂלמה, ועשה מליצות משובצות זהב סביב, והבהיק מזיוום והדרם, שיהיו כולם כדאים להשתמש באור הגדול. [...] גאוני עולם וקדושי עליון כרבי אלעזר הקליר ורבינו שמעון הגדול, ורוח הקודש שורה עליהם; [...] ומי לא יראה שעל כל דבריהם שורה קדושה ויראה והשתפכות הנפש. ותיפח רוחם של הכסילים האומרים שלשונם מגומגם, הלוא אנו רואים התפילות של הקלירי בראש השנה ויום הכיפורים וטל וגשם, קלים ונוחים להבין, וקדושה וטהרה חופפת עליהם; וזה שעשו כמה פיוטים בלשונות חדים ומסותרים - עשו בכוונה, לדעתי, מפני שגילו בהם סודות נוראים, ולכן הסתירו דבריהם הקדושים כדרכם בקודש. הגדיל לעשות רבי אלעזר מגרמייזא בעל ספר ה'רוקח', שבפירושו על פיוטי ה'הושענות' אף מונה את תיבותיו של כל פיוט, וכותב על כך סודות ורמזים שונים, דבר המעיד על החשיבות הרבה שייחס לפיוטים אלו. הארכנו בעניין זה על מנת להבהיר את גודל החשיבות הקיימת בהתבוננות מעמיקה בלשונותיהם של פיוטי הקליר, ובתוכם ה'הושענות'; על ידי כך, ניתן לחשוף רעיונות עמוקים ונשגבים הגנוזים בתוכם. מתוך התבוננות באופן ניסוח הדברים ובדרך סידורם, ובפרט מתוך התחקות אחר מקורות הביטויים המשובצים בהם, אם במקרא ואם בדברי חז\"ל בתלמוד ובמדרשים, עולות ומאירות הבנות חדשות השופכות אור על הפיוט, ומרוממות את כוונת המתפלל לגבהי מרומים, בשעת רצון מיוחדת ונשגבה זו של ההקפות ואמירת ה'הושענות'. הערות 40 ספר 'מנהגים דבי מהר\"ם [מרוטנבורג]', סדר הושענות, וראה גם בציונים דלהלן, בהם מובאים ציטוטים מה'הושענות', בשם הקליר: רש\"י על איוב כד ו; פירוש בעלי התוספות על בראשית לח ח; רקאנטי שם; פירוש ה'רוקח' על ההגדה, על המילים \"ואת לחצנו\"; ציוני על בראשית יב ו. 41 חגיגה יג. ד\"ה ורגלי 42 פסקי הרא\"ש על מסכת ברכות, פרק ה, סימן כא 43 שו\"ת הרשב\"א, חלק א, סימן תסט 44 בשו\"ת 'זכרון יוסף' (סימן יג) הוכיח מה'קרובץ' לתשעה באב שיסד הקליר, ובו נכתב (בברכת 'אבות'): \"אַאֲנִין תְּשַׁע מֵאוֹת שָׁנָה\" – הרי שחי כתשע מאות שנה לאחר חורבן בית שני, ורבי יעקב עמדין בספרו 'מור וקציעה' (סימן קיב) ציין שבכמה מפיוטיו האקרוסטיכון הוא: \"אלעזר בר' יעקב'. 45 בפרט לאור פיוטים חדשים של הקליר שהתגלו בגניזה הקהירית, בהם קיימים רמזים לשלטון הנוצרי בארץ ישראל. 46 שם, ודבריו הובאו בספר 'מחזיק ברכה' לחיד\"א (סימן קיב) וב'שערי תשובה' (על ה'שולחן ערוך', סימן סח סעיף קטן ב). 47 פיוט לקדושה בראש השנה 48 רבינו תם, בתשובה המובאת ב'שבולי הלקט' (סימן כח) ובמחזור ויטרי (סימן שכה). 49 שער הכוונות, דף נ ע\"ג 50 איגרות רבי עקיבא איגר, איגרת נד. רבי עקיבא איגר (תקכ\"ב-תקצ\"ח) נחשב לאחד מגדולי הדורות האחרונים, כיהן כרב בפוזנא, חיבר שו\"ת וחידושים על המשנה והתלמוד. 51 שו\"ת תשובה מאהבה, חלק א, סימן א (לרבי אלעזר פלקלס [תקי\"ד-תקפ\"ו], תלמיד ה'נודע ביהודה', כיהן כראש ישיבה וכדיין בפראג). 52 ערוך השולחן, סימן סח סעיף ב (לרבי יחיאל מיכל אפשטיין [תקפ\"ט – תרס\"ח], כיהן כרב בערים שונות ברוסיה). 53 (ד'תתקכ\"ה-ה'א, בקירוב), פוסק ומקובל מחוג 'חסידי אשכנז'. כתב את ספר ה'רוקח' העוסק בענייני הלכה, אמונה, ומוסר (הספר נקרא כך בהתאם למה שכתב בהקדמתו, שעל המחבר לרמוז את שמו בשם ספרו: 'רֹקח' בגימטריה 'אלעזר'), וחיבורים נוספים בנושאי הלכה ומנהג, סודות ורמזים במקרא ובסידור התפילה, וענייני חזרה בתשובה. בעניין סדרם של פיוטי ה'הושענות' ואופן חלוקתם לימי החג, רבו חילוקי המנהגים בין הקהילות השונות בזמן הראשונים; בימינו קיים מנהג אחיד בקרב כל קהילות יוצאי אשכנז, על פי ספרי המנהגים של רבי אברהם קלויזנר ותלמידו רבי אייזיק טירנא, שדבריהם הובאו ב'מגן אברהם' וב'לבוש'. סדר זה מבוסס על ארבעה כללים: א. בשני הימים הראשונים של החג, שבחוץ לארץ הם יום טוב, אומרים את הפיוטים: 'למען אמיתך' – העוסק בכבוד השכינה, ו'אבן שתייה' – העוסק בבית המקדש. מפני חשיבות נושאים אלו, ראוי להזכירם בימים המקודשים ביותר שבחג. ב. את הפיוט 'אערוך שועי' יש להסמיך ליום הכיפורים ככל האפשר, כיוון שתוכנו עוסק בעבודתו הרוחנית של האדם ביום הכיפורים; אך לא ניתן לאומרו ביום-טוב או בשבת, מפני שהוא דומה לווידוי. ג. את הפיוט 'אדון המושיע', המכיל בקשות לגשמים, יש לומר רק סמוך לסוף החג, ביום שלפני 'הושענא רבה', מפני שירידת גשמים בסוכות היא סימן קללה. ד. הפיוט 'אום נצורה', העוסק בעניין השבת, תמיד יֵאמר בשבת. ביום שאינו מחוייב לאחד מכללים אלו, ייאמר הפיוט 'אל למושעות', ואם יש יום נוסף כזה – ייאמר בו הפיוט 'אום אני חומה'. על פי יסודות אלו, נפרט את הסדר הנהוג: א. כשיום-טוב חל ביום שלישי בשבוע - מתקיימים כל הכללים הנ\"ל, ובשנה כזו הסדר הוא: 'למען אמיתך', 'אבן שתייה', 'אערוך שועי', 'אל למושעות', 'אום נצורה', 'אדון המושיע'. ב. כשיום-טוב חל ביום חמישי בשבוע - גם כן מתקיימים כל אותם כללים, אלא ש'אערוך שועי' נדחה ליום הרביעי של החג, שהרי היום השלישי הוא שבת; בשנה כזו הסדר הוא: 'למען אמיתך', 'אבן שתייה', 'אום נצורה', 'אערוך שועי', 'אל למושעות', 'אדון המושיע'. ג. כשיום-טוב חל בשבת - נדחה כלל א מפני כלל ד, ו'אבן שתייה' נדחה ליום הרביעי; בשנה כזו הסדר הוא: 'אום נצורה', 'למען אמיתך', 'אערוך שועי', 'אבן שתייה', 'אל למושעות', 'אדון המושיע'. מכיוון שממילא בשנה זו 'אבן שתייה' לא נאמר ביום-טוב, מוטב לדחותו לאחר 'אערוך שועי', כדי לקיים את כלל ב. ד. כשיום-טוב חל ביום שני בשבוע - אין אומרים כלל 'אדון המושיע', שהרי היום הסמוך ל'הושענא רבה' הוא שבת, והקדמת פיוט זה אינה אפשרית, כמבואר בכלל ג; במקומו נאמר הפיוט 'אום אני חומה', ובשנה כזו הסדר הוא: 'למען אמיתך', 'אבן שתייה', 'אערוך שועי', 'אום אני חומה', 'אל למושעות', 'אום נצורה'. ה'לבושי שרד' העיר, שלכאורה כלל א אינו תקף בארץ ישראל לגבי היום השני, שכן בה היום השני של החג הוא חול המועד, ואם כן ראוי היה לומר בו 'אערוך שועי', על פי כלל ב, אך הוא כותב כי 'לא מלאני ליבי לשנות המנהג'. ניתן ליישב את תמיהתו על פי ההסבר המופיע בספר 'אוצר דינים ומנהגים' וב'ספר התודעה', לפיו הפיוט 'אערוך שועי' צריך להיאמר דווקא ביום השלישי של החג, מפני שהוא חל באותו יום בשבוע שבו חל יום הכיפורים. טעם זה תקף גם בארץ ישראל, ולפיכך גם בה הסדר זהה לסדר שבגלויות. הערות 54 למעט מנהג חב\"ד, לפיו ה'הושענות' נאמרות בכל שנה בסדר זהה, שהוא כסדר אמירתן ב'הושענא רבה': 'למען אמיתך', 'אבן שתייה', 'אום אני חומה', אדון המושיע', 'אדם ובהמה', 'אדמה מארר', ובשבת – 'אום נצורה'. 55 מחכמי אשכנז בסוף תקופת הראשונים. 56 סימן תקסג. הכתוב להלן מבוסס על דבריהם, וכן על הפוסקים המאוחרים שדנו בהם: 'מחצית השקל', 'פרי מגדים', 'לבושי שרד', ו'ביכורי יעקב', על אתר. בגוף הביאור שבספר זה נכתבו טעמים נוספים לסדר הפיוטים. 57 ראה להלן לגבי תוקפו של כלל זה בארץ ישראל, בה היום השני של החג הוא חול המועד. 58 עמ' 96. ספר זה הוא אנציקלופדיה לענייני הלכה ומנהג, נכתב על ידי ר' יהודה דוד אייזנשטיין (תרט\"ו-תשט\"ז), ניו יורק. 59 עמ' קיח במהד' תשכ\"ג \"נִשָּׂא לְבָבֵנוּ אֶל כַּפָּיִם, אֶל אֵל בַּשָּׁמָיִם\" (איכה ג מא); תפילתנו, שמתוך לימוד מעמיק והבנה של משמעות ההקפות ונוסח תפילות ה'הושענות', שספר זה פותח להם פתח - תפילות חג הסוכות יהוו עבור הקורא חוויה של רוממות הרוח והתעלות הנפש, שיאצילו מהודן על השנה כולה. יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, מֶלֶךְ רַחֲמָן, שֶׁתָּשׁוּב וּתְרַחֵם עָלֵינוּ וְעַל מִקְדָּשְׁךָ בְּרַחֲמֶיךָ הָרַבִּים, וְתִבְנֵהוּ מְהֵרָה וּתְגַדֵּל כְּבוֹדוֹ. אָבִינוּ מַלְכֵּנוּ, גַּלֵּה כְּבוֹד מַלְכוּתְךָ עָלֵינוּ מְהֵרָה, וְהוֹפַע וְהִנָּשֵׂא עָלֵינוּ לְעֵינֵי כָּל חָי, וְקָרֵב פְּזוּרֵינוּ מִבֵּין הַגּוֹיִם, וּנְפוּצוֹתֵינוּ כַּנֵּס מִיַּרְכְּתֵי אָרֶץ. וַהֲבִיאֵנוּ לְצִיּוֹן עִירְךָ בְּרִנָּה, וְלִירוּשָׁלַיִם בֵּית מִקְדָּשְׁךָ בְּשִׂמְחַת עוֹלָם. הערות 60 מתוך תפילת מוסף לחגים"],[11,"n2","הערה 2","הראשונים (רוקח, סימן רכא; ראבי\"ה, סימנים תרצב ותרצט; 'אור זרוע', סימן שטו; 'שבולי הלקט', סימן שסט) הביאו את המדרש דלקמן, וכתבו שמקורו בתלמוד הירושלמי בפרק 'לולב וערבה', אך בנוסח הירושלמי שלפנינו אין זה מופיע."],[11,"n3","הערה 3","סידור רס\"ג; שו\"ת הגאונים 'שערי תשובה', סימן לא"],[11,"n4","הערה 4","ילקוט שמעוני, תהילים, רמז תשג"],[11,"n5","הערה 5","מסכת סוכה, פרק ד, משנה ה"],[12,"main","","פותחים את ארון הקודש למשך כל זמן אמירת ההושענות, ומוציאים ספר תורה אל הבימה. הוֹשַׁע נָא לְמַעַנְךָ אֱלֹהֵינוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ בּוֹרְאֵנוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ גּוֹאֲלֵנוּ, הוֹשַׁע נָא. הוֹשַׁע נָא לְמַעַנְךָ דּוֹרְשֵׁנוּ, הוֹשַׁע נָא. בכל יום אומרים אחד מהפיוטים הבאים (כמפורט בסוף המבוא), ולאחריו את הפיוט 'כהושעת אלים' (עמ' 37). הושענות לשבת בעמ' 38. הוֹשַׁע נָא לְמַעַן אֲמִתָּךְ. לְמַעַן לִמּוּדָךְ. לְמַעַן בְּרִיתָךְ. לְמַעַן מַלְכוּתָךְ. לְמַעַן גָּדְלָךְ וְתִפְאַרְתָּךְ. לְמַעַן נִצְחָךְ. לְמַעַן דָּתָךְ. לְמַעַן סוֹדָךְ. לְמַעַן הוֹדָךְ. לְמַעַן עֻזָּךְ. לְמַעַן וִעוּדָךְ. לְמַעַן פְּאֵרָךְ. לְמַעַן זִכְרָךְ. לְמַעַן צִדְקָתָךְ. לְמַעַן חַסְדָּךְ. לְמַעַן קְדֻשָּׁתָךְ. לְמַעַן טוּבָךְ. לְמַעַן רַחֲמֶיךָ הָרַבִּים. לְמַעַן יִחוּדָךְ. לְמַעַן שְׁכִינָתָךְ. לְמַעַן כְּבוֹדָךְ. לְמַעַן תְּהִלָּתָךְ. הוֹשַׁע נָא. הוֹשַׁע נָא אֶבֶן שְׁתִיָּה. לִינַת הַצֶּדֶק. בֵּית הַבְּחִירָה. מָכוֹן לְשִׁבְתֶּךָ. גֹּרֶן אָרְנָן. נָוֶה שַׁאֲנָן. דְּבִיר הַמֻּצְנָע. סֻכַּת שָׁלֵם. הַר הַמּוֹרִיָּה. עֲלִיַּת שְׁבָטִים. וְהַר יֵרָאֶה. פִּנַּת יִקְרַת. זְבוּל תִּפְאַרְתֶּךָ. צִיּוֹן הַמְצֻיֶּנֶת. חָנָה דָוִד. קֹדֶשׁ הַקֳּדָשִׁים. טוֹב הַלְּבָנוֹן. רָצוּף אַהֲבָה. יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. שְׁכִינַת כְּבוֹדֶךָ. כְּלִילַת יֹפִי. תֵּל תַּלְפִּיּוֹת. הוֹשַׁע נָא. הוֹשַׁע נָא אֶעֱרוֹךְ שׁוּעִי. לְבַל עוֹד תַּרְשִׁיעִי. בְּבֵית שַׁוְעִי. מַהֵר אֱלֹהֵי יִשְׁעִי. גִּלִּיתִי בַצּוֹם פִּשְׁעִי. נֶצַח לְהוֹשִׁיעִי. דְּרַשְׁתִּיךָ בּוֹ לְהוֹשִׁיעִי. שָׂא נָא עֲוֹן רִשְׁעִי. הַקְשִׁיבָה לְקוֹל שַׁוְעִי. עֲבוֹר עַל פִּשְׁעִי. וְקוּמָה וְהוֹשִׁיעִי. פְּנֵה נָא לְהוֹשִׁיעִי. זְכוֹר וְרַחֵם מוֹשִׁיעִי. צוּר צַדִּיק מוֹשִׁיעִי. חַי כֵּן תְּשַׁעְשְׁעִי. קַבֵּל נָא שַׁוְעִי. טוֹב בְּאֶנֶק שְׁעִי. רוֹמֵם קֶרֶן יִשְׁעִי. יוּחַשׁ מוֹשִׁיעִי. שַׁדַּי מוֹשִׁיעִי. כַּלֵּה מַרְשִׁיעִי. תּוֹפִיעַ וְתוֹשִׁיעִי. הוֹשַׁע נָא. הוֹשַׁע נָא אוֹם אֲנִי חוֹמָה. לוֹמֶדֶת יִרְאָתָךְ. בָּרָה כַּחַמָּה. מְרוּטַת לֶחִי. גּוֹלָה וְסוּרָה. נְתוּנָה לְמַכִּים. דָּמְתָה לְתָמָר. סוֹבֶלֶת סִבְלָךְ. הַהֲרוּגָה עָלֶיךָ. עֲנִיָּה סֹעֲרָה. וְנֶחֱשֶׁבֶת כְּצֹאן טִבְחָה. פְּדוּיַת טוֹבִיָּה. זְרוּיָה בֵּין מַכְעִיסֶיהָ. צֹאן קָדָשִׁים. חֲבוּקָה וּדְבוּקָה בָּךְ. קְהִלּוֹת יַעֲקֹב. טוֹעֶנֶת עֻלָּךְ. רְשׁוּמִים בִּשְׁמֶךָ. יְחִידָה לְיַחֲדָךְ. שׁוֹאֲגִים. כְּבוּשָׁה בַגּוֹלָה. תְּמוּכִים עָלֶיךָ. הוֹשַׁע נָא. הוֹשַׁע נָא אֵל לְמוֹשָׁעוֹת. לְהָבִין שְׁמוּעוֹת. בְּאַרְבַּע שְׁבוּעוֹת. מִפִּיךָ נִשְׁמָעוֹת. גָּשִׁים בְּשַׁוְעוֹת. נוֹתֵן תְּשׁוּעוֹת. דּוֹפְקֵי עֶרֶךְ שׁוּעוֹת. סְפוּרוֹת מְשַׁמְּעוֹת. הוֹגֵי שַׁעְשְׁעוֹת. עֵדוּת מַשְׁמִיעוֹת. וְחִידוֹתָם מִשְׁתַּעְשְׁעוֹת. פּוֹעֵל יְשׁוּעוֹת. זוֹעֲקִים לְהַשְׁעוֹת. צַדִּיק נוֹשָׁעוֹת. חוֹכֵי יְשׁוּעוֹת. קָרֵב תְּשׁוּעוֹת. טְפוּלִים בְּךָ שְׁעוֹת. רֶגֶשׁ תְּשׁוּאוֹת. יוֹדְעֵי בִין שָׁעוֹת. שָׁלשׁ שָׁעוֹת. כּוֹרְעֶיךָ בְּשַׁוְעוֹת. תָּחִישׁ לִתְשׁוּעוֹת. הוֹשַׁע נָא. הוֹשַׁע נָא אָדוֹן הַמּוֹשִׁיעַ. לְגֵיא בַּל תַּרְשִׁיעַ. בִּלְתְּךָ אֵין לְהוֹשִׁיעַ. מְגָדִים תַּמְתִּיק וְתוֹשִׁיעַ. גִּבּוֹר וְרַב לְהוֹשִׁיעַ. נְשִׂיאִים לְהַסִּיעַ. דַּלֹּתִי וְלִי יְהוֹשִׁיעַ. שְׂעִירִים לְהָנִיעַ. הָאֵל הַמּוֹשִׁיעַ. עֲנָנִים מִלְּהַמְנִיעַ. וּמַצִּיל וּמוֹשִׁיעַ. פּוֹתֵחַ יָד וּמַשְׂבִּיעַ. זוֹעֲקֶיךָ תּוֹשִׁיעַ. צְמֵאֶיךָ תַּשְׂבִּיעַ. חוֹכֶיךָ הוֹשִׁיעַ. קוֹרְאֶיךָ תּוֹשִׁיעַ. טְלָאֶיךָ תַּשְׂבִּיעַ. רְחוּמֶיךָ תּוֹשִׁיעַ. יְבוּל לְהַשְׁפִּיעַ. שׁוֹחֲרֶיךָ הוֹשִׁיעַ. כָּל שִׂיחַ תַּדְשֵׁא וְתוֹשִׁיעַ. תְּמִימֶיךָ תּוֹשִׁיעַ. הוֹשַׁע נָא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ אֵלִים בְּלוּד עִמָּךְ, בְּצֵאתְךָ לְיֵשַׁע עַמָּךְ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ גּוֹי וֵאלֹהִים, דְּרוּשִׁים לְיֵשַׁע אֱלֹהִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ הֲמוֹן צְבָאוֹת, וְעִמָּם מַלְאֲכֵי צְבָאוֹת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ זַכִּים מִבֵּית עֲבָדִים, חַנּוּן בְּיָדָם מַעֲבִידִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ טְבוּעִים בְּצוּל גְּזָרִים, יְקָרְךָ עִמָּם מַעֲבִירִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ כַּנָּה מְשׁוֹרֶרֶת וַיּוֹשַׁע, לְגוֹחָהּ מְצֻיֶּנֶת וַיִּוָּשַׁע, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מַאֲמַר וְהוֹצֵאתִי אֶתְכֶם, נָקוּב וְהוּצֵאתִי אִתְּכֶם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ סוֹבְבֵי מִזְבֵּחַ, עוֹמְסֵי עֲרָבָה לְהַקִּיף מִזְבֵּחַ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ פִּלְאֵי אָרוֹן כְּהֻפְשַׁע, צִעֵר פְּלֶשֶׁת בַּחֲרוֹן אַף וְנוֹשַׁע, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ קְהִלּוֹת בָּבֶלָה שִׁלַּחְתָּ, רַחוּם לְמַעֲנָם שֻׁלַּחְתָּ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב, וְהוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי יְשׁוּעוֹת, אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא. תהילים הוֹשִׁיעָה אֶת עַמֶּךָ, וּבָרֵךְ אֶת נַחֲלָתֶךָ, וּרְעֵם וְנַשְּׂאֵם עַד הָעוֹלָם. מלכים וְיִהְיוּ דְּבָרַי אֵלֶּה אֲשֶׁר הִתְחַנַּנְתִּי לִפְנֵי יְהֹוָה, קְרוֹבִים אֶל יְהֹוָה אֱלֹהֵינוּ יוֹמָם וָלָיְלָה, לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל דְּבַר יוֹם בְּיוֹמוֹ. לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי יְהֹוָה הוּא הָאֱלֹהִים, אֵין עוֹד. הושענות לשבת פותחים את ארון הקודש, ואומרים הושענות ללא הקפות: הוֹשַׁע נָא אוֹם נְצוּרָה כְּבָבַת. לְבוּשׁ וּכְסוּת מַחְלֶפֶת בַּשַּׁבָּת. בּוֹנֶנֶת בְּדַת נֶפֶשׁ מְשִׁיבַת. מַאֲכָל וּמִשְׁתֶּה מְכִינָה לַשַּׁבָּת. גּוֹמֶרֶת הִלְכוֹת שַׁבָּת. נֹעַם מְגָדִים מַנְעֶמֶת לַשַּׁבָּת. דּוֹרֶשֶׁת מַשְׂאַת שַׁבָּת. סְעוּדוֹת שָׁלשׁ מְקַיֶּמֶת בַּשַּׁבָּת. הַקּוֹבַעַת אַלְפַּיִם תְּחוּם שַׁבָּת. עַל שְׁתֵּי כִכָּרוֹת בּוֹצַעַת בַּשַּׁבָּת. וּמְשִׁיבַת רֶגֶל מִשַּׁבָּת. פּוֹרֶטֶת אַרְבַּע רְשׁוּיוֹת בַּשַּׁבָּת. זָכוֹר וְשָׁמוֹר מְקַיֶּמֶת בַּשַּׁבָּת. צִוּוּי הַדְלָקַת נֵר מַדְלֶקֶת בַּשַּׁבָּת. חָשָׁה לְמַהֵר בִּיאַת שַׁבָּת. קִדּוּשׁ הַיּוֹם מְקַדֶּשֶׁת בַּשַּׁבָּת. טוֹרַחַת כֹּל מִשִּׁשָּׁה לַשַּׁבָּת. רֶנֶן שֶׁבַע מְפַלֶּלֶת בַּשַּׁבָּת. יוֹשֶׁבֶת וּמַמְתֶּנֶת עַד כְּלוֹת שַׁבָּת. שִׁבְעָה בַדָּת קוֹרְאָה בַשַּׁבָּת. כָּבוֹד וָעֹנֶג קוֹרְאָה לַשַּׁבָּת. תַּנְחִילֶנָּה יוֹם שֶׁכֻּלּוֹ שַׁבָּת. הוֹשַׁע נָא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ אָדָם יְצִיר כַּפֶּיךָ לְגוֹנְנָה, בְּשַׁבַּת קֹדֶשׁ הִמְצֵאתוֹ כֹּפֶר וַחֲנִינָה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ גּוֹי מְצֻיָּן מְקַוִּים חֹפֶשׁ, דֵּעָה כִּוְּנוּ לָבוּר שְׁבִיעִי לְנֹפֶשׁ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ הָעָם נִהַגְתָּ כַּצֹּאן לְהַנְחוֹת, וְחֹק שַׂמְתָּ בְּמָרָה עַל מֵי מְנוּחוֹת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ זְבוּדֶיךָ בְּמִדְבַּר סִין בַּמַחֲנֶה, חָכְמוּ וְלָקְטוּ בַּשִּׁשִּׁי לֶחֶם מִשְׁנֶה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ טְפוּלֶיךָ הוֹרוּ הֲכָנָה בְּמַדָּעָם, יִשַּׁר כֹּחָם וְהוֹדָה לָמוֹ רוֹעָם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ כֻּלְכְּלוּ בְּעֹנֶג מָן הַמְּשֻׁמָּר, לֹא הָפַךְ עֵינוֹ וְרֵיחוֹ לֹא נָמָר, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מִשְׁפְּטֵי מַשְׂאֹת שַׁבָּת גָּמָרוּ, נָחוּ וְשָׁבְתוּ, רְשׁוּיוֹת וּתְחוּמִים שָׁמָרוּ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ סִינַי הָשְׁמְעוּ בְּדִבּוּר רְבִיעִי, עִנְיַן זָכוֹר וְשָׁמוֹר לְקַדֵּשׁ שְׁבִיעִי, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ פֻּקְּדוּ יְרִיחוֹ שֶׁבַע לְהַקֵּף, צָרוּ עַד רִדְתָּהּ בַּשַּׁבָּת לְתַקֵּף, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ קֹהֶלֶת וְעַמּוֹ בְּבֵית עוֹלָמִים, רִצּוּךָ בְּחָגְגָם שִׁבְעָה וְשִׁבְעָה יָמִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שָׁבִים עוֹלֵי גוֹלָה לְפִדְיוֹם, תּוֹרָתְךָ בְּקָרְאָם בֶּחָג יוֹם יוֹם, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מְשַׂמְּחֶיךָ בְּבִנְיַן שֵׁנִי הַמְחֻדָּשׁ, נוֹטְלִין לוּלָב כָּל שִׁבְעָה בַּמִּקְדָּשׁ, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ חִבּוּט עֲרָבָה שַׁבָּת מַדְחִים, מֻרְבִּיּוֹת מוֹצָא לִיסוֹד מִזְבֵּחַ מַנִּיחִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ בְּרַכּוֹת וַאֲרוּכּוֹת וּגְבוֹהוֹת מְעַלְּסִים, בִּפְטִירָתָן יֹפִי לְךָ מִזְבֵּחַ מְקַלְּסִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ מוֹדִים וּמְיַחֲלִים וְלֹא מְשַׁנִּים, כֻּלָּנוּ אָנוּ לְיָהּ וְעֵינֵינוּ לְיָהּ שׁוֹנִים, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ יֶקֶב מַחֲצָבֶיךָ סוֹבְבִים בְּרַעֲנָנָה, רוֹנְנִים אֲנִי וָהוּ הוֹשִׁיעָה נָּא, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ חֵיל זְרִיזִים מְשָׁרְתִים בִּמְנוּחָה, קָרְבַּן שַׁבָּת כָּפוּל עוֹלָה וּמִנְחָה, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ לְוִיֶּךָ עַל דּוּכָנָם לְהַרְבָּת, אוֹמְרִים מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ נִחוּמֶיךָ בְּמִצְוֹתֶיךָ תָּמִיד יִשְׁתַּעְשְׁעוּן, וּרְצֵם וְהַחֲלִיצֵם, בְּשׁוּבָה וָנַחַת יִוָּשֵׁעוּן, כֵּן הוֹשַׁע נָא. כְּהוֹשַׁעְתָּ שְׁבוּת שִׁבְטֵי יַעֲקֹב, תָּשׁוּב וְתָשִׁיב שְׁבוּת אָהֳלֵי יַעֲקֹב, וְהוֹשִׁיעָה נָּא. כְּהוֹשַׁעְתָּ שׁוֹמְרֵי מִצְוֹת וְחוֹכֵי יְשׁוּעוֹת, אֵל לְמוֹשָׁעוֹת, וְהוֹשִׁיעָה נָּא. אֲנִי וָהוּ הוֹשִׁיעָה נָּא. תהילים הוֹשִׁיעָה אֶת עַמֶּךָ, וּבָרֵךְ אֶת נַחֲלָתֶךָ, וּרְעֵם וְנַשְּׂאֵם עַד הָעוֹלָם. מלכים וְיִהְיוּ דְּבָרַי אֵלֶּה אֲשֶׁר הִתְחַנַּנְתִּי לִפְנֵי יְהֹוָה, קְרוֹבִים אֶל יְהֹוָה אֱלֹהֵינוּ יוֹמָם וָלָיְלָה, לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל דְּבַר יוֹם בְּיוֹמוֹ. לְמַעַן דַּעַת כָּל עַמֵּי הָאָרֶץ כִּי יְהֹוָה הוּא הָאֱלֹהִים, אֵין עוֹד."]]});